def input_sha256_status(raw: bytes) -> tuple[str, str | None]:
    """Return the complete input hash and its tested-reference name, if known."""
    digest = hashlib.sha256(raw).hexdigest()
    return digest, SUPPORTED_MAINUI_SHA256.get(digest)


def unrecognized_input_warning_lines(input_sha256: str) -> tuple[str, ...]:
    """Describe the risks of continuing with an unrecognized MainUI image."""
    return (
        f'[WARNING] Unrecognized MainUI SHA-256: {input_sha256}',
        '[WARNING] Continuing in compatibility mode; this input has not been tested.',
        '[WARNING] ELF, protected-data, and hook checks still apply, but a successful',
        '          build does not prove runtime compatibility. Keep the original backup.',
    )


class PatchProgressMeter:
    """Visible host-side progress with a low-frequency working heartbeat.

    Every update is a complete, flushed line rather than an in-place carriage
    return.  That keeps progress visible in terminals, launchers, redirected
    logs, and front ends that only render newline-terminated output.  A daemon
    heartbeat repeats the current stage if one build phase takes long enough
    that the patcher would otherwise appear stuck.  Expensive patch-body work is
    also split into real sub-stages so both the message and percentage continue
    moving while the selected patches are being prepared.  This never changes
    patched binary contents.
    """

    WIDTH = 28
    HEARTBEAT_SECONDS = 2.0

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._stop = threading.Event()
        self._thread: threading.Thread | None = None
        self._stage_started_at = 0.0
        self._last_emit_at = 0.0
        self._percent = 0
        self._message = 'Starting patch build'
        self._last_reported: tuple[int, str] | None = None

    @classmethod
    def _line(cls, percent: int, message: str, suffix: str = '') -> str:
        filled = cls.WIDTH * percent // 100
        bar = '#' * filled + '-' * (cls.WIDTH - filled)
        return f'  [PROGRESS] [{bar}] {percent:3d}% {message}{suffix}'

    def start(self, message: str = 'Starting patch build') -> None:
        if self._thread is not None:
            return
        now = time.monotonic()
        self._stage_started_at = now
        self._last_emit_at = now
        self._message = message
        print(self._line(0, message), flush=True)
        self._last_reported = (0, message)
        self._thread = threading.Thread(
            target=self._heartbeat, name='mainui-patch-progress', daemon=True)
        self._thread.start()

    def update(self, percent: int, message: str) -> None:
        percent = max(0, min(100, int(percent)))
        now = time.monotonic()
        with self._lock:
            state = (percent, message)
            if state == self._last_reported:
                return
            self._percent = percent
            self._message = message
            self._stage_started_at = now
            print(self._line(percent, message), flush=True)
            self._last_reported = state
            self._last_emit_at = now

    def _heartbeat(self) -> None:
        while not self._stop.is_set():
            with self._lock:
                wait_for = max(
                    0.0, self.HEARTBEAT_SECONDS
                    - (time.monotonic() - self._last_emit_at))
            if self._stop.wait(wait_for):
                return
            now = time.monotonic()
            with self._lock:
                if now - self._last_emit_at < self.HEARTBEAT_SECONDS:
                    continue
                elapsed = max(0, int(now - self._stage_started_at))
                suffix = f' (working, {elapsed}s on this step)'
                print(self._line(self._percent, self._message, suffix),
                      flush=True)
                self._last_emit_at = now

    def finish_line(self) -> None:
        self._stop.set()
        if self._thread is not None:
            self._thread.join(timeout=0.25)
            self._thread = None


def fsync_directory_best_effort(directory: Path) -> None:
    """Persist a same-directory rename when the host filesystem supports it."""
    flags = os.O_RDONLY | getattr(os, 'O_DIRECTORY', 0)
    try:
        fd = os.open(directory, flags)
    except OSError:
        return
    try:
        try:
            os.fsync(fd)
        except OSError:
            # Some filesystems accept atomic rename but reject directory fsync.
            pass
    finally:
        os.close(fd)


def atomic_write_bytes(destination: Path, data: bytes | bytearray, mode: int) -> None:
    """Publish bytes with a checked same-directory temporary file and replace."""
    directory = destination.parent
    fd, temporary_name = tempfile.mkstemp(
        prefix=f'.{destination.name}.', suffix='.tmp', dir=directory)
    temporary = Path(temporary_name)
    try:
        with os.fdopen(fd, 'wb') as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.chmod(temporary, mode & 0o7777)
        os.replace(temporary, destination)
        fsync_directory_best_effort(directory)
    except BaseException:
        try:
            temporary.unlink()
        except FileNotFoundError:
            pass
        raise

