GAME_LIST_COVER_CHECK_CONTINUE_VA = 0x00031704
GAME_LIST_COVER_CHECK_STOCK_WORD = 0xE51B30F0

# Ordinary ROM-folder setup queues a hard-coded top-of-list worker before
