# Both cache rebuild paths load this stock transaction string into r1 and call
# MainUI's SQLite execution wrapper. The wrapper uses sqlite3_get_table, which
# accepts this sequence because only journal_mode returns a one-column result;
# the setting PRAGMAs and BEGIN do not create an incompatible result shape.
# temp_store and the moderate negative cache_size are connection-local and are
# limited to these derived cache6.db rebuild connections. locking_mode is not
# enabled: unlike the two added setting PRAGMAs, it returns a result row and its
# connection-lifetime semantics have not been proven safe in MainUI.
ROM_DATABASE_BEGIN_STOCK = b"BEGIN TRANSACTION;\0"
ROM_DATABASE_FAST_REBUILD_BEGIN = (
    b"PRAGMA synchronous=OFF;PRAGMA journal_mode=OFF;"
    b"PRAGMA temp_store=MEMORY;PRAGMA cache_size=-8000;"
    b"BEGIN TRANSACTION;\0")

# When both the rebuild and browse-index optimizations are selected, table
# creation remains index-free during insertion. Site-specific wrappers at the
# two verified END TRANSACTION calls format and execute one CREATE INDEX just
# before committing. The wrappers use each caller's still-live system table
# name, and commit even if index creation fails so the derived cache remains
# usable through stock unindexed browse queries.
ROM_DATABASE_DEFERRED_INDEX_BINARY = (
    b"CREATE INDEX mainui_rom_browse ON %s_roms"
    b"(ppath,type DESC,disp);\0")
