# miyoogamelist.xml importer. The function and loop are located from the
# verified XML-rebuild prologue, while imported call targets are resolved from
# .rel.plt/.dynsym. Relative offsets are then checked against invariant stock
# instructions before any write. The transient filename set is one 512 KiB
# calloc block: a 16-byte header, 8192 open-addressed pointer slots, and a
# bounded string pool. At most 6000 entries are admitted; any failure or bound
# hit discards the set and preserves stock per-entry access() semantics.
MIYOOGAMELIST_IMPORT_END_REL = 0xC44
MIYOOGAMELIST_LOOP_START_REL = 0x3EC
MIYOOGAMELIST_LOOP_END_REL = 0xA70
MIYOOGAMELIST_PRELOOP_HOOK_REL = 0x3E8
MIYOOGAMELIST_NORMAL_CLEANUP_REL = 0xA74
MIYOOGAMELIST_EXCEPTION_CLEANUP_REL = 0xBB4
MIYOOGAMELIST_ACCESS_RELS = (0x264, 0x6AC)
MIYOOGAMELIST_GETTIMEOFDAY_RELS = (0xE0, 0x6E4, 0x9F4, 0xB30)
MIYOOGAMELIST_MISSING_IMAGE_EXIT_REL = 0x5C8
MIYOOGAMELIST_MISSING_IMAGE_TEXT_REL = 0x5F0
MIYOOGAMELIST_EMPTY_IMAGE_REJECT_REL = 0x67C
MIYOOGAMELIST_IMAGE_VALIDATION_REL = 0x638
MIYOOGAMELIST_IMAGE_ACCEPT_REL = 0x680
MIYOOGAMELIST_MISSING_IMAGE_EXIT_STOCK = 0xEA000129
MIYOOGAMELIST_MISSING_IMAGE_TEXT_STOCK = 0x0A000010
MIYOOGAMELIST_EMPTY_IMAGE_REJECT_STOCK = 0x0A000001
MIYOOGAMELIST_LOOP_ACCESS_BYTES = bytes.fromhex('ddcfffeb')
MIYOOGAMELIST_LOOP_GETTIMEOFDAY_BYTES = (
    bytes.fromhex('dbcfffeb'), bytes.fromhex('17cfffeb'))
MIYOOGAMELIST_SET_STATE_SIZE = 4
MIYOOGAMELIST_SET_BLOCK_SIZE = 0x80000
MIYOOGAMELIST_SET_TABLE_OFFSET = 16
MIYOOGAMELIST_SET_CAPACITY = 8192
MIYOOGAMELIST_SET_MASK = MIYOOGAMELIST_SET_CAPACITY - 1
MIYOOGAMELIST_SET_POOL_OFFSET = (
    MIYOOGAMELIST_SET_TABLE_OFFSET + MIYOOGAMELIST_SET_CAPACITY * 4)
MIYOOGAMELIST_SET_MAX_ENTRIES = 6000
MIYOOGAMELIST_DIRENT_NAME_OFFSET = 11
MIYOOGAMELIST_FNV_OFFSET = 0x811C9DC5
MIYOOGAMELIST_FNV_PRIME = 0x01000193


def find_miyoogamelist_import_sites(
        data: bytes | bytearray, segs: list['Segment'], access_va: int,
        gettimeofday_va: int) -> dict[str, object]:
    """Resolve and verify the XML-import hooks and imported call sites."""
    start = unique(bytes(data), ROM_DATABASE_XML_REBUILD_FUNCTION_SIG,
                   'miyoogamelist XML importer')
    end = start + MIYOOGAMELIST_IMPORT_END_REL
    if end > len(data):
        raise ValueError('miyoogamelist XML importer extends beyond file')
    loop_start = start + MIYOOGAMELIST_LOOP_START_REL
    loop_end = start + MIYOOGAMELIST_LOOP_END_REL

    access_all = _direct_call_sites_in_range(
        data, segs, start, end, access_va)
    access_rels = tuple(site - start for site in access_all)
    if access_rels != MIYOOGAMELIST_ACCESS_RELS:
        raise ValueError(
            'miyoogamelist access() sites changed: ' +
            ', '.join(hex(x) for x in access_rels))
    loop_access = [x for x in access_all if loop_start <= x < loop_end]
    if len(loop_access) != 1:
        raise ValueError('expected one access() call inside XML entry loop')
    if bytes(data[loop_access[0]:loop_access[0] + 4]) != (
            MIYOOGAMELIST_LOOP_ACCESS_BYTES):
        raise ValueError('XML-loop access() bytes do not match 354-clean')

    gtod_all = _direct_call_sites_in_range(
        data, segs, start, end, gettimeofday_va)
    gtod_rels = tuple(site - start for site in gtod_all)
    if gtod_rels != MIYOOGAMELIST_GETTIMEOFDAY_RELS:
        raise ValueError(
            'miyoogamelist gettimeofday sites changed: ' +
            ', '.join(hex(x) for x in gtod_rels))
    loop_gtod = [x for x in gtod_all if loop_start <= x < loop_end]
    if len(loop_gtod) != 2:
        raise ValueError(
            'expected two gettimeofday calls inside XML entry loop')
    for site, expected in zip(loop_gtod,
                              MIYOOGAMELIST_LOOP_GETTIMEOFDAY_BYTES):
        if bytes(data[site:site + 4]) != expected:
            raise ValueError(
                f'XML-loop gettimeofday bytes differ at '
                f'{off2va(segs, site):#x}')

    preloop = start + MIYOOGAMELIST_PRELOOP_HOOK_REL
    if tuple(read_word(data, preloop + 4 * i) for i in range(3)) != (
            0xE50B3020, 0xE51B3020, 0xE3530000):
        raise ValueError('XML pre-loop iterator store signature changed')
    normal_cleanup = start + MIYOOGAMELIST_NORMAL_CLEANUP_REL
    if tuple(read_word(data, normal_cleanup + 4 * i) for i in range(3)) != (
            0xE24B3801, 0xE243300C, 0xE1A00003):
        raise ValueError('XML normal-cleanup signature changed')
    missing_image_exit = start + MIYOOGAMELIST_MISSING_IMAGE_EXIT_REL
    missing_image_text = start + MIYOOGAMELIST_MISSING_IMAGE_TEXT_REL
    empty_image_reject = start + MIYOOGAMELIST_EMPTY_IMAGE_REJECT_REL
    image_validation = start + MIYOOGAMELIST_IMAGE_VALIDATION_REL
    image_accept = start + MIYOOGAMELIST_IMAGE_ACCEPT_REL
    if read_word(data, missing_image_exit) != (
            MIYOOGAMELIST_MISSING_IMAGE_EXIT_STOCK):
        raise ValueError('missing-image XML exit branch changed')
    if decode_arm_branch_target(
            read_word(data, missing_image_exit),
            off2va(segs, missing_image_exit)) != off2va(segs, normal_cleanup):
        raise ValueError('missing-image XML exit target changed')
    if read_word(data, missing_image_text) != (
            MIYOOGAMELIST_MISSING_IMAGE_TEXT_STOCK):
        raise ValueError('missing-image XML null-text branch changed')
    if decode_arm_branch_target(
            read_word(data, missing_image_text),
            off2va(segs, missing_image_text)) != off2va(segs, image_validation):
        raise ValueError('missing-image XML null-text target changed')
    if read_word(data, empty_image_reject) != (
            MIYOOGAMELIST_EMPTY_IMAGE_REJECT_STOCK):
        raise ValueError('empty-image XML rejection branch changed')
    if decode_arm_branch_target(
            read_word(data, empty_image_reject),
            off2va(segs, empty_image_reject)) != off2va(
                segs, image_accept + 8):
        raise ValueError('empty-image XML rejection target changed')
    validation_words = tuple(
        read_word(data, image_validation + 4 * i) for i in range(3))
    if validation_words[:2] != (0xE24B307C, 0xE1A00003):
        raise ValueError('missing-image XML validation signature changed')
    if decode_arm_branch_target(
            validation_words[2], off2va(segs, image_validation + 8)) != 0x000157F0:
        raise ValueError('missing-image XML validation call target changed')

    exception_cleanup = start + MIYOOGAMELIST_EXCEPTION_CLEANUP_REL
    if tuple(read_word(data, exception_cleanup + 4 * i) for i in range(3)) != (
            0xE24B3050, 0xE1A00003, 0xEBFFCFFB):
        raise ValueError('XML exception-cleanup signature changed')

    return {
        'start': start,
        'loop_access': loop_access[0],
        'loop_gettimeofday': tuple(loop_gtod),
        'retained_gettimeofday': (gtod_all[0], gtod_all[-1]),
        'preloop': preloop,
        'normal_cleanup': normal_cleanup,
        'exception_cleanup': exception_cleanup,
        'missing_image_exit': missing_image_exit,
        'missing_image_text': missing_image_text,
        'empty_image_reject': empty_image_reject,
        'image_validation': image_validation,
        'image_accept': image_accept,
    }


