def verify_favourite_flat_symbol_offsets(
        core: bytes, symbols: dict[str, int]) -> None:
    """Reject ELF-VMA offsets accidentally used for a flat .text payload."""
    expected = {
        'fav_action_delete': 0xE1A02009,
        'fav_load': 0xE1A00009,
        'fav_keyboard_title_for_window': 0xE1A02009,
    }
    for name, word in expected.items():
        off = symbols.get(name)
        if off is None or off < 0 or off + 4 > len(core) or off & 3:
            raise ValueError(f'invalid Favourite flat-core symbol offset: {name}')
        actual = struct.unpack_from('<I', core, off)[0]
        if actual != word:
            raise ValueError(
                f'Favourite flat-core symbol offset mismatch for {name}: '
                f'word {actual:#010x}, expected {word:#010x}. '
                'Do not use raw ELF symbol VMAs; subtract the .text section VMA.')


