def verify_main_menu_flat_symbol_offsets(
        core: bytes, symbols: dict[str, int]) -> None:
    expected = {
        'main_menu_build': 0xE92D4FF0,
        'main_menu_get_action': 0xE92D48F0,
        'main_menu_action_regular_dtor': 0xE3500000,
        'main_menu_action_deleting_dtor': 0xE92D4830,
        'main_menu_action_execute': 0xE3500000,
        'main_menu_finish_action': 0xE92D47F0,
        'main_menu_show_context': 0xE3500000,
        'main_menu_build_settings': 0xE92D4FF0,
        'main_menu_draw_label': 0xE92D4FF0,
        'popup_background_load': 0xE92D4FF0,
    }
    for name, word in expected.items():
        off = symbols.get(name)
        if off is None or off < 0 or off + 4 > len(core) or off & 3:
            raise ValueError(f'invalid main-menu flat-core symbol offset: {name}')
        actual = struct.unpack_from('<I', core, off)[0]
        if actual != word:
            raise ValueError(
                f'main-menu flat-core symbol offset mismatch for {name}: '
                f'word {actual:#010x}, expected {word:#010x}')

RECENT_REMOVE_C_SOURCE = r'''


/* SPDX-License-Identifier: GPL-3.0-only
 * Copyright (C) 2026 robcodedev
 */
typedef unsigned int u32;
typedef signed int i32;
typedef unsigned char u8;

#define RECENT_IDENTITY_LIMIT 4096u
#define RECENT_SCAN_LIMIT 10000u
#define IDENTITY_KEY 1u
#define IDENTITY_APP_LAUNCH 2u
#define IDENTITY_LABEL 3u
#ifdef HOST_TEST
#define MENU_BEGIN_OFF 0xf8u
#define MENU_END_OFF (0xf8u + sizeof(void *))
#else
#define MENU_BEGIN_OFF 0xf8u
#define MENU_END_OFF 0xfcu
#endif

typedef struct RecentRemoveContext RecentRemoveContext;
typedef struct RecentRemoveAction {
    u32 *vptr;
    i32 type;
    void *window;
    void *selected_item;
    RecentRemoveContext *context;
    char *identity;
    u32 identity_kind;
} RecentRemoveAction;

struct RecentRemoveContext {
    void *(*op_new_)(u32);
    void (*op_delete_sized_)(void *, u32);
    void *(*base_action_ctor_)(void *, i32);
    void *(*base_action_dtor_)(void *);
    void *(*item_ctor_)(void *, const char *, void *, void *, i32);
    void (*item_dtor_)(void *);
    void (*list_add_)(void *, void *);
    const char *(*translate_)(i32);
    const char *(*string_c_str_)(const void *);
    i32 (*strcmp_)(const char *, const char *);
    i32 (*remove_recent_key_)(void *, const char *);
    i32 (*write_recent_)(void *);
    void *recent_list;
    void *(*recent_begin_)(void *);
    void *(*recent_end_)(void *);
    i32 (*recent_iter_ne_)(const void *, const void *);
    void *(*recent_iter_inc_)(void *, i32);
    void *(*recent_iter_deref_)(void *);
    void *(*recent_const_iter_ctor_)(void *, const void *);
    void *(*recent_erase_iter_)(void *, const void *);
    u32 *custom_action_vptr;
    u32 game_action_vptr;
    u32 app_action_vptr;
    void *(*malloc_)(u32);
    void (*free_)(void *);
    u32 (*strlen_)(const char *);
    void *(*memcpy_)(void *, const void *, u32);
    void (*menu_remove_index_)(void *, i32);
};

static const char remove_fallback[] = "Remove from list";

static char *copy_identity(RecentRemoveContext *c, const char *text) {
    u32 len;
    char *copy;
    if (!c || !text) return 0;
    len = c->strlen_(text);
    if (!len || len > RECENT_IDENTITY_LIMIT) return 0;
    copy = (char *)c->malloc_(len + 1u);
    if (!copy) return 0;
    c->memcpy_(copy, text, len + 1u);
    return copy;
}

__attribute__((visibility("default"))) void *recent_remove_regular_dtor(RecentRemoveAction *a) {
    RecentRemoveContext *c;
    if (!a || !(c = a->context)) return a;
    a->vptr = c->custom_action_vptr;
    if (a->identity) c->free_(a->identity);
    a->identity = 0;
    c->base_action_dtor_(a);
    return a;
}

__attribute__((visibility("default"))) void *recent_remove_deleting_dtor(RecentRemoveAction *a) {
    RecentRemoveContext *c;
    if (!a || !(c = a->context)) return a;
    recent_remove_regular_dtor(a);
    c->op_delete_sized_(a, sizeof(*a));
    return a;
}

static int capture_recent_identity(RecentRemoveAction *a, void *selected_item,
                                   void *row_action) {
    RecentRemoveContext *c;
    const char *text = 0;
    u32 vptr = 0;
    if (!a || !(c = a->context) || !selected_item) return 0;
    a->identity_kind = IDENTITY_LABEL;
    if (row_action) vptr = *(u32 *)row_action;
    if (vptr == c->game_action_vptr) {
        text = c->string_c_str_((u8 *)row_action + 0x24);
        a->identity_kind = IDENTITY_KEY;
    } else if (vptr == c->app_action_vptr) {
        void *app = *(void **)((u8 *)row_action + 8);
        text = app ? c->string_c_str_((u8 *)app + 0x48) : 0;
        a->identity_kind = IDENTITY_APP_LAUNCH;
    }
    if (!text || !text[0]) {
        text = c->string_c_str_(selected_item);
        a->identity_kind = IDENTITY_LABEL;
    }
    a->identity = copy_identity(c, text);
    return a->identity != 0;
}

static int erase_matching_identity(RecentRemoveContext *c, u32 kind,
                                   const char *identity) {
    void *it, *end, *record, *converted;
    const char *candidate;
    u32 scanned = 0;
    if (!c || !c->recent_list || !identity || !identity[0]) return 0;
    it = c->recent_begin_(c->recent_list);
    end = c->recent_end_(c->recent_list);
    while (c->recent_iter_ne_(&it, &end) && scanned++ < RECENT_SCAN_LIMIT) {
        record = c->recent_iter_deref_(&it);
        if (record) {
            candidate = 0;
            if (kind == IDENTITY_APP_LAUNCH) {
                candidate = c->string_c_str_((u8 *)record + 0x18);
                if (!candidate || c->strcmp_(candidate, identity) != 0)
                    candidate = c->string_c_str_((u8 *)record + 0x48);
            } else if (kind == IDENTITY_LABEL) {
                candidate = c->string_c_str_(record);
            }
            if (candidate && c->strcmp_(candidate, identity) == 0) {
                converted = 0;
                c->recent_const_iter_ctor_(&converted, &it);
                c->recent_erase_iter_(c->recent_list, converted);
                return 1;
            }
        }
        c->recent_iter_inc_(&it, 0);
    }
    return 0;
}

__attribute__((visibility("default"))) i32 recent_remove_execute(RecentRemoveAction *a, u32 original_r1) {
    RecentRemoveContext *c;
    void *window;
    void **begin, **end, **it;
    i32 result, index = -1;
    (void)original_r1;
    if (!a || !(c = a->context) || !a->identity) return 1;
    if (a->identity_kind == IDENTITY_KEY)
        result = c->remove_recent_key_(c->recent_list, a->identity);
    else
        result = erase_matching_identity(c, a->identity_kind, a->identity);
    if (result <= 0) return 1;
    c->write_recent_(c->recent_list);
    window = a->window;
    if (window && a->selected_item && c->menu_remove_index_) {
        begin = *(void ***)((u8 *)window + MENU_BEGIN_OFF);
        end = *(void ***)((u8 *)window + MENU_END_OFF);
        if (begin && end && end >= begin && (u32)(end - begin) <= RECENT_SCAN_LIMIT) {
            for (it = begin; it != end; ++it) {
                if (*it == a->selected_item) {
                    index = (i32)(it - begin);
                    break;
                }
            }
        }
        if (index >= 0) c->menu_remove_index_(window, index);
    }
    return 1;
}

__attribute__((visibility("default"))) i32 recent_remove_add_item(
        void *menu, void *selected_item, void *event, RecentRemoveContext *c) {
    RecentRemoveAction *a;
    void *item;
    const char *label;
    if (!menu || !selected_item || !event || !c) return 0;
    a = (RecentRemoveAction *)c->op_new_(sizeof(*a));
    if (!a) return 0;
    c->base_action_ctor_(a, *(i32 *)((u8 *)event + 8));
    a->vptr = c->custom_action_vptr;
    a->window = *(void **)((u8 *)event + 12);
    a->selected_item = selected_item;
    a->context = c;
    a->identity = 0;
    a->identity_kind = 0;
    if (!capture_recent_identity(a, selected_item,
                                 *(void **)((u8 *)selected_item + 24))) {
        recent_remove_deleting_dtor(a);
        return 0;
    }
    item = c->op_new_(116);
    if (!item) {
        recent_remove_deleting_dtor(a);
        return 0;
    }
    label = c->translate_(52);
    if (!label || !label[0]) label = remove_fallback;
    c->item_ctor_(item, label, 0, a, 1);
    c->list_add_(menu, item);
    return 1;
}

#ifndef HOST_TEST
_Static_assert(sizeof(RecentRemoveAction) == 28, "RecentRemoveAction size");
_Static_assert(sizeof(RecentRemoveContext) == 112, "RecentRemoveContext size");
#endif
'''

