MIYOOGAMELIST_DETAIL_META_DRAW_OFF = 0x0000
MIYOOGAMELIST_DETAIL_META_INPUT_OFF = 0x095c
MIYOOGAMELIST_DETAIL_META_CLEANUP_OFF = 0x0a5c
MIYOOGAMELIST_DETAIL_STATE_SIZE = 49528
MIYOOGAMELIST_DETAIL_FONT_PTR_OFF = 32
MIYOOGAMELIST_DETAIL_TITLE_SIZE_OFF = 36
MIYOOGAMELIST_DETAIL_CONTEXT_SIZE = 168
MIYOOGAMELIST_DETAIL_INPUT_DEFAULT_VA = 0x00035BEC
MIYOOGAMELIST_DETAIL_INPUT_STOCK_DEFAULT_VA = 0x00035FC8
MIYOOGAMELIST_DETAIL_INPUT_STOCK_RETURN_VA = 0x00035FD0
MIYOOGAMELIST_DETAIL_UP_BLOCK_VA = 0x00035E6C
MIYOOGAMELIST_DETAIL_DOWN_BLOCK_VA = 0x00035F1C
MIYOOGAMELIST_DETAIL_UP_RETURN_VA = 0x00035FD0
MIYOOGAMELIST_DETAIL_DOWN_RETURN_VA = 0x00035FC8
MIYOOGAMELIST_DETAIL_UPDATE_VA = 0x00035538
MIYOOGAMELIST_DETAIL_UPDATE_CONTINUE_VA = 0x0003553C
MIYOOGAMELIST_DETAIL_SELECTED_INDEX_VA = 0x000395A4
MIYOOGAMELIST_DETAIL_VECTOR_SIZE_VA = 0x0003C538
MIYOOGAMELIST_DETAIL_STRINGS = (
    b'r\0', b'gamelist.xml\0', b'\0', b'<game\0', b'</game>\0',
    b'<path>\0', b'</path>\0', b'<desc>\0', b'</desc>\0',
    b'<rating>\0', b'</rating>\0', b'<genre>\0', b'</genre>\0',
    b'gamelist detail index: %u entries, %u us\n\0',
)


def find_game_detail_system_font_loader_sites(
        data: bytes | bytearray,
        segs: list[Segment]) -> tuple[list[int], int]:
    """Find the six loads of the font used by the detail system-name line."""
    sites, target = find_game_font_loader_sites(data, segs)
    return sites, target


def find_game_detail_metadata_hooks(
        data: bytes | bytearray, segs: list[Segment]) -> dict[str, object]:
    """Resolve and verify the scoped detail-view vtable/input/font hooks."""
    vtable = unique(data, GAME_DETAIL_VTABLE_SIG, 'GameDetailWindow vtable')
    expected = (0x00034D0C, 0x00034D98, 0x00035BBC, GAME_DETAIL_DRAW_VA)
    for i, va in enumerate(expected):
        if read_word(data, vtable + i * 4) != va:
            raise ValueError('GameDetailWindow vtable entry changed')
    default_off = va2off(segs, MIYOOGAMELIST_DETAIL_INPUT_DEFAULT_VA,
                         executable=True)
    default_word = read_word(data, default_off)
    if decode_arm_branch_target(default_word,
                                MIYOOGAMELIST_DETAIL_INPUT_DEFAULT_VA) !=             MIYOOGAMELIST_DETAIL_INPUT_STOCK_DEFAULT_VA:
        raise ValueError('GameDetailWindow default input branch changed')
    # Verify the draw routine still obtains the wrapped-title vector size from
    # this+0x6c at the known scoped call used to place metadata below the title.
    vector_call = va2off(segs, 0x00035920, executable=True)
    if decode_arm_branch_target(read_word(data, vector_call), 0x00035920) !=             MIYOOGAMELIST_DETAIL_VECTOR_SIZE_VA:
        raise ValueError('GameDetailWindow title-line count call changed')
    font_sites, font_loader = find_game_detail_system_font_loader_sites(data, segs)
    return {
        'vtable': vtable,
        'regular_destructor_entry': vtable,
        'deleting_destructor_entry': vtable + 4,
        'draw_entry': vtable + GAME_DETAIL_DRAW_VTABLE_OFF,
        'input_default': default_off,
        'font_loader': font_loader,
        'font_sites': font_sites,
    }



def verify_mainui_xstat_abi(
        data: bytes | bytearray, segs: list[Segment], xstat_plt_va: int) -> None:
    """Verify MainUI's ARM glibc stat veneer uses __xstat version 3."""
    sig = bytes.fromhex('0120a0e1 0010a0e1 0300a0e3')
    matches: list[int] = []
    start = 0
    while True:
        off = data.find(sig, start)
        if off < 0:
            break
        try:
            va = off2va(segs, off)
            branch_va = va + len(sig)
            target = decode_arm_branch_target(
                read_word(data, off + len(sig)), branch_va)
            if target == xstat_plt_va:
                matches.append(off)
        except ValueError:
            pass
        start = off + 1
    if len(matches) != 1:
        raise ValueError(
            'expected exactly one MainUI __xstat(version=3) ARM veneer')


def build_game_detail_metadata_draw_stub(
        base_va: int, state_va: int, context_va: int, helper_va: int) -> bytes:
    a = ArmBuilder(base_va)
    a.ldr_literal(2, state_va)
    a.ldr_literal(3, context_va)
    a.branch(helper_va)
    return a.finish()


def build_game_detail_metadata_input_stub(
        base_va: int, state_va: int, context_va: int, helper_va: int) -> bytes:
    """Offer one translated detail action to the metadata scroller.

    The patched stock site exposes `this` and the translated action in its
    frame. The C helper returns nonzero when it consumed L2/R2; otherwise the
    stub resumes MainUI's normal input dispatcher. Only r4/lr are owned here.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D4010)             # push {r4,lr}; retain 8-byte alignment
    a.emit(0xE51B0030)             # r0 = detail this
    a.emit(0xE51B1018)             # r1 = translated action
    a.ldr_literal(2, state_va)      # r2 = persistent metadata state
    a.ldr_literal(3, context_va)    # r3 = imported-function/context table
    a.branch(helper_va, link=True)  # helper(this,action,state,context)
    a.emit(0xE3500000)             # cmp helper result,#0
    a.emit(0xE8BD4010)             # pop {r4,lr}; preserve condition flags
    a.branch(MIYOOGAMELIST_DETAIL_INPUT_STOCK_RETURN_VA, cond=0x1)  # consumed
    a.branch(MIYOOGAMELIST_DETAIL_INPUT_STOCK_DEFAULT_VA)           # stock
    return a.finish()


def build_game_detail_metadata_destructor_stub(
        base_va: int, state_va: int, context_va: int, helper_va: int,
        original_va: int) -> bytes:
    """Release metadata-owned resources, then tail-call the stock destructor.

    `r0` is the original C++ object and must survive the cleanup helper. The
    extra saved `r1` preserves the deleting-destructor variant's argument.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D4013)             # push {r0,r1,r4,lr}
    a.emit(0xE1A00000)             # mov r0,r0; stable four-byte hook body
    a.ldr_literal(1, state_va)      # r1 = metadata state
    a.ldr_literal(2, context_va)    # r2 = helper context
    a.branch(helper_va, link=True)  # cleanup(state/context for this window)
    a.emit(0xE59D0000)             # restore original this
    a.emit(0xE28DD004)             # skip saved r0
    a.emit(0xE8BD4012)             # pop {r1,r4,lr}
    a.branch(original_va)
    return a.finish()


def build_game_detail_metadata_font_loader(
        base_va: int, state_va: int, stock_loader_va: int,
        raw_loader_va: int, close_font_va: int, set_style_va: int) -> bytes:
    """Open and publish the detail metadata font without changing stock output.

    Entry matches the stock five-argument font loader, with the size at [sp].
    All caller-visible registers are saved while a second font is opened at
    75% of that size. r4 retains the stock result; r5 retains the metadata font.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE59DC000)             # ip = fifth argument: system-name font size
    a.emit(0xE92D5FFF)             # push {r0-r12,lr} (56-byte aligned save)
    a.emit(0xE24DD008)             # reserve aligned stack argument area
    a.emit(0xE58DC000)             # original size as stock stack argument
    a.branch(stock_loader_va, link=True)
    a.emit(0xE28DD008)             # discard stock loader stack argument
    a.emit(0xE1A04000)             # r4 = stock system-name font result
    a.ldr_literal(6, state_va)
    a.emit(0xE5960020)             # old metadata font
    a.emit(0xE3500000)             # cmp old metadata font,#0
    a.branch('no_old', cond=0x0)
    a.emit(0xE3A05000)             # r5 = NULL before closing old font
    a.emit(0xE5865020)             # clear before close
    a.branch(close_font_va, link=True)
    a.label('no_old')
    a.emit(0xE59D5030)             # saved original size (saved ip)
    a.emit(0xE5865024)             # publish system-font size for metadata layout
    a.emit(0xE0857085)             # r7 = size * 3
    a.emit(0xE2877002)             # rounded divide by 4
    a.emit(0xE1A07127)             # r7 = (size * 3 + 2) >> 2
    a.emit(0xE357000F)             # cmp scaled size,#15
    a.emit(0xB3A0700F)             # minimum 15
    a.emit(0xE89D000F)             # restore original r0-r3 without popping
    a.emit(0xE24DD008)             # aligned stack slot for scaled size
    a.emit(0xE58D7000)             # fifth stock-loader argument
    a.branch(raw_loader_va, link=True)
    a.emit(0xE28DD008)             # discard metadata loader argument
    a.emit(0xE1A05000)             # r5 = metadata font result
    a.emit(0xE3500000)             # cmp metadata font,#0
    a.branch('publish', cond=0x0)
    a.emit(0xE1A00005)             # r0 = metadata font
    a.emit(0xE3A01000)             # TTF_STYLE_NORMAL
    a.branch(set_style_va, link=True)
    a.label('publish')
    a.emit(0xE5865020)             # publish metadata font
    a.emit(0xE1A00004)             # return stock system-name font
    a.emit(0xE28DD004)             # skip saved r0
    a.emit(0xE8BD5FFE)             # pop {r1-r12,lr}
    a.emit(0xE12FFF1E)             # bx lr
    return a.finish()



def build_game_detail_folder_skip_move(
        base_va: int, move_vtable_off: int,
        reverse_vtable_off: int) -> bytes:
    """Move detail selection to the next non-folder TextMenu item.

    Register contract: r4 is the detail window, r5 its parent TextMenu, r6 the
    starting index, r7 the current candidate, and r8 the candidate item. The
    virtual move call may wrap. A failed/null candidate is unwound with the
    opposite virtual move until the last valid index is restored.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}
    a.emit(0xE1A04000)             # r4 = detail this
    a.emit(0xE5945098)             # r5 = parent TextMenu
    a.emit(0xE3550000)             # cmp parent menu,#0
    a.branch('done', cond=0x0)
    a.emit(0xE1A00005)             # r0 = parent TextMenu
    a.branch(MIYOOGAMELIST_DETAIL_SELECTED_INDEX_VA, link=True)
    a.emit(0xE1A06000)             # r6 = original index
    a.emit(0xE1A07000)             # r7 = previous index
    a.label('scan')
    a.emit(0xE5953000)             # r3 = TextMenu vtable
    a.emit(0xE5933000 | move_vtable_off)  # r3 = direction move method
    a.emit(0xE1A00005)             # r0 = parent TextMenu
    a.emit(0xE12FFF33)             # virtual move(menu)
    a.emit(0xE1A00005)
    a.branch(MIYOOGAMELIST_DETAIL_SELECTED_INDEX_VA, link=True)
    a.emit(0xE1500007)             # cmp new,previous
    a.branch('restore', cond=0x0)
    a.emit(0xE1500006)             # wrapped to original?
    a.branch('done', cond=0x0)
    a.emit(0xE1A07000)
    a.emit(0xE5953000)
    a.emit(0xE5933014)             # TextMenu item getter
    a.emit(0xE1A01007)
    a.emit(0xE1A00005)
    a.emit(0xE12FFF33)
    a.emit(0xE1A08000)             # r8 = item
    a.emit(0xE3580000)             # cmp candidate item,#0
    a.branch('restore', cond=0x0)
    a.emit(0xE5982018)             # item action
    a.emit(0xE3520000)             # cmp candidate action,#0
    a.branch('accept', cond=0x0)
    a.emit(0xE5923004)             # Action type
    a.emit(0xE3530003)             # TYPE_APP has no folder field
    a.branch('accept', cond=0x0)
    a.emit(0xE5923058)             # GameAction folder flag
    a.emit(0xE3530000)             # cmp GameAction folder flag,#0
    a.branch('scan', cond=0x1)
    a.label('accept')
    a.emit(0xE1A02007)             # r2 = accepted raw index
    a.emit(0xE1A01008)             # r1 = accepted item
    a.emit(0xE1A00004)             # r0 = detail window
    a.branch(MIYOOGAMELIST_DETAIL_UPDATE_VA, link=True)
    a.branch('done')
    a.label('restore')
    a.emit(0xE1570006)
    a.branch('done', cond=0x0)
    a.label('restore_loop')
    a.emit(0xE5953000)
    a.emit(0xE5933000 | reverse_vtable_off)
    a.emit(0xE1A00005)
    a.emit(0xE12FFF33)
    a.emit(0xE1A00005)
    a.branch(MIYOOGAMELIST_DETAIL_SELECTED_INDEX_VA, link=True)
    a.emit(0xE1500007)
    a.branch('done', cond=0x0)
    a.emit(0xE1A07000)
    a.emit(0xE1570006)
    a.branch('restore_loop', cond=0x1)
    a.label('done')
    a.emit(0xE8BD81F0)             # pop {r4-r8,pc}
    return a.finish()


def build_game_detail_game_ordinal_entry(base_va: int) -> bytes:
    """Replace the raw row index with a zero-based non-folder ordinal.

    r4/r5 preserve the stock `this` and item arguments, r6 is the selected raw
    row, r7 is the parent menu, r8 is the scan index, and r10 counts games. The
    original function prologue is replayed after r2 has been rewritten.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D4FF8)             # push {r3-r11,lr}; 40 bytes
    a.emit(0xE1A04000)             # original self
    a.emit(0xE1A05001)             # original item
    a.emit(0xE1A06002)             # raw selected index
    a.emit(0xE1A00004)
    a.branch(GAME_DETAIL_RESOLVE_PARENT_VA, link=True)
    a.emit(0xE5947098)             # parent TextMenu
    a.emit(0xE3570000)             # cmp parent TextMenu,#0
    a.branch('replay', cond=0x0)
    a.emit(0xE3A08000)             # i = 0
    a.emit(0xE3A0A000)             # game count = 0
    a.label('loop')
    a.emit(0xE1580006)             # cmp i,raw
    a.branch('ordinal', cond=0x8)   # bhi
    a.emit(0xE5973000)             # r3 = TextMenu vtable
    a.emit(0xE5933014)             # r3 = item getter
    a.emit(0xE1A01008)             # r1 = scan index
    a.emit(0xE1A00007)             # r0 = parent TextMenu
    a.emit(0xE12FFF33)             # virtual item(menu,index)
    a.emit(0xE3500000)             # cmp item,#0
    a.branch('count', cond=0x0)     # null action/item behaves non-folder
    a.emit(0xE5902018)
    a.emit(0xE3520000)             # cmp action,#0
    a.branch('count', cond=0x0)
    a.emit(0xE5923004)             # Action type
    a.emit(0xE3530003)             # TYPE_APP has no folder field
    a.branch('count', cond=0x0)
    a.emit(0xE5923058)             # GameAction folder flag
    a.emit(0xE3530000)             # cmp GameAction folder flag,#0
    a.branch('next', cond=0x1)
    a.label('count')
    a.emit(0xE28AA001)             # game count++
    a.label('next')
    a.emit(0xE2888001)             # scan index++
    a.branch('loop')
    a.label('ordinal')
    a.emit(0xE35A0000)             # cmp game count,#0
    a.emit(0x124A2001)             # subne r2,r10,#1
    a.emit(0x03A02000)             # moveq r2,#0
    a.label('replay')
    a.emit(0xE1A00004)             # replay r0 = original self
    a.emit(0xE1A01005)             # replay r1 = original item
    a.emit(0xE8BD4FF8)             # restore scratch registers
    a.emit(0xE92D4870)             # replay stock push {r4-r6,r11,lr}
    a.branch(MIYOOGAMELIST_DETAIL_UPDATE_CONTINUE_VA)
    return a.finish()


def build_rom_parent_action_entry(base_va: int) -> bytes:
    """Return the stock close-current-window result for synthetic type-2 rows."""
    a = ArmBuilder(base_va)
    a.emit(0xE5903058)             # r3 = GameAction folder/type marker
    a.emit(0xE3530002)             # synthetic parent row uses marker 2
    a.emit(0x03A00001)             # return close-current-window result
    a.emit(0x012FFF1E)             # bxeq lr
    a.emit(0xE92D4870)             # replay stock push {r4-r6,r11,lr}
    a.branch(ROM_PARENT_ACTION_CONTINUE_VA)
    return a.finish()


def build_rom_parent_list_format_entry(
        base_va: int, snprintf_va: int,
        parent_binary_va: int, stock_binary_va: int,
        parent_nocase_va: int | None = None,
        stock_nocase_va: int | None = None) -> bytes:
    """Use stock indexed SQL at root; add ``..`` only in real subfolders.

    At the normal list call r3 is the table name and [sp] is ppath.  The
    synthetic-parent query consumes ppath first and table second, so nested
    folders still need the compact vararg swap used by the original patch.

    Root (ppath == ``.``) never emits ``..``.  In that common case restore
    MainUI's original simple query shape and original argument order so the
    browse index can satisfy WHERE+ORDER BY directly without the compound
    UNION/temporary-sort plan.  If runtime case sorting is active, preserve
    the already-selected BINARY/NOCASE collation when mapping back to the
    corresponding simple query.
    """
    if (parent_nocase_va is None) != (stock_nocase_va is None):
        raise ValueError('parent/root NOCASE query mapping must be complete')

    a = ArmBuilder(base_va)
    a.emit(0xE59DC000)             # ldr ip,[sp]      ; ppath char*
    a.emit(0xE5DCC000)             # ldrb ip,[ip]
    a.emit(0xE35C002E)             # cmp ip,#'.'
    a.branch('nested', cond=0x1)   # bne nested
    a.emit(0xE59DC000)             # ldr ip,[sp]
    a.emit(0xE5DCC001)             # ldrb ip,[ip,#1]
    a.emit(0xE35C0000)             # cmp ip,#0
    a.branch('nested', cond=0x1)   # bne nested

    # Root: only translate one of the exact parent-query pointers installed
    # by this patch.  Any unexpected query pointer falls back to the existing
    # nested formatter instead of guessing about its vararg contract.
    a.ldr_literal(12, parent_binary_va)
    a.emit(0xE152000C)             # cmp r2,ip
    a.branch('root_binary', cond=0x0)
    if parent_nocase_va is not None:
        a.ldr_literal(12, parent_nocase_va)
        a.emit(0xE152000C)         # cmp r2,ip
        a.branch('root_nocase', cond=0x0)
    a.branch('nested')

    a.label('root_binary')
    a.ldr_literal(2, stock_binary_va)
    a.branch(snprintf_va)          # root: stock argument order

    if parent_nocase_va is not None:
        a.label('root_nocase')
        a.ldr_literal(2, stock_nocase_va)
        a.branch(snprintf_va)      # root: stock NOCASE query/order

    a.label('nested')
    a.emit(0xE59DC000)             # ldr ip,[sp]
    a.emit(0xE58D3000)             # str r3,[sp]
    a.emit(0xE1A0300C)             # mov r3,ip
    a.branch(snprintf_va)           # nested: synthetic-parent query
    return a.finish()

def build_rom_parent_count_format_entry(
        base_va: int, snprintf_va: int,
        parent_count_va: int, root_count_va: int) -> bytes:
    """Restore the simple indexed COUNT query at ROM-list root.

    The ordinary COUNT formatter receives the table name in r3 and the ppath
    char pointer as the first stacked variadic argument.  Parent-folder SQL is
    only needed when ppath is a real subfolder; at ``.`` swap only the exact
    parent-query pointer back to the corresponding simple COUNT format.  The
    vararg order is identical, so no object or stack ownership changes.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE59DC000)             # ldr ip,[sp]      ; ppath char*
    a.emit(0xE5DCC000)             # ldrb ip,[ip]
    a.emit(0xE35C002E)             # cmp ip,#'.'
    a.branch('tail', cond=0x1)     # bne tail
    a.emit(0xE59DC000)             # ldr ip,[sp]
    a.emit(0xE5DCC001)             # ldrb ip,[ip,#1]
    a.emit(0xE35C0000)             # cmp ip,#0
    a.branch('tail', cond=0x1)     # bne tail
    a.ldr_literal(12, parent_count_va)
    a.emit(0xE152000C)             # cmp r2,ip
    a.branch('tail', cond=0x1)
    a.ldr_literal(2, root_count_va)
    a.label('tail')
    a.branch(snprintf_va)
    return a.finish()



def build_rom_parent_delete_count_adjust_entry(
        base_va: int, string_c_str_va: int) -> bytes:
    """Add the synthetic ``..`` row to deleteRow's post-delete size.

    Stock DBCachedTextMenu::deleteRow recounts physical SQLite rows and passes
    that number directly to ``setSize``.  ``add-parent-folder-to-rom-lists``
    adds one logical row only in non-root folders, so a successful delete would
    otherwise make the in-memory list one item too short until the system is
    reopened.  The caller's ``fp-0x18`` is the already-validated SQLite count
    and ``fp-0x28`` is the menu.  Its ppath std::string lives at +0x418; empty
    or exactly ``.`` is root and receives no adjustment.

    The helper replaces only ``ldr r1,[fp,#-0x18]`` immediately before stock
    ``setSize(this, r1)``.  It never changes the database, selected index,
    cache invalidation, or reload arguments.
    """
    a = ArmBuilder(base_va)
    # Six saved registers = 24 bytes, preserving 8-byte EABI alignment for the
    # std::string::c_str() call. r11 intentionally remains the caller's frame.
    a.emit(0xE92D403D)             # push {r0,r2-r5,lr}
    a.emit(0xE51B4018)             # r4 = stock DB row count [caller fp-0x18]
    a.emit(0xE51B3028)             # r3 = menu [caller fp-0x28]
    a.emit(0xE2830E41)             # r0 = menu + 0x410
    a.emit(0xE2800008)             # r0 = &menu->ppath (+0x418)
    a.branch(string_c_str_va, link=True)
    a.emit(0xE3500000)             # defensive NULL => root/no adjustment
    a.branch('done', cond=0x0)
    a.emit(0xE5D02000)             # first byte
    a.emit(0xE3520000)             # empty string => root
    a.branch('done', cond=0x0)
    a.emit(0xE352002E)             # '.' ?
    a.branch('nested', cond=0x1)
    a.emit(0xE5D02001)             # second byte
    a.emit(0xE3520000)             # exactly "." => root
    a.branch('done', cond=0x0)
    a.label('nested')
    a.emit(0xE2844001)             # logical rows = DB rows + synthetic '..'
    a.label('done')
    a.emit(0xE1A01004)             # stock destination register r1
    a.emit(0xE8BD403D)             # pop {r0,r2-r5,lr}; preserve r1 result
    a.emit(0xE12FFF1E)             # bx lr
    return a.finish()

def build_rom_list_count_entry_clear_helper(base_va: int,
                                                  folder_count_state_va: int) -> bytes:
    """Clear the normal-view folder count and replay ``add fp,sp,#8``.

    This runs immediately after the stock ``push {r4,fp,lr}``, before r0-r3
    are saved, so it uses only r4/r12 and restores r4 from its stack slot.
    Search/count variants that do not execute the normal ppath query therefore
    leave the state at zero instead of inheriting a previous ROM folder count.
    """
    a = ArmBuilder(base_va)
    a.ldr_literal(12, folder_count_state_va)
    a.emit(0xE3A04000)             # mov r4,#0
    a.emit(0xE58C4000)             # str r4,[r12]
    a.emit(0xE59D4000)             # restore caller r4 from saved stack slot
    a.emit(0xE28DB008)             # replay add fp,sp,#8
    a.emit(0xE12FFF1E)
    return a.finish()


def build_rom_list_count_columns_helper(base_va: int,
                                         folder_count_state_va: int) -> bytes:
    """Read total-row/folder columns from the normal ppath COUNT result.

    Input r0 is MainUI's SQLite result wrapper. Return column 0 (all rows) in
    r0 exactly as the displaced stock call did, preserving stock pagination.
    Retain column 1 (folder/non-game rows) solely for converting MainUI's raw
    physical ordinal and total at draw time.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D4070)             # push {r4-r6,lr}; aligned 16-byte frame
    a.emit(0xE1A04000)             # r4 = result wrapper
    a.emit(0xE3A01000)
    a.branch(ROM_LIST_COUNT_COLUMN_INT_VA, link=True)
    a.emit(0xE1A05000)             # r5 = stock total row count
    a.emit(0xE1A00004)
    a.emit(0xE3A01001)
    a.branch(ROM_LIST_COUNT_COLUMN_INT_VA, link=True)
    a.ldr_literal(6, folder_count_state_va)
    a.emit(0xE5860000)             # publish folder count
    a.emit(0xE1A00005)             # return stock total row count
    a.emit(0xE8BD8070)             # pop {r4-r6,pc}
    return a.finish()


def build_rom_list_count_publish_helper(
        base_va: int, folder_count_state_va: int,
        folder_map_state_va: int) -> bytes:
    """Publish COUNT(*) unchanged and associate its folder count with menu.

    This replaces the stock BL to ``0x3A9B0(menu,total)``.  The stock setter
    is still called with the exact original arguments.  A small fixed map
    retains the supplementary folder count by menu pointer, so returning from
    nested folders cannot reuse the last child's count.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}; aligned
    a.emit(0xE1A04000)             # r4 = menu
    a.emit(0xE1A05001)             # r5 = stock total
    a.ldr_literal(6, folder_count_state_va)
    a.emit(0xE5966000)             # r6 = supplementary folder count
    a.ldr_literal(7, folder_map_state_va)
    a.emit(0xE1A08007)             # r8 = map base
    a.emit(0xE3A03010)             # 16 entries
    a.label('scan')
    a.emit(0xE5972000)             # existing menu
    a.emit(0xE1520004)             # cmp r2,r4
    a.branch('store', cond=0x0)
    a.emit(0xE3520000)             # empty slot
    a.branch('store', cond=0x0)
    a.emit(0xE2877008)             # next pair
    a.emit(0xE2533001)             # subs r3,r3,#1
    a.branch('scan', cond=0x1)
    # Full map: replace round-robin entry. Cursor follows the 16 pairs.
    a.emit(0xE5982080)             # cursor @ map+128
    a.emit(0xE202200F)             # index &= 15
    a.emit(0xE0887182)             # r7 = base + index*8
    a.emit(0xE5982080)
    a.emit(0xE2822001)
    a.emit(0xE202200F)
    a.emit(0xE5882080)
    a.label('store')
    a.emit(0xE5874000)             # entry.menu = menu
    a.emit(0xE5876004)             # entry.folders = count
    a.emit(0xE1A00004)
    a.emit(0xE1A01005)
    a.branch(ROM_LIST_COUNT_SETTER_VA, link=True)
    a.emit(0xE8BD81F0)             # return stock setter result
    return a.finish()


def build_rom_list_game_counter_entry(
        base_va: int, game_list_state_va: int,
        precise_list_state_va: int | None = None,
        folder_mode_state_va: int | None = None,
        folder_count_state_va: int | None = None,
        folder_map_state_va: int | None = None,
        favourite_counter_stub_va: int | None = None) -> bytes:
    """Draw the live bottom-right list counter with game-only semantics.

    This wrapper replaces the BL at 0x31854, where r0 is the destination
    surface, r1 is MainUI's one-based physical ordinal and r2 is the physical
    row total.  It never alters the stock pagination total or the unrelated
    loading-progress globals at 0x18190c/0x181910.

    Favourite game rows use the sidecar core's packed logical result. Favourite
    folder rows draw their direct game count as one number. Ordinary ROM
    views subtract the separately retained leading folder count; stock SQL
    orders every type!=0 row before games. Invalid logical rows suppress the
    draw rather than showing a guessed value.
    """
    del game_list_state_va, precise_list_state_va
    mode_va = int(folder_mode_state_va or 0)
    folders_va = int(folder_count_state_va or 0)
    folder_map_va = int(folder_map_state_va or 0)
    fav_counter = int(favourite_counter_stub_va or 0)
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}; 24-byte aligned frame
    a.emit(0xE1A04000)             # r4 = destination SDL_Surface
    a.emit(0xE1A05001)             # r5 = physical current
    a.emit(0xE1A06002)             # r6 = physical total
    a.emit(0xE51B30F0)             # caller frame: window
    a.emit(0xE593800C)             # r8 = active menu
    if mode_va:
        a.ldr_literal(3, mode_va)
        a.emit(0xE3A02000)
        a.emit(0xE5832000)         # default to stock N/N format

    if fav_counter:
        a.ldr_literal(3, fav_counter)
        a.emit(0xE12FFF33)         # packed logical Favourite counter in r0
        a.emit(0xE1A08000)         # r8 = packed
        a.emit(0xE1A03F28)         # r3 = packed >> 30 (mode)
        a.emit(0xE3530000)
        a.branch('ordinary', cond=0x0)
        a.emit(0xE3530001)
        a.branch('fav_game', cond=0x0)
        a.emit(0xE3530002)
        a.branch('fav_folder', cond=0x0)
        # Mode 3 is suppress/invalid.
        a.branch('done')
        a.label('fav_game')
        a.emit(0xE1A05208)         # r5 = packed << 4
        a.emit(0xE1A05925)         # r5 = (packed >> 14) & 0x3fff
        a.emit(0xE1A06908)         # r6 = packed << 18
        a.emit(0xE1A06926)         # r6 = packed & 0x3fff
        a.emit(0xE3550000)
        a.emit(0x13560000)         # cmpne r6,#0
        a.branch('done', cond=0x0)
        a.branch('draw')
        a.label('fav_folder')
        a.emit(0xE1A06908)         # r6 = packed << 18
        a.emit(0xE1A06926)         # r6 = direct game count
        a.emit(0xE1A05006)         # single-number value
        if mode_va:
            a.ldr_literal(3, mode_va)
            a.emit(0xE3A02001)
            a.emit(0xE5832000)     # suppress the current/slash half of N/N
        a.branch('draw')
    else:
        a.branch('ordinary')

    a.label('ordinary')
    a.emit(0xE51B30F0)             # recover caller window after Favourite call
    a.emit(0xE593800C)             # r8 = active menu
    if folder_map_va:
        a.ldr_literal(7, folder_map_va)
        a.emit(0xE3A03010)         # 16 menu/count pairs
        a.label('map_scan')
        a.emit(0xE5972000)
        a.emit(0xE1520008)         # cmp entry.menu,r8
        a.branch('map_found', cond=0x0)
        a.emit(0xE2877008)
        a.emit(0xE2533001)
        a.branch('map_scan', cond=0x1)
        # No exact association: preserve stock display rather than guessing.
        a.branch('draw')
        a.label('map_found')
        a.emit(0xE5977004)         # r7 = exact leading folder count
    else:
        a.ldr_literal(7, folders_va)
        a.emit(0xE5977000)
    a.emit(0xE3570000)
    a.branch('draw', cond=0x0)
    a.emit(0xE1550007)
    a.branch('done', cond=0x9)     # selected physical row is a folder
    a.emit(0xE1560007)
    a.branch('done', cond=0x9)     # no games / inconsistent total
    a.emit(0xE0455007)             # game current = physical - folders
    a.emit(0xE0466007)             # game total = physical - folders
    a.emit(0xE1550006)
    a.branch('done', cond=0x8)     # game current > game total

    a.label('draw')
    a.emit(0xE1A00004)
    a.emit(0xE1A01005)
    a.emit(0xE1A02006)
    a.branch(ROM_LIST_COUNTER_DRAW_VA, link=True)
    if mode_va:
        a.ldr_literal(3, mode_va)
        a.emit(0xE3A02000)
        a.emit(0xE5832000)         # never leak single-number formatting
    a.label('done')
    a.emit(0xE8BD81F0)             # pop {r4-r8,pc}
    return a.finish()

def build_rom_list_counter_total_format_selector(
        base_va: int, folder_mode_state_va: int,
        folder_total_format_va: int) -> bytes:
    """Load stock ``%d`` or Favourite-folder ``(%d)`` total format."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D4008)             # push {r3,lr}; preserve total value in r3
    a.ldr_literal(2, ROM_LIST_COUNTER_STOCK_TOTAL_FORMAT_VA)
    a.ldr_literal(3, folder_mode_state_va)
    a.emit(0xE5933000)
    a.emit(0xE3530000)
    a.branch('done', cond=0x0)
    a.ldr_literal(2, folder_total_format_va)
    a.label('done')
    a.emit(0xE8BD4008)
    a.emit(0xE12FFF1E)
    return a.finish()


def build_rom_list_counter_format_selector(
        base_va: int, folder_mode_state_va: int,
        folder_format_va: int) -> bytes:
    """Load the stock current/slash format or an empty Favourite-folder one."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D4008)             # push {r3,lr}; r2 is the result
    a.ldr_literal(3, folder_mode_state_va)
    a.emit(0xE5933000)
    a.emit(0xE3530000)
    a.ldr_literal(2, ROM_LIST_COUNTER_STOCK_FORMAT_VA)
    a.branch('done', cond=0x0)
    a.ldr_literal(2, folder_format_va)
    a.label('done')
    a.emit(0xE8BD4008)
    a.emit(0xE12FFF1E)
    return a.finish()


def build_game_detail_folder_counter_guard(base_va: int) -> bytes:
    """Recompute the selected game's non-folder ordinal at draw time.

    This is deliberately independent of the Up/Down navigation hook: opening a
    detail page directly with Right reaches this draw path before any navigation
    update, which was the remaining folder-inclusive counter bug.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D47FF)             # push {r0-r10,lr}; 48 bytes
    a.emit(0xE51B4030)             # detail object
    a.emit(0xE3540000)
    a.branch('stock', cond=0x0)
    a.emit(0xE1A00004)
    a.branch(GAME_DETAIL_RESOLVE_PARENT_VA, link=True)
    a.emit(0xE5945098)             # parent TextMenu
    a.emit(0xE3550000)
    a.branch('stock', cond=0x0)
    a.emit(0xE1A00005)
    a.branch(MIYOOGAMELIST_DETAIL_SELECTED_INDEX_VA, link=True)
    a.emit(0xE1A06000)             # selected raw row
    a.emit(0xE5953000)
    a.emit(0xE5933020)             # virtual count
    a.emit(0xE1A00005)
    a.emit(0xE12FFF33)
    a.emit(0xE1560000)
    a.branch('stock', cond=0x2)    # selected >= count
    a.emit(0xE3A07000)             # i
    a.emit(0xE3A08000)             # non-folder count through selected
    a.label('loop')
    a.emit(0xE1570006)
    a.branch('ordinal', cond=0x8)  # i > selected
    a.emit(0xE5953000)
    a.emit(0xE5933014)             # item getter
    a.emit(0xE1A01007)
    a.emit(0xE1A00005)
    a.emit(0xE12FFF33)
    a.emit(0xE3500000)
    a.branch('game', cond=0x0)
    a.emit(0xE5902018)
    a.emit(0xE3520000)
    a.branch('game', cond=0x0)
    a.emit(0xE5923004)
    a.emit(0xE3530003)             # TYPE_APP has no folder field
    a.branch('game', cond=0x0)
    a.emit(0xE5923058)
    a.emit(0xE3530000)
    a.branch('game', cond=0x0)
    a.emit(0xE1570006)
    a.branch('skip', cond=0x0)     # selected parent row is a folder
    a.branch('next')
    a.label('game')
    a.emit(0xE2888001)
    a.label('next')
    a.emit(0xE2877001)
    a.branch('loop')
    a.label('ordinal')
    a.emit(0xE3580000)
    a.branch('stock', cond=0x0)
    a.emit(0xE2483001)
    a.emit(0xE5843078)             # zero-based game ordinal for stock draw
    a.label('stock')
    a.emit(0xE8BD47FF)
    a.emit(0xE30231BC)             # replay movw r3,#0x21bc
    a.branch(GAME_DETAIL_COUNTER_CONTINUE_VA)
    a.label('skip')
    a.emit(0xE8BD47FF)
    a.branch(GAME_DETAIL_COUNTER_SKIP_VA)
    return a.finish()


def build_game_detail_metadata_context(
        imports: dict[str, int], original_draw_va: int,
        string_vas: list[int], title_base_y: int,
        text_x: int, text_w: int, title_line_height_state_va: int) -> bytes:
    values = [
        imports['fopen'], imports['fclose'], imports['fseek'], imports['ftell'],
        imports['fread'], imports['malloc'], imports['calloc'], imports['free'],
        imports['strstr'], imports['strcasecmp'], imports['strlen'],
        imports['strrchr'], imports[CXX_STRING_C_STR],
        imports['TTF_RenderUTF8_Blended'], imports['SDL_FreeSurface'],
        imports['TTF_FontHeight'], imports['SDL_UpperBlit'],
        MIYOOGAMELIST_DETAIL_VECTOR_SIZE_VA, imports['SDL_PushEvent'],
        imports['gettimeofday'], imports['printf'], imports['__xstat'],
        original_draw_va,
        *string_vas, GAME_DETAIL_TEXT_COLOR_GLOBAL, title_base_y,
        text_x, text_w, title_line_height_state_va,
    ]
    blob = b''.join(struct.pack('<I', value & 0xFFFFFFFF) for value in values)
    if len(blob) != MIYOOGAMELIST_DETAIL_CONTEXT_SIZE:
        raise ValueError('game-detail metadata context size changed')
    return blob

