@dataclass(frozen=True)
class Segment:
    ph_index: int
    ph_file_off: int
    file_off: int
    vaddr: int
    file_size: int
    mem_size: int
    flags: int
    align: int


class ArmBuilder:
    """Small ARM-state assembler for fixed words, branches and literals."""
    def __init__(self, base_va: int):
        self.base = base_va
        self.words: list[int] = []
        self.labels: dict[str, int] = {}
        self.branch_fixups: list[tuple[int, str | int, int, bool]] = []
        self.literal_fixups: list[tuple[int, int, int]] = []

    @property
    def va(self) -> int:
        return self.base + len(self.words) * 4

    def emit(self, word: int) -> None:
        self.words.append(word & 0xFFFFFFFF)

    def label(self, name: str) -> None:
        if name in self.labels:
            raise ValueError(f'duplicate label {name}')
        self.labels[name] = self.va

    def branch(self, target: str | int, cond: int = 0xE, link: bool = False) -> None:
        idx = len(self.words)
        self.words.append(0)
        self.branch_fixups.append((idx, target, cond, link))

    def ldr_literal(self, rd: int, value: int) -> None:
        idx = len(self.words)
        self.words.append(0)
        self.literal_fixups.append((idx, rd, value & 0xFFFFFFFF))

    def finish(self) -> bytes:
        # Append one literal per use. Later literals do not move earlier ones.
        for idx, rd, value in self.literal_fixups:
            lit_va = self.base + len(self.words) * 4
            instr_va = self.base + idx * 4
            delta = lit_va - (instr_va + 8)
            if not 0 <= delta <= 0xFFF:
                raise ValueError('literal outside ARM LDR range')
            self.words[idx] = 0xE59F0000 | (rd << 12) | delta
            self.words.append(value)
        for idx, target, cond, link in self.branch_fixups:
            dst = self.labels[target] if isinstance(target, str) else target
            src = self.base + idx * 4
            self.words[idx] = branch_word(src, dst, cond=cond, link=link)
        return b''.join(struct.pack('<I', w) for w in self.words)


def align_up(value: int, alignment: int = 4) -> int:
    if alignment <= 0 or alignment & (alignment - 1):
        raise ValueError(f'alignment must be a positive power of two, got {alignment}')
    return (value + alignment - 1) & ~(alignment - 1)


def branch_word(src_va: int, dst_va: int, cond: int = 0xE, link: bool = False) -> int:
    delta = dst_va - (src_va + 8)
    if delta % 4:
        raise ValueError(f'unaligned branch {src_va:#x}->{dst_va:#x}')
    words = delta // 4
    if not -(1 << 23) <= words < (1 << 23):
        raise ValueError(f'branch outside ARM range {src_va:#x}->{dst_va:#x}')
    return ((cond & 0xF) << 28) | (0x0B000000 if link else 0x0A000000) | (words & 0xFFFFFF)



def segments(data: bytes) -> tuple[list[Segment], int, int]:
    if data[:4] != b'\x7fELF' or data[4] != 1 or data[5] != 1:
        raise ValueError('expected ELF32 little-endian')
    phoff = struct.unpack_from('<I', data, 0x1C)[0]
    entsize = struct.unpack_from('<H', data, 0x2A)[0]
    count = struct.unpack_from('<H', data, 0x2C)[0]
    out: list[Segment] = []
    for index in range(count):
        p = phoff + index * entsize
        typ, off, va, _pa, fsz, msz, flags, align = struct.unpack_from('<8I', data, p)
        if typ == 1:
            out.append(Segment(index, p, off, va, fsz, msz, flags, align))
    return out, phoff, entsize


def validate_final_elf_layout(data: bytes | bytearray) -> None:
    'Re-parse the completed ELF and fail closed on unsafe segment metadata.'
    if data[:4] != b'\x7fELF' or data[4] != 1 or data[5] != 1:
        raise ValueError('final output is not ELF32 little-endian')
    phoff = struct.unpack_from('<I', data, 0x1C)[0]
    entsize = struct.unpack_from('<H', data, 0x2A)[0]
    count = struct.unpack_from('<H', data, 0x2C)[0]
    entry = struct.unpack_from('<I', data, 0x18)[0]
    if entsize < 32 or phoff + count * entsize > len(data):
        raise ValueError('final ELF program-header table is out of file bounds')

    loads: list[tuple[int, int, int, int, int, int, int]] = []
    stack_seen = False
    for index in range(count):
        p = phoff + index * entsize
        typ, off, va, _pa, fsz, msz, flags, align = struct.unpack_from('<8I', data, p)
        if typ == 0x6474E551:
            stack_seen = True
            if flags & 1:
                raise ValueError('final GNU_STACK unexpectedly executable')
        if typ != 1:
            continue
        if fsz > msz:
            raise ValueError(f'final PT_LOAD {index} has filesz > memsz')
        if off > len(data) or fsz > len(data) - off:
            raise ValueError(f'final PT_LOAD {index} exceeds output file')
        if flags & 2 and flags & 1:
            raise ValueError(f'final PT_LOAD {index} is writable and executable')
        if align not in (0, 1):
            if align & (align - 1):
                raise ValueError(f'final PT_LOAD {index} has non-power-of-two alignment')
            if off % align != va % align:
                raise ValueError(f'final PT_LOAD {index} offset/VA alignment mismatch')
        loads.append((index, off, va, fsz, msz, flags, align))
    if not stack_seen:
        raise ValueError('final ELF has no GNU_STACK program header')
    if not loads:
        raise ValueError('final ELF has no PT_LOAD segments')
    if not any((flags & 1) and va <= entry < va + msz
               for _i, _o, va, _f, msz, flags, _a in loads):
        raise ValueError('final ELF entry point is outside executable PT_LOAD')

    by_va = sorted(loads, key=lambda item: item[2])
    for left, right in zip(by_va, by_va[1:]):
        if left[2] + left[4] > right[2]:
            raise ValueError(
                f'final PT_LOAD virtual ranges overlap: {left[0]} and {right[0]}')



def _arm_immediate_value(word: int) -> int:
    """Decode ARM data-processing immediate imm12 (8-bit value + rotate)."""
    imm8 = word & 0xFF
    rotate = ((word >> 8) & 0xF) * 2
    if rotate == 0:
        return imm8
    return ((imm8 >> rotate) | (imm8 << (32 - rotate))) & 0xFFFFFFFF


def _is_arm_push(word: int) -> bool:
    return (word & 0x0FFF0000) == 0x092D0000  # stmdb sp!,{...}


def _is_arm_pop(word: int) -> bool:
    return (word & 0x0FFF0000) == 0x08BD0000  # ldmia sp!,{...}


def _is_arm_call(word: int) -> bool:
    # ARM BL immediate or BLX register. The appended payload is ARM-state code.
    return ((word & 0x0F000000) == 0x0B000000 or
            (word & 0x0FFFFFF0) == 0x012FFF30)


def _is_unconditional_arm_branch(word: int) -> bool:
    return (word & 0xFF000000) == 0xEA000000


def validate_appended_rx_stack_call_alignment(
        data: bytes | bytearray, payload_off: int, payload_va: int,
        payload_size: int) -> None:
    """Cheap AAPCS guard for odd PUSHes in the appended ARM payload.

    A public ARM call boundary requires an 8-byte aligned SP. Scan every odd
    register-count PUSH and follow its straight-line basic block, accounting for
    further PUSH/POP and immediate ADD/SUB adjustments to SP. Any BL/BLX reached
    while SP is provably 4-byte misaligned is rejected. We stop at an
    unconditional branch because proving alignment across a full CFG would turn
    this inexpensive post-build guard into a substantially heavier analysis.
    """
    end = payload_off + payload_size
    if payload_off < 0 or payload_size < 0 or end > len(data):
        raise ValueError('appended-RX stack audit range is outside output')
    for off in range(payload_off, end - 3, 4):
        word = read_word(data, off)
        if not _is_arm_push(word):
            continue
        count = (word & 0xFFFF).bit_count()
        if not (count & 1):
            continue
        sp_mod8 = (-4 * count) & 7
        # The concern is a hand-written odd PUSH followed by a nested call in
        # the same basic block. 64 instructions is ample for the existing
        # prologues while keeping the audit tiny.
        for probe in range(off + 4, min(end, off + 4 * 65), 4):
            current = read_word(data, probe)
            if _is_arm_push(current):
                sp_mod8 = (sp_mod8 - 4 * (current & 0xFFFF).bit_count()) & 7
            elif _is_arm_pop(current):
                sp_mod8 = (sp_mod8 + 4 * (current & 0xFFFF).bit_count()) & 7
                break
            elif (((current >> 25) & 0x7) == 0x1 and
                  ((current >> 16) & 0xF) == 13 and
                  ((current >> 12) & 0xF) == 13):
                opcode = (current >> 21) & 0xF
                if opcode in (2, 4):  # SUB/ADD sp,sp,#imm
                    amount = _arm_immediate_value(current) & 7
                    if opcode == 2:
                        sp_mod8 = (sp_mod8 - amount) & 7
                    else:
                        sp_mod8 = (sp_mod8 + amount) & 7
            if _is_arm_call(current) and sp_mod8:
                push_va = payload_va + off - payload_off
                call_va = payload_va + probe - payload_off
                raise ValueError(
                    'appended-RX AAPCS stack misalignment: odd PUSH at '
                    f'{push_va:#x} reaches call {call_va:#x} with SP mod 8 = '
                    f'{sp_mod8}')
            if _is_unconditional_arm_branch(current):
                break


def validate_documented_stack_asymmetry_patterns(
        data: bytes | bytearray, payload_off: int, payload_va: int,
        payload_size: int, *, require_complete: bool) -> None:
    """Pin the three intentional push/pop asymmetries in the generated payload.

    Two wrappers manually reload saved r0, discard its slot, then pop the
    remaining registers. A third large wrapper similarly discards the saved r0
    slot before a pop that omits r0. These are deliberate exceptions to a
    future generic push/pop symmetry check; fail if their exact balancing
    sequences disappear or multiply unexpectedly.
    """
    end = payload_off + payload_size
    short_sites: list[int] = []
    long_sites: list[int] = []
    for off in range(payload_off, end - 3, 4):
        word = read_word(data, off)
        if word == 0xE92D4013 and off + 28 < end:
            if (read_word(data, off + 20) == 0xE59D0000 and
                    read_word(data, off + 24) == 0xE28DD004 and
                    read_word(data, off + 28) == 0xE8BD4012):
                short_sites.append(payload_va + off - payload_off)
        elif word == 0xE92D5FFF and off + 0x88 < end:
            if (read_word(data, off + 4) == 0xE24DD008 and
                    read_word(data, off + 8) == 0xE58DC000 and
                    read_word(data, off + 0x80) == 0xE1A00004 and
                    read_word(data, off + 0x84) == 0xE28DD004 and
                    read_word(data, off + 0x88) == 0xE8BD5FFE):
                long_sites.append(payload_va + off - payload_off)
    if len(short_sites) > 2 or len(long_sites) > 1:
        raise ValueError(
            'documented appended-RX push/pop asymmetry set grew unexpectedly: '
            f'short={list(map(hex, short_sites))}, '
            f'long={list(map(hex, long_sites))}')
    if require_complete and (len(short_sites) != 2 or len(long_sites) != 1):
        raise ValueError(
            'integrated appended-RX push/pop asymmetry set changed: '
            f'short={list(map(hex, short_sites))}, '
            f'long={list(map(hex, long_sites))}')


def validate_new_bss_literal_bounds(
        data: bytes | bytearray, payload_off: int, payload_va: int,
        payload_size: int, data_va: int, data_size: int) -> None:
    """Reject appended-payload literals that point just beyond new BSS.

    New patch state occupies [data_va, data_va+data_size). The next patch-owned
    virtual area is the appended RX segment at payload_va. Any aligned literal
    in that intervening address band is therefore intended to refer to new
    writable state; values at or beyond the allocated BSS end are invalid.
    This cheap check caught the important zero-slack condition without doing a
    full register/data-flow analysis on every load/store.
    """
    if data_size <= 0:
        return
    data_end = data_va + data_size
    if data_end > payload_va:
        raise ValueError('new BSS overlaps appended RX virtual address range')
    end = payload_off + payload_size
    highest = None
    for off in range(payload_off, end - 3, 4):
        value = read_word(data, off)
        if data_va <= value < payload_va:
            if value >= data_end:
                literal_va = payload_va + off - payload_off
                raise ValueError(
                    f'appended-RX literal {literal_va:#x} points beyond new '
                    f'BSS: {value:#x} >= {data_end:#x}')
            highest = value if highest is None else max(highest, value)
    if highest is not None and highest + 4 > data_end:
        raise ValueError('highest new-BSS state literal overruns writable state')


def _direct_arm_branch_target_from_blob(
        code: bytes, base_va: int, offset: int) -> int | None:
    if offset < 0 or offset + 4 > len(code):
        return None
    word = struct.unpack_from('<I', code, offset)[0]
    if (word & 0x0E000000) != 0x0A000000:
        return None
    return decode_arm_branch_target(word, base_va + offset)


def validate_dynamic_symbol_fail_open_guards(
        *, clip_wrapper_code: bytes | None, clip_wrapper_va: int | None,
        clip_resolver_va: int | None, preview_code: bytes | None,
        preview_va: int | None, dlsym_va: int | None) -> None:
    """Pin the cheap null-guard structure around all four dlsym APIs."""
    if clip_wrapper_code:
        if clip_wrapper_va is None or clip_resolver_va is None:
            raise ValueError('clip-wrapper symbol audit is missing addresses')
        hits = []
        for off in range(0, len(clip_wrapper_code) - 20, 4):
            if _direct_arm_branch_target_from_blob(
                    clip_wrapper_code, clip_wrapper_va, off) == clip_resolver_va:
                hits.append(off)
        if len(hits) != 1:
            raise ValueError('SDL clip resolver call count changed')
        off = hits[0]
        words = [struct.unpack_from('<I', clip_wrapper_code, off + i * 4)[0]
                 for i in range(1, 5)]
        if not (words[0] == 0xE3500000 and
                (words[1] & 0xFF000000) == 0x0A000000 and
                words[2] == 0xE3510000 and
                (words[3] & 0xFF000000) == 0x0A000000):
            raise ValueError(
                'SDL_GetClipRect/SDL_SetClipRect independent NULL guards changed')

    if preview_code:
        if preview_va is None or dlsym_va is None:
            raise ValueError('preview dlsym audit is missing addresses')
        calls: list[int] = []
        for off in range(0, len(preview_code) - 16, 4):
            if _direct_arm_branch_target_from_blob(
                    preview_code, preview_va, off) == dlsym_va:
                calls.append(off)
        if len(calls) != 2:
            raise ValueError(
                f'SDL_LockSurface/SDL_UnlockSurface dlsym call count changed: '
                f'{len(calls)}')
        expected_stores = (0xE588002C, 0xE5880030)
        for off, store in zip(calls, expected_stores):
            words = [struct.unpack_from('<I', preview_code, off + i * 4)[0]
                     for i in range(1, 4)]
            if not (words[0] == store and words[1] == 0xE3500000 and
                    (words[2] & 0xFF000000) == 0x0A000000):
                raise ValueError(
                    'SDL_LockSurface/SDL_UnlockSurface NULL guard changed')


def off2va(segs: list[Segment], off: int) -> int:
    for seg in segs:
        if seg.file_off <= off < seg.file_off + seg.file_size:
            return seg.vaddr + off - seg.file_off
    raise ValueError(f'file offset {off:#x} outside file-backed PT_LOAD')


def va2off(segs: list[Segment], va: int, *, executable: bool = False) -> int:
    """Convert a file-backed virtual address to its file offset."""
    for seg in segs:
        if executable and not (seg.flags & 1):
            continue
        if seg.vaddr <= va < seg.vaddr + seg.file_size:
            return seg.file_off + va - seg.vaddr
    kind = ' executable' if executable else ''
    raise ValueError(f'virtual address {va:#x} outside file-backed{kind} PT_LOAD')


def unique(data: bytes | bytearray, sig: bytes, label: str) -> int:
    first = data.find(sig)
    if first < 0:
        raise ValueError(f'{label}: signature not found')
    if data.find(sig, first + 1) >= 0:
        raise ValueError(f'{label}: signature not unique')
    return first


def find_all(data: bytes | bytearray, sig: bytes) -> list[int]:
    """Return every non-overlapping occurrence of ``sig``."""
    out: list[int] = []
    start = 0
    while True:
        off = data.find(sig, start)
        if off < 0:
            return out
        out.append(off)
        start = off + max(1, len(sig))


def read_word(data: bytes | bytearray, off: int) -> int:
    return struct.unpack_from('<I', data, off)[0]


def write_word(data: bytearray, off: int, word: int) -> None:
    struct.pack_into('<I', data, off, word & 0xFFFFFFFF)


def parse_sections(data: bytes) -> dict[str, tuple[int, int, int, int, int, int]]:
    """Return name -> (file_off, vaddr, size, entsize, link, info)."""
    shoff = struct.unpack_from('<I', data, 0x20)[0]
    shentsize = struct.unpack_from('<H', data, 0x2E)[0]
    shnum = struct.unpack_from('<H', data, 0x30)[0]
    shstrndx = struct.unpack_from('<H', data, 0x32)[0]
    headers = [struct.unpack_from('<10I', data, shoff + i * shentsize) for i in range(shnum)]
    shstr = headers[shstrndx]
    strings = data[shstr[4]:shstr[4] + shstr[5]]

    def cstr(blob: bytes, start: int) -> str:
        end = blob.find(b'\0', start)
        return blob[start:end].decode('ascii')

    result = {}
    for h in headers:
        result[cstr(strings, h[0])] = (h[4], h[3], h[5], h[9], h[6], h[7])
    return result


def all_plt_addresses(data: bytes) -> dict[str, int]:
    """Return every dynamic PLT symbol name mapped to its ARM PLT entry."""
    secs = parse_sections(data)
    for required in ('.plt', '.rel.plt', '.dynsym', '.dynstr'):
        if required not in secs:
            raise ValueError(f'missing ELF section {required}')
    _plt_off, plt_va, _plt_size, _plt_ent, _l, _i = secs['.plt']
    rel_off, _rel_va, rel_size, rel_ent, _l, _i = secs['.rel.plt']
    sym_off, _sym_va, _sym_size, sym_ent, _l, _i = secs['.dynsym']
    str_off, _str_va, str_size, _str_ent, _l, _i = secs['.dynstr']
    dynstr = data[str_off:str_off + str_size]
    out: dict[str, int] = {}
    count = rel_size // rel_ent
    for idx in range(count):
        _r_offset, r_info = struct.unpack_from('<II', data, rel_off + idx * rel_ent)
        sym_index = r_info >> 8
        st_name = struct.unpack_from('<I', data, sym_off + sym_index * sym_ent)[0]
        end = dynstr.find(b'\0', st_name)
        name = dynstr[st_name:end].decode('ascii')
        # ARM GNU PLT: 20-byte resolver header, then 12-byte entries.
        out[name] = plt_va + 20 + idx * 12
    return out


class ImportAddressMap(dict[str, int]):
    """PLT addresses with a useful error for undeclared patch dependencies."""

    def __missing__(self, key: str) -> int:
        raise ValueError(
            f"internal patch dependency error: import {key!r} is required by "
            "the selected patch combination but was not requested")


def plt_addresses(data: bytes, wanted: set[str]) -> dict[str, int]:
    available = all_plt_addresses(data)
    missing = wanted - available.keys()
    if missing:
        raise ValueError(f'missing required imports: {sorted(missing)}')
    return {name: available[name] for name in wanted}


class GapAllocator:
    def __init__(self, start_off: int, start_va: int, limit_off: int):
        self.off = align_up(start_off, 4)
        self.va = start_va + (self.off - start_off)
        self.limit = limit_off
        self.start_off = self.off
        self.start_va = self.va

    def alloc(self, size: int, alignment: int = 4) -> tuple[int, int]:
        new_off = align_up(self.off, alignment)
        new_va = self.va + (new_off - self.off)
        end = new_off + size
        if end > self.limit:
            raise ValueError(f'injected code exceeds executable/file gap by {end - self.limit} bytes')
        self.off = end
        self.va = new_va + size
        return new_off, new_va


def validate_arm_builder_allocator_models() -> None:
    'Self-tests for shared ARM branch/literal assembly and finite-gap allocation.'
    for src, dst, cond, link in (
            (0x1000, 0x1008, 0xE, False),
            (0x1000, 0x0FF0, 0x1, True),
            (0x200000, 0x200000 + 8 + ((1 << 23) - 1) * 4, 0xE, False),
            (0x200000, 0x200000 + 8 - (1 << 23) * 4, 0xE, True)):
        word = branch_word(src, dst, cond=cond, link=link)
        if decode_arm_branch_target(word, src) != dst:
            raise ValueError(f'ARM branch round-trip regression {src:#x}->{dst:#x}')
        if (word >> 28) != cond or bool(word & 0x01000000) != link:
            raise ValueError('ARM branch condition/link encoding regression')
        if link:
            if decode_arm_branch_target(
                    word ^ 0x01000000, src, expected_link=True) is not None:
                raise ValueError('ARM BL link-bit guard regression')
        else:
            if decode_arm_branch_target(
                    word ^ 0x01000000, src, expected_link=False) is not None:
                raise ValueError('ARM B link-bit guard regression')
    for src, dst in ((0x1000, 0x1009),
                     (0x200000, 0x200000 + 8 + (1 << 23) * 4),
                     (0x200000, 0x200000 + 8 - ((1 << 23) + 1) * 4)):
        try:
            branch_word(src, dst)
        except ValueError:
            pass
        else:
            raise ValueError('invalid ARM branch was accepted')

    builder = ArmBuilder(0x4000)
    builder.label('start')
    builder.ldr_literal(2, 0x12345678)
    builder.branch('start')
    code = builder.finish()
    if len(code) != 12 or read_word(code, 8) != 0x12345678:
        raise ValueError('ARM literal-pool assembly regression')
    if decode_arm_branch_target(read_word(code, 4), 0x4004) != 0x4000:
        raise ValueError('ARM label branch assembly regression')
    duplicate = ArmBuilder(0)
    duplicate.label('x')
    try:
        duplicate.label('x')
    except ValueError:
        pass
    else:
        raise ValueError('duplicate ARM label was accepted')

    completion = build_preview_completion_scheduler(
        0x3000, 0x9000, 0x5000, 0x6000, 0x7000)
    if len(completion) != 104:
        raise ValueError('preview completion scheduler size regression')
    if read_word(completion, 12) != 0xE5943000 or read_word(
            completion, 16) != 0xE2833001 or read_word(
            completion, 20) != 0xE5843000:
        raise ValueError('preview completion generation publication regression')
    mid_draw = build_preview_mid_draw_refresh_wrapper(
        0x4000, 0x9000, GAME_LIST_PREVIEW_REFRESH_VA,
        GAME_LIST_COVER_CHECK_CONTINUE_VA)
    if len(mid_draw) != 68:
        raise ValueError('preview mid-draw wrapper size regression')
    if read_word(mid_draw, 28) != 0xE5850004:
        raise ValueError('preview consumed-generation publication regression')
    if decode_arm_branch_target(read_word(mid_draw, 48), 0x4030) != (
            GAME_LIST_PREVIEW_REFRESH_VA):
        raise ValueError('preview updater branch regression')
    if read_word(mid_draw, 56) != GAME_LIST_COVER_CHECK_STOCK_WORD:
        raise ValueError('preview cover-check displaced instruction regression')
    if decode_arm_branch_target(read_word(mid_draw, 60), 0x403C) != (
            GAME_LIST_COVER_CHECK_CONTINUE_VA):
        raise ValueError('preview cover-check continuation regression')

    allocator = GapAllocator(0x101, 0x1001, 0x130)
    off1, va1 = allocator.alloc(4, 4)
    off2, va2 = allocator.alloc(8, 8)
    if (off1, va1) != (0x104, 0x1004) or (off2, va2) != (0x108, 0x1008):
        raise ValueError('gap allocator alignment regression')
    exact = GapAllocator(0x100, 0x2000, 0x110)
    exact.alloc(16, 4)
    try:
        exact.alloc(1, 1)
    except ValueError:
        pass
    else:
        raise ValueError('gap allocator accepted one-byte overflow')
    for bad_alignment in (0, 3, 6):
        try:
            align_up(5, bad_alignment)
        except ValueError:
            pass
        else:
            raise ValueError(f'invalid alignment was accepted: {bad_alignment}')


def require_exact_code_size(code: bytes, expected: int, label: str) -> None:
    """Guard exact-size allocations against accidental helper growth."""
    if len(code) != expected:
        raise ValueError(
            f'{label} emitted {len(code)} bytes; exact allocation is {expected}')


def build_get_rows(base_va: int, data_va: int, path_va: int,
                   open_va: int, read_va: int, close_va: int, atoi_va: int) -> bytes:
    """Read the configured path once; cache rows, height and SDL_Rect.h."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}; SP remains 8-byte aligned
    a.ldr_literal(4, data_va)       # r4 = cache
    a.emit(0xE5940000)             # ldr r0,[r4] rows/sentinel
    a.emit(0xE3500000)             # cmp r0,#0
    a.branch('done', cond=0x1)     # bne done
    a.emit(0xE3A05006)             # mov r5,#6 default

    # Read the one configured path.
    a.ldr_literal(0, path_va)
    a.emit(0xE3A01000)             # mov r1,#O_RDONLY
    a.branch(open_va, link=True)
    a.emit(0xE1A06000)             # mov r6,r0 fd
    a.emit(0xE3560000)             # cmp r6,#0
    a.branch('calculate', cond=0xB) # blt calculate

    # Buffer is initially zero because it is newly extended BSS. Read at most
    # 12 bytes, leaving at least four zero bytes for atoi termination.
    a.emit(0xE1A00006)             # mov r0,r6
    a.emit(0xE2841010)             # add r1,r4,#16 buffer
    a.emit(0xE3A0200C)             # mov r2,#12
    a.branch(read_va, link=True)
    a.emit(0xE1A07000)             # mov r7,r0 bytes read
    a.emit(0xE1A00006)             # mov r0,r6
    a.branch(close_va, link=True)
    a.emit(0xE3570000)             # cmp r7,#0
    a.branch('calculate', cond=0xD) # ble calculate
    a.emit(0xE2840010)             # add r0,r4,#16
    a.branch(atoi_va, link=True)
    a.emit(0xE1A05000)             # mov r5,r0
    a.emit(0xE3550006)             # cmp r5,#6
    a.emit(0xB3A05006)             # movlt r5,#6
    a.emit(0xE3550014)             # cmp r5,#20
    a.emit(0xC3A05014)             # movgt r5,#20

    a.label('calculate')
    # floor(360 / rows), one-time repeated subtraction (18..60 iterations).
    a.emit(0xE3A06000)             # mov r6,#0 quotient
    a.emit(0xE3007168)             # movw r7,#360
    a.label('divloop')
    a.emit(0xE1570005)             # cmp r7,r5
    a.branch('divdone', cond=0xB)  # blt divdone
    a.emit(0xE0477005)             # sub r7,r7,r5
    a.emit(0xE2866001)             # add r6,r6,#1
    a.branch('divloop')
    a.label('divdone')
    a.emit(0xE5846004)             # str r6,[r4,#4] height
    a.emit(0xE1C460BE)             # strh r6,[r4,#14] SDL_Rect.h
    a.emit(0xE5845000)             # str r5,[r4] rows last (sentinel)
    a.emit(0xE1A00005)             # mov r0,r5
    a.label('done')
    a.emit(0xE8BD81F0)             # pop {r4-r8,pc}
    return a.finish()


def build_game_list_bg_loader_wrapper(
        base_va: int, data_va: int, get_rows_va: int,
        full_path_buffer_va: int, path_table_va: int, format_va: int,
        open_va: int, close_va: int, snprintf_va: int,
        original_loader_va: int) -> bytes:
    """Load bg-list-s_N.png only for tagged ROM/Favourites/Recent lists.

    The shared TextMenu constructor reaches this wrapper before its row-height
    hook consumes the one-shot pending game-list marker at data+0x3c. For those
    tagged constructors, probe only the active theme prefix for the numbered
    asset. If it is absent (or fails to decode), call MainUI's stock loader with
    the original bg-list-s.png arguments. Non-game TextMenu users go straight
    through the exact stock call.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}; keep 8-byte alignment
    a.emit(0xE1A04000)             # r4 = active-theme prefix (stock r0)
    a.emit(0xE1A05001)             # r5 = stock fallback prefix (stock r1)
    a.emit(0xE1A06002)             # r6 = stock bg-list-s.png path (stock r2)
    a.emit(0xE1A07003)             # r7 = stock log/debug argument (stock r3)
    a.emit(0xE51B8010)             # r8 = caller TextMenu object [fp,#-0x10]
    a.ldr_literal(12, data_va)
    a.emit(0xE59CC03C)             # ip = pending tagged game-list object
    a.emit(0xE158000C)             # cmp r8,ip
    a.branch('stock', cond=0x1)     # non-game TextMenu -> exact stock loader

    a.branch(get_rows_va, link=True)
    a.emit(0xE2400006)             # rows 6..20 -> table index 0..14
    a.ldr_literal(2, path_table_va)
    a.emit(0xE0822100)             # add r2,r2,r0,lsl#2
    a.emit(0xE5928000)             # r8 = numbered relative path

    # Build the active-theme absolute path only for the existence probe.
    # snprintf(buf, 256, "%s%s", theme_prefix, numbered_relative_path)
    a.emit(0xE24DD008)             # sub sp,sp,#8; fifth arg + alignment
    a.emit(0xE58D8000)             # fifth arg = numbered relative path
    a.ldr_literal(0, full_path_buffer_va)
    a.emit(arm_movw(1, GAME_LIST_BG_FULL_PATH_BUFFER_SIZE))
    a.ldr_literal(2, format_va)
    a.emit(0xE1A03004)             # r3 = active-theme prefix
    a.branch(snprintf_va, link=True)
    a.emit(0xE28DD008)
    a.emit(0xE3500000)             # snprintf < 0 -> fallback
    a.branch('stock', cond=0xB)
    a.emit(0xE35000FF)             # 255 chars max before terminator
    a.branch('stock', cond=0xC)     # signed >255 -> truncated/fallback

    # Probe only the current theme. Do not let a numbered asset in MainUI's
    # generic ./skin fallback directory override the requested stock fallback.
    a.ldr_literal(0, full_path_buffer_va)
    a.emit(0xE3A01000)             # O_RDONLY
    a.branch(open_va, link=True)
    a.emit(0xE3500000)
    a.branch('stock', cond=0xB)     # fd < 0: numbered file absent
    a.branch(close_va, link=True)   # r0 is still the fd

    # The numbered file exists in the active theme. Use the active-theme prefix
    # for both loader prefixes so decode failure cannot select ./skin/_N.
    a.emit(0xE24DD008)
    a.emit(0xE3A0C000)
    a.emit(0xE58DC000)             # stock fifth argument = 0
    a.emit(0xE1A00004)
    a.emit(0xE1A01004)
    a.emit(0xE1A02008)
    a.emit(0xE1A03007)
    a.branch(original_loader_va, link=True)
    a.emit(0xE28DD008)
    a.emit(0xE3500000)
    a.branch('done', cond=0x1)      # valid numbered surface

    a.label('stock')
    a.emit(0xE24DD008)
    a.emit(0xE3A0C000)
    a.emit(0xE58DC000)             # stock fifth argument = 0
    a.emit(0xE1A00004)
    a.emit(0xE1A01005)
    a.emit(0xE1A02006)
    a.emit(0xE1A03007)
    a.branch(original_loader_va, link=True)
    a.emit(0xE28DD008)
    a.label('done')
    a.emit(0xE8BD81F0)             # pop {r4-r8,pc}; surface in r0
    return a.finish()


def build_popup_selection_background_wrapper(
        base_va: int, custom_path_va: int, original_loader_va: int,
        free_surface_va: int) -> bytes:
    """Optionally replace a PopupWindow child TextMenu selection surface.

    This helper runs from PopupWindow's constructor after stock has already
    loaded/stored the ordinary selection background and attached the child menu.
    It tries the active theme's ``skin/bg-list-popup-s.png`` using the active-theme
    prefix for both loader prefixes, so there is no generic/default-skin fallback
    for the optional asset.  A missing or undecodable custom surface therefore
    leaves the existing TextMenu surface untouched.  On success the old private
    TextMenu surface is freed and the custom surface becomes normal menu-owned
    state, so the stock destructor later frees exactly one surface.

    The overwritten stock instruction (``ldr r3,[fp,#-0x18]``) is replayed before
    return so PopupWindow construction resumes byte-for-byte at the next site.
    """
    a = ArmBuilder(base_va)
    # Six saved registers = 24 bytes, preserving 8-byte AAPCS alignment at BLs.
    a.emit(0xE92D41F0)             # push {r4-r8,lr}
    a.emit(0xE51B4020)             # r4 = child menu [fp,#-0x20]
    a.emit(0xE3540000)             # cmp r4,#0
    a.branch('done', cond=0x0)      # no child menu -> stock continuation
    a.emit(0xE594504C)             # r5 = existing TextMenu selection surface

    # MainUI's stock skin loader arguments mirror PopupWindow's own background
    # load. Use the active-theme prefix for both prefixes so only the current
    # theme can satisfy the optional asset.
    a.ldr_literal(6, POPUP_SELECTION_BACKGROUND_ACTIVE_THEME_GLOBAL_VA)
    a.emit(0xE5960000)             # r0 = active-theme prefix
    a.emit(0xE1A01000)             # r1 = same active-theme prefix
    a.ldr_literal(2, custom_path_va)
    a.ldr_literal(7, POPUP_SELECTION_BACKGROUND_LOG_GLOBAL_VA)
    a.emit(0xE5973000)             # r3 = stock loader debug/log arg
    a.emit(0xE24DD008)             # fifth arg + keep stack aligned
    a.emit(0xE3A08000)             # r8 = 0
    a.emit(0xE58D8000)             # fifth arg = 0
    a.branch(original_loader_va, link=True)
    a.emit(0xE28DD008)
    a.emit(0xE3500000)             # custom decode failed?
    a.branch('done', cond=0x0)
    a.emit(0xE1A06000)             # r6 = custom surface
    a.emit(0xE3550000)             # old surface exists?
    a.branch('store', cond=0x0)
    a.emit(0xE1A00005)             # r0 = old surface
    a.branch(free_surface_va, link=True)
    a.label('store')
    a.emit(0xE584604C)             # menu+0x4c = custom surface
    a.label('done')
    a.emit(0xE51B3018)             # replay ldr r3,[fp,#-0x18]
    a.emit(0xE8BD81F0)             # pop {r4-r8,pc}
    return a.finish()


def build_rows_r3(base_va: int, get_rows_va: int) -> bytes:
    a = ArmBuilder(base_va)
    a.emit(0xE92D5017)             # push {r0-r2,r4,ip,lr}
    a.branch(get_rows_va, link=True)
    a.emit(0xE1A03000)             # mov r3,r0
    a.emit(0xE8BD9017)             # pop {r0-r2,r4,ip,pc}; r3 survives
    return a.finish()


def build_mark_game_list(base_va: int, data_va: int) -> tuple[bytes, int, int]:
    """Tag a known game-list object before entering the shared constructor.

    The Favourites/Recent call sites have the object in r4 and originally execute
    ``mov r0,r4``. The ROM call site originally loads it from ``[fp,#-8]``.
    Both entries record a one-constructor pending pointer and make the object the
    active game list. When Search creates a second list, retain the old active
    object as the previous list so returning through the Search keyboard can
    reactivate it even if MainUI does not run its constructor hook again.
    """
    a = ArmBuilder(base_va)
    fav_recent_entry = a.va
    a.emit(0xE1A00004)             # mov r0,r4
    a.branch('common')
    rom_entry = a.va
    a.emit(0xE51B0008)             # ldr r0,[fp,#-8]
    a.label('common')
    a.emit(0xE92D1002)             # push {r1,ip}; preserve constructor args
    a.ldr_literal(12, data_va)      # ip = row/font cache
    a.emit(0xE59C1040)             # r1 = old active game-list pointer
    a.emit(0xE1500001)             # cmp new object,old active
    a.emit(0x158C1044)             # strne r1,[ip,#68] previous game list
    a.emit(0xE58C003C)             # str r0,[ip,#60] pending constructor ptr
    a.emit(0xE58C0040)             # str r0,[ip,#64] active game-list ptr
    a.emit(0xE8BD1002)             # pop {r1,ip}
    a.emit(0xE12FFF1E)             # bx lr
    return a.finish(), fav_recent_entry, rom_entry


def build_recent_list_identity_wrapper(base_va: int, state_va: int,
                                       chain_va: int, *, recent: bool) -> bytes:
    """Record/clear the exact Recent TextMenu, then enter the existing marker.

    The hooked Favourites/Recent constructor sites both have the TextMenu in r4.
    Keeping this as a tiny pre-marker wrapper lets the established row/font marker
    remain byte-for-byte unchanged while providing a stable Recent identity for
    Game Details. The clear path preserves r0 locally instead of relying on the
    chained marker to reconstruct it.
    """
    a = ArmBuilder(base_va)
    if recent:
        a.emit(0xE52DC004)         # push {ip}; leaf helper, preserve caller ip
        a.ldr_literal(12, state_va)
        a.emit(0xE58C4000)         # state = r4 (Recent TextMenu)
        a.emit(0xE49DC004)         # pop {ip}
    else:
        a.emit(0xE92D1002)         # push {r1,ip}; r0 remains untouched
        a.ldr_literal(12, state_va)
        a.emit(0xE3A01000)         # r1 = 0
        a.emit(0xE58C1000)         # clear stale Recent TextMenu identity
        a.emit(0xE8BD1002)         # pop {r1,ip}
    a.branch(chain_va)
    return a.finish()


def build_recent_rom_identity_clear_wrapper(base_va: int, state_va: int,
                                            chain_va: int) -> bytes:
    """Clear stale Recent identity before the established ROM-list marker."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D1002)             # push {r1,ip}; r0 remains untouched
    a.ldr_literal(12, state_va)
    a.emit(0xE3A01000)             # r1 = 0
    a.emit(0xE58C1000)             # clear Recent TextMenu identity
    a.emit(0xE8BD1002)             # pop {r1,ip}
    a.branch(chain_va)
    return a.finish()


def build_recent_identity_destructor_wrapper(base_va: int, state_va: int,
                                             continue_va: int) -> bytes:
    """Clear a tracked Recent TextMenu exactly when that object is destroyed.

    Entry is TextMenu's complete destructor with r0=this. No calls are made. The
    wrapper preserves temporary registers, clears state only on exact pointer
    equality, replays the displaced stock ``push {fp,lr}``, and continues at the
    next stock instruction. The deleting destructor naturally reaches this same
    entry, so no second lifecycle hook is needed.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D1002)             # push {r1,ip}; preserve caller scratch
    a.ldr_literal(12, state_va)
    a.emit(0xE59C1000)             # r1 = tracked Recent TextMenu
    a.emit(0xE1500001)             # cmp this,tracked
    a.emit(0x03A01000)             # moveq r1,#0
    a.emit(0x058C1000)             # streq r1,[ip]
    a.emit(0xE8BD1002)             # pop {r1,ip}
    a.emit(RECENT_TEXTMENU_COMPLETE_DTOR_STOCK_WORD)
    a.branch(continue_va)
    return a.finish()


def build_recent_list_thumb_wrapper(base_va: int, make_thumb_va: int,
                                    c_str_va: int, strstr_va: int) -> bytes:
    """Choose explicit saved PNG only for a Recent list preview.

    The stock call already has r2 = config->image-directory. For mode 0xA only,
    inspect the selected GameAction's saved imgpath and replace the saved r2 stack
    slot only when that string contains `.png`. Bare labels therefore keep the
    stock directory-derived path, while Search-origin explicit PNGs become usable.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D401F)             # push {r0-r4,lr}; 24 bytes, AAPCS aligned
    a.emit(0xE51B3118)             # r3 = containing MenuWindow (caller fp-0x118)
    a.emit(0xE3530000)
    a.branch('done', cond=0x0)
    a.emit(0xE5933008)             # r3 = window mode
    a.emit(0xE353000A)             # Recent == 0x0a
    a.branch('done', cond=0x1)
    a.emit(0xE51B3020)             # r3 = selected GameAction (caller fp-0x20)
    a.emit(0xE3530000)
    a.branch('done', cond=0x0)
    a.emit(0xE283000C)             # r0 = &GameAction::imgpath std::string
    a.branch(c_str_va, link=True)
    a.emit(0xE1A04000)             # r4 = saved imgpath c_str
    a.emit(0xE3540000)
    a.branch('done', cond=0x0)
    a.emit(0xE1A00004)             # r0 = saved imgpath
    a.ldr_literal(1, RECENT_THUMB_PNG_SUFFIX_VA)
    a.branch(strstr_va, link=True)
    a.emit(0xE3500000)
    a.emit(0x158D4008)             # if .png: replace saved r2 with explicit path
    a.label('done')
    a.emit(0xE8BD401F)             # pop {r0-r4,lr}; chosen r2 restored from stack
    a.branch(make_thumb_va)        # tail-call stock makeThumbPath
    return a.finish()


def build_recent_initial_detail_image_wrapper(
        base_va: int, state_va: int, game_list_state_va: int,
        c_str_va: int, strstr_va: int) -> bytes:
    """Return the canonical Recent image argument during RIGHT-open.

    The stock ordinary GameAction detail-entry path calls c_str on GameAction::imgpath
    before constructing GameDetailWindow. At that point the detail object does
    not yet contain its source TextMenu, so identify Recent by requiring the
    globally active game-list pointer to equal the exact tracked Recent TextMenu.
    Explicit saved PNGs remain authoritative. A non-PNG/bare saved imgpath is
    replaced only for Recent with the source system config image directory,
    matching the later Up/Down refresh path.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D507E)             # push {r1-r6,ip,lr}; 32 bytes, aligned
    a.emit(0xE1A04000)             # r4 = &GameAction::imgpath std::string
    a.branch(c_str_va, link=True)
    a.emit(0xE1A05000)             # r5 = stock imgpath c_str / default return
    a.ldr_literal(2, state_va)
    a.emit(0xE5922000)             # r2 = tracked Recent TextMenu
    a.emit(0xE3520000)
    a.branch('done', cond=0x0)
    a.ldr_literal(3, game_list_state_va)
    a.emit(0xE5933040)             # r3 = active game-list TextMenu
    a.emit(0xE1530002)             # active == tracked Recent?
    a.branch('done', cond=0x1)
    a.emit(0xE1A00005)             # r0 = saved imgpath c_str
    a.ldr_literal(1, RECENT_THUMB_PNG_SUFFIX_VA)
    a.branch(strstr_va, link=True)
    a.emit(0xE3500000)
    a.branch('done', cond=0x1)      # explicit .png remains authoritative
    a.emit(0xE244400C)             # r4 = GameAction pointer
    a.emit(0xE5943008)             # r3 = source system/config object
    a.emit(0xE3530000)
    a.branch('done', cond=0x0)
    a.emit(0xE2830090)             # r0 = &config image-directory std::string
    a.branch(c_str_va, link=True)
    a.emit(0xE1A05000)             # r5 = canonical source image directory
    a.label('done')
    a.emit(0xE1A00005)             # return chosen c_str in r0
    a.emit(0xE8BD507E)             # pop {r1-r6,ip,lr}
    a.emit(0xE12FFF1E)             # bx lr
    return a.finish()


def build_recent_detail_image_wrapper(base_va: int, state_va: int,
                                      c_str_va: int, strstr_va: int) -> bytes:
    """Return the canonical Recent Game Details image argument.

    Stock enters with r0 = &GameAction::imgpath. Keep its c_str for all non-Recent
    sources and for explicit .png Recent paths. If the exact source TextMenu is the
    tracked Recent menu and imgpath is not explicit, return config+0x90 c_str so
    makeThumbPath derives the same ROM-basename PNG used by the Recent list.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D507E)             # push {r1-r6,ip,lr}; 32 bytes, aligned
    a.emit(0xE1A04000)             # r4 = &GameAction::imgpath
    a.branch(c_str_va, link=True)
    a.emit(0xE1A05000)             # r5 = stock imgpath c_str / default return
    a.emit(0xE51B2048)             # r2 = GameDetailWindow (caller fp-0x48)
    a.emit(0xE3520000)
    a.branch('done', cond=0x0)
    a.emit(0xE5922098)             # r2 = exact source TextMenu
    a.ldr_literal(3, state_va)
    a.emit(0xE5933000)             # r3 = tracked Recent TextMenu
    a.emit(0xE3530000)
    a.branch('done', cond=0x0)
    a.emit(0xE1520003)             # source menu == Recent menu?
    a.branch('done', cond=0x1)
    a.emit(0xE1A00005)             # r0 = saved imgpath c_str
    a.ldr_literal(1, RECENT_THUMB_PNG_SUFFIX_VA)
    a.branch(strstr_va, link=True)
    a.emit(0xE3500000)
    a.branch('done', cond=0x1)      # explicit .png remains authoritative
    a.emit(0xE244400C)             # r4 = GameAction pointer
    a.emit(0xE5943008)             # r3 = system/config object
    a.emit(0xE3530000)
    a.branch('done', cond=0x0)
    a.emit(0xE2830090)             # r0 = &config image-directory std::string
    a.branch(c_str_va, link=True)
    a.emit(0xE1A05000)             # r5 = canonical system image directory
    a.label('done')
    a.emit(0xE1A00005)             # return chosen c_str in r0
    a.emit(0xE8BD507E)             # pop {r1-r6,ip,lr}
    a.emit(0xE12FFF1E)             # bx lr
    return a.finish()


def build_recent_search_canonical_add_wrapper(
        base_va: int, launch_buffer_va: int, downstream_va: int) -> bytes:
    """Canonicalize Search-origin Recent identity before Add2RecentList.

    Entry has the stock Add2RecentList ABI: r0=list, r1=label, r2=launch,
    r3=rompath, followed by imgpath/type/front-back on the caller stack.
    SearchFilter encodes r3 as ``<real launch.sh>:<real ROM path>`` while r2
    names the synthetic Search launcher. Detect that exact marker, copy the
    real launcher prefix into bounded writable scratch, and pass the suffix as
    r3. Exact ``launch == "setstate"`` pseudo-records are rejected before they
    can consume a Recent slot. The underlying GameAction and Search row are not
    modified; only the Recent record arguments become console-shaped. Other
    non-encoded paths fail open to the original arguments.
    """
    a = ArmBuilder(base_va)
    # Preserve original r0/r1 and scratch registers. r2/r3 are deliberately
    # left live across the final pop because they carry the chosen arguments.
    a.emit(0xE92D40F3)             # push {r0,r1,r4-r7,lr}
    a.emit(0xE1A04002)             # r4 = original launch
    a.emit(0xE1A05003)             # r5 = original rompath
    # Synthetic navigation/state rows can use this same game-style Recent ABI.
    # They are not renderable game rows, so reject exact launch == "setstate"
    # for both live insertion and file reconstruction before Add2RecentList.
    for off, ch in enumerate(b'setstate'):
        a.emit(0xE5D4C000 | off)   # ldrb ip,[r4,#off]
        a.emit(0xE35C0000 | ch)    # cmp ip,#ch
        a.branch('not_setstate', cond=0x1)
    a.emit(0xE5D4C008)             # ldrb ip,[r4,#8]
    a.emit(0xE35C0000)             # exact NUL-terminated token?
    a.branch('not_setstate', cond=0x1)
    a.emit(0xE8BD40F3)             # restore original call arguments
    a.emit(0xE3A00000)             # return value is ignored at both call sites
    a.emit(0xE12FFF1E)             # bx lr -- skip Add2RecentList
    a.label('not_setstate')
    a.emit(0xE1A06005)             # r6 = scan pointer
    a.label('scan')
    a.emit(0xE5D6C000)             # ldrb ip,[r6]
    a.emit(0xE35C0000)             # cmp ip,#0
    a.branch('stock', cond=0x0)
    a.emit(0xE35C006C)             # cmp ip,#'l'
    a.branch('next', cond=0x1)
    for off, ch in enumerate(b'aunch.sh:', 1):
        a.emit(0xE5D6C000 | off)   # ldrb ip,[r6,#off]
        a.emit(0xE35C0000 | ch)    # cmp ip,#ch
        a.branch('next', cond=0x1)
    a.emit(0xE5D6C00A)             # ldrb ip,[r6,#10]
    a.emit(0xE35C002F)             # cmp ip,#'/' -- real ROM must be absolute
    a.branch('stock', cond=0x1)
    # Prefix length is colon - start = marker_offset + 9. Keep one byte for NUL.
    a.emit(0xE046C005)             # sub ip,r6,r5
    a.emit(0xE28CC009)             # add ip,ip,#9
    a.ldr_literal(0, RECENT_SEARCH_CANON_LAUNCH_BUFFER_SIZE - 1)
    a.emit(0xE15C0000)             # cmp ip,r0
    a.branch('stock', cond=0x8)     # bhi
    a.ldr_literal(7, launch_buffer_va)
    a.emit(0xE1A00005)             # r0 = source start
    a.emit(0xE1A01007)             # r1 = destination
    a.label('copy')
    a.emit(0xE35C0000)             # cmp ip,#0
    a.branch('copied', cond=0x0)
    a.emit(0xE5D02000)             # ldrb r2,[r0]
    a.emit(0xE5C12000)             # strb r2,[r1]
    a.emit(0xE2800001)             # add r0,r0,#1
    a.emit(0xE2811001)             # add r1,r1,#1
    a.emit(0xE24CC001)             # sub ip,ip,#1
    a.branch('copy')
    a.label('copied')
    a.emit(0xE3A00000)             # mov r0,#0
    a.emit(0xE5C10000)             # strb r0,[r1] -- terminate launcher
    a.emit(0xE1A02007)             # r2 = canonical real launcher
    a.emit(0xE286300A)             # r3 = real ROM suffix after 'launch.sh:'
    a.branch('call')
    a.label('next')
    a.emit(0xE2866001)             # add r6,r6,#1
    a.branch('scan')
    a.label('stock')
    a.emit(0xE1A02004)             # restore original launch
    a.emit(0xE1A03005)             # restore original rompath
    a.label('call')
    a.emit(0xE8BD40F3)             # pop {r0,r1,r4-r7,lr}
    a.branch(downstream_va)         # tail-call current Add2RecentList chain
    return a.finish()


def build_search_favourite_status_wrapper(
        base_va: int, search_image_marker_va: int, delimiter_va: int,
        c_str_va: int, strstr_va: int, is_favourite_va: int) -> bytes:
    """Normalize Onion Search's encoded database path before star lookup.

    The ROM page-fetch call enters with ``r0`` = optional favourite buffer,
    ``r1`` = FILE*/legacy handle and ``r2`` = the raw SQLite path. SearchFilter
    stores game rows as ``<source launch>:/mnt/SDCARD/...``. MainUI's later
    GameAction constructor splits that encoding, so favourite.json contains only
    the real ROM suffix. Gate normalization to the Search console's configured
    image directory; every non-Search page and every non-encoded Search row
    tail-calls the existing isFavourite implementation with its original path.
    """
    a = ArmBuilder(base_va)
    # Six saved registers = 24 bytes, preserving AAPCS alignment for both BLs.
    a.emit(0xE92D403B)             # push {r0,r1,r3-r5,lr}
    a.emit(0xE1A04002)             # r4 = raw SQLite path / default r2
    a.emit(0xE51B3148)             # r3 = page-fetch self [caller fp,#-0x148]
    a.emit(0xE3530000)
    a.branch('stock', cond=0x0)
    a.emit(0xE5933280)             # r3 = attached source config
    a.emit(0xE3530000)
    a.branch('stock', cond=0x0)
    a.emit(0xE2830090)             # r0 = &config image-directory std::string
    a.branch(c_str_va, link=True)
    a.emit(0xE3500000)
    a.branch('stock', cond=0x0)
    a.ldr_literal(1, search_image_marker_va)
    a.branch(strstr_va, link=True)
    a.emit(0xE3500000)             # not the synthetic Search config?
    a.branch('stock', cond=0x0)
    a.emit(0xE1A00004)             # r0 = raw encoded database path
    a.ldr_literal(1, delimiter_va)
    a.branch(strstr_va, link=True)
    a.emit(0xE3500000)
    a.branch('stock', cond=0x0)
    a.emit(0xE2802001)             # r2 = slash after ':' -> real ROM path
    # New/fixed Favorite records use the real ROM path.  Try that first.
    a.emit(0xE59D0000)             # restore original r0 favourite buffer
    a.emit(0xE59D1004)             # restore original r1 file/legacy handle
    a.branch(is_favourite_va, link=True)
    a.emit(0xE3500000)
    a.branch('return_result', cond=0x1)
    # Legacy Search-created Favorite records may still contain the encoded path.
    # Fall back to the original raw Search DB identity so old files keep their star.
    a.emit(0xE59D0000)
    a.emit(0xE59D1004)
    a.emit(0xE1A02004)
    a.branch(is_favourite_va, link=True)
    a.label('return_result')
    a.emit(0xE1A02000)             # preserve result across saved-r0 pop
    a.emit(0xE8BD403B)
    a.emit(0xE1A00002)
    a.emit(0xE12FFF1E)
    a.label('stock')
    a.emit(0xE1A02004)             # r2 = unmodified database path
    a.emit(0xE8BD403B)
    a.branch(is_favourite_va)      # non-Search path remains a tail-call
    return a.finish()


def build_search_favourite_add_cstr_wrapper(
        base_va: int, launch_buffer_va: int, encoded_marker_va: int,
        c_str_va: int, strstr_va: int, *, return_launch: bool) -> bytes:
    """Canonicalize Search-origin fields while AddFavoriteAction serializes.

    The stock AddFavoriteAction extracts ``config->launch`` first and
    ``GameAction::rompath`` later.  The selected GameAction remains available in
    the caller frame at ``fp-0x1c``.  If its rompath contains the exact
    SearchFilter marker ``launch.sh:/mnt/SDCARD/``, return either a bounded copy
    of the source-launch prefix or the real-ROM suffix.  Otherwise return the
    original c_str result.  The stock Favorite JSON schema remains unchanged.
    """
    a = ArmBuilder(base_va)
    # r1-r8,ip,lr = ten registers / 40 bytes, preserving AAPCS alignment.
    a.emit(0xE92D51FE)             # push {r1-r8,ip,lr}
    a.emit(0xE1A04000)             # r4 = original std::string* argument
    a.emit(0xE51B501C)             # r5 = selected GameAction from caller frame
    a.emit(0xE3550000)
    a.branch('stock', cond=0x0)
    a.emit(0xE2850024)             # r0 = &GameAction::rompath
    a.branch(c_str_va, link=True)
    a.emit(0xE1A06000)             # r6 = raw/possibly encoded rompath
    a.emit(0xE3500000)
    a.branch('stock', cond=0x0)
    a.ldr_literal(1, encoded_marker_va)
    a.branch(strstr_va, link=True)
    a.emit(0xE3500000)
    a.branch('stock', cond=0x0)
    a.emit(0xE1A07000)             # r7 = pointer to 'launch.sh:/mnt/SDCARD/'
    if return_launch:
        a.emit(0xE0473006)         # r3 = marker - encoded start
        a.emit(0xE2833009)         # + strlen('launch.sh') = prefix before ':'
        a.ldr_literal(8, SEARCH_FAVOURITE_CANON_LAUNCH_BUFFER_SIZE - 1)
        a.emit(0xE1530008)         # cmp prefix length, max
        a.branch('stock', cond=0x8) # bhi
        a.emit(0xE1A02006)         # r2 = source encoded start
        a.ldr_literal(1, launch_buffer_va)
        a.emit(0xE1A05001)         # r5 = buffer start for return
        a.label('copy')
        a.emit(0xE3530000)
        a.branch('copied', cond=0x0)
        a.emit(0xE5D20000)         # ldrb r0,[r2]
        a.emit(0xE5C10000)         # strb r0,[r1]
        a.emit(0xE2822001)
        a.emit(0xE2811001)
        a.emit(0xE2433001)
        a.branch('copy')
        a.label('copied')
        a.emit(0xE3A00000)
        a.emit(0xE5C10000)         # NUL terminate
        a.emit(0xE1A00005)         # return canonical source launcher
        a.branch('done')
    else:
        a.emit(0xE287000A)         # return slash after 'launch.sh:'
        a.branch('done')
    a.label('stock')
    a.emit(0xE1A00004)             # original std::string*
    a.branch(c_str_va, link=True)
    a.label('done')
    a.emit(0xE8BD51FE)             # pop {r1-r8,ip,lr}; preserve r0 result
    a.emit(0xE12FFF1E)
    return a.finish()


def build_search_favourite_game_action_ctor_wrapper(
        base_va: int, launch_buffer_va: int, encoded_marker_va: int,
        strstr_va: int, game_find_va: int, game_size_va: int, game_get_va: int,
        c_str_va: int, stock_ctor_va: int) -> bytes:
    """Canonicalize legacy Search-shaped Favorite rows at construction time.

    Existing bad favourite.json records can contain Search as ``launch`` and an
    encoded ``<source launch.sh>:<real ROM>`` rompath.  The folder-aware Favorite
    core passes those values to GameAction construction.  This context-level
    adapter leaves the model/file untouched but substitutes the real source
    emulator config and real ROM path so launch and thumbnail derivation work.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D47F0)             # push {r4-r10,lr}; 32-byte aligned frame
    a.emit(0xE1A04000)             # r4 = action object
    a.emit(0xE1A07001)             # r7 = original/source config
    a.emit(0xE1A05002)             # r5 = label
    a.emit(0xE1A06003)             # r6 = original rompath
    a.emit(0xE3560000)
    a.branch('call', cond=0x0)
    a.emit(0xE1A00006)
    a.ldr_literal(1, encoded_marker_va)
    a.branch(strstr_va, link=True)
    a.emit(0xE3500000)
    a.branch('call', cond=0x0)
    a.emit(0xE1A08000)             # r8 = marker pointer
    a.emit(0xE0483006)             # r3 = marker - encoded start
    a.emit(0xE2833009)             # prefix length before ':'
    a.ldr_literal(2, SEARCH_FAVOURITE_CANON_LAUNCH_BUFFER_SIZE - 1)
    a.emit(0xE1530002)
    a.branch('call', cond=0x8)     # bhi
    a.emit(0xE1A02006)             # source encoded start
    a.ldr_literal(9, launch_buffer_va)
    a.emit(0xE1A01009)             # destination buffer
    a.label('copy')
    a.emit(0xE3530000)
    a.branch('copied', cond=0x0)
    a.emit(0xE5D2C000)
    a.emit(0xE5C1C000)
    a.emit(0xE2822001)
    a.emit(0xE2811001)
    a.emit(0xE2433001)
    a.branch('copy')
    a.label('copied')
    a.emit(0xE3A03000)
    a.emit(0xE5C13000)             # NUL terminate source-launch buffer
    # Search ordinary + alternate game config vectors for the canonical launcher.
    a.ldr_literal(0, 0x00181944)    # game vector type 5
    a.emit(0xE1A01009)
    a.branch(game_find_va, link=True)
    a.emit(0xE1A0A000)             # r10 = index
    a.emit(0xE35A0000)
    a.branch('try_alt', cond=0xB)  # blt
    a.ldr_literal(0, 0x00181944)
    a.branch(game_size_va, link=True)
    a.emit(0xE15A0000)             # cmp index,size
    a.branch('try_alt', cond=0x2)  # bhs
    a.ldr_literal(0, 0x00181944)
    a.emit(0xE1A0100A)
    a.branch(game_get_va, link=True)
    a.emit(0xE1A07000)             # r7 = canonical source config
    a.branch('canonical_rom')
    a.label('try_alt')
    a.ldr_literal(0, 0x00181950)    # alternate game vector type 17
    a.emit(0xE1A01009)
    a.branch(game_find_va, link=True)
    a.emit(0xE1A0A000)
    a.emit(0xE35A0000)
    a.branch('call', cond=0xB)     # fail open to original config/path
    a.ldr_literal(0, 0x00181950)
    a.branch(game_size_va, link=True)
    a.emit(0xE15A0000)
    a.branch('call', cond=0x2)
    a.ldr_literal(0, 0x00181950)
    a.emit(0xE1A0100A)
    a.branch(game_get_va, link=True)
    a.emit(0xE1A07000)
    a.label('canonical_rom')
    a.emit(0xE288600A)             # r6 = real ROM suffix after 'launch.sh:'
    # Legacy Search Favorites normally have no imgpath. Replace the original
    # fifth constructor argument with the canonical source emulator image
    # directory so Game Details derives the same PNG as the Favorite list.
    a.emit(0xE2870090)             # r0 = &canonical config image-dir string
    a.branch(c_str_va, link=True)
    a.emit(0xE58D0020)             # original ctor stack arg0 after 32-byte push
    a.label('call')
    a.emit(0xE1A00004)
    a.emit(0xE1A01007)
    a.emit(0xE1A02005)
    a.emit(0xE1A03006)
    a.emit(0xE8BD47F0)             # restore r4-r10,lr; keep r0-r3 arguments
    a.branch(stock_ctor_va)        # tail-call stock GameAction constructor
    return a.finish()


def build_height_r2(base_va: int, data_va: int, *, custom_rows: bool) -> bytes:
    """Return custom height only for a tagged game-list construction.

    The hook is also installed in font-only builds so a non-game constructor
    reusing either remembered game-list address clears that stale tag. If the
    active Search-results object is reused by the keyboard, promote the previous
    list; this preserves the original list identity for the second B press while
    keeping Language and unrelated menus untagged. In font-only mode every
    constructor still receives the stock height of 60 pixels.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D501B)             # push {r0,r1,r3,r4,ip,lr}
    a.ldr_literal(4, data_va)       # r4 = row/font cache
    a.emit(0xE594103C)             # r1 = pending game-list constructor ptr
    a.emit(0xE1530001)             # cmp r3,r1 (r3 = this)
    a.emit(0xE3A00000)             # mov r0,#0; consume one-shot marker
    a.emit(0xE584003C)             # clear pending pointer for every constructor
    a.branch('stock', cond=0x1)    # bne stock/non-game constructor
    if custom_rows:
        a.emit(0xE5942004)         # r2 = cached configured row height
    else:
        a.emit(0xE3A0203C)         # font-only mode: stock 60 pixels
    a.branch('done')
    a.label('stock')
    a.emit(0xE5941040)             # r1 = active game-list pointer
    a.emit(0xE5940044)             # r0 = previous game-list pointer
    a.emit(0xE1530001)             # reused active pointer?
    a.emit(0x05840040)             # streq r0,[r4,#64] promote previous
    a.emit(0x03A00000)             # moveq r0,#0
    a.emit(0x05840044)             # streq r0,[r4,#68] clear previous
    a.emit(0x11530000)             # cmpne r3,r0 (reused previous pointer?)
    a.emit(0x03A00000)             # moveq r0,#0
    a.emit(0x05840044)             # streq r0,[r4,#68]
    a.emit(0xE3A0203C)             # mov r2,#60
    a.label('done')
    a.emit(0xE8BD901B)             # pop {r0,r1,r3,r4,ip,pc}; r2 survives
    return a.finish()

def build_rom_list_repaint_timer_callback(
        base_va: int, push_event_va: int) -> bytes:
    """Post a normal repaint event and retry if SDL's queue is still full.

    Rapid shoulder-button navigation can temporarily fill the SDL 1.2 event
    queue. A single delayed SDL_PushEvent can then fail, leaving already-loaded
    rows visually stuck as LOADING until some later input causes a redraw.
    SDL timer callbacks remain active when they return a non-zero interval, so
    retry at a modest cadence until the repaint event is actually accepted.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D4010)             # push {r4,lr}; preserve 8-byte alignment
    a.emit(0xE24DD018)             # sub sp,sp,#24 (one SDL_Event)
    a.emit(0xE3A03018)             # r3 = SDL_USEREVENT (24)
    a.emit(0xE5CD3000)             # event.type = 24
    a.emit(0xE58D3004)             # event.user.code = 24
    a.emit(0xE1A0000D)             # r0 = &event
    a.branch(push_event_va, link=True)
    a.emit(0xE3500000)             # SDL 1.2: 0 success, -1 failure
    a.emit(0x03A00000)             # moveq r0,#0: stop timer
    if not 0 <= ROM_LIST_REPAINT_RETRY_MS <= 255:
        raise ValueError('ROM-list repaint retry must fit a compact MOV immediate')
    a.emit(0x13A00000 | ROM_LIST_REPAINT_RETRY_MS)
                                    # movne r0,#retry_ms: queue-full retry
    a.emit(0xE28DD018)             # add sp,sp,#24
    a.emit(0xE8BD8010)             # pop {r4,pc}
    return a.finish()


def build_scheduled_rom_list_repaint_callback(
        base_va: int, push_event_va: int, add_timer_va: int,
        timer_callback_va: int) -> bytes:
    """Post stock repaint now and schedule another after this callback returns."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D4010)             # push {r4,lr}
    a.emit(0xE24DD018)             # sub sp,sp,#24 (one SDL_Event)
    a.emit(0xE3A04018)             # r4 = SDL_USEREVENT (24)
    a.emit(0xE5CD4000)             # event.type = 24
    a.emit(0xE58D4004)             # event.user.code = 24
    a.emit(0xE1A0000D)             # r0 = &event
    a.branch(push_event_va, link=True)
    if not 0 <= ROM_LIST_REPAINT_DELAY_MS <= 255:
        raise ValueError('ROM-list repaint delay must fit a compact MOV immediate')
    a.emit(0xE3A00000 | ROM_LIST_REPAINT_DELAY_MS)  # r0 = interval ms
    a.ldr_literal(1, timer_callback_va)              # r1 = timer callback
    a.emit(0xE3A02000)             # r2 = NULL callback parameter
    a.branch(add_timer_va, link=True)
    a.emit(0xE28DD018)             # add sp,sp,#24
    a.emit(0xE8BD8010)             # pop {r4,pc}
    return a.finish()



def build_preview_completion_scheduler(
        base_va: int, state_va: int, push_event_va: int, add_timer_va: int,
        timer_callback_va: int) -> bytes:
    """Publish one completion generation, then preserve OD repaint behavior.

    Only the generation increment is cross-thread. UI work remains deferred to
    the shared preview-window draw. The existing immediate repaint and 120 ms
    bounded fallback are retained byte-for-byte in behavior.
    """
    if not 0 <= ROM_LIST_REPAINT_DELAY_MS <= 255:
        raise ValueError('ROM-list repaint delay must fit a compact MOV immediate')
    a = ArmBuilder(base_va)
    a.emit(0xE92D40F0)             # push {r4-r7,lr}; 20 bytes
    a.emit(0xE24DD01C)             # sub sp,sp,#28; total frame remains 8-byte aligned
    a.ldr_literal(4, state_va)      # r4 = generation state
    a.emit(0xE5943000)             # produced generation
    a.emit(0xE2833001)             # ++produced
    a.emit(0xE5843000)
    a.emit(0xE3A05018)             # r5 = SDL_USEREVENT (24)
    a.emit(0xE5CD5000)             # event.type = 24
    a.emit(0xE58D5004)             # event.user.code = 24
    a.emit(0xE1A0000D)             # r0 = &event
    a.branch(push_event_va, link=True)
    a.ldr_literal(7, timer_callback_va)  # preserve callback across SDL_AddTimer
    a.emit(0xE3A00000 | ROM_LIST_REPAINT_DELAY_MS)
    a.emit(0xE1A01007)             # r1 = timer callback
    a.emit(0xE3A02000)             # NULL timer param
    a.branch(add_timer_va, link=True)
    a.emit(0xE3500000)             # SDL_AddTimer: NULL means timer creation failed
    a.branch('timer_done', cond=0x1)
    a.emit(0xE3A00000 | ROM_LIST_REPAINT_DELAY_MS)
    a.emit(0xE1A01007)             # retry once with the same callback
    a.emit(0xE3A02000)
    a.branch(add_timer_va, link=True)
    a.label('timer_done')
    a.emit(0xE28DD01C)
    a.emit(0xE8BD80F0)             # pop {r4-r7,pc}
    return a.finish()


def build_preview_mid_draw_refresh_wrapper(
        base_va: int, state_va: int, updater_va: int,
        continue_va: int) -> bytes:
    """Refresh once when completion arrived during the current outer draw.

    The hook runs at the stock cover-null check, before cover dimensions or the
    selected-cover blit are read. Every observed completion generation is marked
    consumed. The stock updater is called only when the generation is new and
    the cover remains NULL. Publishing consumed before the call ensures a newer
    completion arriving during the updater remains pending for a later draw.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D407F)             # push {r0-r6,lr}; 32 bytes, ABI aligned
    a.emit(0xE51B40F0)             # r4 = draw object from fp-0xf0
    a.ldr_literal(5, state_va)      # r5 = generation state
    a.emit(0xE5950000)             # r0 = produced
    a.emit(0xE5951004)             # r1 = consumed
    a.emit(0xE1500001)
    a.branch('restore', cond=0x0)  # no new completion
    a.emit(0xE5850004)             # consumed = observed produced
    a.emit(0xE5943038)             # current cover
    a.emit(0xE3530000)
    a.branch('restore', cond=0x1)  # stock updater already attached it
    a.emit(0xE1A00004)             # r0 = preview-window object
    a.branch(updater_va, link=True)
    a.label('restore')
    a.emit(0xE8BD407F)             # pop {r0-r6,lr}
    a.emit(GAME_LIST_COVER_CHECK_STOCK_WORD)  # displaced ldr r3,[fp,#-0xf0]
    a.branch(continue_va)
    return a.finish()


def build_rom_list_repaint_burst_scheduler(
        base_va: int, push_event_va: int, add_timer_va: int,
        timer_callback_va: int) -> bytes:
    """Post now and add two bounded one-shot repaints for ROM row loads.

    The ROM database worker can finish while MainUI is still unwinding a
    previous navigation/completion path. A single delayed event is normally
    enough, but an occasional draw can still precede the final visible-window
    state. Two independent one-shot timers cover that bounded race without
    sleeping in the worker callback or polling indefinitely.
    """
    delays = (ROM_LIST_REPAINT_DELAY_MS, ROM_LIST_REPAINT_LATE_DELAY_MS)
    if any(not 0 < delay <= 0xFFFF for delay in delays):
        raise ValueError('ROM-list repaint delays must fit MOVW immediates')
    a = ArmBuilder(base_va)
    a.emit(0xE92D4010)             # push {r4,lr}; preserve 8-byte alignment
    a.emit(0xE24DD018)             # sub sp,sp,#24 (one SDL_Event)
    a.emit(0xE3A03018)             # r3 = SDL_USEREVENT (24)
    a.emit(0xE5CD3000)             # event.type = 24
    a.emit(0xE58D3004)             # event.user.code = 24
    a.emit(0xE1A0000D)             # r0 = &event
    a.branch(push_event_va, link=True)
    a.ldr_literal(4, timer_callback_va)  # r4 = retrying one-shot callback
    for index, delay in enumerate(delays):
        retry_done = f'timer_{index}_done'
        a.emit(arm_movw(0, delay))
        a.emit(0xE1A01004)         # r1 = timer callback
        a.emit(0xE3A02000)         # r2 = NULL callback parameter
        a.branch(add_timer_va, link=True)
        a.emit(0xE3500000)         # NULL means timer creation failed
        a.branch(retry_done, cond=0x1)
        a.emit(arm_movw(0, delay)) # retry timer creation once, never on success
        a.emit(0xE1A01004)
        a.emit(0xE3A02000)
        a.branch(add_timer_va, link=True)
        a.label(retry_done)
    a.emit(0xE28DD018)             # add sp,sp,#24
    a.emit(0xE8BD8010)             # pop {r4,pc}
    return a.finish()


def build_rom_list_initial_warmup_wrapper(
        base_va: int, original_load_va: int, delay_va: int,
        c_str_va: int) -> bytes:
    """Run the restored load, then briefly wait for the visible window.

    This keeps the device-tested stock request topology. With stale romwinidx spans already
    normalized around the saved selection, the stock loader receives exactly the
    viewport that contains that selection. The bounded wait is read-only and applies
    to index zero as well as restored deeper windows; only negative indices bypass it.
    """
    if ROM_LIST_INITIAL_WARMUP_MAX_MS % ROM_LIST_INITIAL_WARMUP_DELAY_MS:
        raise ValueError('ROM-list warm-up bound must divide evenly')
    attempts = (ROM_LIST_INITIAL_WARMUP_MAX_MS //
                ROM_LIST_INITIAL_WARMUP_DELAY_MS)
    if not 0 < attempts <= 255:
        raise ValueError('ROM-list warm-up attempts must fit MOV immediate')
    if not 0 < ROM_LIST_INITIAL_WARMUP_DELAY_MS <= 255:
        raise ValueError('ROM-list warm-up delay must fit MOV immediate')

    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}; 8-byte aligned
    a.emit(0xE1A04000)             # r4 = ROM-list object
    a.branch(original_load_va, link=True)
    a.emit(0xE5945010)             # r5 = restored first visible index
    a.emit(0xE3550000)
    a.branch('done', cond=0xB)     # only negative/invalid windows bypass readiness wait
    a.emit(0xE5946014)             # r6 = restored last visible index
    a.emit(0xE1560005)
    a.branch('done', cond=0xB)     # last < first
    a.emit(0xE3A08000 | attempts)  # r8 = bounded retry count
    a.label('retry')
    a.emit(0xE1A07005)             # r7 = first visible index
    a.label('scan')
    a.emit(0xE5943000)             # r3 = vtable
    a.emit(0xE5933014)             # r3 = virtual item(index) accessor
    a.emit(0xE1A01007)             # r1 = index
    a.emit(0xE1A00004)             # r0 = object
    a.emit(0xE12FFF33)             # blx r3
    a.emit(0xE3500000)
    a.branch('missing', cond=0x0)
    a.branch(c_str_va, link=True)  # primary row label
    a.emit(0xE3500000)
    a.branch('missing', cond=0x0)
    # Match the proven L2/R2 page-wait readiness rule: a non-null
    # TextItem whose primary label is still exactly "LOADING" is not
    # resident yet and must not end the initial/restored-window warm-up.
    for off, ch in enumerate(b'LOADING'):
        a.emit(0xE5D01000 | off)   # ldrb r1,[r0,#off]
        a.emit(0xE3510000 | ch)    # cmp r1,#ch
        a.branch('ready_item', cond=0x1)
    a.emit(0xE5D01007)             # ldrb r1,[r0,#7]
    a.emit(0xE3510000)             # cmp r1,#0
    a.branch('missing', cond=0x0)  # exact "LOADING" + NUL
    a.label('ready_item')
    a.emit(0xE1570006)
    a.emit(0xB2877001)             # addlt r7,r7,#1
    a.branch('scan', cond=0xB)
    a.branch('done')
    a.label('missing')
    a.emit(0xE3A00000 | ROM_LIST_INITIAL_WARMUP_DELAY_MS)
    a.branch(delay_va, link=True)
    a.emit(0xE2588001)             # subs r8,r8,#1
    a.branch('retry', cond=0x1)
    a.label('done')
    a.emit(0xE8BD81F0)             # pop {r4-r8,pc}
    return a.finish()

def build_count_reset_stub(base_va: int, continue_va: int,
                              reset_va: int) -> bytes:
    """Reset a successful real COUNT statement without destroying it.

    Cache hits jump directly to ``continue_va`` and never reach this helper.
    Therefore ``fp-0x40`` is a valid real prepared COUNT statement here.
    sqlite3_reset() releases its read transaction while preserving ownership.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D401F)
    a.emit(0xE51B4040)
    a.emit(0xE3540000)
    a.branch('done', cond=0x0)
    a.emit(0xE1A00004)
    a.branch(reset_va, link=True)
    a.label('done')
    a.emit(0xE8BD401F)
    a.branch(continue_va)
    return a.finish()

def build_delete_snprintf_escape_wrapper(base_va: int, escape_buffer_va: int,
                                         snprintf_va: int) -> bytes:
    """Escape only snprintf's fifth SQL string argument.

    The filesystem path and stock deleteRow stack stores stay untouched. Only
    the SQL-bound temporary copy doubles apostrophes before calling snprintf.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)
    a.emit(0xE1A04000)
    a.emit(0xE1A05001)
    a.emit(0xE1A06002)
    a.emit(0xE1A07003)
    a.emit(0xE59D8018)
    a.ldr_literal(0, escape_buffer_va)
    a.emit(0xE1A01000)
    a.emit(arm_movw(2, 1023))
    a.label('copy')
    a.emit(0xE3520000)
    a.branch('term', cond=0x0)
    a.emit(0xE4D83001)
    a.emit(0xE3530000)
    a.branch('term', cond=0x0)
    a.emit(0xE3530027)
    a.branch('single', cond=0x1)
    a.emit(0xE3520002)             # quote requires two remaining bytes
    a.branch('term', cond=0x3)     # blo term; never publish half a pair
    a.emit(0xE4C13001)
    a.emit(0xE2422001)
    a.emit(0xE4C13001)
    a.emit(0xE2422001)
    a.branch('copy')
    a.label('single')
    a.emit(0xE4C13001)
    a.emit(0xE2422001)
    a.branch('copy')
    a.label('term')
    a.emit(0xE3A03000)
    a.emit(0xE5C13000)
    a.ldr_literal(8, escape_buffer_va)
    a.emit(0xE24DD008)
    a.emit(0xE58D8000)
    a.emit(0xE1A00004)
    a.emit(0xE1A01005)
    a.emit(0xE1A02006)
    a.emit(0xE1A03007)
    a.branch(snprintf_va, link=True)
    a.emit(0xE28DD008)
    a.emit(0xE8BD81F0)
    return a.finish()

def build_rom_list_page_wait_wrapper(
        base_va: int, original_load_va: int, delay_va: int,
        c_str_va: int, get_rows_va: int, prefetch_forward: bool) -> bytes:
    """Load the visible page and wait briefly for its rows to become available.

    Retain the established adjacent-page prefetch. Disabling it did not address
    Delete ROM's SQLite lock; ownership tracing located that lock in the
    positive COUNT statement instead.
    """
    if ROM_LIST_PAGE_WAIT_MAX_MS % ROM_LIST_PAGE_WAIT_DELAY_MS:
        raise ValueError('ROM-list page-wait bound must divide evenly')
    attempts = ROM_LIST_PAGE_WAIT_MAX_MS // ROM_LIST_PAGE_WAIT_DELAY_MS
    if not 0 < attempts <= 255:
        raise ValueError('ROM-list page-wait attempts must fit MOV immediate')
    if not 0 < ROM_LIST_PAGE_WAIT_DELAY_MS <= 255:
        raise ValueError('ROM-list page-wait delay must fit MOV immediate')

    a = ArmBuilder(base_va)
    a.emit(0xE92D47F0)             # push {r4-r10,lr}; 8-byte aligned
    a.emit(0xE1A04000)             # r4 = ROM-list object
    a.branch(original_load_va, link=True)
    a.emit(0xE1A0A000)             # r10 = original return value
    a.emit(0xE5945010)             # r5 = first visible index
    a.emit(0xE3550000)
    a.branch('done', cond=0xB)     # first < 0 / invalid window
    a.emit(0xE5946014)             # r6 = last visible index
    a.emit(0xE1560005)
    a.branch('done', cond=0xB)     # last < first / invalid window
    a.emit(0xE3A08000 | attempts)  # r8 = bounded retry count
    a.label('retry')
    a.emit(0xE1A07005)             # r7 = first visible index
    a.label('scan')
    a.emit(0xE5943000)             # vtable
    a.emit(0xE5933014)             # virtual item(index) accessor
    a.emit(0xE1A01007)
    a.emit(0xE1A00004)
    a.emit(0xE12FFF33)             # blx r3
    a.emit(0xE3500000)
    a.branch('missing', cond=0x0)
    a.branch(c_str_va, link=True)  # primary row label
    a.emit(0xE3500000)
    a.branch('missing', cond=0x0)
    # Exact stock placeholder check: "LOADING". Byte loads avoid any
    # unaligned-word assumption on std::string storage.
    for off, ch in enumerate(b'LOADING'):
        a.emit(0xE5D01000 | off)   # ldrb r1,[r0,#off]
        a.emit(0xE3510000 | ch)    # cmp r1,#ch
        a.branch('ready_item', cond=0x1)
    a.emit(0xE5D01007)             # ldrb r1,[r0,#7]
    a.emit(0xE3510000)             # cmp r1,#0
    a.branch('missing', cond=0x0)  # exact "LOADING" + NUL
    a.label('ready_item')
    a.emit(0xE1570006)
    a.emit(0xB2877001)             # addlt r7,r7,#1
    a.branch('scan', cond=0xB)
    a.branch('prefetch')
    a.label('missing')
    a.emit(0xE3A00000 | ROM_LIST_PAGE_WAIT_DELAY_MS)
    a.branch(delay_va, link=True)
    a.emit(0xE2588001)             # subs r8,r8,#1
    a.branch('retry', cond=0x1)
    a.branch('done')               # timed out: do not queue a second worker

    a.label('prefetch')
    if ROM_LIST_PAGE_PREFETCH_ENABLED:
        a.emit(0xE594900C)         # r9 = current page-selection anchor
        a.branch(get_rows_va, link=True)
        a.emit(0xE1A08000)         # r8 = configured visible row count
        if prefetch_forward:
            # This wrapper serves page-up/L2.  The stock forward loader starts
            # exactly at its anchor, so warm selection-row_count (clamped 0).
            a.emit(0xE3590000)
            a.branch('done', cond=0x0)  # already at the list start
            a.emit(0xE1590008)     # selection >= row count?
            a.emit(0x20497008)     # subhs r7,r9,r8
            a.emit(0x33A07000)     # movlo r7,#0
        else:
            # This wrapper serves page-down/R2.  The stock backward loader
            # starts at anchor-(rows-1).  selection+rows therefore starts its
            # worker at selection+1, exactly after the current viewport.
            a.emit(0xE2897001)     # r7 = adjacent start = selection + 1
            a.emit(0xE5943178)     # total logical rows
            a.emit(0xE1570003)
            a.branch('done', cond=0xA)  # adjacent start >= total
            a.emit(0xE0897008)     # r7 = backward-loader anchor
        a.emit(0xE584700C)
        a.emit(0xE1A00004)
        a.branch(original_load_va, link=True)
        a.emit(0xE584900C)         # restore visible selection immediately
    a.label('done')
    a.emit(0xE1A0000A)             # preserve stock loader result
    a.emit(0xE8BD87F0)             # pop {r4-r10,pc}
    return a.finish()


def build_rom_list_wrap_wait_gate(
        base_va: int, original_load_va: int, delay_va: int, c_str_va: int,
        get_rows_va: int, wrap_to_start: bool) -> bytes:
    """Wait on the destination rows only when one-row navigation wraps.

    One-row Down/Up changes TextMenu::selected before invoking the async ROM
    loader, but stock does not publish the new viewport start/end at that
    point.  Therefore this gate derives the wrapped destination directly from
    selected, total, and the effective row count instead of consulting the
    stale +0x10/+0x14 viewport fields.  Non-wrap moves use the original loader
    directly.
    """
    if ROM_LIST_WRAP_WAIT_MAX_MS % ROM_LIST_WRAP_WAIT_DELAY_MS:
        raise ValueError('ROM-list wrap-wait bound must divide evenly')
    attempts = ROM_LIST_WRAP_WAIT_MAX_MS // ROM_LIST_WRAP_WAIT_DELAY_MS
    if not 0 < attempts <= 255:
        raise ValueError('ROM-list wrap-wait attempts must fit MOV immediate')
    if not 0 < ROM_LIST_WRAP_WAIT_DELAY_MS <= 255:
        raise ValueError('ROM-list wrap-wait delay must fit MOV immediate')

    a = ArmBuilder(base_va)
    a.emit(0xE92D47F0)             # push {r4-r10,lr}; 8-byte aligned
    a.emit(0xE1A04000)             # r4 = ROM-list object
    a.emit(0xE5949178)             # r9 = total logical rows
    a.emit(0xE3590000)
    a.branch('stock', cond=0x0)    # empty/unpublished total: fail open

    if wrap_to_start:
        a.emit(0xE594300C)         # selected index
        a.emit(0xE3530000)
        a.branch('stock', cond=0x1) # only exact last->first wrap
    else:
        a.emit(0xE2493001)         # r3 = final index = total - 1
        a.emit(0xE594200C)         # selected index
        a.emit(0xE1520003)
        a.branch('stock', cond=0x1) # only exact first->last wrap

    # Queue the real stock destination worker first.
    a.emit(0xE1A00004)
    a.branch(original_load_va, link=True)
    a.emit(0xE1A0A000)             # r10 = stock loader result

    # Compute the destination window independently from stale viewport fields.
    a.branch(get_rows_va, link=True)
    a.emit(0xE1A08000)             # r8 = effective visible row count
    a.emit(0xE3580000)
    a.branch('done', cond=0x0)
    if wrap_to_start:
        a.emit(0xE3A05000)         # r5 = first = 0
        a.emit(0xE2486001)         # r6 = rows - 1
        a.emit(0xE2493001)         # r3 = total - 1
        a.emit(0xE1560003)
        a.emit(0x81A06003)         # movhi r6,r3 = min(rows-1,total-1)
    else:
        a.emit(0xE2496001)         # r6 = last = total - 1
        a.emit(0xE2483001)         # r3 = rows - 1
        a.emit(0xE1560003)
        a.emit(0x20465003)         # subhs r5,r6,r3
        a.emit(0x33A05000)         # movlo r5,#0

    a.emit(0xE3A08000 | attempts)  # r8 = bounded retry count
    a.label('retry')
    a.emit(0xE1A07005)             # r7 = first destination index
    a.label('scan')
    a.emit(0xE5943000)             # vtable
    a.emit(0xE5933014)             # virtual item(index) accessor
    a.emit(0xE1A01007)
    a.emit(0xE1A00004)
    a.emit(0xE12FFF33)             # blx r3
    a.emit(0xE3500000)
    a.branch('missing', cond=0x0)
    a.branch(c_str_va, link=True)
    a.emit(0xE3500000)
    a.branch('missing', cond=0x0)
    for off, ch in enumerate(b'LOADING'):
        a.emit(0xE5D01000 | off)
        a.emit(0xE3510000 | ch)
        a.branch('ready_item', cond=0x1)
    a.emit(0xE5D01007)
    a.emit(0xE3510000)
    a.branch('missing', cond=0x0)
    a.label('ready_item')
    a.emit(0xE1570006)
    a.emit(0xB2877001)             # addlt r7,r7,#1
    a.branch('scan', cond=0xB)
    a.branch('done')

    a.label('missing')
    a.emit(0xE3A00000 | ROM_LIST_WRAP_WAIT_DELAY_MS)
    a.branch(delay_va, link=True)
    a.emit(0xE2588001)
    a.branch('retry', cond=0x1)
    a.branch('done')

    a.label('stock')
    a.emit(0xE1A00004)
    a.branch(original_load_va, link=True)
    a.emit(0xE1A0A000)
    a.label('done')
    a.emit(0xE1A0000A)             # preserve stock loader result
    a.emit(0xE8BD87F0)
    return a.finish()


def build_backward_start_r3(base_va: int, get_rows_va: int) -> bytes:
    a = ArmBuilder(base_va)
    a.emit(0xE92D5017)             # push {r0-r2,r4,ip,lr}
    a.emit(0xE1A04003)             # mov r4,r3 selected index
    a.branch(get_rows_va, link=True)
    a.emit(0xE0443000)             # sub r3,r4,r0
    a.emit(0xE2833001)             # add r3,r3,#1 = selected-(rows-1)
    a.emit(0xE8BD9017)             # pop {r0-r2,r4,ip,pc}
    return a.finish()


def build_rect_r1(base_va: int, data_va: int) -> bytes:
    """Use a cropped selection source only for a non-stock tagged game list."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D501D)             # push {r0,r2,r3,r4,ip,lr}
    a.ldr_literal(4, data_va)       # r4 = cache; selection rect is cache+8
    a.emit(0xE3A01000)             # r1 = NULL stock source rectangle
    a.emit(0xE3A02006)             # r2 = stock row count unless tagged
    a.emit(0xE51B0050)             # r0 = current TextMenu object
    a.emit(0xE594C040)             # ip = active game-list pointer
    a.emit(0xE150000C)             # cmp current,active
    a.emit(0x05942000)             # ldreq r2,[r4] configured rows
    a.emit(0xE3520006)             # cmp rows,#6
    a.emit(0x12841008)             # addne r1,r4,#8
    a.emit(0xE8BD901D)             # pop {r0,r2,r3,r4,ip,pc}; r1 survives
    return a.finish()


def build_icon_rect_r1(base_va: int, data_va: int) -> bytes:
    """
    Crop oversized per-row icons vertically to the cached row height.

    Entry registers are the SDL_UpperBlit arguments except r1:
      r0 = source icon surface
      r2 = destination surface
      r3 = destination SDL_Rect

    If source.h <= rowHeight, return r1 = NULL (stock full-surface blit).
    Otherwise return a centered SDL_Rect {0, cropY, source.w, rowHeight}
    and shift dstrect.y down by cropY. This preserves the icon's original
    vertical centering while clipping equally from its top and bottom.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D507D)             # push {r0,r2-r6,ip,lr}
    a.emit(0xE1A04000)             # mov r4,r0 source surface
    a.emit(0xE1A05003)             # mov r5,r3 destination rect
    a.ldr_literal(6, data_va)       # r6 = cache base
    a.emit(0xE5960000)             # r0 = configured rows
    a.emit(0xE3500006)             # cmp rows,#6
    a.branch('stock', cond=0x0)    # default geometry: preserve stock blit
    a.emit(0xE51B1050)             # r1 = current TextMenu object
    a.emit(0xE596C040)             # ip = active game-list pointer
    a.emit(0xE151000C)             # cmp current,active
    a.branch('stock', cond=0x1)    # Language/unrelated menu: full stock icon
    a.emit(0xE5960004)             # ldr r0,[r6,#4] cached row height
    a.emit(0xE594100C)             # ldr r1,[r4,#12] source surface height
    a.emit(0xE1510000)             # cmp r1,r0
    a.branch('stock', cond=0xD)    # ble stock
    a.emit(0xE0411000)             # sub r1,r1,r0 = excess height
    a.emit(0xE1A010A1)             # lsr r1,r1,#1 = centered crop Y
    a.emit(0xE2866020)             # add r6,r6,#32 = icon SDL_Rect
    a.emit(0xE3A0C000)             # mov ip,#0
    a.emit(0xE1C6C0B0)             # strh ip,[r6,#0] rect.x = 0
    a.emit(0xE1C610B2)             # strh r1,[r6,#2] rect.y = cropY
    a.emit(0xE594C008)             # ldr ip,[r4,#8] source width
    a.emit(0xE1C6C0B4)             # strh ip,[r6,#4] rect.w
    a.emit(0xE1C600B6)             # strh r0,[r6,#6] rect.h = rowHeight
    a.emit(0xE1D5C0F2)             # ldrsh ip,[r5,#2] dstrect.y
    a.emit(0xE08CC001)             # add ip,ip,r1
    a.emit(0xE1C5C0B2)             # strh ip,[r5,#2]
    a.emit(0xE1A01006)             # mov r1,r6 source rect
    a.branch('done')
    a.label('stock')
    a.emit(0xE3A01000)             # mov r1,#0
    a.label('done')
    a.emit(0xE8BD907D)             # pop {r0,r2-r6,ip,pc}; r1 survives
    return a.finish()




def build_game_icon_spacer_crop_guard(base_va: int, continue_va: int) -> bytes:
    """Preserve deliberately wide icon-game assets as horizontal spacers.

    The stock alternate game-icon path constructs a square source rectangle.
    The row patch normally changes that square from 71x71 to rowHeight x
    rowHeight. Only an obvious layout spacer -- at least 120 pixels wide and
    at least three times as wide as it is tall -- keeps the complete source
    width and crops only the vertical excess to rowHeight. The
    helper runs before the existing square-rect block; non-spacer icons replay
    the displaced load and continue through the established code unchanged.

    Entry r2 is the already-computed square/row-height extent used by the
    surrounding renderer. No calls are made, so this does not introduce a new
    ownership or lifetime boundary.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D5013)             # push {r0,r1,r4,ip,lr}; no nested calls
    a.emit(0xE51B4028)             # r4 = current TextItem
    a.emit(0xE3540000)
    a.branch('normal', cond=0x0)
    a.emit(0xE5944070)             # r4 = icon-game SDL_Surface *
    a.emit(0xE3540000)
    a.branch('normal', cond=0x0)
    a.emit(0xE5940008)             # r0 = source width
    a.emit(0xE3500078)             # width >= 120 px
    a.branch('normal', cond=0xB)
    a.emit(0xE594100C)             # r1 = source height
    a.emit(0xE081C001)             # ip = 2 * source height
    a.emit(0xE08CC001)             # ip = 3 * source height
    a.emit(0xE150000C)
    a.branch('normal', cond=0x3)   # blo: ordinary icon, keep square path

    # Replay the first stock instruction group that publishes the destination
    # row Y value, then build source SDL_Rect at fp-0x3c.
    a.emit(0xE51B3030)             # ldr r3,[fp,#-0x30]
    a.emit(0xE6BF3073)             # sxth r3,r3
    a.emit(0xE14B34B6)             # strh r3,[fp,#-70]
    a.emit(0xE3A0C000)
    a.emit(0xE14BC3BC)             # source rect x = 0 at fp-0x3c

    # Center-crop vertically only when the source is taller than rowHeight.
    a.emit(0xE1510002)             # cmp source_h,rowHeight
    a.emit(0xD3A0C000)             # movle ip,#0
    a.emit(0xC041C002)             # subgt ip,r1,r2
    a.emit(0xC1A0C0AC)             # lsrgt ip,ip,#1
    a.emit(0xE14BC3BA)             # source rect y
    a.emit(0xE14B03B8)             # source rect w = full source width
    a.emit(0xD1A03001)             # movle r3,r1 (source shorter than row)
    a.emit(0xC1A03002)             # movgt r3,r2 (crop to row height)
    a.emit(0xE14B33B6)             # source rect h
    a.emit(0xE8BD5013)             # restore preserved registers
    a.emit(0xE1A03002)             # match established block's final r3=rowHeight
    a.branch(continue_va)

    a.label('normal')
    a.emit(0xE8BD5013)
    a.emit(0xE51B3030)             # displaced stock ldr r3,[fp,#-0x30]
    a.emit(0xE12FFF1E)             # bx lr -> continue square block
    return a.finish()


def build_cached_skin_loader_wrapper(base_va: int, state_va: int,
                                     slot_offset: int,
                                     original_loader_va: int,
                                     sdl_convert_surface_va: int,
                                     strlen_va: int, strcmp_va: int,
                                     memcpy_va: int) -> bytes:
    """Cache one verified skin decode while preserving per-window ownership.

    Cache entries are process-retained *source* surfaces.  Every constructor
    still receives its own SDL_Surface clone, so stock destructors and runtime
    theme-reload paths may free/replace members exactly as before.  The first
    observed active-theme prefix owns the cache; a later prefix change bypasses
    reuse instead of mixing theme lifetimes.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D47F0)             # push {r4-r10,lr}; 32-byte aligned frame
    a.emit(0xE1A04000)             # r4=r0 theme prefix
    a.emit(0xE1A05001)             # r5=r1 fallback prefix
    a.emit(0xE1A06002)             # r6=r2 relative path
    a.emit(0xE1A07003)             # r7=r3 debug/log arg
    a.ldr_literal(8, state_va)      # r8=cache state/theme-path buffer
    a.emit(0xE3540000)             # cmp r4,#0
    a.branch('call_nocache', cond=0x0)
    a.emit(0xE5D89000)             # r9=first cached theme-path byte
    a.emit(0xE3590000)
    a.branch('key_known', cond=0x1)
    # First cacheable call: require a bounded path then retain an exact copy.
    a.emit(0xE1A00004)             # r0=current theme path
    a.branch(strlen_va, link=True)
    a.emit(0xE35000FF)             # <=255 bytes plus terminator
    a.branch('call_nocache', cond=0x8)  # bhi
    a.emit(0xE2802001)             # r2=len+1
    a.emit(0xE1A01004)             # r1=source path
    a.emit(0xE1A00008)             # r0=state theme buffer
    a.branch(memcpy_va, link=True)
    a.branch('cache')
    a.label('key_known')
    a.emit(0xE1A01004)             # r1=current theme path
    a.emit(0xE1A00008)             # r0=cached exact path
    a.branch(strcmp_va, link=True)
    a.emit(0xE3500000)
    a.branch('call_nocache', cond=0x1)
    a.label('cache')
    # Use a literal absolute slot address.  ARM data-processing immediates
    # are rotated 8-bit encodings; OR-ing raw offsets >=256 into ADD
    # mis-encodes them (the PI startup-crash bug).
    a.ldr_literal(10, state_va + slot_offset)
    a.emit(0xE59A0000)             # r0=cached source
    a.emit(0xE3500000)
    a.branch('cache_miss', cond=0x0)
    # Clone cached source for independent stock ownership.
    a.emit(0xE5901004)             # r1=surface->format
    a.emit(0xE3A02000)             # r2=flags 0
    a.branch(sdl_convert_surface_va, link=True)
    a.emit(0xE3500000)
    a.branch('done', cond=0x1)     # clone success
    # Allocation failure: fall back to a normal decode rather than returning
    # NULL while a valid cached source exists.
    a.branch('call_nocache')
    a.label('cache_miss')
    a.emit(0xE24DD008)
    a.emit(0xE3A0C000)
    a.emit(0xE58DC000)
    a.emit(0xE1A00004)
    a.emit(0xE1A01005)
    a.emit(0xE1A02006)
    a.emit(0xE1A03007)
    a.branch(original_loader_va, link=True)
    a.emit(0xE28DD008)
    a.emit(0xE3500000)
    a.branch('done', cond=0x0)
    a.emit(0xE1A09000)             # r9=first window-owned result
    a.emit(0xE5901004)             # r1=result->format
    a.emit(0xE3A02000)
    a.branch(sdl_convert_surface_va, link=True)
    a.emit(0xE3500000)
    a.emit(0x158A0000)             # cache independent clone on success
    a.emit(0xE1A00009)             # return first window-owned result
    a.branch('done')
    a.label('call_nocache')
    a.emit(0xE24DD008)
    a.emit(0xE3A0C000)
    a.emit(0xE58DC000)
    a.emit(0xE1A00004)
    a.emit(0xE1A01005)
    a.emit(0xE1A02006)
    a.emit(0xE1A03007)
    a.branch(original_loader_va, link=True)
    a.emit(0xE28DD008)
    a.label('done')
    a.emit(0xE8BD87F0)
    return a.finish()


def build_cached_game_list_bg_loader_wrapper(
        base_va: int, state_va: int, original_loader_va: int,
        row_state_va: int | None, get_rows_va: int | None,
        sdl_convert_surface_va: int, strlen_va: int, strcmp_va: int,
        memcpy_va: int) -> bytes:
    """Cache selection-background decode with independent window surfaces.

    Stock and tagged ``bg-list-s_N`` sources use separate cache slots.  The
    numbered source is pinned to the first observed row count; if that runtime
    configuration changes later, tagged constructors bypass reuse instead of
    serving a background with stale geometry.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D47F0)             # push {r4-r10,lr}
    a.emit(0xE1A04000)
    a.emit(0xE1A05001)
    a.emit(0xE1A06002)
    a.emit(0xE1A07003)
    a.ldr_literal(8, state_va)
    a.emit(0xE3540000)             # NULL theme prefix -> no cache
    a.branch('call_nocache', cond=0x0)
    a.emit(0xE5D89000)             # first cached theme-path byte
    a.emit(0xE3590000)
    a.branch('key_known', cond=0x1)
    a.emit(0xE1A00004)
    a.branch(strlen_va, link=True)
    a.emit(0xE35000FF)
    a.branch('call_nocache', cond=0x8)  # bhi
    a.emit(0xE2802001)
    a.emit(0xE1A01004)
    a.emit(0xE1A00008)
    a.branch(memcpy_va, link=True)
    a.branch('pick_slot')
    a.label('key_known')
    a.emit(0xE1A01004)
    a.emit(0xE1A00008)
    a.branch(strcmp_va, link=True)
    a.emit(0xE3500000)
    a.branch('call_nocache', cond=0x1)
    a.label('pick_slot')
    a.ldr_literal(10, state_va + SKIN_CACHE_BG_STOCK_OFF)
    if row_state_va is not None:
        if get_rows_va is None:
            raise ValueError('tagged game-list background cache needs get_rows')
        a.ldr_literal(0, row_state_va)
        a.emit(0xE590003C)         # pending tagged TextMenu
        a.emit(0xE51B1010)         # constructor this
        a.emit(0xE1510000)
        a.branch('slot_ready', cond=0x1)
        a.ldr_literal(10, state_va + SKIN_CACHE_BG_GAME_OFF)
        a.branch(get_rows_va, link=True)
        a.ldr_literal(9, state_va + SKIN_CACHE_BG_GAME_ROWS_OFF)
        a.emit(0xE5991000)         # pinned numbered-bg row count
        a.emit(0xE3510000)
        a.branch('rows_known', cond=0x1)
        a.emit(0xE5890000)         # pin first numbered-bg row count
        a.branch('slot_ready')
        a.label('rows_known')
        a.emit(0xE1510000)
        a.branch('call_nocache', cond=0x1)
    a.label('slot_ready')
    a.emit(0xE59A0000)
    a.emit(0xE3500000)
    a.branch('cache_miss', cond=0x0)
    a.emit(0xE5901004)             # cached->format
    a.emit(0xE3A02000)
    a.branch(sdl_convert_surface_va, link=True)
    a.emit(0xE3500000)
    a.branch('done', cond=0x1)
    a.branch('call_nocache')
    a.label('cache_miss')
    a.emit(0xE24DD008)
    a.emit(0xE3A0C000)
    a.emit(0xE58DC000)
    a.emit(0xE1A00004)
    a.emit(0xE1A01005)
    a.emit(0xE1A02006)
    a.emit(0xE1A03007)
    a.branch(original_loader_va, link=True)
    a.emit(0xE28DD008)
    a.emit(0xE3500000)
    a.branch('done', cond=0x0)
    a.emit(0xE1A09000)
    a.emit(0xE5901004)
    a.emit(0xE3A02000)
    a.branch(sdl_convert_surface_va, link=True)
    a.emit(0xE3500000)
    a.emit(0x158A0000)
    a.emit(0xE1A00009)
    a.branch('done')
    a.label('call_nocache')
    a.emit(0xE24DD008)
    a.emit(0xE3A0C000)
    a.emit(0xE58DC000)
    a.emit(0xE1A00004)
    a.emit(0xE1A01005)
    a.emit(0xE1A02006)
    a.emit(0xE1A03007)
    a.branch(original_loader_va, link=True)
    a.emit(0xE28DD008)
    a.label('done')
    a.emit(0xE8BD87F0)
    return a.finish()


def build_favourite_refresh_gate(base_va: int, dirty_va: int,
                                 original_va: int) -> bytes:
    """Run the O(n) mode-2 deferred-delete sweep only after a real setter."""
    a = ArmBuilder(base_va)
    a.emit(0xE3510002)             # cmp r1,#2
    a.branch(original_va, cond=0x1)  # non-Favorite mode -> stock
    a.ldr_literal(12, dirty_va)
    a.emit(0xE59C2000)             # r2=dirty
    a.emit(0xE3520000)
    a.emit(0x03A00000)             # moveq r0,#0 (stock no-removal result)
    a.emit(0x012FFF1E)             # bxeq lr
    a.emit(0xE3A02000)
    a.emit(0xE58C2000)             # clear before stock sweep
    a.branch(original_va)
    return a.finish()


def build_favourite_refresh_dirty_setter(base_va: int, dirty_va: int,
                                         continue_va: int) -> bytes:
    """Replay TextItem+0x1e=1 and publish a dirty bit without clobbering ABI."""
    a = ArmBuilder(base_va)
    a.emit(FAVOURITE_REFRESH_DIRTY_SET_STOCK)
    a.emit(0xE92D1000)             # push {r12}; no calls, flags unchanged
    a.ldr_literal(12, dirty_va)
    a.emit(0xE58C2000)             # setter's verified r2==1 -> dirty=1
    a.emit(0xE8BD1000)             # pop {r12}
    a.branch(continue_va)
    return a.finish()


def build_game_icon_text_item_wrapper(
        base_va: int, text_item_constructor_va: int) -> bytes:
    """Supply the stock themed icon-game surface, then tail-call TextItem."""
    a = ArmBuilder(base_va)
    a.ldr_literal(2, GAME_ICON_SURFACE_GLOBAL_VA)
    a.emit(0xE5922000)             # ldr r2,[r2]: active theme icon-game surface
    a.branch(text_item_constructor_va)  # preserve caller LR and stack argument
    return a.finish()


def build_game_list_predraw_geometry_fix(
        base_va: int, title_scroll_state_va: int | None = None) -> bytes:
    """Publish stock preview/no-preview child geometry before its first draw.

    The containing game-list window has already computed its local preview-ready
    byte at fp-0x19. Stock later combines that byte with MenuWindow+0x1d and
    writes child TextMenu+4 to either 250 (preview pane active) or 0 (full-width
    list), but only after calling the child's draw virtual. Repeating that exact
    decision before the draw makes the first presentation match all later frames.
    The original post-draw stock write is intentionally retained as a backstop.

    When title scrolling is enabled, publish the same live decision into the
    spare final state word. This lets the marquee ignore stale preview-pane x
    values on selections that currently have no thumbnail.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D5017)             # push {r0-r2,r4,ip,lr}; hook overwrites r3
    a.emit(0xE51B40F0)             # r4 = containing game-list MenuWindow
    a.emit(0xE594000C)             # r0 = child TextMenu
    a.emit(0xE3500000)             # no child -> just replay displaced load
    a.branch('replay', cond=0x0)
    a.emit(0xE5D4101D)             # r1 = stock window preview-layout enable byte
    a.emit(0xE3510000)
    a.emit(0x03A02000)             # moveq r2,#0 (full-width/no-preview)
    a.branch('store', cond=0x0)
    a.emit(0xE55B1019)             # r1 = stock local preview-ready byte [fp-0x19]
    a.emit(0xE3510000)
    a.emit(0x03A02000)             # moveq r2,#0
    a.emit(0x13A02000 | GAME_LIST_PREVIEW_ORIGIN)  # movne r2,#250
    a.label('store')
    if title_scroll_state_va is not None:
        # r2 is the exact stock geometry decision. Save a boolean without
        # disturbing the child x-origin value used immediately below.
        a.emit(0xE3520000)         # cmp r2,#0
        a.emit(0x03A01000)         # moveq r1,#0
        a.emit(0x13A01001)         # movne r1,#1
        a.ldr_literal(12, title_scroll_state_va)
        a.emit(0xE58C1084)         # state+132 = live preview-active flag
    a.emit(0xE5802004)             # child TextMenu x-origin = stock decision
    a.label('replay')
    a.emit(0xE8BD5017)             # pop {r0-r2,r4,ip,lr}
    a.emit(GAME_LIST_PREDRAW_GEOMETRY_STOCK)
    a.emit(0xE12FFF1E)             # bx lr
    return a.finish()


def build_dynamic_fav_position_mode(base_va: int, state_va: int,
                                    path_va: int, access_va: int) -> bytes:
    """Return 0 for fixed(default), 1 for legacy dynamic positioning.

    The presence-only config is checked once per MainUI process. BSS starts at
    zero; cached values are 1=fixed and 2=dynamic so the helper can distinguish
    uninitialized state without another byte/word.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D4010)             # push {r4,lr}; 8-byte aligned
    a.ldr_literal(4, state_va)
    a.emit(0xE5940000)             # cached state
    a.emit(0xE3500000)
    a.branch('cached', cond=0x1)
    a.ldr_literal(0, path_va)
    a.emit(0xE3A01000)             # F_OK
    a.branch(access_va, link=True)
    a.emit(0xE3500000)
    a.emit(0x03A00002)             # exists -> state 2 (dynamic)
    a.emit(0x13A00001)             # missing/error -> state 1 (fixed)
    a.emit(0xE5840000)
    a.label('cached')
    a.emit(0xE2400001)             # return cached-1 => 0 fixed / 1 dynamic
    a.emit(0xE8BD8010)             # pop {r4,pc}
    return a.finish()


def build_favourite_marker_left(base_va: int, mode_va: int) -> bytes:
    """Return the exact current Favorite-marker left edge, or zero.

    Inputs: r0=TextMenu*, r1=row renderer's stock base-x term. The formula is
    identical to the stock sequence at 0x20400..0x20450 except that fixed mode
    substitutes the preview origin (250) for TextMenu+4. Deliberately wide
    icon-game layout spacers (>=120 px and >=3:1) instead force origin zero so
    the marker occupies the far-right stock lane regardless of preview state.
    The marker surface's live decoded width is used, so no PNG dimension is
    assumed.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D4070)             # push {r4-r6,lr}; 8-byte aligned
    a.emit(0xE1A04000)             # r4 = TextMenu
    a.emit(0xE1A05001)             # r5 = base x
    a.emit(0xE5946050)             # r6 = favourite marker SDL_Surface*
    a.emit(0xE3560000)
    a.branch('none', cond=0x0)
    a.emit(0xE5940034)             # packed TextMenu w/h
    a.emit(0xE6FF0070)             # uxth r0,r0 -> width
    a.emit(0xE6FF5075)             # uxth r5,r5 -> stock base term
    a.emit(0xE0800005)             # menu width + base x
    a.emit(0xE5961008)             # marker surface width
    a.emit(0xE6FF1071)             # uxth r1,r1
    a.emit(0xE0406001)             # r6 = right edge before list origin

    # Wide icon-game assets are deliberate horizontal layout spacers. They
    # place title/content to the right of left-anchored artwork, so the normal
    # fixed preview-safe Favorite lane can collide with that content. Detect
    # the same >=120 px and >=3:1 geometry used by the row/icon path and force
    # the stock far-right lane by using origin zero.
    a.ldr_literal(2, GAME_ICON_SURFACE_GLOBAL_VA)
    a.emit(0xE5922000)             # active theme icon-game SDL_Surface*
    a.emit(0xE3520000)
    a.branch('normal_mode', cond=0x0)
    a.emit(0xE5923008)             # r3 = icon width
    a.emit(0xE3530078)             # width >= 120
    a.branch('normal_mode', cond=0xB)
    a.emit(0xE592200C)             # r2 = icon height
    a.emit(0xE1A0C002)             # ip = height
    a.emit(0xE0822002)             # r2 = 2 * height
    a.emit(0xE082200C)             # r2 = 3 * height
    a.emit(0xE1530002)             # cmp width,3*height
    a.branch('normal_mode', cond=0xB)
    a.emit(0xE3A01000)             # wide spacer -> origin 0 (far right)
    a.branch('have_origin')

    a.label('normal_mode')
    a.branch(mode_va, link=True)
    a.emit(0xE3500000)             # dynamic compatibility?
    a.emit(0x15941004)             # ldrne r1,[r4,#4]
    a.emit(0x03A010FA)             # moveq r1,#250
    a.label('have_origin')
    a.emit(0xE0460001)             # subtract x-origin
    a.emit(0xE2400014)             # subtract stock 20px right margin
    a.emit(0xE8BD8070)             # pop {r4-r6,pc}
    a.label('none')
    a.emit(0xE3A00000)
    a.emit(0xE8BD8070)
    return a.finish()


def build_favourite_marker_origin_load(base_va: int, mode_va: int) -> bytes:
    """Replay marker origin with automatic wide-spacer far-right mode.

    Normal themes preserve the existing fixed/dynamic behavior. If the active
    icon-game surface is an obvious layout spacer (>=120 px and >=3:1), origin
    zero is forced so the Favorite marker uses the far-right stock lane.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D5017)             # push {r0-r2,r4,ip,lr}; aligned
    a.emit(0xE1A04003)             # r4 = TextMenu pointer supplied in r3
    a.ldr_literal(0, GAME_ICON_SURFACE_GLOBAL_VA)
    a.emit(0xE5900000)             # active theme icon-game SDL_Surface*
    a.emit(0xE3500000)
    a.branch('normal_mode', cond=0x0)
    a.emit(0xE5901008)             # r1 = icon width
    a.emit(0xE3510078)             # width >= 120
    a.branch('normal_mode', cond=0xB)
    a.emit(0xE590200C)             # r2 = icon height
    a.emit(0xE1A0C002)             # ip = height
    a.emit(0xE0822002)             # r2 = 2 * height
    a.emit(0xE082200C)             # r2 = 3 * height
    a.emit(0xE1510002)             # cmp width,3*height
    a.branch('normal_mode', cond=0xB)
    a.emit(0xE3A03000)             # wide spacer -> origin 0 (far right)
    a.branch('done')
    a.label('normal_mode')
    a.branch(mode_va, link=True)
    a.emit(0xE3500000)
    a.emit(0x15943004)             # ldrne r3,[r4,#4] (dynamic mode)
    a.emit(0x03A030FA)             # moveq r3,#250 (fixed default)
    a.label('done')
    a.emit(0xE8BD5017)
    a.emit(0xE12FFF1E)
    return a.finish()


def build_sdl_clip_api_resolver(base_va: int, state_va: int,
                                get_name_va: int, set_name_va: int,
                                dlsym_va: int) -> bytes:
    """Resolve SDL_GetClipRect/SDL_SetClipRect once through RTLD_DEFAULT.

    Returns r0=SDL_GetClipRect pointer and r1=SDL_SetClipRect pointer. Missing
    symbols are cached as NULL so the title wrapper can fail open to stock.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D4070)             # push {r4-r6,lr}; 16 bytes, aligned
    a.ldr_literal(4, state_va)
    a.emit(0xE5942008)             # initialized?
    a.emit(0xE3520000)
    a.branch('ready', cond=0x1)
    a.emit(0xE3A00000)             # RTLD_DEFAULT
    a.ldr_literal(1, get_name_va)
    a.branch(dlsym_va, link=True)
    a.emit(0xE5840000)             # cache SDL_GetClipRect
    a.emit(0xE3A00000)             # RTLD_DEFAULT
    a.ldr_literal(1, set_name_va)
    a.branch(dlsym_va, link=True)
    a.emit(0xE5840004)             # cache SDL_SetClipRect
    a.emit(0xE3A02001)
    a.emit(0xE5842008)             # initialized = 1
    a.label('ready')
    a.emit(0xE5940000)
    a.emit(0xE5941004)
    a.emit(0xE8BD8070)             # pop {r4-r6,pc}
    return a.finish()


def emit_game_list_right_bound(a: ArmBuilder, surface_reg: int,
                               row_cache_va: int, out_reg: int,
                               rows_reg: int, pad_reg: int,
                               label: str) -> None:
    """Emit one authoritative game-list right edge from the draw surface.

    The physical destination surface width is authoritative. Right padding is
    20 px through row 9, then max(15, 29-rows). Folder/game/no-icon title
    paths therefore share one absolute right edge regardless of their left-X
    geometry.
    """
    a.emit(0xE5900008 | (surface_reg << 16) | (out_reg << 12))
    a.ldr_literal(rows_reg, row_cache_va)
    a.emit(0xE5900000 | (rows_reg << 16) | (rows_reg << 12))
    a.emit(0xE3A00014 | (pad_reg << 12))
    a.emit(0xE3500009 | (rows_reg << 16))
    a.branch(label, cond=0xD)      # rows <= 9 -> 20 px
    a.emit(0xE3A0001D | (pad_reg << 12))
    a.emit(0xE0400000 | (pad_reg << 16) | (pad_reg << 12) | rows_reg)
    a.emit(0xE350000F | (pad_reg << 16))
    a.emit(0xB3A0000F | (pad_reg << 12))
    a.label(label)
    a.emit(0xE0400000 | (out_reg << 16) | (out_reg << 12) | pad_reg)


def build_favourite_title_renderer_wrapper(
        base_va: int, mode_va: int, marker_left_va: int,
        clip_resolver_va: int, stock_renderer_va: int,
        row_cache_va: int) -> bytes:
    """Clip tagged game-list titles to the renderer's own label box.

    Entry ABI is exactly the stock row-title call: r0-r3 plus seven 32-bit
    stack arguments. The caller's r11 is deliberately retained so the wrapper
    can read the current TextItem and row base-x term. The seven stack words
    are copied verbatim into this wrapper's outgoing argument area before
    calling stock 0x1EDE4.

    MainUI's final SDL_UpperBlit uses a NULL source rectangle and therefore
    does not treat the destination rectangle width as a clipping boundary.
    For tagged game lists, temporarily intersect the actual destination
    surface clip with one row-count-aware right edge derived from the real
    destination surface width. In fixed Favorite-marker mode that bound is
    narrowed further to 6 px before
    the live marker. The exact original SDL clip is restored after the stock
    renderer returns. Untagged TextMenu users and API-resolution failures keep
    the stock path.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D47F0)             # push {r4-r10,lr}; 32 bytes, aligned
    a.emit(0xE24DD040)             # 64-byte frame; sp remains 8-byte aligned
    a.emit(0xE1A04000)             # r4 = TextMenu
    a.emit(0xE1A05001)             # r5 = destination SDL_Surface
    a.emit(0xE1A06002)             # r6 = font
    a.emit(0xE1A07003)             # r7 = label rect x/y packed word
    a.emit(0xE1A0800B)             # r8 = caller fp (row renderer)

    # Forward the seven original stack words verbatim. Original entry sp is
    # current sp + 64(frame) + 32(push) = +96.
    for off in range(0, 28, 4):
        a.emit(0xE59D3060 | off)    # ldr r3,[sp,#96+off]
        a.emit(0xE58D3000 | off)    # str r3,[sp,#off]

    # Only constructor-tagged game-list TextMenus get the new row-bound clip.
    a.ldr_literal(9, row_cache_va)
    a.emit(0xE5990040)             # active tagged game-list object
    a.emit(0xE1540000)             # cmp TextMenu,active
    a.branch('tagged', cond=0x0)
    a.emit(0xE5990044)             # previous tagged game-list object
    a.emit(0xE1540000)
    a.branch('stock', cond=0x1)
    a.label('tagged')

    # One absolute right edge for every tagged game-list title. Derive it
    # from the actual destination surface, not from the row-kind-specific
    # label width. This is the same formula used by the marquee cache below.
    emit_game_list_right_bound(
        a, surface_reg=5, row_cache_va=row_cache_va, out_reg=9,
        rows_reg=0, pad_reg=1, label='clip_outer_done')
    a.emit(0xE3590000)
    a.branch('stock', cond=0xD)

    # Fixed Favorite-marker mode may narrow, but never widen, the row bound.
    # Dynamic compatibility mode keeps only the base label-box clip.
    a.branch(mode_va, link=True)
    a.emit(0xE3500000)
    a.branch('bound_ready', cond=0x1)
    a.emit(0xE5180028)             # current TextItem
    a.emit(0xE3500000)
    a.branch('bound_ready', cond=0x0)
    a.emit(0xE5D0001D)             # Favorite byte
    a.emit(0xE3500000)
    a.branch('bound_ready', cond=0x0)
    a.emit(0xE5950050)             # TextMenu->favorite marker surface
    a.emit(0xE3500000)
    a.branch('bound_ready', cond=0x0)
    a.emit(0xE1A00004)
    a.emit(0xE518102C)             # row renderer stock base-x term
    a.branch(marker_left_va, link=True)
    a.emit(0xE2500006)             # marker_left - 6, set flags
    a.branch('bound_ready', cond=0xD)
    a.emit(0xE1590000)             # cmp label bound, marker bound
    a.emit(0xC1A09000)             # movgt r9,r0 -> min(bound,marker)
    a.label('bound_ready')

    # Resolve public SDL clip APIs once. r0=get, r1=set.
    a.branch(clip_resolver_va, link=True)
    a.emit(0xE3500000)
    a.branch('stock', cond=0x0)
    a.emit(0xE3510000)
    a.branch('stock', cond=0x0)
    a.emit(0xE1A03000)             # r3 = SDL_GetClipRect function pointer
    a.emit(0xE1A0A001)             # r10 = SDL_SetClipRect function pointer

    # saved rect at sp+32, current rect at sp+40.
    a.emit(0xE1A00005)
    a.emit(0xE28D1020)
    a.emit(0xE12FFF33)             # SDL_GetClipRect(dest,&saved)

    for load_word, store_word in (
            (0xE1DD02B0, 0xE1CD02B8),
            (0xE1DD02B2, 0xE1CD02BA),
            (0xE1DD02B4, 0xE1CD02BC),
            (0xE1DD02B6, 0xE1CD02BE),
    ):
        a.emit(load_word)
        a.emit(store_word)

    # Intersect current clip with (-inf, bound). Never extend.
    a.emit(0xE1DD02F8)             # current clip x (signed 16-bit)
    a.emit(0xE0591000)             # available = bound - current.x
    a.emit(0xD3A01000)             # <=0 -> zero width
    a.emit(0xE1DD22BC)             # current clip width
    a.emit(0xE1510002)
    a.branch('clip_ready', cond=0x2)
    a.emit(0xE1CD12BC)             # narrow current.w
    a.label('clip_ready')

    a.emit(0xE1A00005)
    a.emit(0xE28D1028)
    a.emit(0xE12FFF3A)             # SDL_SetClipRect(dest,&current)

    a.emit(0xE1A00004)
    a.emit(0xE1A01005)
    a.emit(0xE1A02006)
    a.emit(0xE1A03007)
    a.branch(stock_renderer_va, link=True)
    a.emit(0xE1A09000)             # preserve stock return

    a.emit(0xE1A00005)
    a.emit(0xE28D1020)
    a.emit(0xE12FFF3A)             # restore exact original clip
    a.emit(0xE1A00009)
    a.branch('done')

    a.label('stock')
    a.emit(0xE1A00004)
    a.emit(0xE1A01005)
    a.emit(0xE1A02006)
    a.emit(0xE1A03007)
    a.branch(stock_renderer_va, link=True)

    a.label('done')
    a.emit(0xE28DD040)
    a.emit(0xE8BD87F0)
    return a.finish()


def build_dynamic_row_padding(
        base_va: int, data_va: int,
        icon_left_margin_state_va: int) -> tuple[bytes, dict[str, int]]:
    """Return renderer entry points for custom-row horizontal geometry.

    Keep the five established renderer modes in their original semantic
    order and append the generic-icon destination hook as mode 5.

    ``gamelist.iconLeftMargin`` is one shared absolute theme-author margin for
    folder and game rows.  Internally, MainUI's existing row-count-dependent
    game-vs-generic destination compensation is retained automatically so both
    icon types move as one visually aligned layout rather than exposing two
    separate margins to the theme.

    State is 0=unset and N+1=explicit margin N (0..300).  Missing settings use
    the existing stock-compatible geometry.  Obvious wide ``icon-game.png`` spacers are
    >=120 px and >=3:1 and retain real width.
    """
    a = ArmBuilder(base_va)
    entry_names = (
        'item_text', 'game_icon_x', 'game_text', 'no_icon_text',
        'text_width', 'item_icon_x', 'game_text_width')
    for mode, name in enumerate(entry_names):
        a.label(name)
        a.emit(0xE3A0C000 | mode)  # mov ip,#mode
        a.branch('common')

    a.label('common')
    a.emit(0xE92D51F7)             # push {r0-r2,r4-r8,ip,lr}; 40 bytes/aligned
    a.emit(0xE1A0400C)             # r4 = mode
    a.ldr_literal(7, data_va)       # r7 = shared row cache
    a.emit(0xE51B0050)             # current TextMenu object
    a.emit(0xE5971040)             # active tagged game-list object
    a.emit(0xE1500001)
    a.branch('tagged', cond=0x0)
    a.emit(0xE5971044)             # previous tagged game-list object
    a.emit(0xE1500001)
    a.branch('stock', cond=0x1)
    a.label('tagged')
    a.emit(0xE5975000)             # r5 = configured rows
    a.emit(0xE5976004)             # r6 = cached row height
    a.ldr_literal(8, icon_left_margin_state_va)
    a.emit(0xE5988000)             # r8 = 0 unset, base margin+1 explicit
    a.emit(0xE3550007)
    a.branch('dense_rows', cond=0xC)  # rows > 7
    a.emit(0xE3580000)
    a.branch('stock', cond=0x0)    # <=7 without override stays exact stock
    a.branch('custom_stock')

    a.label('dense_rows')
    # r1 = normal game-icon inset: stock 20 through row 9, then
    # max(15, 29 - rows).  Generic/folder inset remains stock 5.
    a.emit(0xE3A01014)
    a.emit(0xE3550009)
    a.branch('outer_done', cond=0xD)
    a.emit(0xE3A0101D)
    a.emit(0xE0411005)
    a.emit(0xE351000F)
    a.emit(0xB3A0100F)
    a.label('outer_done')

    # r2 = max(5, 22 - rows): row 8 => 14, row 17+ => 5.
    a.emit(0xE3A02016)
    a.emit(0xE0422005)
    a.emit(0xE3520005)
    a.emit(0xB3A02005)

    a.emit(0xE3540000)
    a.branch('dynamic_item_text', cond=0x0)
    a.emit(0xE3540001)
    a.branch('dynamic_game_icon_x', cond=0x0)
    a.emit(0xE3540002)
    a.branch('dynamic_game_text', cond=0x0)
    a.emit(0xE3540003)
    a.branch('dynamic_no_icon_text', cond=0x0)
    a.emit(0xE3540004)
    a.branch('dynamic_width', cond=0x0)
    a.emit(0xE3540005)
    a.branch('dynamic_item_icon_x', cond=0x0)
    a.branch('dynamic_game_width')

    a.label('dynamic_item_icon_x')
    # r0 = effective generic/folder left inset.
    a.emit(0xE3580000)
    a.emit(0x12480001)             # subne r0,r8,#1 = explicit base margin
    a.emit(0x03A00005)             # moveq r0,#5 = stock generic inset
    a.emit(0xE0833000)             # result x += inset
    a.branch('done')

    a.label('dynamic_item_text')
    # r3 already contains row_x + actual generic-icon width.
    a.emit(0xE3580000)
    a.emit(0x12480001)             # explicit base margin
    a.emit(0x03A00005)             # stock generic inset
    a.emit(0xE0833000)
    a.emit(0xE0833002)             # post-icon gap
    a.branch('done')

    a.label('dynamic_game_icon_x')
    # r0 = effective game inset.  Explicit iconLeftMargin is the folder/base
    # inset; preserve the current default game-vs-folder delta (r1 - 5).
    a.emit(0xE3580000)
    a.branch('dynamic_game_icon_default', cond=0x0)
    a.emit(0xE2410005)             # r0 = default game inset - stock folder 5
    a.emit(0xE0800008)             # + encoded explicit base margin
    a.emit(0xE2400001)             # decode N+1 -> N
    a.branch('dynamic_game_icon_have_inset')
    a.label('dynamic_game_icon_default')
    a.emit(0xE1A00001)             # r0 = default game inset
    a.label('dynamic_game_icon_have_inset')
    a.emit(0xE0833000)
    a.branch('done')

    a.label('dynamic_game_text')
    # Normal icon width is row height; obvious layout spacers use real width.
    a.emit(0xE1A00006)             # r0 = normal icon width = row height
    a.emit(0xE51B5028)             # r5 = current row item
    a.emit(0xE3550000)
    a.branch('game_text_width_ready', cond=0x0)
    a.emit(0xE595C020)             # generic item icon surface
    a.emit(0xE35C0000)
    a.branch('game_text_have_surface', cond=0x1)
    a.emit(0xE595C070)             # DBCached icon-game surface
    a.label('game_text_have_surface')
    a.emit(0xE35C0000)
    a.branch('game_text_width_ready', cond=0x0)
    a.emit(0xE59C0008)             # source width
    a.emit(0xE3500078)             # width >= 120?
    a.emit(0xB1A00006)             # no: normal row-height slot
    a.branch('game_text_width_ready', cond=0xB)
    a.emit(0xE59C500C)             # source height
    a.emit(0xE085C005)             # ip = 2*height
    a.emit(0xE08CC005)             # ip = 3*height
    a.emit(0xE150000C)
    a.emit(0x31A00006)             # width < 3*h -> normal row-height slot
    a.label('game_text_width_ready')
    a.emit(0xE0833000)             # chosen icon/spacer width
    # Apply effective game inset after consuming r0 as icon width.
    a.emit(0xE3580000)
    a.branch('game_text_default_left', cond=0x0)
    a.emit(0xE2410005)             # default game-folder delta
    a.emit(0xE0800008)
    a.emit(0xE2400001)
    a.emit(0xE0833000)
    a.emit(0xE0833002)
    a.branch('done')
    a.label('game_text_default_left')
    a.emit(0xE0833001)             # established game left padding
    a.emit(0xE0833002)             # established post-icon gap
    a.branch('done')

    a.label('dynamic_no_icon_text')
    a.emit(0xE0833001)             # established geometry; no iconLeftMargin involvement
    a.branch('done')

    a.label('dynamic_game_width')
    # Game-icon rows need a width calculation that mirrors dynamic_game_text.
    # Favorites/Recent expose icon-game through TextItem+0x20; DBCached ROM
    # rows use +0x70. Normal icons consume one row-height slot, while an
    # obvious wide spacer consumes its complete decoded source width.
    #
    # IMPORTANT: initialize the default width before touching the current item
    # and keep the TextItem pointer in ip.  r5 still contains the configured
    # row count on entry to this mode, so a NULL-item branch must never fall
    # through to code that treats r5 as SDL_Surface*.  NULL jumps directly to
    # the already-chosen default row-height width.
    a.emit(0xE1A00006)             # default consumed icon width = row height
    a.emit(0xE51BC028)             # ip = current row item
    a.emit(0xE35C0000)
    a.branch('dynamic_game_width_chosen', cond=0x0)
    a.emit(0xE59C5020)             # Favorite/Recent icon-game surface
    a.emit(0xE3550000)
    a.emit(0x059C5070)             # ROM DBCached icon-game surface
    a.emit(0xE3550000)
    a.branch('dynamic_game_width_chosen', cond=0x0)
    a.emit(0xE595C008)             # source width
    a.emit(0xE35C0078)             # width >= 120?
    a.branch('dynamic_game_width_chosen', cond=0xB)
    a.emit(0xE595500C)             # source height
    a.emit(0xE0857005)             # r7 = 2*height
    a.emit(0xE0877005)             # r7 = 3*height
    a.emit(0xE15C0007)
    a.emit(0x21A0000C)             # true spacer -> full source width
    a.label('dynamic_game_width_chosen')
    a.emit(0xE0433000)             # subtract icon/spacer width
    a.emit(0xE3580000)
    a.branch('dynamic_game_width_default_left', cond=0x0)
    a.emit(0xE2410005)             # default game-folder delta
    a.emit(0xE0800008)
    a.emit(0xE2400001)             # explicit effective game inset
    a.emit(0xE0433000)
    a.branch('dynamic_game_width_left_done')
    a.label('dynamic_game_width_default_left')
    a.emit(0xE0433001)             # normal game inset
    a.label('dynamic_game_width_left_done')
    a.emit(0xE0433002)             # post-icon gap
    a.emit(0xE0433001)             # right outer padding
    a.branch('width_clamp')

    a.label('dynamic_width')
    a.emit(0xE51B0028)             # current row item
    a.emit(0xE3500000)
    a.branch('width_no_icon', cond=0x0)
    a.emit(0xE5905020)             # generic item-icon surface
    a.emit(0xE3550000)
    a.branch('width_game_icon', cond=0x0)
    a.emit(0xE5955008)             # generic icon width
    a.emit(0xE0433005)
    a.emit(0xE3580000)
    a.emit(0x12480001)             # explicit folder/base inset
    a.emit(0x03A00005)             # default folder inset
    a.emit(0xE0433000)
    a.emit(0xE0433002)             # dynamic post-icon gap
    a.emit(0xE0433001)             # dynamic right padding
    a.branch('width_clamp')

    a.label('width_game_icon')
    a.emit(0xE5905070)             # DBCached icon-game surface
    a.emit(0xE3550000)
    a.branch('width_no_icon', cond=0x0)
    a.emit(0xE1A00006)             # normal width = row height
    a.emit(0xE595C008)             # source width
    a.emit(0xE35C0078)
    a.branch('width_game_chosen', cond=0xB)
    # Keep r2 intact: it still holds the post-icon gap.
    a.emit(0xE595000C)             # source height
    a.emit(0xE0805000)             # r5 = 2*h
    a.emit(0xE0855000)             # r5 = 3*h
    a.emit(0xE15C0005)
    a.emit(0x21A0000C)             # wide spacer -> real source width
    a.emit(0x31A00006)             # otherwise row-height width
    a.label('width_game_chosen')
    a.emit(0xE0433000)             # subtract chosen icon width
    a.emit(0xE3580000)
    a.branch('width_game_default_left', cond=0x0)
    a.emit(0xE2410005)             # default game-folder delta
    a.emit(0xE0800008)
    a.emit(0xE2400001)
    a.emit(0xE0433000)             # subtract effective game inset
    a.branch('width_game_left_done')
    a.label('width_game_default_left')
    a.emit(0xE0433001)             # established game left padding
    a.label('width_game_left_done')
    a.emit(0xE0433002)             # real post-icon gap
    a.emit(0xE0433001)             # dynamic right padding
    a.branch('width_clamp')

    a.label('width_no_icon')
    a.emit(0xE0433001)
    a.emit(0xE0433001)

    a.label('width_clamp')
    a.emit(0xE3530001)
    a.emit(0xB3A03001)
    a.branch('done')

    # <=7 rows: stock folder inset is 5 and stock game inset is 20, so an
    # explicit base margin N maps to folder=N and game=N+15.
    a.label('custom_stock')
    a.emit(0xE3540000)
    a.branch('stock_margin_item_text', cond=0x0)
    a.emit(0xE3540001)
    a.branch('stock_margin_game_icon', cond=0x0)
    a.emit(0xE3540002)
    a.branch('stock_margin_game_text', cond=0x0)
    a.emit(0xE3540003)
    a.branch('stock_margin_no_icon', cond=0x0)
    a.emit(0xE3540004)
    a.branch('stock_margin_width', cond=0x0)
    a.emit(0xE3540005)
    a.branch('stock_margin_item_icon', cond=0x0)
    a.branch('stock_margin_game_width')

    a.label('stock_margin_item_icon')
    a.emit(0xE2480001)             # r0 = explicit folder/base inset
    a.emit(0xE0833000)
    a.branch('done')
    a.label('stock_margin_item_text')
    a.emit(0xE2480001)
    a.emit(0xE0833000)
    a.emit(0xE283300F)             # stock 15px icon->text gap
    a.branch('done')
    a.label('stock_margin_game_icon')
    a.emit(0xE288000E)             # r0 = (N+1)+14 = N+15
    a.emit(0xE0833000)
    a.branch('done')
    a.label('stock_margin_game_text')
    a.emit(0xE288000E)             # effective game inset N+15
    a.emit(0xE0833000)
    a.emit(0xE283305B)             # +91 after actual game-icon X
    a.branch('stock_game_text_extra')
    a.label('stock_margin_no_icon')
    a.emit(0xE2833014)
    a.branch('done')

    a.label('stock_margin_game_width')
    # Stock-six/seven game text starts at N+106 pixels for explicit base
    # margin N (default N=5 -> 111). A wide spacer extends beyond the stock
    # 71px icon extent, so subtract only that extra obstruction.
    a.emit(0xE2880069)             # r0 = encoded(N+1)+105 = N+106
    a.emit(0xE0433000)
    a.branch('stock_game_width_extra')

    a.label('stock_margin_width')
    a.emit(0xE51B0028)
    a.emit(0xE3500000)
    a.branch('stock_margin_width_no_icon', cond=0x0)
    a.emit(0xE5905020)
    a.emit(0xE3550000)
    a.branch('stock_margin_width_game', cond=0x0)
    # Favorite/Recent game rows carry icon-game through the generic TextItem
    # icon slot.  At stock-style 6/7 rows MainUI's generic width arithmetic
    # never subtracts that icon width even though the text X already includes
    # it.  Keep normal icons stock, but a deliberate wide spacer must consume
    # its real width so renderer and marquee see the same right edge.
    a.emit(0xE5950008)             # generic icon source width
    a.emit(0xE3500078)             # width >= 120?
    a.branch('stock_margin_generic_base', cond=0xB)
    a.emit(0xE595500C)             # source height
    a.emit(0xE0857005)             # r7 = 2*h
    a.emit(0xE0877005)             # r7 = 3*h
    a.emit(0xE1500007)
    a.emit(0x20433000)             # subhs r3,r3,r0 for true spacer
    a.label('stock_margin_generic_base')
    a.emit(0xE2433023)             # generic base cost 35
    a.emit(0xE2480001)             # explicit folder/base inset N
    a.emit(0xE0433000)
    a.branch('width_clamp')
    a.label('stock_margin_width_game')
    a.emit(0xE5905070)
    a.emit(0xE3550000)
    a.branch('stock_margin_width_no_icon', cond=0x0)
    a.emit(0xE2433014)             # game base cost 20
    a.emit(0xE288000E)             # effective game inset N+15
    a.emit(0xE0433000)
    a.branch('width_clamp')
    a.label('stock_margin_width_no_icon')
    a.emit(0xE2433028)
    a.branch('width_clamp')

    a.label('stock')
    a.emit(0xE3540002)
    a.branch('stock_game_text', cond=0x0)
    a.emit(0xE3540004)
    a.branch('stock_width', cond=0x0)
    a.emit(0xE3540005)
    a.branch('stock_item_icon', cond=0x0)
    a.emit(0xE3540006)
    a.branch('stock_game_width', cond=0x0)
    a.emit(0xE2833014)             # item-text/game-icon/no-icon stock +20
    a.branch('done')
    a.label('stock_item_icon')
    a.emit(0xE2833005)
    a.branch('done')
    a.label('stock_game_text')
    a.emit(0xE283306F)             # stock game-title x after 71px icon
    a.label('stock_game_text_extra')
    # Keep stock-six/seven title x paired with the wide-spacer width rewrite.
    # A qualifying spacer consumes its real width rather than stock's 71px
    # icon extent, so move the title right by exactly (source_width - 71).
    # Width mode subtracts the same delta; the right edge therefore stays fixed.
    a.emit(0xE51B0028)             # current row item
    a.emit(0xE3500000)
    a.branch('done', cond=0x0)
    a.emit(0xE5905020)             # Favorite/Recent icon-game surface
    a.emit(0xE3550000)
    a.emit(0x05905070)             # ROM DBCached icon-game surface
    a.emit(0xE3550000)
    a.branch('done', cond=0x0)
    a.emit(0xE595C008)             # source width
    a.emit(0xE35C0078)             # width >= 120?
    a.branch('done', cond=0xB)
    a.emit(0xE595500C)             # source height
    a.emit(0xE0857005)             # r7 = 2*h
    a.emit(0xE0877005)             # r7 = 3*h
    a.emit(0xE15C0007)
    a.branch('done', cond=0x3)     # width < 3*h -> normal icon geometry
    a.emit(0xE24CC047)             # extra obstruction = source width - 71
    a.emit(0xE083300C)             # move title x right by same extra
    a.branch('done')
    a.label('stock_width')
    # Stock 6/7 generic-icon rows use an actual icon-width-dependent text X,
    # but stock's width remains only total-40.  That overstates the visible
    # rectangle for the 240x48 transparent icon-game spacer used by parsed
    # Favorite/Recent rows.  Narrow only qualifying wide spacers; ordinary
    # generic icons retain exact stock geometry.
    a.emit(0xE51B0028)             # current row item
    a.emit(0xE3500000)
    a.branch('stock_width_base', cond=0x0)
    a.emit(0xE5905020)             # generic TextItem icon surface
    a.emit(0xE3550000)
    a.branch('stock_width_base', cond=0x0)
    a.emit(0xE5950008)             # source width
    a.emit(0xE3500078)             # width >= 120?
    a.branch('stock_width_base', cond=0xB)
    a.emit(0xE595500C)             # source height
    a.emit(0xE0857005)             # r7 = 2*h
    a.emit(0xE0877005)             # r7 = 3*h
    a.emit(0xE1500007)
    a.emit(0x20433000)             # subhs r3,r3,r0 for true spacer
    a.label('stock_width_base')
    a.emit(0xE2433028)
    a.branch('done')
    a.label('stock_game_width')
    a.emit(0xE243306F)             # exact stock game-row label width
    a.label('stock_game_width_extra')
    a.emit(0xE51B0028)             # current row item
    a.emit(0xE3500000)
    a.branch('width_clamp', cond=0x0)
    a.emit(0xE5905020)             # Favorite/Recent icon-game surface
    a.emit(0xE3550000)
    a.emit(0x05905070)             # ROM DBCached icon-game surface
    a.emit(0xE3550000)
    a.branch('width_clamp', cond=0x0)
    a.emit(0xE595C008)             # source width
    a.emit(0xE35C0078)
    a.branch('width_clamp', cond=0xB)
    a.emit(0xE595500C)             # source height
    a.emit(0xE0857005)             # r7 = 2*h
    a.emit(0xE0877005)             # r7 = 3*h
    a.emit(0xE15C0007)
    a.branch('width_clamp', cond=0x3)
    a.emit(0xE24CC047)             # extra obstruction = source width - 71
    a.emit(0xE043300C)             # subtract only spacer excess over stock
    a.branch('width_clamp')

    a.label('done')
    a.emit(0xE8BD91F7)
    return a.finish(), {name: a.labels[name] for name in entry_names}


def validate_dynamic_row_padding_null_item_codegen() -> None:
    """Fail closed if ROW_PAD mode 6 can reuse row count as a surface pointer.

    The game-text-width mode enters with r5 holding the configured row count.
    A NULL current TextItem must therefore jump directly to the default-width
    continuation before any SDL_Surface dereference.  This is intentionally a
    generated-code/path check rather than the broader dataflow lint: the bad
    shape is a *missing initialization on one branch*, not a self-clobber.
    """
    base_va = 0x00400000
    code, _ = build_dynamic_row_padding(base_va, 0x00500000, 0x00500100)
    words = [read_word(code, off) for off in range(0, len(code), 4)]
    signature = (0xE1A00006, 0xE51BC028, 0xE35C0000)
    hits = [i for i in range(len(words) - 3)
            if tuple(words[i:i + 3]) == signature]
    if len(hits) != 1:
        raise ValueError(
            'ROW_PAD game-width NULL-guard signature is missing or ambiguous')
    i = hits[0]
    branch = words[i + 3]
    # Exact BEQ: NULL TextItem must skip the +0x20/+0x70 surface loads and
    # land on the already-chosen default-width subtraction.
    if (branch >> 28) != 0x0 or ((branch >> 25) & 0x7) != 0x5:
        raise ValueError('ROW_PAD game-width NULL guard is not an EQ branch')
    target = decode_arm_branch_target(branch, base_va + (i + 3) * 4)
    if target is None or target < base_va or target >= base_va + len(code):
        raise ValueError('ROW_PAD game-width NULL guard has invalid target')
    target_i = (target - base_va) // 4
    if words[target_i] != 0xE0433000:  # sub r3,r3,r0
        raise ValueError(
            'ROW_PAD NULL TextItem does not jump directly to default-width continuation')
    # Reject the exact old mode-6 shape: NULL branched over the surface load
    # but landed on ``mov r0,r6`` while r5 still held configured rows.
    if any(words[j] == 0xE51B0028 and words[j + 1] == 0xE3500000
           and words[j + 3] == 0xE5905020 and words[j + 4] == 0xE3550000
           and words[j + 5] == 0x05905070 and words[j + 6] == 0xE1A00006
           for j in range(len(words) - 6)):
        raise ValueError('ROW_PAD stale-r5 NULL-item code shape reappeared')


def build_page_step_r2(base_va: int, data_va: int, continue_va: int, *, down: bool) -> bytes:
    """Use configured shoulder paging only for the active game-list object."""
    a = ArmBuilder(base_va)
    a.ldr_literal(1, data_va)       # r1 = cache
    a.emit(0xE591C040)             # ip = active game-list pointer
    a.emit(0xE150000C)             # cmp this,active
    a.emit(0x05911000)             # ldreq r1,[r1] configured rows
    a.emit(0x13A01006)             # movne r1,#6 stock page step
    a.emit(0xE0832001 if down else 0xE0432001)
    a.branch(continue_va)           # preserve surrounding function's LR
    return a.finish()


def build_restore_window(base_va: int, continue_va: int) -> bytes:
    a = ArmBuilder(base_va)
    for word in (
        0xE51B3028, # ldr r3,[fp,#-0x28] this
        0xE5931010, # ldr r1,[r3,#0x10] first
        0xE59320C4, # ldr r2,[r3,#0xc4] visible count
        0xE0812002, # add r2,r1,r2
        0xE2422001, # sub r2,r2,#1 desired last
        0xE5930178, # ldr r0,[r3,#0x178] total
        0xE2400001, # sub r0,r0,#1 final index
        0xE1520000, # cmp r2,r0
        0xC1A02000, # movgt r2,r0
        0xE5832014, # str r2,[r3,#0x14]
        0xE0422001, # sub r2,r2,r1
        0xE2822001, # add r2,r2,#1 actual worker count
        0xE50B2020, # str r2,[fp,#-0x20]
    ):
        a.emit(word)
    a.branch(continue_va)
    return a.finish()


def build_generic_restore(base_va: int, continue_va: int, data_va: int) -> bytes:
    """Keep the device-tested generic TextMenu restore/search behavior.

    This function performs no new persisted-window arithmetic.
    The saved triple is normalized earlier at the verified ROM-list apply call,
    so the fallback path also receives a current-width end value. Search-result
    active/previous-list restoration remains stock-equivalent.
    """
    target_size = 408
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}
    a.emit(0xE51B4008)             # r4 = this
    a.emit(0xE51B5010)             # r5 = restored first index
    a.emit(0xE5845010)             # store first
    a.ldr_literal(8, data_va)
    a.emit(0xE5986000)             # r6 = configured rows
    a.emit(0xE3560006)
    a.branch('fallback', cond=0x0) # stock/default geometry
    a.emit(0xE5986040)             # r6 = active game-list pointer
    a.emit(0xE1540006)             # cmp this,active
    a.branch('active', cond=0x0)
    a.emit(0xE5987044)             # r7 = previous game-list pointer
    a.emit(0xE1540007)             # cmp this,previous
    a.branch('fallback', cond=0x1)
    a.emit(0xE5886044)             # previous = old active
    a.emit(0xE5884040)             # active = restored object
    a.label('active')
    a.emit(0xE59460C4)             # configured object visible count
    a.emit(0xE0857006)             # desired last = first + count - 1
    a.emit(0xE2477001)
    a.emit(0xE5943000)             # virtual size()
    a.emit(0xE5933020)
    a.emit(0xE1A00004)
    a.emit(0xE12FFF33)             # blx r3
    a.emit(0xE2400001)             # final valid index
    a.emit(0xE1570000)
    a.emit(0xC1A07000)             # clamp desired last
    a.branch('store')
    a.label('fallback')
    a.emit(0xE51B7014)             # saved last; stale wider spans were repaired before menu restore
    a.label('store')
    a.emit(0xE5847014)
    a.emit(0xE8BD41F0)
    a.branch(continue_va)
    literal_bytes = 4
    while len(a.words) * 4 + literal_bytes < target_size:
        a.emit(0xE320F000)
    code = a.finish()
    if len(code) != target_size:
        raise ValueError(f'generic restore helper is {len(code)}, expected {target_size}')
    return code


def build_romwinidx_stack_fix_wrapper(
        base_va: int, get_rows_va: int,
        context_search_state_va: int | None = None) -> bytes:
    '''Normalize stale/malformed persisted ROM windows before menu restore.

    The successful romwinidx lookup has already copied pos/start/end into the
    MenuWindow caller frame at fp-0xAC/fp-0xA8/fp-0xA4. The patch repairs only these
    plain integers before any menu virtual is called. The values are also
    bounded by the current DBCachedTextMenu total so source-console state cannot
    request beyond a smaller contextual-Search result set. Valid windows already
    compatible with the current row count and current list total are untouched.

    When the separate contextual-Search selector marks its exact MenuWindow
    activation as in progress, that result list is deliberately initialized at
    row zero before the first worker request. Parsed TextMenu and
    MultiDBCachedTextMenu restore paths are intentionally not generalized here.

    Provenance for those caller-frame slots is guarded separately: the caller
    passes an output object at fp-0xC4 to the stock lookup; its copy helper
    writes fields +0x18/+0x1C/+0x20, exactly fp-0xAC/-0xA8/-0xA4.
    '''
    a = ArmBuilder(base_va)
    a.emit(0xE92D47FF)             # push {r0-r10,lr}; preserve caller state
    a.emit(0xE51B40AC)             # r4 = saved pos
    a.emit(0xE51B50A8)             # r5 = saved start
    a.emit(0xE51B60A4)             # r6 = saved end

    a.branch(get_rows_va, link=True)
    a.emit(0xE1A07000)             # r7 = current configured rows (6..20)

    # A successful romwinidx lookup is keyed to the source console, but this
    # same restore path is also used by a newly-created contextual Search
    # result list. Its result count can be smaller than the source list, so a
    # saved pos/start/end can extend beyond the new DBCachedTextMenu. Clamp
    # only when the current child has the exact DBCachedTextMenu vptr and a
    # positive published total.
    a.emit(0xE51B90C8)             # r9 = MenuWindow* caller object
    a.emit(0xE599A00C)             # r10 = current child menu
    a.emit(0xE35A0000)
    a.branch('range_only', cond=0x0)
    a.emit(0xE59A8000)             # r8 = child vptr
    a.ldr_literal(0, ROM_VTABLE)
    a.emit(0xE1580000)             # exact DBCachedTextMenu only
    a.branch('range_only', cond=0x1)
    a.emit(0xE59AA178)             # r10 = current logical result/list total
    a.emit(0xE35A0000)
    a.branch('range_only', cond=0xD)  # total <= 0: preserve stock path

    # Contextual Search behavior: while the exact SearchAction-created MenuWindow is
    # in its slot-5 activation, initialize the result list at the first row.
    # This happens before TextMenu::restoreState and before the first DB worker.
    if context_search_state_va is not None:
        a.ldr_literal(8, context_search_state_va)
        a.emit(0xE5988014)
        a.emit(arm_movw(0, CONTEXT_SEARCH_BUILDING_FLAG))
        a.emit(0xE1580000)
        a.branch('bound_total', cond=0x1)
        a.emit(0xE5998000)         # exact MenuWindow vptr
        a.ldr_literal(0, CONTEXT_SEARCH_MENU_WINDOW_VPTR)
        a.emit(0xE1580000)
        a.branch('bound_total', cond=0x1)
        a.emit(0xE5998004)         # stock translation/title id
        a.emit(arm_movw(0, 153))
        a.emit(0xE1580000)
        a.branch('bound_total', cond=0x1)
        a.emit(0xE3A04000)         # pos = 0
        a.emit(0xE3A05000)         # start = 0
        a.emit(0xE157000A)         # rows >= total?
        a.emit(0xA1A0800A)         # movge r8,total
        a.emit(0xB1A08007)         # movlt r8,rows
        a.emit(0xE2486001)         # end = min(rows,total)-1
        a.emit(0xE50B40AC)
        a.emit(0xE50B50A8)
        a.emit(0xE50B60A4)
        a.branch('done')

    a.label('bound_total')
    a.emit(0xE24AA001)             # r10 = final valid index
    a.emit(0xE154000A)             # saved pos > final?
    a.emit(0xC1A0400A)             # movgt r4,r10
    a.emit(0xC50B40AC)             # strgt r4,[fp,#-0xac]
    a.emit(0xE155000A)             # saved start > final?
    a.emit(0xC1A0500A)             # movgt r5,r10
    a.emit(0xC50B50A8)             # strgt r5,[fp,#-0xa8]
    a.emit(0xE156000A)             # saved end > final?
    a.emit(0xC1A0600A)             # movgt r6,r10
    a.emit(0xC50B60A4)             # strgt r6,[fp,#-0xa4]

    # DBCachedTextMenu's loader immediately computes end-start+1. Stock
    # restoreState checks each endpoint for bounds but not start<=end, so a
    # non-negative descending pair could otherwise become a negative worker
    # count. Preserve negative sentinel semantics; repair only a fully concrete
    # non-negative pair.
    a.emit(0xE3550000)             # start < 0?
    a.branch('range_only', cond=0xB)
    a.emit(0xE3560000)             # end < 0?
    a.branch('range_only', cond=0xB)
    a.emit(0xE1560005)             # end < start?
    a.branch('range_only', cond=0xA)  # end >= start
    a.emit(0xE3540000)             # pos < 0?
    a.branch('descending_no_pos', cond=0xB)
    a.branch('anchor_bottom')
    a.label('descending_no_pos')
    # Keep the pos sentinel, but publish a valid first page so worker count is
    # never negative. start/end are concrete and total is known positive here.
    a.emit(0xE3A05000)             # start = 0
    a.emit(0xE2878000)             # r8 = rows
    a.emit(0xE1A0000A)             # r0 = final valid index
    a.emit(0xE2488001)             # candidate end = rows-1
    a.emit(0xE1580000)             # candidate > final?
    a.emit(0xC1A08000)             # movgt candidate,final
    a.emit(0xE1A06008)             # end = candidate
    a.branch('store')

    a.label('range_only')
    a.emit(0xE1560005)             # saved end < start? preserve malformed/sentinel pair
    a.branch('done', cond=0xB)

    # Repair pos outside the saved span even if the span is already narrow.
    a.emit(0xE1540005)             # pos < start?
    a.branch('anchor_top', cond=0xB)
    a.emit(0xE1540006)             # pos > saved end?
    a.branch('anchor_bottom', cond=0xC)

    a.emit(0xE0468005)             # r8 = end-start
    a.emit(0xE2888001)             # saved span
    a.emit(0xE1580007)
    a.branch('done', cond=0xD)     # span <= rows and pos inside: unchanged

    # Wide stale span. Keep start if it still contains pos at the new width.
    a.emit(0xE0858007)             # r8 = start + rows
    a.emit(0xE2488001)             # desired last = start + rows - 1
    a.emit(0xE1540008)             # pos > desired last?
    a.branch('anchor_bottom', cond=0xC)
    a.emit(0xE1A06008)             # keep start; end = desired last
    a.branch('store')

    a.label('anchor_bottom')
    # end = pos; start = max(0, pos-rows+1)
    a.emit(0xE2478001)             # r8 = rows - 1
    a.emit(0xE1540008)             # pos < rows-1?
    a.emit(0x20445008)             # subhs r5,pos,rows-1
    a.emit(0x33A05000)             # movlo r5,#0
    a.emit(0xE1A06004)             # end = pos
    a.branch('store')

    a.label('anchor_top')
    # start = pos; end = min(saved_end, pos+rows-1). Never extend past old end.
    a.emit(0xE1A05004)             # start = pos
    a.emit(0xE0848007)             # candidate end = pos + rows
    a.emit(0xE2488001)             #               - 1
    a.emit(0xE1580006)             # candidate > saved_end?
    a.emit(0xD1A06008)             # movle r6,candidate; else keep saved_end

    a.label('store')
    a.emit(0xE50B50A8)             # caller saved start
    a.emit(0xE50B60A4)             # caller saved end
    a.label('done')
    a.emit(0xE8BD47FF)             # restore caller state
    a.emit(ROMWINIDX_STACK_FIX_STOCK)  # replay ldr r3,[fp,#-0xc8]
    a.branch(ROMWINIDX_STACK_FIX_CONTINUE_VA)
    return a.finish()



def build_romwinidx_menu_exit_gate(base_va: int, state_va: int) -> bytes:
    """Persist a stock ROM snapshot on normal list exit, or return snapshot-only.

    Stock MenuWindow slot +0x10 (0x2FC74) has already copied the live DBCached
    pos/start/end into the global romwinidx vector before this hook. On a normal
    real ROM-list exit, serialize that vector immediately. When state[0] is set
    by the power/handoff helper, skip both serialization and child destruction:
    the caller only wanted the stock snapshot side effect.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D5017)             # push {r0-r2,r4,ip,lr}
    a.emit(0xE51B4080)             # r4 = MenuWindow this
    a.emit(0xE3540000)
    a.branch('stock', cond=0x0)
    a.emit(0xE5940000)             # exact MenuWindow vptr
    a.ldr_literal(1, CONTEXT_SEARCH_MENU_WINDOW_VPTR)
    a.emit(0xE1500001)
    a.branch('stock', cond=0x1)
    a.emit(0xE5940008)             # mode: real DBCached ROM windows are 5/17
    a.emit(0xE3500005)
    a.branch('mode_ok', cond=0x0)
    a.emit(0xE3500011)
    a.branch('stock', cond=0x1)
    a.label('mode_ok')
    a.emit(0xE594000C)             # child menu
    a.emit(0xE3500000)
    a.branch('stock', cond=0x0)
    a.emit(0xE5900000)             # exact DBCachedTextMenu vptr
    a.ldr_literal(1, ROM_VTABLE)
    a.emit(0xE1500001)
    a.branch('stock', cond=0x1)
    a.emit(0xE5940004)             # do not persist contextual Search geometry
    a.emit(arm_movw(1, 153))
    a.emit(0xE1500001)
    a.branch('stock', cond=0x0)
    a.ldr_literal(12, state_va)
    a.emit(0xE59C0000)             # snapshot-only request?
    a.emit(0xE3500000)
    a.branch('snapshot_return', cond=0x1)
    a.ldr_literal(0, ROMWINIDX_GLOBAL_VA)
    a.branch(ROMWINIDX_WRITER_VA, link=True)
    a.label('stock')
    a.emit(0xE8BD5017)
    a.emit(ROMWINIDX_MENU_EXIT_STOCK)
    a.branch(ROMWINIDX_MENU_EXIT_CONTINUE_VA)
    a.label('snapshot_return')
    a.emit(0xE8BD5017)
    a.branch(ROMWINIDX_MENU_EXIT_EARLY_RETURN_VA)
    return a.finish()


def build_romwinidx_active_snapshot(base_va: int, state_va: int) -> bytes:
    """Run the exact stock MenuWindow ROM snapshot on the current top window.

    Returns r0=1 only when an exact non-Search DBCached ROM MenuWindow was
    snapshotted. The exit-gate flag prevents 0x2FC74 from destroying its child.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D50F0)             # push {r4-r7,ip,lr}; 24 bytes / aligned
    a.ldr_literal(4, ROMWINIDX_NAV_VECTOR_GLOBAL_VA)
    a.emit(0xE5944000)             # navigation vector object
    a.emit(0xE3540000)
    a.branch('miss', cond=0x0)
    a.emit(0xE5945000)             # begin
    a.emit(0xE5946004)             # end
    a.emit(0xE1560005)
    a.branch('miss', cond=0x0)
    a.emit(0xE2466004)
    a.emit(0xE5964000)             # top MenuWindow*
    a.emit(0xE3540000)
    a.branch('miss', cond=0x0)
    a.emit(0xE5945000)             # exact MenuWindow vptr
    a.ldr_literal(6, CONTEXT_SEARCH_MENU_WINDOW_VPTR)
    a.emit(0xE1550006)
    a.branch('miss', cond=0x1)
    a.emit(0xE5945008)             # mode 5 or 17 only
    a.emit(0xE3550005)
    a.branch('mode_ok', cond=0x0)
    a.emit(0xE3550011)
    a.branch('miss', cond=0x1)
    a.label('mode_ok')
    a.emit(0xE594500C)             # child
    a.emit(0xE3550000)
    a.branch('miss', cond=0x0)
    a.emit(0xE5955000)
    a.ldr_literal(6, ROM_VTABLE)
    a.emit(0xE1550006)
    a.branch('miss', cond=0x1)
    a.emit(0xE5945004)             # contextual Search title/id 153 excluded
    a.emit(arm_movw(6, 153))
    a.emit(0xE1550006)
    a.branch('miss', cond=0x0)
    a.ldr_literal(7, state_va)
    a.emit(0xE3A05001)
    a.emit(0xE5875000)             # snapshot-only flag = 1
    a.emit(0xE1A00004)             # r0 = top MenuWindow
    a.branch(ROMWINIDX_MENU_SNAPSHOT_VA, link=True)
    a.emit(0xE3A05000)
    a.emit(0xE5875000)             # clear flag
    a.emit(0xE3A00001)             # success
    a.emit(0xE8BD90F0)             # pop {r4-r7,ip,pc}
    a.label('miss')
    a.emit(0xE3A00000)
    a.emit(0xE8BD90F0)
    return a.finish()


def build_romwinidx_power_snapshot(base_va: int, active_snapshot_va: int,
                                    sync_va: int) -> bytes:
    """On the first SDLK_POWER down, snapshot+write+sync before keymon SIGKILL."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D50FF)             # push {r0-r7,ip,lr}; aligned
    a.ldr_literal(4, ROMWINIDX_POWER_COUNT_VA)
    a.emit(0xE5944000)             # stock power repeat count before increment
    a.emit(0xE3540000)
    a.branch('done', cond=0x1)     # only first power-down event
    a.branch(active_snapshot_va, link=True)
    a.emit(0xE3500000)
    a.branch('done', cond=0x0)     # no active real DBCached ROM list
    a.ldr_literal(0, ROMWINIDX_GLOBAL_VA)
    a.branch(ROMWINIDX_WRITER_VA, link=True)
    a.branch(sync_va, link=True)
    a.label('done')
    a.emit(0xE8BD50FF)
    a.emit(ROMWINIDX_POWER_STOCK)
    a.branch(ROMWINIDX_POWER_CONTINUE_VA)
    return a.finish()


def build_romwinidx_handoff_snapshot(base_va: int,
                                      active_snapshot_va: int) -> bytes:
    """Snapshot an active ROM list immediately before stock result-2/3 save."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D500F)             # push {r0-r3,ip,lr}; aligned
    a.branch(active_snapshot_va, link=True)
    a.emit(0xE8BD500F)
    a.emit(ROMWINIDX_HANDOFF_STOCK)
    a.branch(ROMWINIDX_HANDOFF_CONTINUE_VA)
    return a.finish()


def normalize_rom_window_model(pos: int, start: int, saved_end: int,
                               rows: int) -> tuple[int, int, int]:
    '''Host-side model of persisted-window normalization.'''
    rows = min(max(rows, 1), 20)
    if saved_end < start:
        return pos, start, saved_end
    if pos < start:
        new_start = max(0, pos)
        return pos, new_start, min(saved_end, new_start + rows - 1)
    if pos > saved_end:
        return pos, max(0, pos - rows + 1), pos
    span = saved_end - start + 1
    if span <= rows:
        return pos, start, saved_end
    desired_last = start + rows - 1
    if pos > desired_last:
        return pos, max(0, pos - rows + 1), pos
    return pos, start, desired_last


def normalize_rom_window_total_model(pos: int, start: int, saved_end: int,
                                     rows: int, total: int) -> tuple[int, int, int]:
    '''Model exact-DBCached total bounds and descending-range hardening.'''
    if total <= 0:
        return pos, start, saved_end
    rows = min(max(rows, 1), 20)
    final = total - 1
    pos = min(pos, final)
    start = min(start, final)
    saved_end = min(saved_end, final)
    if start >= 0 and saved_end >= 0 and saved_end < start:
        if pos >= 0:
            return pos, max(0, pos - rows + 1), pos
        return pos, 0, min(rows - 1, final)
    return normalize_rom_window_model(pos, start, saved_end, rows)


def normalize_context_search_window_model(rows: int, total: int) -> tuple[int, int, int] | None:
    '''Model the pre-worker first-page viewport for contextual Search results.'''
    if total <= 0:
        return None
    rows = min(max(rows, 1), 20)
    return 0, 0, min(rows, total) - 1


def validate_rom_window_model() -> None:
    '''Regression cases for stale and malformed persisted ROM windows.'''
    cases = (
        ((71, 58, 71, 10), (71, 62, 71)),
        ((41, 28, 41, 10), (41, 32, 41)),
        ((113, 110, 119, 10), (113, 110, 119)),
        ((62, 58, 71, 10), (62, 58, 67)),
        ((71, 58, 71, 14), (71, 58, 71)),
        ((3, 0, 6, 10), (3, 0, 6)),
        ((5, 8, 21, 10), (5, 5, 14)),
        ((99, 58, 63, 10), (99, 90, 99)),
        ((5, 8, 12, 10), (5, 5, 12)),
    )
    for args, expected in cases:
        got = normalize_rom_window_model(*args)
        if got != expected:
            raise ValueError(
                f'ROM-window normalization regression for {args}: {got} != {expected}')

    total_cases = (
        ((43, 43, 52, 10, 50), (43, 43, 49)),
        ((71, 62, 71, 10, 50), (49, 49, 49)),
        ((3, 0, 9, 10, 5), (3, 0, 4)),
        ((43, 40, 49, 10, 50), (43, 40, 49)),
        ((10, 15, 5, 10, 50), (10, 1, 10)),
        ((-1, 15, 5, 10, 50), (-1, 0, 9)),
        ((43, 43, 52, 10, 0), (43, 43, 52)),
        ((43, 43, 52, 10, -1), (43, 43, 52)),
    )
    for args, expected in total_cases:
        got = normalize_rom_window_total_model(*args)
        if got != expected:
            raise ValueError(
                f'ROM-window total-bound regression for {args}: {got} != {expected}')

    for rows, total, expected in (
            (10, 50, (0, 0, 9)),
            (10, 5, (0, 0, 4)),
            (6, 1, (0, 0, 0)),
            (10, 0, None),
            (10, -1, None)):
        got = normalize_context_search_window_model(rows, total)
        if got != expected:
            raise ValueError(
                f'contextual Search first-page regression for {(rows, total)}: '
                f'{got} != {expected}')

    # Exhaustive bounded property sweep. Persisted positions are non-negative.
    for rows_arg in range(1, 21):
        rows = min(max(rows_arg, 1), 20)
        for pos in range(25):
            for first in range(25):
                for last in range(25):
                    original = (pos, first, last)
                    got = normalize_rom_window_model(pos, first, last, rows_arg)
                    if normalize_rom_window_model(*got, rows_arg) != got:
                        raise ValueError(
                            f'ROM-window normalization is not idempotent: {original}/{rows}')
                    if last < first:
                        if got != original:
                            raise ValueError(
                                f'malformed descending ROM window should remain stock: {original}')
                        continue
                    compatible = first <= pos <= last and last - first + 1 <= rows
                    if compatible and got != original:
                        raise ValueError(
                            f'compatible ROM window changed unexpectedly: {original}/{rows}')
                    gpos, gfirst, glast = got
                    if gfirst < 0 or not (gfirst <= gpos <= glast):
                        raise ValueError(
                            f'normalized ROM window has invalid bounds: {original}->{got}/{rows}')
                    if glast - gfirst + 1 > rows:
                        raise ValueError(
                            f'normalized ROM window exceeds configured rows: {original}->{got}/{rows}')


def sql_escape_model(value: bytes, capacity: int = 1024) -> bytes:
    'Model SQL apostrophe escaping without ever emitting half a quote pair.'
    if capacity <= 0:
        return b''
    out = bytearray()
    limit = capacity - 1
    for byte in value.split(b'\0', 1)[0]:
        needed = 2 if byte == 0x27 else 1
        if len(out) + needed > limit:
            break
        out.append(byte)
        if byte == 0x27:
            out.append(byte)
    return bytes(out)


def count_cache_key_model(query: bytes,
                          key_size: int = ROM_LIST_COUNT_CACHE_QUERY_SIZE) -> bytes:
    'Model the one-entry COUNT-cache key stored by the ARM helper.'
    if key_size <= 0:
        return b''
    raw = query.split(b'\0', 1)[0]
    return raw[:key_size - 1]


def bounded_snprintf_text_model(value: bytes, capacity: int) -> bytes:
    'Model the maximum text that snprintf can publish into a C buffer.'
    if capacity <= 0:
        return b''
    return value.split(b'\0', 1)[0][:capacity - 1]


def favourite_order_model(items: list[tuple[int, int | None]]) -> list[int]:
    """Model Favourite ordering: explicit sidecar order first, then new items.

    ``items`` contains ``(source_id, explicit_order_or_none)``. Missing sidecar
    order is deliberately later than every explicit order, while source ids
    preserve favourite.json order among multiple missing entries.
    """
    return [source_id for source_id, _order in sorted(
        items, key=lambda item: (item[1] is None,
                                 item[1] if item[1] is not None else 0,
                                 item[0]))]


def favourite_recent_label_model(model_label: str, visible_cut: bool,
                                 stale_action_label: str | None = None) -> tuple[str, str]:
    """Model separation of Favourite presentation from GameAction state.

    The visible TextItem may carry the cut marker, but the execute wrapper
    reasserts the canonical model label before stock Add2Recent consumes it.
    """
    display = f'> {model_label}' if visible_cut else model_label
    action_label = stale_action_label if stale_action_label is not None else model_label
    action_label = model_label
    return display, action_label


def validate_favourite_models() -> None:
    ordered = [(0, 50), (1, 80), (2, 120), (3, None), (4, None)]
    if favourite_order_model(ordered) != [0, 1, 2, 3, 4]:
        raise ValueError('Favourite missing-order append regression')
    mixed = [(0, 200), (1, None), (2, 5), (3, None), (4, 200)]
    if favourite_order_model(mixed) != [2, 0, 4, 1, 3]:
        raise ValueError('Favourite explicit/missing order regression')
    all_missing = [(7, None), (8, None), (9, None)]
    if favourite_order_model(all_missing) != [7, 8, 9]:
        raise ValueError('Favourite missing-order source stability regression')
    # Explicit order remains authoritative even when numerically larger than the
    # total number of current favourites; missing metadata always appends.
    if favourite_order_model([(10, 9000), (11, None)]) != [10, 11]:
        raise ValueError('Favourite high explicit-order precedence regression')

    display, recent = favourite_recent_label_model(
        'Metal Slug', True, stale_action_label='> Metal Slug')
    if display != '> Metal Slug' or recent != 'Metal Slug':
        raise ValueError('Favourite cut marker leaked into Recent model')
    display, recent = favourite_recent_label_model('Metal Slug', False)
    if display != recent or recent != 'Metal Slug':
        raise ValueError('Favourite canonical label model regression')


def recent_reader_limit_model(records: list[int], read_limit: int = RECENT_READ_LIMIT,
                              retain_limit: int = 50) -> list[int]:
    """Model Recent reconstruction: first occurrence wins, at most 50 retained."""
    retained: list[int] = []
    seen: set[int] = set()
    for record in records[:read_limit]:
        if record in seen:
            continue
        seen.add(record)
        if len(retained) < retain_limit:
            retained.append(record)
    return retained


def recent_reader_app_filter_model(
        records: list[tuple[int, int]], read_limit: int = RECENT_READ_LIMIT,
        retain_limit: int = 50) -> list[int]:
    """Model combined Recent load policy: type-3 apps do not consume game slots."""
    retained: list[int] = []
    seen: set[int] = set()
    for identity, record_type in records[:read_limit]:
        if record_type == 3:
            continue
        if identity in seen:
            continue
        seen.add(identity)
        if len(retained) < retain_limit:
            retained.append(identity)
    return retained


def recent_reader_launch_filter_model(
        records: list[tuple[int, int, str]], read_limit: int = RECENT_READ_LIMIT,
        retain_limit: int = 50) -> list[int]:
    """Model Recent load policy: filtered pseudo-records do not consume slots."""
    retained: list[int] = []
    seen: set[int] = set()
    for identity, record_type, launch in records[:read_limit]:
        if record_type == 3 or launch == 'setstate':
            continue
        if identity in seen:
            continue
        seen.add(identity)
        if len(retained) < retain_limit:
            retained.append(identity)
    return retained


def validate_recent_reader_limit_model() -> None:
    records = list(range(1700))
    got = recent_reader_limit_model(records)
    if len(got) != 50 or got[0] != 0 or got[-1] != 49:
        raise ValueError('Recent first-200/top-50 reader model regression')
    if recent_reader_limit_model([1, 2, 1]) != [1, 2]:
        raise ValueError('Recent first-occurrence precedence regression')
    duplicate_heavy = [i % 25 for i in range(100)] + list(range(25, 125))
    got = recent_reader_limit_model(duplicate_heavy)
    if got != list(range(50)):
        raise ValueError('Recent duplicate-heavy fill regression')
    mixed = [(1000 + i, 3) if i % 5 == 0 else (i, 5) for i in range(200)]
    got = recent_reader_app_filter_model(mixed)
    if len(got) != 50 or any(identity >= 1000 for identity in got):
        raise ValueError('Recent stale-AppAction slot filtering regression')
    # Pseudo setstate rows can appear in the persisted file but are not real
    # game rows.  They must be filtered before the retained-vector limit so
    # later real games within the 200-record read window can still fill 50.
    pseudo_mixed = []
    for i in range(80):
        launch = 'setstate' if i in (3, 17, 41) else '/Emu/X/launch.sh'
        pseudo_mixed.append((i, 5, launch))
    got = recent_reader_launch_filter_model(pseudo_mixed)
    expected = [i for i in range(80) if i not in (3, 17, 41)][:50]
    if got != expected or len(got) != 50:
        raise ValueError('Recent setstate slot filtering regression')



def recent_search_identity_model(launch: str, rompath: str) -> tuple[str, str] | None:
    """Model the Recent insertion contract owned by fix-recent-preview-paths."""
    if launch == 'setstate':
        return None
    marker = 'launch.sh:'
    pos = rompath.find(marker)
    if pos < 0:
        return launch, rompath
    suffix = rompath[pos + len(marker):]
    if not suffix.startswith('/'):
        return launch, rompath
    source_launch = rompath[:pos + len('launch.sh')]
    if not source_launch or len(source_launch.encode('utf-8')) >= RECENT_SEARCH_CANON_LAUNCH_BUFFER_SIZE:
        return launch, rompath
    return source_launch, suffix


def recent_thumbnail_argument_model(saved_imgpath: str, source_image_dir: str) -> str:
    """Model the one Recent image-argument rule shared by all three consumers."""
    return saved_imgpath if '.png' in saved_imgpath else source_image_dir


def favourite_detail_image_argument_model(saved_imgpath: str | None,
                                            source_image_dir: str) -> str:
    """Model folder-aware Favourite GameAction construction for Game Details."""
    return saved_imgpath if saved_imgpath else source_image_dir


def search_favourite_rom_identity_model(rompath: str) -> str:
    """Model Search's canonical Favorite membership/storage/removal identity."""
    marker = 'launch.sh:/mnt/SDCARD/'
    pos = rompath.find(marker)
    if pos < 0:
        return rompath
    return rompath[pos + len('launch.sh:'):]


def validate_recent_favourite_identity_models() -> None:
    real_launch = '/mnt/SDCARD/Emu/GG/launch.sh'
    real_rom = '/mnt/SDCARD/Roms/GG/Chicago Syndicate (USA, Europe).gg'
    encoded = real_launch + ':' + real_rom
    search_launch = '/mnt/SDCARD/Emu/SEARCH/../../App/Search/launch.sh'

    if recent_search_identity_model(search_launch, encoded) != (real_launch, real_rom):
        raise ValueError('Search-to-Recent canonical identity regression')
    if recent_search_identity_model(real_launch, real_rom) != (real_launch, real_rom):
        raise ValueError('ordinary Recent identity changed by Search canonicalizer')
    if recent_search_identity_model('setstate', '/mnt/SDCARD/Emu/GG') is not None:
        raise ValueError('Recent setstate filtering regression')
    # A lookalike without an absolute ROM suffix must fail open.
    odd = real_launch + ':relative.rom'
    if recent_search_identity_model(search_launch, odd) != (search_launch, odd):
        raise ValueError('Recent Search canonicalizer accepted non-absolute suffix')

    explicit = '/mnt/SDCARD/Roms/GG/Imgs/game.png'
    source_dir = '/mnt/SDCARD/Roms/GG/Imgs'
    if recent_thumbnail_argument_model(explicit, source_dir) != explicit:
        raise ValueError('Recent explicit-PNG thumbnail contract regression')
    for bad in ('game', '', 'game.jpg'):
        if recent_thumbnail_argument_model(bad, source_dir) != source_dir:
            raise ValueError('Recent source-directory thumbnail fallback regression')
    # The initial RIGHT-open and later Up/Down refresh deliberately consume the
    # same modeled argument; list preview uses the same decision before makeThumbPath.
    chosen = recent_thumbnail_argument_model('game', source_dir)
    if chosen != recent_thumbnail_argument_model('game', source_dir):
        raise ValueError('Recent thumbnail consumers diverged')

    if favourite_detail_image_argument_model(None, source_dir) != source_dir:
        raise ValueError('Favourite missing-imgpath detail fallback regression')
    if favourite_detail_image_argument_model('', source_dir) != source_dir:
        raise ValueError('Favourite empty-imgpath detail fallback regression')
    if favourite_detail_image_argument_model(explicit, source_dir) != explicit:
        raise ValueError('Favourite explicit imgpath precedence regression')

    if search_favourite_rom_identity_model(encoded) != real_rom:
        raise ValueError('Search Favorite canonical ROM identity regression')
    if search_favourite_rom_identity_model(real_rom) != real_rom:
        raise ValueError('ordinary Favorite identity changed by Search normalizer')


def count_cache_access_model(cache_key: bytes | None, query: bytes,
                             generation: int, cache_generation: int
                             ) -> tuple[bytes, int, tuple[str, ...]]:
    'Model resource ownership for one ROM COUNT-cache access.'
    key = count_cache_key_model(query)
    if cache_key == key and cache_generation == generation:
        return cache_key, cache_generation, ('hit',)
    return key, generation, ('miss', 'prepare', 'store', 'reset')


def validate_count_cache_ownership_model() -> None:
    'Prove cache hits never run cleanup for resources they did not acquire.'
    generation = 7
    cache_key: bytes | None = None
    cache_generation = -1
    query_a = b"SELECT COUNT(*) FROM roms WHERE ppath='A'"
    query_b = b"SELECT COUNT(*) FROM roms WHERE ppath='B'"

    cache_key, cache_generation, actions = count_cache_access_model(
        cache_key, query_a, generation, cache_generation)
    if actions != ('miss', 'prepare', 'store', 'reset'):
        raise ValueError(f'COUNT-cache miss ownership regression: {actions}')

    cache_key, cache_generation, actions = count_cache_access_model(
        cache_key, query_a, generation, cache_generation)
    if actions != ('hit',) or 'reset' in actions or 'prepare' in actions:
        raise ValueError(f'COUNT-cache hit touched query-owned resources: {actions}')

    cache_key, cache_generation, actions = count_cache_access_model(
        cache_key, query_b, generation, cache_generation)
    if actions != ('miss', 'prepare', 'store', 'reset'):
        raise ValueError(f'COUNT-cache query-change regression: {actions}')

    generation += 1
    cache_key, cache_generation, actions = count_cache_access_model(
        cache_key, query_b, generation, cache_generation)
    if actions != ('miss', 'prepare', 'store', 'reset'):
        raise ValueError(f'COUNT-cache invalidation regression: {actions}')


def c_atoi_prefix_model(text: str) -> int:
    'Small host model of the decimal prefix behavior used by C atoi().' 
    i = 0
    while i < len(text) and text[i].isspace():
        i += 1
    sign = 1
    if i < len(text) and text[i] in '+-':
        if text[i] == '-':
            sign = -1
        i += 1
    start = i
    while i < len(text) and text[i].isdigit():
        i += 1
    return sign * int(text[start:i]) if i > start else 0


def rom_rows_config_model(text: str | None) -> tuple[int, int]:
    rows = 6 if text is None else c_atoi_prefix_model(text[:12])
    rows = min(max(rows, 6), 20)
    return rows, 360 // rows


def signed_half_toward_zero_model(value: int) -> int:
    """Model stock ARM signed division by two with truncation toward zero."""
    shifted = value >> 1
    if value < 0 and (value & 1):
        shifted += 1
    return shifted


def validate_game_icon_crop_model() -> None:
    """Protect stock-six and custom-row icon crop arithmetic.

    The square-crop branch is selected using the uncompensated row height.
    At six rows the crop extent deliberately remains stock-compatible at 71px,
    so source dimensions 61..70 produce a small negative centered offset. Keep
    stock's signed round-toward-zero behavior for that range; custom row counts
    use their real row height and therefore enter this branch only with a
    non-negative delta. This host sweep replaces repeated manual spacer-asset
    checks as the arithmetic regression gate.
    """
    for rows in range(6, 21):
        branch_extent = 360 // rows
        crop_extent = 71 if rows == 6 else branch_extent
        for dimension in range(branch_extent + 1, 513):
            delta = dimension - crop_extent
            got = signed_half_toward_zero_model(delta)
            expected = (abs(delta) // 2) * (-1 if delta < 0 else 1)
            if got != expected:
                raise ValueError(
                    f'game-icon crop signed-rounding regression: rows={rows}, '
                    f'dimension={dimension}, delta={delta}, got={got}, '
                    f'expected={expected}')
    # Pin the exact stock-six edge cases that motivated the signedness audit.
    expected_edges = {61: -5, 62: -4, 69: -1, 70: 0, 71: 0, 72: 0}
    for dimension, expected in expected_edges.items():
        got = signed_half_toward_zero_model(dimension - 71)
        if got != expected:
            raise ValueError(
                f'game-icon six-row crop edge regression for {dimension}px: '
                f'{got} != {expected}')


def game_icon_wide_spacer_model(width: int, height: int) -> bool:
    """Return the single documented icon-game spacer classification."""
    return width >= 120 and width >= 3 * height


def validate_game_icon_wide_spacer_model() -> None:
    """Pin the single spacer classifier used by every geometry path."""
    cases = {
        (20, 8): False,
        (119, 20): False,
        (120, 40): True,
        (120, 41): False,
        (121, 40): True,
        (240, 48): True,
        (120, 60): False,
    }
    for (width, height), expected in cases.items():
        got = game_icon_wide_spacer_model(width, height)
        if got != expected:
            raise ValueError(
                f'game-icon spacer classification regression: {width}x{height}: '
                f'{got} != {expected}')


def game_row_title_x_model(rows: int, icon_width: int, icon_height: int,
                           explicit_base_margin: int | None = None) -> int:
    """Model the patched game-row title X coordinate for a zero-origin row."""
    rows = min(max(rows, 6), 20)
    wide = game_icon_wide_spacer_model(icon_width, icon_height)
    if rows <= 7:
        x = 111 if explicit_base_margin is None else explicit_base_margin + 106
        if wide:
            x += max(0, icon_width - 71)
        return x
    outer, gap = row_horizontal_padding_model(rows)
    game_inset = (outer if explicit_base_margin is None
                  else (outer - 5) + explicit_base_margin)
    consumed_icon = icon_width if wide else 360 // rows
    return consumed_icon + game_inset + gap


def game_row_title_width_model(rows: int, total_width: int,
                               icon_width: int, icon_height: int,
                               explicit_base_margin: int | None = None) -> int:
    """Model the patched game-row title rectangle width.

    Rows 6/7 move X and reduce width by the same wide-spacer excess over
    stock's 71px game-icon extent. Dense rows use the same dynamic game inset,
    icon/spacer width, gap, and right padding as the renderer hook.
    """
    rows = min(max(rows, 6), 20)
    wide = game_icon_wide_spacer_model(icon_width, icon_height)
    if rows <= 7:
        left_cost = 111 if explicit_base_margin is None else explicit_base_margin + 106
        if wide:
            left_cost += max(0, icon_width - 71)
        return max(1, total_width - left_cost)
    outer, gap = row_horizontal_padding_model(rows)
    game_inset = (outer if explicit_base_margin is None
                  else (outer - 5) + explicit_base_margin)
    consumed_icon = icon_width if wide else 360 // rows
    return max(1, total_width - consumed_icon - game_inset - gap - outer)


def parsed_game_title_geometry_model(rows: int, total_width: int,
                                     icon_width: int, icon_height: int,
                                     explicit_base_margin: int | None = None) -> tuple[int, int]:
    """Model Favorite/Recent TextItem icon-game geometry.

    Parsed Favorite/Recent rows carry the themed icon-game surface in the
    generic TextItem icon slot. At rows 6/7 stock already places text after the
    icon's real width, but its generic label width ignores that width. The patch
    narrows only deliberate wide spacers so normal stock icon geometry remains
    untouched. Dense rows already use the exact generic-icon geometry.
    """
    rows = min(max(rows, 6), 20)
    wide = game_icon_wide_spacer_model(icon_width, icon_height)
    if rows <= 7:
        if explicit_base_margin is None:
            x = icon_width + 20
            width = total_width - 40 - (icon_width if wide else 0)
        else:
            x = icon_width + explicit_base_margin + 15
            width = (total_width - explicit_base_margin - 35 -
                     (icon_width if wide else 0))
        return x, max(1, width)
    outer, gap = row_horizontal_padding_model(rows)
    base = 5 if explicit_base_margin is None else explicit_base_margin
    x = base + icon_width + gap
    width = total_width - icon_width - base - gap - outer
    return x, max(1, width)


def validate_game_row_title_width_model() -> None:
    if game_row_title_width_model(6, 640, 71, 71) != 529:
        raise ValueError('stock six-row game title width regression')
    if game_row_title_x_model(6, 71, 71) != 111:
        raise ValueError('stock six-row game title x regression')
    if game_row_title_width_model(6, 640, 240, 48) != 360:
        raise ValueError('stock six-row wide-spacer title width regression')
    if game_row_title_x_model(6, 240, 48) != 280:
        raise ValueError('stock six-row wide-spacer title x regression')
    if game_row_title_width_model(7, 640, 240, 48) != 360:
        raise ValueError('seven-row wide-spacer title width regression')
    if game_row_title_x_model(7, 240, 48) != 280:
        raise ValueError('seven-row wide-spacer title x regression')
    if parsed_game_title_geometry_model(6, 640, 240, 48) != (260, 360):
        raise ValueError('six-row parsed-game wide-spacer geometry regression')
    if parsed_game_title_geometry_model(7, 640, 240, 48) != (260, 360):
        raise ValueError('seven-row parsed-game wide-spacer geometry regression')
    if parsed_game_title_geometry_model(7, 640, 240, 48, 12) != (267, 353):
        raise ValueError('seven-row parsed-game explicit-margin spacer regression')
    if parsed_game_title_geometry_model(8, 640, 240, 48) != (259, 361):
        raise ValueError('dense parsed-game spacer geometry regression')
    if game_row_title_width_model(6, 640, 240, 48, 12) != 353:
        raise ValueError('stock-row explicit-margin wide-spacer width regression')
    if game_row_title_x_model(6, 240, 48, 12) != 287:
        raise ValueError('stock-row explicit-margin wide-spacer x regression')
    if game_row_title_width_model(10, 640, 36, 36) != 554:
        raise ValueError('dense normal game title width regression')
    if game_row_title_x_model(10, 36, 36) != 67:
        raise ValueError('dense normal game title x regression')
    if game_row_title_width_model(10, 640, 240, 48) != 350:
        raise ValueError('dense wide-spacer game title width regression')
    if game_row_title_x_model(10, 240, 48) != 271:
        raise ValueError('dense wide-spacer game title x regression')

    # The stock-style wide-spacer rewrite must move X and shrink width by the
    # same amount, preserving the original right edge. This is what the
    # preview-boundary marquee activation depends on.
    for rows in (6, 7):
        for width, height in ((120, 40), (180, 40), (240, 48), (320, 64)):
            normal_x = game_row_title_x_model(rows, 71, 71)
            normal_w = game_row_title_width_model(rows, 640, 71, 71)
            wide_x = game_row_title_x_model(rows, width, height)
            wide_w = game_row_title_width_model(rows, 640, width, height)
            if normal_x + normal_w != wide_x + wide_w:
                raise ValueError(
                    f'wide-spacer title right-edge regression at rows={rows}, '
                    f'icon={width}x{height}')


def row_horizontal_padding_model(rows: int) -> tuple[int, int]:
    """Return (outer padding, visible post-icon gap).

    Rows 6 through 9 retain the stock 20-pixel outer inset. Rows 6 and 7
    retain the stock 15-pixel post-icon gap; from row 8 onward the visible
    post-icon gap follows max(5, 22-rows). From row 10 onward outer padding
    follows max(15, 29-rows).
    """
    rows = min(max(rows, 6), 20)
    outer = 20 if rows <= 9 else max(15, 29 - rows)
    gap = 15 if rows <= 7 else max(5, 22 - rows)
    return outer, gap


def row_text_geometry_model(rows: int, kind: str, total_width: int = 640,
                            icon_width: int = 32) -> tuple[int, int]:
    """Model custom-row text x/width relative to the menu rectangle."""
    rows = min(max(rows, 6), 20)
    if rows == 6:
        return ({'none': 20, 'item': icon_width + 20,
                 'game': 111}[kind], total_width - 40)
    outer, icon_gap = row_horizontal_padding_model(rows)
    if kind == 'none':
        x = outer
    elif kind == 'item':
        x = 5 + icon_width + icon_gap
    elif kind == 'game':
        x = outer + (360 // rows) + icon_gap
    else:
        raise ValueError(f'unknown row geometry kind {kind!r}')
    return x, max(1, total_width - x - outer)


def rom_font_config_model(text: str | None) -> int:
    if text is None:
        return 0
    size = c_atoi_prefix_model(text[:12])
    if size <= 0:
        return 0
    return min(max(size, 8), 60)


def title_scroll_config_model(text: str | None) -> tuple[int, int, int]:
    'Return (status,idle_ms,pixels_per_second), matching fscanf semantics.'
    if text is None:
        return 1, 0, 0
    import re
    match = re.match(r'\s*([+-]?\d+)([, ]+)([+-]?\d+)', text)
    if not match:
        return 1, 0, 0
    idle = int(match.group(1))
    speed = int(match.group(3))
    if idle < 0 or speed <= 0:
        return 1, idle, speed
    return 2, min(max(idle, TITLE_SCROLL_MIN_IDLE_MS), TITLE_SCROLL_MAX_IDLE_MS), min(
        max(speed, TITLE_SCROLL_MIN_SPEED), TITLE_SCROLL_MAX_SPEED)


def key_repeat_config_model(text: str | None) -> tuple[int, int]:
    'Model the documented compact key-repeat parser forms.'
    default = (500, 100)
    if not text:
        return default
    text = text[:31]
    delay = c_atoi_prefix_model(text)
    delimiter = next((i for i, ch in enumerate(text) if ch in ', '), None)
    if delimiter is None:
        return default
    interval = c_atoi_prefix_model(text[delimiter + 1:])
    if delay <= 0 or interval <= 0:
        return default
    return (min(max(delay, 100), 2000),
            min(max(interval, 30), 500))


def title_scroll_loop_geometry_model(phase: int, title_width: int,
                                     visible_width: int,
                                     gap_px: int = TITLE_SCROLL_LOOP_GAP_PX
                                     ) -> tuple[tuple[int, int, int] | None,
                                                tuple[int, int, int] | None]:
    """Return (source_x,width,dest_offset) for suffix/prefix marquee blits."""
    if title_width <= visible_width or title_width <= 0 or visible_width <= 0:
        return None, None
    cycle = title_width + gap_px
    phase %= cycle
    first = second = None
    if phase < title_width:
        suffix = title_width - phase
        first_w = min(suffix, visible_width)
        first = (phase, first_w, 0)
        offset = suffix + gap_px
        if offset < visible_width:
            second = (0, min(title_width, visible_width - offset), offset)
    else:
        offset = cycle - phase
        if offset < visible_width:
            second = (0, min(title_width, visible_width - offset), offset)
    return first, second


def title_scroll_phase_absolute_model(now: int, active_epoch: int,
                                      speed: int, title_width: int,
                                      gap_px: int = TITLE_SCROLL_LOOP_GAP_PX) -> int:
    """Return marquee phase from wall-clock time, not render-call count."""
    cycle = title_width + gap_px
    if cycle <= 0:
        return 0
    elapsed = (now - active_epoch) & 0xFFFFFFFF
    return ((elapsed * speed) // 1000) % cycle


def validate_title_scroll_model() -> None:
    """Geometry properties for continuous ``title + gap + title`` marquee."""
    title_width, visible_width = 420, 180
    gap = TITLE_SCROLL_LOOP_GAP_PX
    first, second = title_scroll_loop_geometry_model(0, title_width, visible_width)
    if first != (0, visible_width, 0) or second is not None:
        raise ValueError('title-scroll loop initial geometry regression')
    phase = title_width - visible_width
    first, second = title_scroll_loop_geometry_model(phase, title_width, visible_width)
    if first != (phase, visible_width, 0) or second is not None:
        raise ValueError('title-scroll loop rightmost-title regression')
    phase = title_width - 20
    first, second = title_scroll_loop_geometry_model(phase, title_width, visible_width)
    if first != (phase, 20, 0) or second is None or second[2] != 20 + gap:
        raise ValueError('title-scroll loop suffix/gap/prefix regression')
    phase = title_width + gap - 1
    first, second = title_scroll_loop_geometry_model(phase, title_width, visible_width)
    if first is not None or second != (0, min(title_width, visible_width - 1), 1):
        raise ValueError('title-scroll loop wrap-edge regression')
    if title_scroll_loop_geometry_model(title_width + gap, title_width,
                                        visible_width) != \
            title_scroll_loop_geometry_model(0, title_width, visible_width):
        raise ValueError('title-scroll loop modulo regression')
    cycle = title_width + gap
    if title_scroll_phase_absolute_model(2000, 1000, 120, title_width, gap) != 120:
        raise ValueError('title-scroll absolute phase regression')
    # Wrapping 32-bit tick arithmetic remains valid. 0x30 ms at 100 px/s = 4px.
    if title_scroll_phase_absolute_model(0x20, 0xFFFFFFF0, 100, title_width, gap) != 4:
        raise ValueError('title-scroll tick-wrap regression')
    # Dense, sparse, and duplicate renderer entries must resolve to the same
    # phase for the same wall-clock timestamp.
    epoch = 1000
    dense = [title_scroll_phase_absolute_model(t, epoch, 120, 10000, gap)
             for t in list(range(1033, 1991, 33)) + [2000]]
    sparse = [title_scroll_phase_absolute_model(t, epoch, 120, 10000, gap)
              for t in (1100, 1220, 1370, 1550, 1760, 2000)]
    duplicate = [title_scroll_phase_absolute_model(2000, epoch, 120, 10000, gap)
                 for _ in range(3)]
    if dense[-1] != 120 or sparse[-1] != 120 or duplicate != [120, 120, 120]:
        raise ValueError('title-scroll absolute-speed regression')


def main_menu_marker_fallback_model(menu_seen: int, menu_mask: int,
                                    recents_marker: bool,
                                    expert_marker: bool) -> int:
    """Model the post-parse legacy-marker precedence contract."""
    menu_recents = 1 << 0
    menu_favorites = 1 << 1
    menu_games = 1 << 2
    menu_apps = 1 << 3
    menu_settings = 1 << 4
    menu_expert = 1 << 5
    if not menu_mask:
        menu_mask = menu_favorites | menu_games | menu_apps | menu_settings
    if not (menu_seen & menu_recents) and recents_marker:
        menu_mask |= menu_recents
    if not (menu_seen & menu_expert) and expert_marker:
        menu_mask |= menu_expert
    return menu_mask


def validate_main_menu_marker_fallback_model() -> None:
    recents = 1 << 0
    favorites = 1 << 1
    games = 1 << 2
    apps = 1 << 3
    settings = 1 << 4
    expert = 1 << 5
    defaults = favorites | games | apps | settings
    cases = (
        # Missing/malformed JSON: set_fallback has no seen bits, so markers win.
        ((0, defaults, True, True), defaults | recents | expert),
        # Valid JSON that omits both keys keeps marker compatibility.
        ((games, games, True, True), games | recents | expert),
        # Explicit false for both keys wins over both stale markers.
        ((recents | expert | games, games, True, True), games),
        # Explicit false for Recent, omitted Expert: only Expert marker applies.
        ((recents | games, games, True, True), games | expert),
        # Explicit true remains true regardless of marker state.
        ((recents | games, recents | games, False, False), recents | games),
        # All-false declarations fall back to the four safe defaults, but seen
        # Recent/Expert bits still prevent stale markers from re-enabling them.
        ((recents | favorites | games | apps | settings | expert, 0, True, True),
         defaults),
    )
    for args, expected in cases:
        actual = main_menu_marker_fallback_model(*args)
        if actual != expected:
            raise ValueError(
                f'main-menu marker precedence regression: {args} -> '
                f'{actual:#x}, expected {expected:#x}')
    required_source = (
        'q->s->menu_seen |= bit;',
        'if (!(s->menu_seen & MENU_RECENTS) && marker_exists(c, recents_marker))',
        'if (!(s->menu_seen & MENU_EXPERT) && marker_exists(c, expert_marker))',
    )
    for snippet in required_source:
        if snippet not in MAIN_MENU_LAYOUT_C_SOURCE:
            raise ValueError(
                'main-menu marker precedence source contract missing: ' + snippet)


def validate_config_models() -> None:
    'Regression checks for the documented runtime config contracts.'
    validate_main_menu_marker_fallback_model()
    validate_game_icon_crop_model()
    validate_game_icon_wide_spacer_model()
    validate_game_row_title_width_model()
    for text, expected in (
            (None, (6, 60)), ('5', (6, 60)), ('6', (6, 60)),
            ('10', (10, 36)), ('20', (20, 18)), ('21', (20, 18)),
            (' 14junk', (14, 25))):
        if rom_rows_config_model(text) != expected:
            raise ValueError(f'ROM-row config regression for {text!r}')
    expected_padding = {
        6: (20, 15), 7: (20, 15), 8: (20, 14), 9: (20, 13),
        10: (19, 12), 11: (18, 11), 12: (17, 10), 13: (16, 9),
        14: (15, 8), 15: (15, 7), 16: (15, 6), 17: (15, 5),
        18: (15, 5), 19: (15, 5), 20: (15, 5),
    }
    for rows, expected in expected_padding.items():
        if row_horizontal_padding_model(rows) != expected:
            raise ValueError(
                f'ROM-row horizontal-padding regression for {rows}: '
                f'{row_horizontal_padding_model(rows)} != {expected}')
    for rows in range(7, 21):
        outer, gap = row_horizontal_padding_model(rows)
        if outer < 15 or gap < 5:
            raise ValueError('ROM-row horizontal padding fell below its clamp')
        for kind in ('none', 'item', 'game'):
            x, width = row_text_geometry_model(rows, kind)
            if x < 0 or width < 1 or x + width != 640 - outer:
                raise ValueError(
                    f'ROM-row {kind} text geometry regression for {rows}: '
                    f'x={x}, width={width}, outer={outer}')
    if row_text_geometry_model(6, 'none') != (20, 600):
        raise ValueError('stock six-row geometry changed')
    for text, expected in (
            (None, 0), ('0', 0), ('-3', 0), ('1', 8), ('8', 8),
            ('34', 34), ('61', 60)):
        if rom_font_config_model(text) != expected:
            raise ValueError(f'ROM-font config regression for {text!r}')
    for text, expected in (
            (None, (1, 0, 0)), ('1000,60', (2, 1000, 60)),
            (' 1000 60', (2, 1000, 60)), ('0,1', (2, 10, 5)),
            ('40000,250', (2, 30000, 250)), ('-1,60', (1, -1, 60)),
            ('1000,0', (1, 1000, 0)), ('garbage', (1, 0, 0))):
        if title_scroll_config_model(text) != expected:
            raise ValueError(f'title-scroll config regression for {text!r}')
    for text, expected in (
            (None, (500, 100)), ('500 100', (500, 100)),
            ('500,100', (500, 100)), ('50 10', (100, 30)),
            ('5000,900', (2000, 500)), ('500', (500, 100)),
            ('0,100', (500, 100)), ('500,0', (500, 100))):
        if key_repeat_config_model(text) != expected:
            raise ValueError(f'key-repeat config regression for {text!r}')


def contextual_search_event_model(pending: bool, event_type: int,
                                  keysym: int) -> tuple[bool, bool]:
    """Return (new_pending, drop_event) for the narrow Search release filter."""
    if not pending:
        return False, False
    if event_type not in (SDL_KEYDOWN, SDL_KEYUP):
        return True, False
    if keysym != SDLK_SPACE:
        return False, False
    return event_type != SDL_KEYUP, True


def validate_contextual_search_event_model() -> None:
    cases = (
        ((False, SDL_KEYUP, SDLK_SPACE), (False, False)),
        ((True, 24, 0), (True, False)),
        ((True, SDL_KEYDOWN, SDLK_SPACE), (True, True)),
        ((True, SDL_KEYUP, SDLK_SPACE), (False, True)),
        ((True, SDL_KEYDOWN, 13), (False, False)),
        ((True, SDL_KEYUP, 13), (False, False)),
    )
    for args, expected in cases:
        actual = contextual_search_event_model(*args)
        if actual != expected:
            raise ValueError(
                f'contextual Search event-filter regression: {args} -> {actual}')


def contextual_search_postgame_back_model(result: int, marker_exists: bool,
                                           exposed_is_search: bool) -> bool:
    return result in (1, 4) and marker_exists and exposed_is_search




def contextual_search_uses_purple_model(color: int) -> bool:
    """Infer a light background from a dark packed SDL_Color text value."""
    red = color & 0xFF
    green = (color >> 8) & 0xFF
    blue = (color >> 16) & 0xFF
    return red + 2 * green + blue < CONTEXT_SEARCH_HIGHLIGHT_LUMA_THRESHOLD


def contextual_search_highlight_choice_model(mode: int, color: int) -> str:
    """Model the guarded fragment-color selector."""
    if mode in (2, 4):
        return 'selected'
    return 'purple' if contextual_search_uses_purple_model(color) else 'yellow'

def context_background_model(count: int, available_rows: set[int]) -> int:
    rows = min(max(count, 0), 6)
    while rows:
        if rows in available_rows:
            return rows
        rows -= 1
    return 4


def popup_fallback_height_model(source_height: int, base_rows: int,
                                requested_rows: int) -> int:
    """Model fixed-height numbered popup expansion."""
    if base_rows <= 0 or requested_rows <= base_rows:
        return source_height
    body = 60 * base_rows
    border_total = source_height - body
    if border_total < 0 or border_total > 32:
        return source_height
    return border_total + 60 * requested_rows


def popup_fallback_row_sources_model(base_rows: int,
                                     requested_rows: int) -> tuple[int, ...]:
    """Model direct pixel-copy tiling of complete 60-pixel row bodies."""
    if base_rows <= 0 or requested_rows <= 0:
        return ()
    return tuple(row % base_rows for row in range(requested_rows))


def popup_visible_row_divisor_model(item_count: int) -> int:
    """PopupWindow uses at most six rows for geometry; extra items scroll."""
    return min(max(item_count, 0), 6)


def validate_contextual_search_models() -> None:
    validate_contextual_search_event_model()
    for result in (1, 4):
        if not contextual_search_postgame_back_model(result, True, True):
            raise ValueError(
                'contextual Search post-game result close rejected exact case')
    for args in (
            (3, True, True), (1, False, True), (1, True, False)):
        if contextual_search_postgame_back_model(*args):
            raise ValueError(
                f'contextual Search post-game result close accepted {args}')
    for count, available, expected in (
            (1, {1}, 1), (3, {3}, 3), (4, {3}, 3),
            (6, {2, 5}, 5), (9, {3, 6}, 6), (4, set(), 4)):
        if context_background_model(count, available) != expected:
            raise ValueError('numbered popup-background fallback regression')
    for args, expected in (
            ((70, 1, 4), 250), ((130, 2, 4), 250),
            ((190, 3, 4), 250), ((190, 3, 6), 370),
            ((190, 3, 3), 190), ((100, 3, 6), 100)):
        if popup_fallback_height_model(*args) != expected:
            raise ValueError('fixed popup-row-height fallback regression')
    for args, expected in (
            ((1, 4), (0, 0, 0, 0)),
            ((2, 5), (0, 1, 0, 1, 0)),
            ((3, 6), (0, 1, 2, 0, 1, 2))):
        if popup_fallback_row_sources_model(*args) != expected:
            raise ValueError('numbered popup row-body tiling regression')
    for count, expected in ((0, 0), (1, 1), (4, 4), (6, 6), (8, 6)):
        if popup_visible_row_divisor_model(count) != expected:
            raise ValueError('popup visible-row divisor regression')
    if CONTEXT_SEARCH_TITLE_SEPARATOR != b': \0':
        raise ValueError('contextual Search title separator regression')
    if len(CONTEXT_SEARCH_TITLE_LOAD_SITES) != 2:
        raise ValueError('contextual Search title-builder coverage regression')
    for color, expected in (
            (0x00424242, True),   # NanoSwitch dark list text -> purple
            (0x00000000, True),
            (0x00FFFFFF, False),  # Silky light list text -> stock yellow
            (0x00888888, False)):
        actual = contextual_search_uses_purple_model(color)
        if actual != expected:
            raise ValueError(
                f'contextual Search highlight contrast regression: '
                f'{color:#x} -> {actual}')
    if CONTEXT_SEARCH_LIGHT_BG_PURPLE_COLOR != 0x00BF2C7B:
        raise ValueError('contextual Search purple color regression')
    for args, expected in (
            ((0, 0x00424242), 'purple'),
            ((3, 0x00FFFFFF), 'yellow'),
            ((2, 0x00424242), 'selected'),
            ((4, 0x00FFFFFF), 'selected')):
        if contextual_search_highlight_choice_model(*args) != expected:
            raise ValueError(
                f'contextual Search fragment-color mode regression: {args}')
    for query in CONTEXT_SEARCH_SORT_QUERIES_BINARY:
        if b'ORDER BY type DESC, disp, path LIMIT' not in query:
            raise ValueError('contextual Search BINARY ordering lost path tie-break')
    for query in CONTEXT_SEARCH_SORT_QUERIES_NOCASE:
        if (b'disp COLLATE NOCASE, path COLLATE NOCASE, path LIMIT'
                not in query):
            raise ValueError('contextual Search NOCASE ordering lost stable tie-break')


def validate_pure_helper_models() -> None:
    'Host regressions for pure SQL/key transformations used by payload code.'
    validate_favourite_models()
    validate_contextual_search_models()
    escape_cases = (
        (b'', 1024, b''),
        (b'abc', 1024, b'abc'),
        (b"Rayman's", 1024, b"Rayman''s"),
        (b"'''", 1024, b"''''''"),
        (b'a\0ignored', 1024, b'a'),
        (b"'", 0, b''),
        (b"'", 1, b''),
        (b"'", 2, b''),
        (b"'", 3, b"''"),
        (b"a'", 3, b'a'),
        (b"'a", 4, b"''a"),
    )
    for src, capacity, expected in escape_cases:
        got = sql_escape_model(src, capacity)
        if got != expected:
            raise ValueError(
                f'SQL escape regression for {src!r}/{capacity}: '
                f'{got!r} != {expected!r}')
    truncated_quotes = sql_escape_model(b"'" * 700)
    if len(truncated_quotes) != 1022 or len(truncated_quotes) % 2:
        raise ValueError('SQL escape quote-pair truncation regression')
    for capacity in range(33):
        for src in (b"''''''''", b"abc'def'ghi", b"a'", b"'a"):
            escaped = sql_escape_model(src, capacity)
            if len(escaped) > max(0, capacity - 1):
                raise ValueError('SQL escape exceeded destination capacity')
            run = 0
            for byte in escaped + b'X':
                if byte == 0x27:
                    run += 1
                else:
                    if run % 2:
                        raise ValueError('SQL escape emitted a half apostrophe pair')
                    run = 0

    key_cases = (
        (b'', b''),
        (b'SELECT COUNT(*)', b'SELECT COUNT(*)'),
        (b'abc\0junk', b'abc'),
        (b'x' * 511, b'x' * 511),
        (b'x' * 700, b'x' * 511),
    )
    for src, expected in key_cases:
        got = count_cache_key_model(src)
        if got != expected:
            raise ValueError(f'COUNT-cache key regression: {len(got)} != {len(expected)}')

    long_a = b'x' * 511 + b'A-tail'
    long_b = b'x' * 511 + b'B-tail'
    generated_a = bounded_snprintf_text_model(
        long_a, ROM_LIST_COUNT_CACHE_QUERY_SIZE)
    generated_b = bounded_snprintf_text_model(
        long_b, ROM_LIST_COUNT_CACHE_QUERY_SIZE)
    if generated_a != b'x' * 511 or generated_b != generated_a:
        raise ValueError('COUNT snprintf-boundary model regression')
    if count_cache_key_model(generated_a) != generated_a:
        raise ValueError('COUNT-cache 511-byte boundary regression')

def validate_romwinidx_stack_provenance(raw: bytes, segs) -> None:
    """Prove the caller-frame slots patched by the ROM-window helper.

    The MenuWindow caller passes ``fp-0xC4`` as the output object to the stock
    romwinidx lookup.  The lookup later passes that exact output pointer to the
    stock copy helper at 0x3AE64, whose three integer copies from source
    +0x18/+0x1C/+0x20 land at caller ``fp-0xAC/-0xA8/-0xA4``.  Guarding the
    whole chain prevents a future MainUI from silently reordering locals while
    leaving the single hook instruction unchanged.
    """
    expected_words = {
        0x0002F518: 0xE24B20C4,  # r2 = fp-0xC4 output object
        0x0002F570: 0xE51B10AC,  # r1 = saved pos
        0x0002F574: 0xE51B20A8,  # r2 = saved start
        0x0002F578: 0xE51B30A4,  # r3 = saved end
        0x0001C8E4: 0xE50B2018,  # lookup saves output pointer
        0x0001C964: 0xE51B0018,  # lookup reloads output pointer as r0
        0x0003AE8C: 0xE51B300C,
        0x0003AE90: 0xE5932018,
        0x0003AE94: 0xE51B3008,
        0x0003AE98: 0xE5832018,  # dst+0x18 = pos
        0x0003AE9C: 0xE51B300C,
        0x0003AEA0: 0xE593201C,
        0x0003AEA4: 0xE51B3008,
        0x0003AEA8: 0xE583201C,  # dst+0x1C = start
        0x0003AEAC: 0xE51B300C,
        0x0003AEB0: 0xE5932020,
        0x0003AEB4: 0xE51B3008,
        0x0003AEB8: 0xE5832020,  # dst+0x20 = end
    }
    for va, expected in expected_words.items():
        off = va2off(segs, va, executable=True)
        if read_word(raw, off) != expected:
            raise ValueError(
                f'romwinidx stack-slot provenance changed at {va:#x}')
    for call_va, target_va in (
            (0x0002F52C, 0x0001C8D0),
            (0x0001C968, 0x0003AE64)):
        off = va2off(segs, call_va, executable=True)
        if decode_arm_branch_target(read_word(raw, off), call_va) != target_va:
            raise ValueError(
                f'romwinidx stack-slot provenance call changed at {call_va:#x}')


def logical_rom_count_after_delete_model(db_rows: int, ppath: str) -> int:
    """Model the post-delete logical row count for ordinary ROM folders."""
    if db_rows < 0:
        return db_rows
    if ppath and ppath != '.':
        return db_rows + 1
    return db_rows


def validate_rom_parent_delete_count_model() -> None:
    """Regression cases for the synthetic ``..`` row after Delete ROM."""
    cases = (
        ((6, '.'), 6),
        ((6, ''), 6),
        ((6, 'A/B'), 7),
        ((0, 'A/B'), 1),
        ((1, "Apostrophe's Folder"), 2),
    )
    for args, expected in cases:
        got = logical_rom_count_after_delete_model(*args)
        if got != expected:
            raise ValueError(
                f'parent-row post-delete count regression for {args}: '
                f'{got} != {expected}')

def decode_arm_branch_target(word: int, src_va: int, *,
                             expected_link: bool | None = None) -> int | None:
    """Decode an ARM-state B/BL immediate, optionally requiring B vs BL.

    ``expected_link=True`` rejects a plain ``B`` whose target bits happen to
    match an expected call target.  ``False`` requires a non-linking branch;
    ``None`` retains generic B/BL decoding for control-flow analysis.
    """
    if ((word >> 25) & 0x7) != 0x5:
        return None
    if expected_link is not None and bool(word & 0x01000000) != expected_link:
        return None
    imm24 = word & 0x00FFFFFF
    if imm24 & 0x00800000:
        imm24 -= 0x01000000
    return src_va + 8 + (imm24 << 2)


def decode_arm_call_target(word: int, src_va: int) -> int | None:
    """Decode only an ARM-state BL immediate call."""
    return decode_arm_branch_target(word, src_va, expected_link=True)


def validate_rom_list_setter_callers(raw: bytes, segs) -> None:
    """Globally prove the direct callers of MainUI's ROM-list size setter.

    A widened stock-text scan found exactly three direct BL calls.  This makes
    the synthetic-parent audit global rather than local: 0x23470 is ordinary
    count publication (already parent-aware), 0x24C94 is the post-delete site
    adjusted for the synthetic parent, and 0x250B0 sizes Search results, which have no synthetic
    ``..`` row.  An added or moved direct caller must be reviewed explicitly.
    """
    found: list[int] = []
    for va in range(MAINUI_TEXT_START_VA, MAINUI_TEXT_END_VA, 4):
        off = va2off(segs, va, executable=True)
        word = read_word(raw, off)
        # BL immediate only (not a tail B whose data bits happen to decode).
        if (word & 0x0F000000) != 0x0B000000:
            continue
        if decode_arm_branch_target(word, va) == ROM_LIST_COUNT_SETTER_VA:
            found.append(va)
    expected = list(ROM_LIST_COUNT_SETTER_DIRECT_CALLS)
    if found != expected:
        raise ValueError(
            'ROM-list size-setter direct-call map changed: '
            f'found {[hex(v) for v in found]}, expected {[hex(v) for v in expected]}')


# Rebuild-time Onion Arcade-name cache. Onion's libgamename already parses the
# text file only once, but does so through iostream/istringstream plus std::map.
# This compact freestanding core reads the file once with fread(), parses it in
# place, and builds a bounded open-addressed FNV-1a table. The hook preserves
# GetGameName's exact call contract and falls back to the stock Onion function
# if initialization cannot be completed.
ARCADE_NAME_CACHE_STATE_SIZE = 16
ARCADE_NAME_CACHE_API_SIZE = 44
ARCADE_NAME_CACHE_PATH = b'/mnt/SDCARD/BIOS/arcade_lists/arcade-rom-names.txt\0'
ARCADE_NAME_CACHE_MODE = b'rb\0'
ARCADE_NAME_CACHE_C_SOURCE = r'''
/* SPDX-License-Identifier: GPL-3.0-only
 * Copyright (C) 2026 robcodedev
 */
typedef unsigned int u32;
typedef signed int i32;

typedef struct ArcadeEntry {
    const char *key;
    const char *value;
    u32 hash;
} ArcadeEntry;

typedef struct ArcadeState {
    volatile u32 state; /* 0=uninitialized, 1=ready, 2=failed, 3=initializing */
    char *buffer;
    ArcadeEntry *table;
    u32 mask;
} ArcadeState;

typedef struct ArcadeApi {
    void *(*fopen_)(const char *, const char *);
    i32 (*fclose_)(void *);
    i32 (*fseek_)(void *, i32, i32);
    i32 (*ftell_)(void *);
    u32 (*fread_)(void *, u32, u32, void *);
    void *(*malloc_)(u32);
    void *(*calloc_)(u32, u32);
    void (*free_)(void *);
    const char *(*stock_get_game_name_)(const char *, const char *);
    const char *path;
    const char *mode;
} ArcadeApi;

#define ARCADE_FILE_MAX (4u * 1024u * 1024u)
#define ARCADE_TABLE_MAX 131072u
#define SEEK_SET_ 0
#define SEEK_END_ 2

static void publish_barrier(void) {
#if defined(__arm__)
    __asm__ volatile("dmb ish" ::: "memory");
#else
    __asm__ volatile("" ::: "memory");
#endif
}

static u32 fnv1a(const char *s) {
    u32 h = 0x811c9dc5u;
    unsigned char c;
    while ((c = (unsigned char)*s++) != 0u) {
        h ^= (u32)c;
        h *= 0x01000193u;
    }
    return h ? h : 1u;
}

static i32 streq(const char *a, const char *b) {
    while (*a && *a == *b) { ++a; ++b; }
    return (unsigned char)*a == (unsigned char)*b;
}

static const char *fallback(ArcadeApi *api, const char *lang, const char *key) {
    if (!api || !api->stock_get_game_name_) return 0;
    return api->stock_get_game_name_(lang, key);
}

static i32 build_cache(ArcadeState *s, ArcadeApi *api) {
    void *file = 0;
    char *buffer = 0;
    ArcadeEntry *table = 0;
    i32 size_i;
    u32 size, lines = 0, cap = 16u, i;
    char *p, *end;

    if (!s || !api) return 0;
    s->state = 3u;
    file = api->fopen_(api->path, api->mode);
    if (!file) goto fail;
    if (api->fseek_(file, 0, SEEK_END_) != 0) goto fail;
    size_i = api->ftell_(file);
    if (size_i <= 0 || (u32)size_i > ARCADE_FILE_MAX) goto fail;
    if (api->fseek_(file, 0, SEEK_SET_) != 0) goto fail;
    size = (u32)size_i;
    buffer = (char *)api->malloc_(size + 1u);
    if (!buffer) goto fail;
    if (api->fread_(buffer, 1u, size, file) != size) goto fail;
    api->fclose_(file);
    file = 0;
    buffer[size] = 0;

    for (i = 0; i < size; ++i)
        if (buffer[i] == '\n') ++lines;
    if (size && buffer[size - 1u] != '\n') ++lines;
    while (cap < (lines << 1u) && cap < ARCADE_TABLE_MAX) cap <<= 1u;
    if (cap < (lines << 1u) || cap > ARCADE_TABLE_MAX) goto fail;
    table = (ArcadeEntry *)api->calloc_(cap, (u32)sizeof(ArcadeEntry));
    if (!table) goto fail;

    p = buffer;
    end = buffer + size;
    while (p < end) {
        char *line = p, *line_end, *sep, *value, *value_end;
        u32 h, slot;
        while (p < end && *p != '\n') ++p;
        line_end = p;
        if (p < end) *p++ = 0;
        if (line_end > line && line_end[-1] == '\r') *--line_end = 0;
        if (!*line) continue;

        sep = line;
        while (*sep && *sep != ' ' && *sep != '\t' && *sep != '\r') ++sep;
        if (!*sep) continue;
        *sep++ = 0;
        while (*sep == ' ' || *sep == '\t') ++sep;
        value = sep;
        value_end = line_end;
        if (value_end <= value + 1) continue;

        /* Match Onion's value.substr(1, value.size() - 2): remove exactly
           the first and last remaining characters after leading whitespace. */
        ++value;
        --value_end;
        *value_end = 0;

        h = fnv1a(line);
        slot = h & (cap - 1u);
        for (;;) {
            ArcadeEntry *e = &table[slot];
            if (!e->key) {
                e->key = line;
                e->value = value;
                e->hash = h;
                break;
            }
            if (e->hash == h && streq(e->key, line)) {
                /* std::map operator[] assignment in Onion makes the last
                   duplicate key win. Preserve that behavior. */
                e->value = value;
                break;
            }
            slot = (slot + 1u) & (cap - 1u);
        }
    }

    s->buffer = buffer;
    s->table = table;
    s->mask = cap - 1u;
    publish_barrier();
    s->state = 1u;
    return 1;

fail:
    if (file) api->fclose_(file);
    if (table) api->free_(table);
    if (buffer) api->free_(buffer);
    s->buffer = 0;
    s->table = 0;
    s->mask = 0;
    s->state = 2u;
    return 0;
}

__attribute__((visibility("default")))
const char *arcade_name_cache_lookup(const char *lang, const char *key,
                                     ArcadeState *s, ArcadeApi *api) {
    u32 h, slot, scanned;
    if (!key || !s || !api) return fallback(api, lang, key);
    if (s->state == 0u && !build_cache(s, api)) return fallback(api, lang, key);
    if (s->state != 1u || !s->table) return fallback(api, lang, key);
    publish_barrier();

    h = fnv1a(key);
    slot = h & s->mask;
    for (scanned = 0; scanned <= s->mask; ++scanned) {
        ArcadeEntry *e = &s->table[slot];
        if (!e->key) return 0;
        if (e->hash == h && streq(e->key, key)) return e->value;
        slot = (slot + 1u) & s->mask;
    }
    return 0;
}
'''
ARCADE_NAME_CACHE_LINKER_SCRIPT = r'''
SECTIONS {
  . = 0;
  .text : { *(.text*) *(.rodata*) }
  /DISCARD/ : { *(.ARM.exidx*) *(.ARM.extab*) *(.comment*) *(.note*) *(.ARM.attributes*) }
}
'''
ARCADE_NAME_CACHE_BUILD_RECIPE = r'''
clang --target=arm-linux-gnueabihf -march=armv7-a -mfloat-abi=hard \
  -mfpu=vfpv3-d16 -marm -O2 -ffreestanding -fno-builtin \
  -fno-stack-protector -fno-unwind-tables -fno-asynchronous-unwind-tables \
  -fvisibility=hidden -ffunction-sections -fdata-sections \
  -c arcade_name_cache.c -o arcade_name_cache.o
ld.lld -m armelf_linux_eabi -T arcade_name_cache.ld --gc-sections \
  -u arcade_name_cache_lookup -o arcade_name_cache.elf arcade_name_cache.o
llvm-objcopy -O binary --only-section=.text \
  arcade_name_cache.elf arcade_name_cache.bin
'''
ARCADE_NAME_CACHE_CORE = bytes.fromhex(
    ''
)
ARCADE_NAME_CACHE_CORE_SHA256 = 'e456cbf9f5c4af429c2c86b3e35fc86c22b891c1f768a011131689e5acbeb7f7'
ARCADE_NAME_CACHE_SYMBOL_OFFSETS = {'arcade_name_cache_lookup': 0}


def verify_arcade_name_cache_flat_symbol_offsets(
        core: bytes, symbols: dict[str, int]) -> None:
    off = symbols.get('arcade_name_cache_lookup')
    if off is None or off < 0 or off + 4 > len(core) or off & 3:
        raise ValueError('invalid Arcade-name cache flat-core symbol offset')
    if struct.unpack_from('<I', core, off)[0] != 0xE92D4FF0:
        raise ValueError('Arcade-name cache flat-core entry word mismatch')


def build_arcade_name_cache_api(imports: dict[str, int],
                                path_va: int, mode_va: int) -> bytes:
    words = [
        imports['fopen'], imports['fclose'], imports['fseek'],
        imports['ftell'], imports['fread'], imports['malloc'],
        imports['calloc'], imports['free'], imports[GET_GAME_NAME],
        path_va, mode_va,
    ]
    blob = struct.pack('<11I', *words)
    if len(blob) != ARCADE_NAME_CACHE_API_SIZE:
        raise ValueError('Arcade-name cache API size mismatch')
    return blob


def build_arcade_name_cache_stub(base_va: int, state_va: int,
                                 api_va: int, core_va: int) -> bytes:
    # Tail-call the freestanding core so MainUI's original LR remains the
    # return address. r0/r1 retain GetGameName(lang,key); r2/r3 add context.
    a = ArmBuilder(base_va)
    a.ldr_literal(2, state_va)
    a.ldr_literal(3, api_va)
    a.branch(core_va)
    return a.finish()


def find_arcade_database_disp_bind_sites(
        data: bytes | bytearray, segs: list[Segment]
        ) -> tuple[int, int, int, int]:
    """Locate the paired SQLite ``disp`` c_str/size source instructions.

    The stock source at ``fp-0xc8`` is filename-derived.  Arcade's resolved
    English label remains available as a raw ``char *`` at ``fp-0x3c``.  The
    later ``fp-0x128`` object is pinyin-derived and must never be used as the
    visible sort key.  Return both source sites and their original string
    helper targets so the fallbacks preserve stock behavior.
    """
    candidates: list[tuple[int, int, int]] = []
    fixed_words = {
        -4: 0xE51B4144,
         0: 0xE24B30C8,
         4: 0xE1A00003,
        12: 0xE1A05000,
        16: 0xE24B30C8,
        20: 0xE1A00003,
        28: 0xE1A03000,
        32: 0xE1A02003,
        36: 0xE3A03000,
        40: 0xE58D3000,
        44: 0xE1A03002,
        48: 0xE1A02005,
        52: 0xE3A01001,
        56: 0xE1A00004,
    }
    for seg in segs:
        if not (seg.flags & 1):
            continue
        start = align_up(max(seg.file_off + 4, 4), 4)
        stop = seg.file_off + seg.file_size - 64
        for site in range(start, stop + 1, 4):
            if any(read_word(data, site + rel) != word
                   for rel, word in fixed_words.items()):
                continue
            cstr_target = decode_arm_branch_target(
                read_word(data, site + 8), off2va(segs, site + 8))
            size_target = decode_arm_branch_target(
                read_word(data, site + 24), off2va(segs, site + 24))
            bind_target = decode_arm_branch_target(
                read_word(data, site + 60), off2va(segs, site + 60))
            if None in (cstr_target, size_target, bind_target):
                continue
            if len({cstr_target, size_target, bind_target}) != 3:
                continue
            candidates.append((site, int(cstr_target), int(size_target)))
    if len(candidates) != 1:
        raise ValueError(
            'Arcade database disp bind signature mismatch: expected one '
            f'structural match, found {len(candidates)}')
    site, cstr_target, size_target = candidates[0]
    return site, site + 16, cstr_target, size_target


def build_arcade_database_disp_cstr_selector(
        base_va: int, stock_cstr_va: int, continue_va: int) -> bytes:
    """Return Arcade's resolved raw label, else the stock disp c_str()."""
    a = ArmBuilder(base_va)
    a.emit(0xE51B3170)             # system descriptor
    a.emit(0xE59330C4)             # short-name / Arcade flag
    a.emit(0xE3530000)
    a.branch('stock', cond=0x0)
    a.emit(0xE51B003C)             # resolved English GetGameName char *
    a.emit(0xE3500000)
    a.branch('done', cond=0x1)
    a.label('stock')
    a.emit(0xE24B00C8)             # filename-derived std::string
    a.branch(stock_cstr_va, link=True)
    a.label('done')
    a.branch(continue_va)
    return a.finish()


def build_arcade_database_disp_size_selector(
        base_va: int, stock_size_va: int, strlen_va: int,
        continue_va: int) -> bytes:
    """Return strlen(resolved Arcade label), else stock disp.size()."""
    a = ArmBuilder(base_va)
    a.emit(0xE51B3170)             # system descriptor
    a.emit(0xE59330C4)             # short-name / Arcade flag
    a.emit(0xE3530000)
    a.branch('stock', cond=0x0)
    a.emit(0xE51B003C)             # resolved English GetGameName char *
    a.emit(0xE3500000)
    a.branch('stock', cond=0x0)
    a.branch(strlen_va, link=True)
    a.branch('done')
    a.label('stock')
    a.emit(0xE24B00C8)             # filename-derived std::string
    a.branch(stock_size_va, link=True)
    a.label('done')
    a.branch(continue_va)
    return a.finish()


def find_redundant_surface_copy_calls(
        data: bytes | bytearray, segs: list[Segment],
        img_load_va: int, sdl_convert_surface_va: int,
        sdl_free_surface_va: int) -> tuple[int, list[int], int]:
    """Return the preview site, four theme sites, and stock image wrapper.

    MainUI's generic image wrapper performs IMG_Load, clones the surface into its
    own format with SDL_ConvertSurface, then frees the original. The known direct
    callers are one 250x360 game-preview load, one lazy theme/image load, and
    three path-selection branches in the shared skin asset resolver. Every site
    is structurally classified before any branch is redirected.
    """
    preview_site = (unique(data, ROM_PREVIEW_LOAD_CALL_SIG,
                           '250x360 game-preview image load') +
                    ROM_PREVIEW_LOAD_CALL_OFF)
    preview_va = off2va(segs, preview_site)
    for index, expected in enumerate(ROM_PREVIEW_LOAD_AFTER, start=1):
        if read_word(data, preview_site + index * 4) != expected:
            raise ValueError('game-preview load call tail is not stock')

    wrapper_va = decode_arm_branch_target(
        read_word(data, preview_site), preview_va)
    if wrapper_va is None:
        raise ValueError('game-preview load site is not an ARM BL instruction')
    wrapper_off = va2off(segs, wrapper_va, executable=True)
    expected_prefix = (
        0xE92D4800,  # push {fp,lr}
        0xE28DB004,  # add fp,sp,#4
        0xE24DD018,  # sub sp,sp,#24
        0xE50B0010,  # str r0,[fp,#-16]
        0xE50B1014,  # str r1,[fp,#-20]
        0xE1A03002,  # mov r3,r2
        0xE54B3015,  # strb r3,[fp,#-21]
        0xE51B0010,  # ldr r0,[fp,#-16]
    )
    for index, expected in enumerate(expected_prefix):
        if read_word(data, wrapper_off + index * 4) != expected:
            raise ValueError('stock image wrapper prefix changed')

    calls = (
        (0x20, img_load_va, 'IMG_Load'),
        (0x4C, sdl_convert_surface_va, 'SDL_ConvertSurface'),
        (0x94, sdl_free_surface_va, 'SDL_FreeSurface'),
    )
    for rel, expected_target, label in calls:
        call_off = wrapper_off + rel
        actual = decode_arm_branch_target(
            read_word(data, call_off), off2va(segs, call_off))
        if actual != expected_target:
            raise ValueError(
                f'stock image wrapper {label} target changed: {actual!r}')

    if read_word(data, wrapper_off + 0x3C) != 0xE5933004:
        raise ValueError('stock image wrapper no longer loads surface->format')
    if read_word(data, wrapper_off + 0x40) != 0xE3A02000:
        raise ValueError('stock image wrapper conversion flags are not zero')
    if read_word(data, wrapper_off + 0x44) != 0xE1A01003:
        raise ValueError('stock image wrapper format argument changed')
    if read_word(data, wrapper_off + 0x48) != 0xE51B0008:
        raise ValueError('stock image wrapper source argument changed')

    references: list[int] = []
    for seg in segs:
        if not (seg.flags & 1):
            continue
        start = (seg.file_off + 3) & ~3
        end = seg.file_off + seg.file_size - 3
        for call_off in range(start, end, 4):
            target = decode_arm_branch_target(
                read_word(data, call_off), off2va(segs, call_off))
            if target == wrapper_va:
                references.append(call_off)
    references.sort()
    if len(references) != 5:
        raise ValueError(
            'stock self-copy wrapper direct-call count changed: '
            f'expected 5, found {len(references)}')
    if preview_site not in references:
        raise ValueError('preview call is missing from wrapper references')

    lazy_prefix = (
        0xE3013928,  # movw r3,#0x1928 -- debug stream/global
        0xE3403018,  # movt r3,#0x18
        0xE5933000,  # ldr r3,[r3]
        0xE3A02000,  # mov r2,#0
        0xE1A01003,  # mov r1,r3
    )
    lazy_suffix = (
        0xE1A02000,  # mov r2,r0
        0xE51B3028,  # ldr r3,[fp,#-0x28]
    )
    resolver_prefix = (
        0xE5DB3004,  # ldrb r3,[fp,#4]
        0xE1A02003,  # mov r2,r3
        0xE51B103C,  # ldr r1,[fp,#-0x3c]
    )
    resolver_returns = {0xE1A03000, 0xE1A04000}  # mov r3/r4,r0

    lazy_sites: list[int] = []
    resolver_sites: list[int] = []
    for call_off in references:
        if call_off == preview_site:
            continue
        if (tuple(read_word(data, call_off - 20 + 4 * i)
                  for i in range(5)) == lazy_prefix and
                tuple(read_word(data, call_off + 4 + 4 * i)
                      for i in range(2)) == lazy_suffix):
            lazy_sites.append(call_off)
            continue
        if (tuple(read_word(data, call_off - 12 + 4 * i)
                  for i in range(3)) == resolver_prefix and
                read_word(data, call_off + 4) in resolver_returns):
            resolver_sites.append(call_off)
            continue
        raise ValueError(
            'unclassified stock self-copy wrapper caller at '
            f'{off2va(segs, call_off):#x}')

    if len(lazy_sites) != 1 or len(resolver_sites) != 3:
        raise ValueError(
            'theme image caller layout changed: expected one lazy and three '
            f'resolver calls, found {len(lazy_sites)} and {len(resolver_sites)}')
    theme_sites = lazy_sites + sorted(resolver_sites)
    return preview_site, theme_sites, wrapper_va


def find_thumbnail_cache_free_callback(
        data: bytes | bytearray, segs: list[Segment],
        sdl_free_surface_va: int) -> tuple[int, list[int]]:
    """Find the game-preview cache cleanup callback and its cache constructors.

    The callback is a dedicated one-argument wrapper around SDL_FreeSurface.
    MainUI constructs three related game-preview cache instances with that same
    callback. Returning the constructor references lets the patch fail closed if
    the cache ownership layout changes in a future binary.
    """
    callback_prefix = (
        0xE92D4800,  # push {fp,lr}
        0xE28DB004,  # add fp,sp,#4
        0xE24DD010,  # sub sp,sp,#16
        0xE50B0010,  # str r0,[fp,#-16]
        0xE51B3010,  # ldr r3,[fp,#-16]
        0xE50B3008,  # str r3,[fp,#-8]
        0xE51B0008,  # ldr r0,[fp,#-8]
    )
    callback_suffix = (
        0xE320F000,  # nop
        0xE24BD004,  # sub sp,fp,#4
        0xE8BD8800,  # pop {fp,pc}
    )
    callback_candidates: list[int] = []
    for seg in segs:
        if not (seg.flags & 1):
            continue
        start = align_up(seg.file_off, 4)
        end = seg.file_off + seg.file_size - 44
        for off in range(start, end + 1, 4):
            if tuple(read_word(data, off + i * 4)
                     for i in range(len(callback_prefix))) != callback_prefix:
                continue
            call_site = off + len(callback_prefix) * 4
            target = decode_arm_branch_target(
                read_word(data, call_site), off2va(segs, call_site))
            if target != sdl_free_surface_va:
                continue
            suffix_site = call_site + 4
            if tuple(read_word(data, suffix_site + i * 4)
                     for i in range(len(callback_suffix))) != callback_suffix:
                continue
            callback_candidates.append(off2va(segs, off))
    if len(callback_candidates) != 1:
        raise ValueError(
            'expected one game-preview SDL_FreeSurface callback, found '
            f'{len(callback_candidates)}')
    callback_va = callback_candidates[0]

    constructor_refs: list[int] = []
    expected_low = arm_movw(1, callback_va & 0xFFFF)
    expected_high = arm_movt(1, (callback_va >> 16) & 0xFFFF)
    for seg in segs:
        if not (seg.flags & 1):
            continue
        start = align_up(seg.file_off, 4)
        end = seg.file_off + seg.file_size - 20
        for off in range(start, end + 1, 4):
            words = tuple(read_word(data, off + i * 4) for i in range(5))
            if words[:4] != (
                    0xE2833080, expected_low, expected_high, 0xE1A00003):
                continue
            if decode_arm_branch_target(words[4], off2va(segs, off + 16)) is None:
                continue
            constructor_refs.append(off2va(segs, off))
    if len(constructor_refs) != 3:
        raise ValueError(
            'expected three game-preview cache constructors, found '
            f'{len(constructor_refs)}')
    return callback_va, constructor_refs


def build_thumbnail_cache_limit_compare(base_va: int,
                                        thumbnail_free_callback_va: int) -> bytes:
    """Return a compare helper that preserves the stock limit for other caches."""
    a = ArmBuilder(base_va)
    a.emit(0xE51BC030)  # ldr ip,[fp,#-0x30] -- generic cache object
    a.emit(0xE59CC00C)  # ldr ip,[ip,#0x0c] -- cleanup callback
    a.emit(arm_movw(0, thumbnail_free_callback_va & 0xFFFF))
    a.emit(arm_movt(0, (thumbnail_free_callback_va >> 16) & 0xFFFF))
    a.emit(0xE15C0000)  # cmp ip,r0
    a.branch('thumbnail', cond=0x0)
    a.emit(THUMBNAIL_CACHE_STOCK_COMPARE)  # cmp r3,#1000
    a.emit(0xE12FFF1E)  # bx lr
    a.label('thumbnail')
    a.emit(0xE353003F)  # cmp r3,#63 -> effective post-insert ceiling 64
    a.emit(0xE12FFF1E)  # bx lr
    return a.finish()


def find_game_font_style_sites(data: bytes | bytearray,
                               segs: list[Segment],
                               set_style_va: int) -> list[int]:
    """Find stock bold-style calls for the shared game-list font.

    MainUI opens the font through one of six loader branches, then applies
    ``TTF_STYLE_BOLD`` at four common post-branch sites. A loader-only wrapper
    runs too early: these calls overwrite an earlier normal-style selection.
    """
    prefix = (
        arm_movw(3, FONT_GLOBAL_PTR & 0xFFFF),
        arm_movt(3, FONT_GLOBAL_PTR >> 16),
        0xE5933000,  # ldr r3,[r3]
        0xE3A01001,  # mov r1,#TTF_STYLE_BOLD
        0xE1A00003,  # mov r0,r3
    )
    sites: list[int] = []
    for seg in segs:
        if not (seg.flags & 1):
            continue
        begin = align_up(seg.file_off, 4)
        finish = seg.file_off + seg.file_size - (len(prefix) + 1) * 4
        for off in range(begin, finish + 1, 4):
            if tuple(read_word(data, off + i * 4)
                     for i in range(len(prefix))) != prefix:
                continue
            call_site = off + len(prefix) * 4
            target = decode_arm_branch_target(
                read_word(data, call_site), off2va(segs, call_site))
            if target == set_style_va:
                sites.append(call_site)
    if len(sites) != 4:
        raise ValueError(
            f'expected 4 stock game-list bold-style calls, found {len(sites)}')
    return sites


def find_game_font_loader_sites(
        data: bytes | bytearray, segs: list[Segment], *, progress=None,
        progress_start: int = 0, progress_end: int = 0,
        progress_label: str = 'Scanning game-font hooks') -> tuple[list[int], int]:
    """Find the six calls that populate global game/list font 0x18217c.

    The scan is one of the patcher's more expensive host-side signature
    searches.  An optional progress callback exposes eight real scan
    checkpoints without changing matching behavior or patched bytes.
    """
    exec_seg = next(s for s in segs if s.flags & 1)
    sites: list[int] = []
    target: int | None = None
    begin = exec_seg.file_off
    end = exec_seg.file_off + exec_seg.file_size - 20
    span = max(1, end - begin)
    checkpoint = 1
    checkpoint_count = 8
    next_checkpoint_off = begin + span * checkpoint // checkpoint_count
    for off in range(begin, end + 1, 4):
        if progress is not None and checkpoint <= checkpoint_count and off >= next_checkpoint_off:
            scan_percent = checkpoint * 100 // checkpoint_count
            outer_percent = (
                progress_start +
                (progress_end - progress_start) * checkpoint // checkpoint_count)
            progress(outer_percent, f'{progress_label} ({scan_percent}%)')
            checkpoint += 1
            if checkpoint <= checkpoint_count:
                next_checkpoint_off = (
                    begin + span * checkpoint // checkpoint_count)
        if tuple(read_word(data, off + 4 + i * 4) for i in range(4)) != FONT_LOADER_STORE_TAIL:
            continue
        src_va = off2va(segs, off)
        dst = decode_arm_branch_target(read_word(data, off), src_va)
        if dst is None:
            continue
        if target is None:
            target = dst
        elif dst != target:
            raise ValueError('game-font loader sites do not share one target')
        sites.append(off)
    if progress is not None and checkpoint <= checkpoint_count:
        progress(progress_end, f'{progress_label} (100%)')
    if len(sites) != 6 or target is None:
        raise ValueError(f'expected 6 game-font loader sites, found {len(sites)}')
    return sites, target


def find_textmenu_keymap_call(data: bytes | bytearray,
                              segs: list[Segment]) -> tuple[int, int]:
    """Return the shared TextMenu key-translator BL and its stock target.

    The retained signature pins the surrounding TextMenu input sequence while
    leaving the branch displacement itself variant-tolerant.  The call word is
    decoded separately as a link-sensitive ARM BL, so a same-target plain B
    cannot satisfy this ownership check.
    """
    call_off = TEXT_MENU_KEYMAP_CALL_OFF
    if call_off < 0 or call_off + 4 > len(TEXT_MENU_KEYMAP_SIG):
        raise ValueError('TextMenu keymap call offset lies outside its signature')
    prefix = TEXT_MENU_KEYMAP_SIG[:call_off]
    suffix = TEXT_MENU_KEYMAP_SIG[call_off + 4:]
    candidates: list[tuple[int, int]] = []
    for off in find_all(data, prefix):
        try:
            start_va = off2va(segs, off)
            end_va = off2va(segs, off + len(TEXT_MENU_KEYMAP_SIG) - 1)
        except ValueError:
            continue
        if end_va - start_va != len(TEXT_MENU_KEYMAP_SIG) - 1:
            continue
        if data[off + call_off + 4:off + len(TEXT_MENU_KEYMAP_SIG)] != suffix:
            continue
        site = off + call_off
        target = decode_arm_call_target(
            read_word(data, site), off2va(segs, site))
        if target is not None:
            candidates.append((site, target))
    if len(candidates) != 1:
        raise ValueError(
            f'expected one signature-owned TextMenu key translator BL, found '
            f'{len(candidates)}')
    return candidates[0]


def decode_mov_imm16(word: int, rd: int, *, top: bool) -> int | None:
    """Decode ARM MOVW/MOVT immediate when the opcode and destination match."""
    opcode = 0xE3400000 if top else 0xE3000000
    if (word & 0xFFF0F000) != (opcode | (rd << 12)):
        return None
    return ((word >> 4) & 0xF000) | (word & 0x0FFF)


def find_navigation_click_sound(data: bytes | bytearray,
                                segs: list[Segment],
                                mix_play_channel_timed_va: int) -> int:
    """Return MainUI's normal navigation-click Mix_Chunk global."""
    tail = (
        0xE5933000,  # ldr r3,[r3]
        0xE3530000,  # cmp r3,#0
    )
    play_tail = (
        0xE5931000,  # ldr r1,[r3]
        0xE3E03000,  # mvn r3,#0
        0xE3A02000,  # mov r2,#0
        0xE3A00001,  # mov r0,#1
    )
    candidates: list[int] = []
    for seg in segs:
        if not (seg.flags & 1):
            continue
        start = align_up(seg.file_off, 4)
        end = seg.file_off + seg.file_size - 48
        for off in range(start, end + 1, 4):
            low = decode_mov_imm16(read_word(data, off), 3, top=False)
            high = decode_mov_imm16(read_word(data, off + 4), 3, top=True)
            if low is None or high is None:
                continue
            global_va = low | (high << 16)
            if tuple(read_word(data, off + 8 + i * 4)
                     for i in range(2)) != tail:
                continue
            # Skip the conditional branch at +16; the same global is reloaded.
            low2 = decode_mov_imm16(read_word(data, off + 20), 3, top=False)
            high2 = decode_mov_imm16(read_word(data, off + 24), 3, top=True)
            if low2 != low or high2 != high:
                continue
            if tuple(read_word(data, off + 28 + i * 4)
                     for i in range(4)) != play_tail:
                continue
            call_site = off + 44
            target = decode_arm_branch_target(
                read_word(data, call_site), off2va(segs, call_site))
            if target == mix_play_channel_timed_va:
                candidates.append(global_va)
    if len(candidates) != 1:
        raise ValueError(
            f'expected one normal navigation-click sound source, found {len(candidates)}')
    return candidates[0]


def find_theme_list_object_call(
        data: bytes | bytearray, segs: list[Segment], *, progress=None,
        progress_start: int = 0, progress_end: int = 0,
        progress_label: str = 'Scanning active-theme list lookup') -> tuple[int, int]:
    """Return the active theme's top-level `list` lookup and stock target.

    The literal ``list`` is shared with unrelated JSON parsers, so require the
    verified theme-root stack slot and the immediately following list-style
    initialization sequence. The wrapper receives the real theme root in r0;
    that is required to read the patch-only top-level ``gamelist`` object.

    This is a deliberately broad signature search.  Optional progress reports
    expose eight real scan checkpoints so slower hosts do not appear stalled.
    """
    needle = b'list\0'
    list_vas: list[int] = []
    search = 0
    while True:
        off = data.find(needle, search)
        if off < 0:
            break
        try:
            list_vas.append(off2va(segs, off))
        except ValueError:
            pass
        search = off + 1

    candidates: list[tuple[int, int]] = []
    post = (
        0xE1A03000,  # mov r3,r0
        0xE50B3010,  # str r3,[fp,#-0x10]
        0xE3A03018,  # mov r3,#24 -- stock list-size default
        0xE50B3024,  # str r3,[fp,#-0x24]
    )
    executable_ranges: list[tuple[int, int]] = []
    window_words = 3 + 1 + len(post)
    for seg in segs:
        if not (seg.flags & 1):
            continue
        begin = align_up(seg.file_off, 4)
        finish = seg.file_off + seg.file_size - window_words * 4
        if finish >= begin:
            executable_ranges.append((begin, finish))
    words_per_literal = sum(
        (finish - begin) // 4 + 1 for begin, finish in executable_ranges)
    total_steps = max(1, words_per_literal * max(1, len(list_vas)))
    completed_steps = 0
    checkpoint = 1
    checkpoint_count = 8
    next_checkpoint = total_steps * checkpoint // checkpoint_count

    for list_va in list_vas:
        pre = (
            arm_movw(1, list_va & 0xFFFF),
            arm_movt(1, list_va >> 16),
            0xE51B01CC,  # ldr r0,[fp,#-0x1cc] -- active theme root
        )
        for begin, finish in executable_ranges:
            for off in range(begin, finish + 1, 4):
                completed_steps += 1
                if (progress is not None and checkpoint <= checkpoint_count and
                        completed_steps >= next_checkpoint):
                    scan_percent = checkpoint * 100 // checkpoint_count
                    outer_percent = (
                        progress_start +
                        (progress_end - progress_start) * checkpoint //
                        checkpoint_count)
                    progress(
                        outer_percent,
                        f'{progress_label} ({scan_percent}%)')
                    checkpoint += 1
                    if checkpoint <= checkpoint_count:
                        next_checkpoint = (
                            total_steps * checkpoint // checkpoint_count)
                if tuple(read_word(data, off + i * 4)
                         for i in range(len(pre))) != pre:
                    continue
                site = off + len(pre) * 4
                if tuple(read_word(data, site + 4 + i * 4)
                         for i in range(len(post))) != post:
                    continue
                target = decode_arm_branch_target(
                    read_word(data, site), off2va(segs, site))
                if target is not None:
                    candidates.append((site, target))
    if progress is not None and checkpoint <= checkpoint_count:
        progress(progress_end, f'{progress_label} (100%)')
    if len(candidates) != 1:
        raise ValueError(
            f'expected one active-theme list object lookup, found '
            f'{len(candidates)}')
    return candidates[0]


def find_dialog_action_style_sites(data: bytes | bytearray,
                                   segs: list[Segment]) -> list[tuple[int, int]]:
    """Return all four DialogWindow action-label font/color MOVW sites."""
    expected_font = (
        arm_movw(3, DIALOG_ACTION_FONT_GLOBAL_STOCK & 0xFFFF),
        arm_movt(3, DIALOG_ACTION_FONT_GLOBAL_STOCK >> 16),
    )

    generic_color = (
        arm_movw(3, DIALOG_ACTION_COLOR_GLOBAL_STOCK_GENERIC & 0xFFFF),
        arm_movt(3, DIALOG_ACTION_COLOR_GLOBAL_STOCK_GENERIC >> 16),
    )
    confirm_color = (
        arm_movw(3, DIALOG_ACTION_COLOR_GLOBAL_STOCK_CONFIRM & 0xFFFF),
        arm_movt(3, DIALOG_ACTION_COLOR_GLOBAL_STOCK_CONFIRM >> 16),
    )

    generic: list[tuple[int, int]] = []
    confirm: list[tuple[int, int]] = []
    for seg in segs:
        if not (seg.flags & 1):
            continue
        begin = align_up(seg.file_off, 4)
        finish = seg.file_off + seg.file_size - 0x60
        for off in range(begin, finish + 1, 4):
            if tuple(read_word(data, off + i * 4) for i in range(2)) != expected_font:
                continue

            # Compact generic dialog: font load, branch-specific state test,
            # then the list-color global 0x44 bytes later.
            if tuple(read_word(data, off + 8 + i * 4)
                     for i in range(3)) == DIALOG_ACTION_GENERIC_FONT_TAIL:
                color_site = off + 0x44
                if tuple(read_word(data, color_site + i * 4)
                         for i in range(2)) == generic_color and tuple(
                             read_word(data, color_site + 8 + i * 4)
                             for i in range(3)) == DIALOG_ACTION_COLOR_TAIL:
                    generic.append((off, color_site))

            # Larger confirmation dialog used by Shutdown: font load is
            # followed immediately by translation ID 45 or 46; its dark action
            # color appears 0x28 bytes after the font global.
            font_tail = tuple(read_word(data, off + 8 + i * 4) for i in range(2))
            if font_tail in DIALOG_ACTION_CONFIRM_FONT_TAILS:
                color_site = off + 0x28
                if tuple(read_word(data, color_site + i * 4)
                         for i in range(2)) == confirm_color and tuple(
                             read_word(data, color_site + 8 + i * 4)
                             for i in range(3)) == DIALOG_ACTION_COLOR_TAIL:
                    confirm.append((off, color_site))

    if len(generic) != 2:
        raise ValueError(
            f'expected two generic dialog action-label style branches, '
            f'found {len(generic)}')
    if len(confirm) != 2:
        raise ValueError(
            f'expected two confirmation dialog action-label style branches, '
            f'found {len(confirm)}')
    return generic + confirm


def verify_rom_window_loader_provenance(
        data: bytes | bytearray, segs: list[Segment],
        forward_va: int, backward_va: int) -> None:
    """Fail closed if the resolved async-loader bodies/ABI change.

    The vtable wrappers already pin the direct BL destinations.  The wrap/page
    helpers additionally rely on those destinations being the stock async
    forward/backward loaders and on r4 being callee-saved.  Verify the loader
    bodies themselves rather than trusting only the encoded wrapper targets.
    """
    def verify_one(loader_va: int, direction: str) -> int:
        off = va2off(segs, loader_va, executable=True)
        # Shared entry shape explicitly proves r4-r8/fp/lr preservation and
        # the stock object/state gate used by both async window loaders.
        expected_prefix = (
            0xE92D49F0,             # push {r4-r8,fp,lr}
            0xE28DB018,             # add fp,sp,#24
            0xE24DD044,             # sub sp,sp,#68
            0xE50B0030,             # str r0,[fp,#-0x30]
            0xE51B3030,             # ldr r3,[fp,#-0x30]
            0xE5933140,             # ldr r3,[r3,#0x140]
            0xE3530000,             # cmp r3,#0
        )
        actual_prefix = tuple(read_word(data, off + i * 4)
                              for i in range(len(expected_prefix)))
        if actual_prefix != expected_prefix:
            raise ValueError(
                f'ROM {direction} async loader provenance changed at '
                f'{loader_va:#x}')

        # Direction-specific selected/window arithmetic identifies which stock
        # loader was resolved without hard-coding only its address.
        if direction == 'forward':
            expected_body = (
                0xE51B3030, 0xE593300C, 0xE50B3024,
                0xE3A03006, 0xE50B3020,
            )
            body_rel = 0x20
            epilogue_rel = 0x138
        else:
            expected_body = (
                0xE51B3030, 0xE593300C, 0xE2433005, 0xE50B3020,
                0xE3A03006, 0xE50B3024,
            )
            body_rel = 0x20
            epilogue_rel = 0x130
        actual_body = tuple(read_word(data, off + body_rel + i * 4)
                            for i in range(len(expected_body)))
        if actual_body != expected_body:
            raise ValueError(
                f'ROM {direction} async loader direction signature changed at '
                f'{loader_va:#x}')

        # Both loaders build the same worker object through the same direct BL.
        worker_calls: list[int] = []
        for rel in range(0, epilogue_rel, 4):
            word = read_word(data, off + rel)
            if (word & 0x0F000000) != 0x0B000000:
                continue
            # The immediately preceding argument-transfer quartet is the
            # distinctive worker-construction call, independent of its VA.
            if rel >= 16 and tuple(read_word(data, off + rel - 16 + i * 4)
                                   for i in range(4)) == (
                    0xE1A03008, 0xE1A02007, 0xE1A01006, 0xE1A00004):
                target = decode_arm_branch_target(word, loader_va + rel)
                if target is not None:
                    worker_calls.append(target)
        if len(worker_calls) != 1:
            raise ValueError(
                f'ROM {direction} async loader worker-call provenance changed')

        # Explicit callee-saved epilogue guard closes the r4-preservation
        # assumption consumed by the injected wrappers.
        if read_word(data, off + epilogue_rel) != 0xE8BD89F0:
            raise ValueError(
                f'ROM {direction} async loader epilogue/register contract changed')
        return worker_calls[0]

    forward_worker = verify_one(forward_va, 'forward')
    backward_worker = verify_one(backward_va, 'backward')
    if forward_worker != backward_worker:
        raise ValueError(
            'ROM async forward/backward loaders no longer share the stock worker')


def find_rom_window_loader_targets(data: bytes | bytearray,
                                   segs: list[Segment]) -> tuple[int, int]:
    """Return ROM-list forward/backward asynchronous window loaders.

    ROM vtable slots +0x24/+0x28 are short wrappers around generic one-row
    movement followed by the corresponding loader. Resolve the second BL in
    each wrapper instead of hard-coding build-specific function addresses.
    """
    vtable_off = va2off(segs, ROM_VTABLE)

    def second_bl(slot: int, label: str) -> int:
        wrapper_va = read_word(data, vtable_off + slot)
        wrapper_off = va2off(segs, wrapper_va, executable=True)
        targets: list[int] = []
        for rel in range(0, 0x60, 4):
            site = wrapper_off + rel
            word = read_word(data, site)
            if (word & 0x0F000000) == 0x0B000000:
                target = decode_arm_branch_target(word, wrapper_va + rel)
                if target is not None:
                    targets.append(target)
            # Stop at the wrapper's first POP/LDM including pc instead of
            # scanning into the following function.
            if (word & 0xFFFF8000) == 0xE8BD8000:
                break
        if len(targets) != 2:
            raise ValueError(
                f'{label}: expected two direct BL calls, found {len(targets)}')
        va2off(segs, targets[1], executable=True)
        return targets[1]

    forward_va = second_bl(0x24, 'ROM forward one-row wrapper')
    backward_va = second_bl(0x28, 'ROM backward one-row wrapper')
    verify_rom_window_loader_provenance(data, segs, forward_va, backward_va)
    return forward_va, backward_va


def find_rom_one_row_loader_call_sites(
        data: bytes | bytearray, segs: list[Segment],
        forward_loader_va: int, backward_loader_va: int) -> tuple[int, int]:
    """Return exact loader-call sites in one-row Down/Up ROM wrappers."""
    vtable_off = va2off(segs, ROM_VTABLE)

    def loader_call_site(slot: int, expected_loader_va: int, label: str) -> int:
        wrapper_va = read_word(data, vtable_off + slot)
        wrapper_off = va2off(segs, wrapper_va, executable=True)
        calls: list[tuple[int, int]] = []
        for rel in range(0, 0x60, 4):
            site = wrapper_off + rel
            word = read_word(data, site)
            if (word & 0x0F000000) == 0x0B000000:
                target = decode_arm_branch_target(word, wrapper_va + rel)
                if target is not None:
                    calls.append((site, target))
            if (word & 0xFFFF8000) == 0xE8BD8000:
                break
        if len(calls) != 2:
            raise ValueError(
                f'{label}: expected two direct BL calls, found {len(calls)}')
        if calls[1][1] != expected_loader_va:
            raise ValueError(
                f'{label}: stock loader call target changed from '
                f'{expected_loader_va:#x} to {calls[1][1]:#x}')
        return calls[1][0]

    return (
        loader_call_site(0x24, forward_loader_va, 'ROM one-row Down wrapper'),
        loader_call_site(0x28, backward_loader_va, 'ROM one-row Up wrapper'))


def find_rom_page_loader_call_sites(
        data: bytes | bytearray, segs: list[Segment],
        page_up_method_va: int, page_down_method_va: int,
        forward_loader_va: int, backward_loader_va: int) -> tuple[int, int]:
    """Return the loader-call sites in ROM page-up/page-down wrappers.

    Stock MainUI changes the selected index by one page and then calls the
    loader associated with the shoulder direction. That is wrong for the
    resulting TextMenu viewport: page-up places the target at the first visible
    row and therefore needs the forward window, while page-down places it at
    the last visible row and therefore needs the backward window. Verify the
    complete two-call wrapper shape before redirecting only the loader call.
    """
    vtable_off = va2off(segs, ROM_VTABLE)

    def loader_call_site(slot: int, expected_step_va: int,
                         expected_loader_va: int, label: str) -> int:
        wrapper_va = read_word(data, vtable_off + slot)
        wrapper_off = va2off(segs, wrapper_va, executable=True)
        calls: list[tuple[int, int]] = []
        for rel in range(0, 0x60, 4):
            site = wrapper_off + rel
            word = read_word(data, site)
            if (word & 0x0F000000) == 0x0B000000:
                target = decode_arm_branch_target(word, wrapper_va + rel)
                if target is not None:
                    calls.append((site, target))
            if (word & 0xFFFF8000) == 0xE8BD8000:
                break
        if len(calls) != 2:
            raise ValueError(
                f'{label}: expected two direct BL calls, found {len(calls)}')
        if calls[0][1] != expected_step_va:
            raise ValueError(
                f'{label}: page-step call target changed from '
                f'{expected_step_va:#x} to {calls[0][1]:#x}')
        if calls[1][1] != expected_loader_va:
            raise ValueError(
                f'{label}: stock loader call target changed from '
                f'{expected_loader_va:#x} to {calls[1][1]:#x}')
        return calls[1][0]

    page_up_loader_site = loader_call_site(
        0x40, page_up_method_va, backward_loader_va,
        'ROM L2/page-up wrapper')
    page_down_loader_site = loader_call_site(
        0x44, page_down_method_va, forward_loader_va,
        'ROM R2/page-down wrapper')
    return page_up_loader_site, page_down_loader_site


def _is_arm_frame_prologue(data: bytes | bytearray, off: int) -> bool:
    """Return whether ``off`` looks like a normal ARM function prologue.

    MainUI functions use ``stmdb sp!, {..., fp, lr}`` followed shortly by an
    fp setup.  Requiring both fp and lr avoids treating a small temporary
    register save inside a function as the start of a new function.
    """
    if off < 0 or off + 4 > len(data):
        return False
    word = read_word(data, off)
    if (word & 0xFFFF0000) != 0xE92D0000:
        return False
    register_mask = word & 0xFFFF
    if not (register_mask & (1 << 11)) or not (register_mask & (1 << 14)):
        return False
    # GCC commonly emits either add fp,sp,#imm or mov fp,sp within the next
    # few instructions.  Keep this deliberately permissive across variants.
    for delta in (4, 8, 12, 16):
        if off + delta + 4 > len(data):
            break
        follow = read_word(data, off + delta)
        if (follow & 0xFFFFF000) == 0xE28DB000:  # add fp,sp,#imm
            return True
        if follow == 0xE1A0B00D:              # mov fp,sp
            return True
    return False


def _arm_function_bounds(data: bytes | bytearray, segs: list[Segment],
                         anchor_off: int) -> tuple[int, int]:
    """Find conservative file bounds for the ARM function containing anchor."""
    exec_seg = next(s for s in segs if s.flags & 1)
    exec_start = exec_seg.file_off
    exec_end = exec_seg.file_off + exec_seg.file_size

    start = None
    lower = max(exec_start, anchor_off - 0x3000)
    for off in range(anchor_off & ~3, lower - 1, -4):
        if _is_arm_frame_prologue(data, off):
            start = off
            break
    if start is None:
        raise ValueError('game-row renderer: enclosing ARM prologue not found')

    end = None
    upper = min(exec_end, start + 0x6000)
    for off in range(start + 4, upper, 4):
        if _is_arm_frame_prologue(data, off):
            end = off
            break
    if end is None:
        raise ValueError('game-row renderer: following ARM prologue not found')
    if not start <= anchor_off < end:
        raise ValueError('game-row renderer: invalid function bounds')
    return start, end


def find_direct_bl_call_sites(data: bytes | bytearray, segs: list[Segment],
                              target_va: int, label: str, *,
                              minimum: int = 1, maximum: int = 16) -> list[int]:
    """Find direct ARM BL calls to one function in executable PT_LOADs."""
    sites: list[int] = []
    for seg in segs:
        if not (seg.flags & 1):
            continue
        start = align_up(seg.file_off, 4)
        end = seg.file_off + seg.file_size
        for off in range(start, end - 3, 4):
            word = read_word(data, off)
            if (word & 0xFF000000) != 0xEB000000:
                continue
            if decode_arm_branch_target(word, off2va(segs, off)) == target_va:
                sites.append(off)
    sites = sorted(set(sites))
    if not minimum <= len(sites) <= maximum:
        raise ValueError(
            f'expected {minimum}..{maximum} direct {label} call sites; '
            f'found {len(sites)}')
    return sites


def find_main_input_wait_site(data: bytes | bytearray, segs: list[Segment],
                              wait_event_va: int) -> int:
    """Locate the single SDL_WaitEvent in MainUI's central event translator."""
    sites = find_direct_bl_call_sites(
        data, segs, wait_event_va, 'SDL_WaitEvent', minimum=1, maximum=16)
    candidates: list[int] = []
    post = (
        0xE1A03000,  # mov r3,r0
        0xE3530000,  # cmp r3,#0
        0x13A03001,  # movne r3,#1
        0x03A03000,  # moveq r3,#0
        0xE6EF3073,  # uxtb r3,r3
        0xE3530000,  # cmp r3,#0
    )
    for site in sites:
        if site < 4 or site + 4 + len(post) * 4 > len(data):
            continue
        if read_word(data, site - 8) != 0xE24B3028:  # sub r3,fp,#40
            continue
        if read_word(data, site - 4) != 0xE1A00003:  # mov r0,r3 event local
            continue
        if tuple(read_word(data, site + 4 + i * 4)
                 for i in range(len(post))) != post:
            continue
        if read_word(data, site + 0x20) != 0xE55B3028:  # event.type
            continue
        if read_word(data, site + 0x24) != 0xE3530018:  # SDL_USEREVENT
            continue
        candidates.append(site)
    if len(candidates) != 1:
        raise ValueError(
            'expected exactly one central MainUI SDL_WaitEvent site; found ' +
            ', '.join(hex(off2va(segs, x)) for x in candidates))
    return candidates[0]


def _direct_call_sites_in_range(data: bytes | bytearray, segs: list[Segment],
                                start: int, end: int, target_va: int) -> list[int]:
    """Return direct ARM BL sites to ``target_va`` in one file range."""
    sites: list[int] = []
    for off in range(align_up(start, 4), end - 3, 4):
        word = read_word(data, off)
        if (word & 0x0F000000) != 0x0B000000:
            continue
        if decode_arm_branch_target(word, off2va(segs, off)) == target_va:
            sites.append(off)
    return sites


def find_game_label_helper_sites(
        data: bytes | bytearray, segs: list[Segment],
        render_utf8_va: int, upper_blit_va: int, free_surface_va: int
        ) -> tuple[list[int], list[int], list[int], int]:
    """Locate the row-title helper, shared label blit, and preview blit.

    MainUI's game-row renderer does *not* call the low-level text helper
    directly for ordinary row titles. It calls a larger row-title/layout
    helper, and that helper selects one of several calls to the shared
    ``TTF_RenderUTF8_Blended -> SDL_UpperBlit -> SDL_FreeSurface`` routine.

    Returns ``(row_helper_call_sites, helper_blit_sites, preview_blit_sites,
    row_helper_va)``. The row-helper wrapper compares the renderer's current-row
    local against ``TextMenu::selected`` directly, so it does not depend on a theme
    selection-bar image being drawn.
    """
    anchor = unique(data, FONT_SELECT_SIG, 'game-row stock font load')
    renderer_start, renderer_end = _arm_function_bounds(data, segs, anchor)

    target_calls: dict[int, list[int]] = {}
    for off in range(renderer_start, renderer_end, 4):
        word = read_word(data, off)
        if (word & 0x0F000000) != 0x0B000000:
            continue
        target = decode_arm_branch_target(word, off2va(segs, off))
        if target is not None:
            target_calls.setdefault(target, []).append(off)

    label_candidates: list[tuple[int, list[int], tuple[int, int]]] = []
    for target in target_calls:
        try:
            target_off = va2off(segs, target, executable=True)
            helper_start, helper_end = _arm_function_bounds(data, segs, target_off)
        except ValueError:
            continue
        if helper_start != target_off:
            continue
        renders = _direct_call_sites_in_range(
            data, segs, helper_start, helper_end, render_utf8_va)
        blits = _direct_call_sites_in_range(
            data, segs, helper_start, helper_end, upper_blit_va)
        frees = _direct_call_sites_in_range(
            data, segs, helper_start, helper_end, free_surface_va)
        if renders and len(blits) == 1 and frees:
            label_candidates.append((target, blits, (helper_start, helper_end)))

    if len(label_candidates) != 1:
        summary = ', '.join(
            f'{target:#x}:blits={len(blits)}'
            for target, blits, _bounds in label_candidates) or 'none'
        raise ValueError(
            'expected exactly one shared label helper with a direct '
            'render/blit/free lifecycle; candidates: ' + summary)

    label_helper_va, blit_sites, _label_bounds = label_candidates[0]

    row_candidates: list[tuple[int, list[int], list[int]]] = []
    for target, renderer_calls in target_calls.items():
        if target == label_helper_va:
            continue
        try:
            target_off = va2off(segs, target, executable=True)
            child_start, child_end = _arm_function_bounds(data, segs, target_off)
            scan_start = child_start
            if child_start != target_off:
                # MainUI's row-title helper begins with ``sub sp,sp,#8`` and
                # places its normal push/fp prologue one instruction later.
                # Direct BL targets point at that leading stack adjustment.
                if (read_word(data, target_off) != 0xE24DD008 or
                        not _is_arm_frame_prologue(data, target_off + 4)):
                    continue
                _inner_start, child_end = _arm_function_bounds(
                    data, segs, target_off + 4)
                if _inner_start != target_off + 4:
                    continue
                scan_start = target_off
        except ValueError:
            continue
        nested_label_calls = _direct_call_sites_in_range(
            data, segs, scan_start, child_end, label_helper_va)
        if len(nested_label_calls) >= 2:
            row_candidates.append((target, renderer_calls, nested_label_calls))

    if len(row_candidates) != 1:
        summary = ', '.join(
            f'{target:#x}:renderer_calls={len(calls)},label_calls={len(nested)}'
            for target, calls, nested in row_candidates) or 'none'
        raise ValueError(
            'expected exactly one nested row-title helper; candidates: ' +
            summary)

    row_helper_va, row_call_sites, _nested_label_calls = row_candidates[0]
    if not 1 <= len(row_call_sites) <= 6:
        raise ValueError(
            f'expected 1..6 row-title helper calls in renderer, found '
            f'{len(row_call_sites)}')

    for site in row_call_sites:
        window_start = max(renderer_start, site - 0x40)
        words = [read_word(data, off)
                 for off in range(window_start, site, 4)]
        if 0xE58D4010 not in words:
            raise ValueError(
                f'row-title call {off2va(segs, site):#x} has no selected '
                'boolean store at [sp,#16]')
        if not any((word & 0xFFFFF000) == 0xE58D3000
                   for word in words):
            raise ValueError(
                f'row-title call {off2va(segs, site):#x} has no packed '
                'label-box store at [sp]')

    # The selected-game preview is not drawn inside the TextMenu row loop. It
    # is drawn later by the surrounding game-list window. The row renderer
    # call at 0x204a8 draws skin/ic-favorite-mark.png and is not a valid
    # preview boundary. The row-count patch may adjust the source-rectangle
    # setup immediately before it for vertical clipping, but title scrolling
    # must never use this icon as the preview-pane edge.
    #
    # Locate both preview-window calls structurally. The first draws the theme's
    # preview background and directly exposes the pane destination x. The second
    # draws the selected cover; when a theme has no preview background, its
    # caller frame still contains the fallback pane x at fp-0x98.
    background_candidates: list[int] = []
    artwork_candidates: list[int] = []
    for seg in segs:
        if not (seg.flags & 0x1):
            continue
        for site in _direct_call_sites_in_range(
                data, segs, seg.file_off, seg.file_off + seg.file_size,
                upper_blit_va):
            if site >= 0x18:
                words6 = [read_word(data, site - delta)
                          for delta in (0x18, 0x14, 0x10, 0x0C, 0x08, 0x04)]
                if words6 == [
                        0xE30231FC,  # movw r3,#0x21fc -- preview-bg global
                        0xE3403018,  # movt r3,#0x18
                        0xE5930000,  # ldr r0,[r3]
                        0xE24B30A0,  # sub r3,fp,#0xa0 -- destination rect
                        0xE24B10A8,  # sub r1,fp,#0xa8 -- source rect
                        0xE51B20F4,  # ldr r2,[fp,#-0xf4] -- screen
                        ]:
                    background_candidates.append(site)
            if site >= 0x14:
                words5 = [read_word(data, site - delta)
                          for delta in (0x14, 0x10, 0x0C, 0x08, 0x04)]
                if words5 == [
                        0xE51B30F0,  # ldr r3,[fp,#-0xf0] -- game-list window
                        0xE5930038,  # ldr r0,[r3,#0x38]  -- selected artwork
                        0xE24B30A0,  # sub r3,fp,#0xa0   -- destination rect
                        0xE51B20F4,  # ldr r2,[fp,#-0xf4] -- screen
                        0xE3A01000,  # mov r1,#0         -- full source
                        ]:
                    artwork_candidates.append(site)
    if len(background_candidates) != 1 or len(artwork_candidates) != 1:
        raise ValueError(
            'expected one preview-background and one selected-artwork blit; '
            f'background={len(background_candidates)}, '
            f'artwork={len(artwork_candidates)}')
    preview_sites = [background_candidates[0], artwork_candidates[0]]

    return (sorted(row_call_sites), sorted(blit_sites), preview_sites,
            row_helper_va)

def build_title_scroll_label_call(base_va: int, row_cache_va: int,
                                  state_va: int, row_helper_va: int,
                                  dynamic_row_padding: bool = False) -> bytes:
    """Wrap a row-title helper call and identify the selected complete title.

    The proven baseline behavior is retained. A previously measured selected
    favourite-marker boundary may narrow the cached marquee viewport before
    the selected title is rendered.
    """
    a = ArmBuilder(base_va)
    a.ldr_literal(12, state_va)
    a.emit(0xE58CE04C)             # state+76 = original LR
    a.ldr_literal(14, row_cache_va)
    a.emit(0xE59EC040)             # active tagged game-list object
    a.emit(0xE150000C)
    a.emit(0x159EC044)             # previous tagged object on active miss
    a.emit(0x1150000C)
    a.branch('not_game', cond=0x1)

    a.ldr_literal(12, state_va)
    a.emit(0xE59CE068)             # previous state object
    a.emit(0xE15E0000)
    a.branch('same_object', cond=0x0)
    a.emit(0xE58C0068)             # current object
    # A/B leave-screen preservation is only meaningful while the same TextMenu
    # object is still drawing its outgoing frame.  Once the active tagged
    # game-list object actually changes, the new/returned list must start from
    # its normal home position rather than inherit the previous object's phase.
    a.emit(0xE3A0E001)             # reset on first selected draw of new object
    a.emit(0xE58CE06C)
    a.emit(0xE3A0E000)
    a.emit(0xE58CE050)             # clear thumbnail
    a.emit(0xE58CE044)             # disarm
    a.emit(0xE58CE07C)             # clear favourite boundary
    a.label('same_object')
    a.emit(0xE58C3074)             # preserve stock fourth argument
    a.emit(0xE59DE000)             # packed label-box w/h
    a.emit(0xE58CE00C)

    # For the integrated row patch, overwrite only the cached marquee width
    # with the same absolute right edge used by the static title clip. The
    # row-kind-specific X remains authoritative; only the right edge is shared.
    if dynamic_row_padding:
        emit_game_list_right_bound(
            a, surface_reg=1, row_cache_va=row_cache_va, out_reg=14,
            rows_reg=3, pad_reg=12, label='marquee_outer_done')
        a.ldr_literal(12, state_va)
        a.emit(0xE59C3074)         # original packed label x/y
        a.emit(0xE6BF3073)         # sxth r3,r3 = label x
        a.emit(0xE04EE003)         # width = right edge - label x
        a.emit(0xE35E0001)
        a.emit(0xB3A0E001)         # clamp malformed geometry to 1 px
        a.emit(0xE1CCE0BC)         # replace cached width, preserve height

    # Without the row patch, preserve the established stock label-box width.

    # Compare renderer current row with TextMenu::selected. r3, the fourth
    # stock row-helper argument, was preserved before the icon-width probe.
    a.emit(0xE590E00C)             # lr = this->selected
    a.emit(0xE51B3018)             # r3 = renderer current row
    a.emit(0xE153000E)
    a.branch('not_selected', cond=0x1)

    a.emit(0xE59C3010)             # previous selected index
    a.emit(0xE153000E)
    a.branch('same_selection', cond=0x0)
    a.emit(0xE58CE010)             # remember selected index
    a.emit(0xE3A03001)
    a.emit(0xE58C306C)             # reset pending
    a.emit(0xE3A03000)
    a.emit(0xE58C3050)             # clear thumbnail
    a.emit(0xE58C3044)             # disarm
    a.emit(0xE58C307C)             # clear stale favourite boundary
    a.label('same_selection')

    # If the selected favourite marker was measured on the preceding frame,
    # narrow only the cached width consumed by the unchanged marquee blit.
    # r1/r2 remain untouched; r3 and lr are scratch and are restored below.
    a.emit(0xE59C307C)             # favourite marker left edge, or zero
    a.emit(0xE3530000)
    a.branch('favourite_ready', cond=0x0)
    a.emit(0xE59CE054)             # previous selected-title destination x
    if dynamic_row_padding:
        a.emit(0xE2433006)         # favourite_x - 6px gap
    a.emit(0xE043300E)             # available = favourite_x[-gap] - title_x
    a.emit(0xE3530000)
    a.branch('favourite_ready', cond=0xD)
    a.emit(0xE1DCE0BC)             # current cached label width
    a.emit(0xE153000E)
    a.emit(0xB1CC30BC)             # strhlt r3,[r12,#12]
    a.label('favourite_ready')

    a.emit(0xE3A03001)
    a.emit(0xE58C3048)             # selected-title marker
    a.emit(0xE28C3078)             # private NUL string at state+120
    a.emit(0xE58D3014)             # replace stack arg +20 for this call only
    a.branch('restore_r3')

    a.label('not_selected')
    a.emit(0xE3A03000)
    a.emit(0xE58C3048)             # no selected-title marker
    a.label('restore_r3')
    a.emit(0xE59C3074)
    a.branch('restore')

    a.label('not_game')
    a.ldr_literal(12, state_va)
    a.emit(0xE3A0E000)
    a.emit(0xE58CE048)

    a.label('restore')
    a.emit(0xE59CE04C)
    a.branch(row_helper_va)
    return a.finish()

def verify_title_scroll_active_previous_gates(label_code: bytes,
                                                blit_code: bytes) -> None:
    checks = (
        ('row-title marker', label_code,
         (0xE59EC040, 0xE150000C, 0x159EC044, 0x1150000C)),
        ('marquee blit', blit_code,
         (0xE5980040, 0xE150000A, 0x15980044, 0x1150000A)),
    )
    for name, code, words in checks:
        sig = struct.pack('<IIII', *words)
        if sig not in code:
            raise ValueError(
                f'title-scroll {name} lost active/previous game-list gate')


def find_title_scroll_long_copy_site(data: bytes | bytearray,
                                     segs: list[Segment],
                                     c_str_va: int,
                                     strncpy_va: int) -> tuple[int, int]:
    """Locate MainUI's selected row long-label ``strncpy(..., 64)`` path.

    Returns ``(hook_file_offset, continuation_va)``. The sequence is unique in
    the supported MainUI binary and sits in the game-row renderer immediately
    before its long-title row-helper call.
    """
    candidates: list[int] = []
    for seg in segs:
        if not (seg.flags & 1):
            continue
        start = align_up(seg.file_off, 4)
        end = seg.file_off + seg.file_size - 48
        for off in range(start, end + 1, 4):
            fixed = (
                read_word(data, off + 0x00) == 0xE51B3050 and
                read_word(data, off + 0x04) == 0xE283405D and
                read_word(data, off + 0x08) == 0xE51B3028 and
                read_word(data, off + 0x0C) == 0xE1A00003 and
                read_word(data, off + 0x14) == 0xE1A03000 and
                read_word(data, off + 0x18) == 0xE3A02040 and
                read_word(data, off + 0x1C) == 0xE1A01003 and
                read_word(data, off + 0x20) == 0xE1A00004 and
                read_word(data, off + 0x28) == 0xE51B3050 and
                read_word(data, off + 0x2C) == 0xE283505D)
            if not fixed:
                continue
            if decode_arm_branch_target(
                    read_word(data, off + 0x10),
                    off2va(segs, off + 0x10)) != c_str_va:
                continue
            if decode_arm_branch_target(
                    read_word(data, off + 0x24),
                    off2va(segs, off + 0x24)) != strncpy_va:
                continue
            candidates.append(off)
    if len(candidates) != 1:
        raise ValueError(
            'expected one stock 64-byte long-title copy path; found ' +
            str(len(candidates)))
    site = candidates[0]
    # Preserve the complete stock strncpy side effect.  Replace only the two
    # instructions that choose the scratch-buffer pointer after the copy.
    return site + 0x28, off2va(segs, site + 0x30)



def build_title_scroll_full_title_path(base_va: int, continue_va: int,
                                       c_str_va: int) -> bytes:
    """Use the complete selected title after preserving MainUI's stock copy.

    MainUI first performs its normal ``strncpy(..., 64)`` into the TextMenu
    scratch buffer.  Stock does not NUL-terminate that buffer when the source is
    at least 64 bytes, so pin scratch[63] to NUL before choosing the render
    pointer.  Non-selected rows keep the safely truncated stock scratch pointer;
    the selected row passes the original title ``std::string::c_str()`` pointer
    to the immediately following renderer call.  No event or menu-selection
    state is touched.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D4010)             # push {r4,lr}; preserve 8-byte alignment
    a.emit(0xE51B3050)             # r3 = TextMenu this
    a.emit(0xE3A00000)             # r0 = 0
    a.emit(0xE5C3009C)             # scratch[63] = NUL (this+93+63)
    a.emit(0xE593200C)             # r2 = selected index
    a.emit(0xE51B1018)             # r1 = renderer current row
    a.emit(0xE1510002)
    a.branch('stock_pointer', cond=0x1)

    a.emit(0xE51B0028)             # current game title std::string
    a.branch(c_str_va, link=True)
    a.emit(0xE1A05000)             # r5 = complete title c_str
    a.branch('done')

    a.label('stock_pointer')
    # r3 still holds TextMenu this: no call has occurred on this branch.
    a.emit(0xE283505D)             # r5 = scratch buffer at this+93
    a.label('done')
    a.emit(0xE8BD4010)             # pop {r4,lr}
    a.branch(continue_va)
    return a.finish()

def build_get_title_scroll_config(base_va: int, state_va: int,
                                  path_va: int, mode_va: int, format_va: int,
                                  fopen_va: int, fscanf_va: int,
                                  fclose_va: int) -> bytes:
    """Read and cache ``idle_ms,scroll_pixels_per_second``.

    MainUI already imports the stdio functions needed to parse the two values
    directly, without an injected byte buffer, manual token scanner, or
    separate ``atoi`` calls.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}; 8-byte aligned
    a.ldr_literal(4, state_va)
    a.emit(0xE5940000)             # status: 0 uninit, 1 disabled, 2 enabled
    a.emit(0xE3500000)
    a.branch('done', cond=0x1)
    a.emit(0xE3A08001)             # disabled unless fully parsed

    a.ldr_literal(0, path_va)
    a.ldr_literal(1, mode_va)      # "r"
    a.branch(fopen_va, link=True)
    a.emit(0xE1A05000)             # FILE *
    a.emit(0xE3550000)
    a.branch('store', cond=0x0)

    a.emit(0xE1A00005)
    a.ldr_literal(1, format_va)    # comma or space separator
    a.emit(0xE2842004)             # &idle
    a.emit(0xE2843008)             # &speed
    a.branch(fscanf_va, link=True)
    a.emit(0xE1A06000)             # conversion count
    a.emit(0xE1A00005)
    a.branch(fclose_va, link=True)
    a.emit(0xE3560002)
    a.branch('store', cond=0x1)

    a.emit(0xE5946004)             # idle
    a.emit(0xE3560000)
    a.branch('store', cond=0xB)    # negative disables
    a.emit(0xE5947008)             # speed
    a.emit(0xE3570000)
    a.branch('store', cond=0xD)    # non-positive disables

    a.emit(0xE356000A)             # cmp idle,#10
    a.emit(0xB3A0600A)             # movlt idle,#10
    a.emit(0xE3070530)             # movw r0,#30000
    a.emit(0xE1560000)
    a.emit(0xC1A06000)             # clamp idle high
    a.emit(0xE3570005)
    a.emit(0xB3A07005)             # clamp speed low
    a.emit(0xE3570E19)             # cmp r7,#400
    a.emit(0xC3A07E19)             # movgt r7,#400
    a.emit(0xE5846004)
    a.emit(0xE5847008)
    a.emit(0xE3A08002)

    a.label('store')
    a.emit(0xE5848000)
    a.emit(0xE1A00008)
    a.label('done')
    a.emit(0xE8BD81F0)
    return a.finish()



def build_title_scroll_ticks(base_va: int, gettimeofday_va: int) -> bytes:
    """Return a wrapping 32-bit millisecond counter in ``r0``.

    MainUI already imports ``gettimeofday``. Reusing that PLT entry keeps
    the helper compact. The
    microsecond division uses the exact unsigned reciprocal for division by
    1000: ``(x * 0x10624dd3) >> 38``.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D4010)             # push {r4,lr}
    a.emit(0xE24DD008)             # 8-byte timeval on stack
    a.emit(0xE1A0000D)             # r0 = sp
    a.emit(0xE3A01000)             # timezone = NULL
    a.branch(gettimeofday_va, link=True)
    a.emit(0xE3500000)
    a.branch('failed', cond=0xB)
    a.emit(0xE59D0000)             # seconds
    a.ldr_literal(1, 1000)
    a.emit(0xE0000091)             # mul r0,r1,r0
    a.emit(0xE59D1004)             # microseconds
    a.ldr_literal(4, 0x10624DD3)
    a.emit(0xE0832491)             # umull r2,r3,r1,r4
    a.emit(0xE1A01323)             # r1 = high_product >> 6
    a.emit(0xE0800001)             # milliseconds
    a.emit(0xE28DD008)
    a.emit(0xE8BD8010)             # pop {r4,pc}
    a.label('failed')
    a.emit(0xE3A00000)
    a.emit(0xE28DD008)
    a.emit(0xE8BD8010)
    return a.finish()


def build_title_scroll_preview_blit(base_va: int, state_va: int,
                                    background_return_va: int,
                                    upper_blit_va: int,
                                    fast_blit_va: int,
                                    dlsym_va: int,
                                    lock_name_va: int,
                                    unlock_name_va: int) -> bytes:
    """Record preview geometry, then try the fixed-format NEON alpha blitter.

    The geometry/probe half preserves the accepted preview-state behavior. After
    that probe, a narrowly guarded NEON software blend handles the two validated
    preview formats. SDL_LockSurface/SDL_UnlockSurface are resolved once into
    otherwise-unused title-scroll scratch words.  The helper returns zero when
    it handled the blit; any unsupported format, symbol failure, or lock failure
    falls through to the original SDL_UpperBlit with all four arguments intact.
    """
    a = ArmBuilder(base_va)
    # Preserve the accepted preview-state bookkeeping first.
    a.emit(0xE92D500F)             # push {r0-r3,ip,lr}; preserve blit args
    a.ldr_literal(3, state_va)
    a.emit(0xE5932070)             # selected-title preview marker pending?
    a.emit(0xE3520001)
    a.branch('probe_restore', cond=0x1)
    a.emit(0xE3A02000)
    a.emit(0xE5832070)
    a.ldr_literal(2, background_return_va)
    a.emit(0xE15E0002)
    a.branch('cover_call', cond=0x1)
    a.emit(0xE59D100C)             # original destination SDL_Rect *
    a.emit(0xE3510000)
    a.branch('probe_restore', cond=0x0)
    a.emit(0xE1D100F0)             # pane x
    a.branch('have_pane_x')
    a.label('cover_call')
    a.emit(0xE15B09F8)             # ldrsh r0,[fp,#-152]
    a.label('have_pane_x')
    a.emit(0xE5830050)
    a.emit(0xE5931054)
    a.emit(0xE5932058)
    a.emit(0xE0400001)
    a.emit(0xE3500000)
    a.branch('probe_restore', cond=0xD)
    a.emit(0xE1520000)
    a.emit(0xC3A01001)
    a.emit(0xC5831044)
    a.label('probe_restore')
    a.emit(0xE8BD500F)             # original r0-r3,ip,lr restored

    # Preserve original blit arguments across lazy API resolution/helper call.
    a.emit(0xE92D41F0)             # push {r4-r8,lr}; 24 bytes, ABI-aligned
    a.emit(0xE1A04000)             # r4 = src
    a.emit(0xE1A05001)             # r5 = srcrect
    a.emit(0xE1A06002)             # r6 = dst
    a.emit(0xE1A07003)             # r7 = dstrect
    a.ldr_literal(8, state_va)
    a.emit(0xE5980034)             # state+52 = API init status
    a.emit(0xE3500001)
    a.branch('have_api', cond=0x0)
    a.emit(0xE3500002)
    a.branch('fallback', cond=0x0)

    # Resolve lock/unlock once. init=2 means permanently fail open this process.
    a.emit(0xE3A00000)             # RTLD_DEFAULT
    a.ldr_literal(1, lock_name_va)
    a.branch(dlsym_va, link=True)
    a.emit(0xE588002C)             # state+44 = SDL_LockSurface
    a.emit(0xE3500000)
    a.branch('api_failed', cond=0x0)
    a.emit(0xE3A00000)
    a.ldr_literal(1, unlock_name_va)
    a.branch(dlsym_va, link=True)
    a.emit(0xE5880030)             # state+48 = SDL_UnlockSurface
    a.emit(0xE3500000)
    a.branch('api_failed', cond=0x0)
    a.emit(0xE3A00001)
    a.emit(0xE5880034)

    a.label('have_api')
    a.emit(0xE1A00004)
    # Both preview call sites cover their entire source surface. The panel passes
    # an explicit (0,0,w,h) SDL_Rect while the cover passes NULL. The fixed-format
    # helper therefore receives NULL (full source); r5 retains the exact original
    # source rect for the fail-open stock fallback below.
    a.emit(0xE3A01000)             # fast helper srcrect = NULL (full source)
    a.emit(0xE1A02006)
    a.emit(0xE1A03007)
    a.emit(0xE24DD008)             # aligned stack space for fifth argument
    a.emit(0xE288C02C)             # ip = &state[44] API pair
    a.emit(0xE58DC000)
    a.branch(fast_blit_va, link=True)
    a.emit(0xE28DD008)
    a.emit(0xE3500000)
    a.branch('handled', cond=0x0)
    a.branch('fallback')

    a.label('api_failed')
    a.emit(0xE3A00002)
    a.emit(0xE5880034)

    a.label('fallback')
    a.emit(0xE1A00004)
    a.emit(0xE1A01005)
    a.emit(0xE1A02006)
    a.emit(0xE1A03007)
    a.emit(0xE8BD41F0)             # restore r4-r8,lr
    a.branch(upper_blit_va)         # tail-call stock SDL_UpperBlit

    a.label('handled')
    a.emit(0xE8BD81F0)             # return helper's r0 == 0
    return a.finish()

def build_title_scroll_favourite_blit(base_va: int, state_va: int,
                                      icon_clip_va: int | None) -> bytes:
    """Record the selected row's favourite-marker boundary safely.

    The marker is recorded after the row title has drawn. On first discovery
    for a selection, request one normal follow-up marquee frame and mark that
    frame as fresh activity. The unchanged baseline blit then restarts its idle
    clock and evaluates the narrowed width; no speed calculation is modified.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D401F)             # push {r0-r4,lr}; 8-byte aligned
    a.emit(0xE1A04003)             # r4 = destination SDL_Rect *
    a.emit(0xE51B2050)             # current TextMenu object
    a.emit(0xE592300C)             # selected row index
    a.emit(0xE51B2018)             # renderer current row
    a.emit(0xE1520003)
    a.branch('restore', cond=0x1)
    a.ldr_literal(2, state_va)
    a.emit(0xE1D430F0)             # marker destination x
    a.emit(0xE592107C)             # previous marker boundary
    a.emit(0xE582307C)             # remember current boundary
    a.emit(0xE3510000)
    a.branch('restore', cond=0x1)  # already known: no timer/state restart
    # Preserve a leave-screen hold marker (reset_pending=2) if one is active;
    # otherwise request the usual one-frame favourite-boundary restart.
    a.emit(0xE592006C)
    a.emit(0xE3500002)
    a.emit(0x13A01001)             # movne r1,#1
    a.emit(0x1582106C)             # strne r1,[r2,#0x6c]
    a.emit(0xE3A01001)
    a.emit(0xE5821044)             # allow exactly that normal follow-up frame
    a.label('restore')
    a.emit(0xE8BD401F)             # pop {r0-r4,lr}
    if icon_clip_va is not None:
        a.branch(icon_clip_va)      # preserve row-height clipping
    else:
        a.emit(0xE3A01000)         # stock NULL source rectangle
        a.emit(0xE12FFF1E)         # bx lr
    return a.finish()

def build_title_scroll_blit(base_va: int, row_cache_va: int, state_va: int,
                            get_config_va: int, get_ticks_va: int,
                            upper_blit_va: int,
                            live_preview_gate: bool = False) -> bytes:
    """Loop-scroll the selected overflowing title as ``title + gap + title``.

    Before the idle timeout the stock full-surface blit is preserved. Once the
    marquee starts, a fixed viewport is filled by at most two clipped blits:
    the remaining suffix and, after a blank gap, the beginning of the title.
    Wall-clock-derived phase makes motion independent of renderer call count.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D47F0)             # push {r4-r10,lr}
    a.emit(0xE24DD010)             # 16 bytes: source2 + destination2
    a.emit(0xE1A04000)             # r4 = rendered text SDL_Surface*
    a.emit(0xE1A05001)             # r5 = stock source SDL_Rect*
    a.emit(0xE1A06002)             # r6 = destination screen
    a.emit(0xE1A07003)             # r7 = destination SDL_Rect*
    a.ldr_literal(8, row_cache_va)
    a.ldr_literal(9, state_va)
    a.emit(0xE5990048)             # consume one-shot game-label marker
    a.emit(0xE3A01000)
    a.emit(0xE5891048)
    a.emit(0xE3500001)
    a.branch('stock', cond=0x1)
    a.emit(0xE599A068)
    a.emit(0xE35A0000)
    a.branch('stock', cond=0x0)
    a.emit(0xE5980040)             # active tagged game-list object
    a.emit(0xE150000A)
    a.emit(0x15980044)             # previous tagged object on active miss
    a.emit(0x1150000A)
    a.branch('stock', cond=0x1)

    a.branch(get_config_va, link=True)
    a.emit(0xE3500002)
    a.branch('disabled', cond=0x1)
    a.branch(get_ticks_va, link=True)
    a.emit(0xE1A01000)             # r1 = now

    # Preserve previous rendered tick for phase/reset handling.
    a.emit(0xE5990018)             # r0 = previous rendered tick
    a.emit(0xE599206C)             # reset pending? 0=none,1=reset,2=frozen exit
    a.emit(0xE3520002)
    a.branch('normal_reset_check', cond=0x1)
    # A/B/RIGHT and other leave-screen inputs freeze the published phase while
    # the outgoing window is still being drawn.  Once this row has not rendered
    # for RETURN_RESET_MS, treat the next draw as a return and reset *before*
    # that first visible frame.  Updating last-rendered below keeps the freeze
    # alive across any number of transition frames without synthetic wakeups.
    a.emit(0xE0413000)             # r3 = now - previous rendered tick
    a.emit(arm_movw(2, TITLE_SCROLL_RETURN_RESET_MS))
    a.emit(0xE1530002)             # elapsed gap vs return threshold
    a.branch('hold_same', cond=0x3)  # unsigned gap < threshold
    a.emit(0xE3A02001)             # long gap: convert hold -> normal reset
    a.emit(0xE589206C)
    a.branch('normal_reset_check')
    a.label('hold_same')
    a.branch('same')
    a.label('normal_reset_check')
    a.emit(0xE3520000)
    a.branch('same', cond=0x0)
    a.emit(0xE3A02000)
    a.emit(0xE589206C)
    a.emit(0xE5891014)             # restart idle timer
    a.emit(0xE5891018)
    a.emit(0xE5892050)
    a.emit(0xE5892044)
    a.emit(0xE5892080)             # phase = 0
    a.emit(0xE5892024)             # active epoch = 0 (state+36)
    a.emit(0xE5892028)             # whole-second base phase = 0 (state+40)
    a.emit(0xE1A00001)             # previous tick = now
    a.label('same')
    a.emit(0xE5891018)             # last rendered tick = now
    a.emit(0xE1D720B0)             # title destination x
    a.emit(0xE5892054)
    a.emit(0xE5943008)             # rendered title width
    a.emit(0xE5893058)
    a.emit(0xE3A02001)
    a.emit(0xE5892070)

    # r10 = actual marquee draw viewport.  Keep the renderer's normal label
    # box (already narrowed by the selected Favorite marker when applicable)
    # as the draw width so scrolling can travel underneath preview artwork.
    # r2 is a separate overflow-activation width: while a live preview exists,
    # preserve the established preview-pane threshold so ROM-list marquee still arms for
    # titles that overflow the unobscured text region.  Once armed, r10 remains
    # the wider draw viewport.
    a.emit(0xE1D9A0BC)             # r10 = renderer label-box / Favorite-bound width
    if live_preview_gate:
        a.emit(0xE1A0200A)         # r2 = activation width starts at draw width
        a.emit(0xE5993084)         # live preview-active flag (state+132)
        a.emit(0xE3530000)
        a.emit(0x15993050)         # ldrne r3,[r9,#0x50] preview-pane left edge
        a.emit(0x15990054)         # ldrne r0,[r9,#0x54] selected title x
        a.emit(0x10533000)         # subne r3,r3,r0 = pane x - title x
        a.emit(0x13530000)         # cmpne r3,#0: ignore stale/invalid pane widths
        a.emit(0xC1520003)         # cmpgt r2,r3 only when pane width is positive
        a.emit(0xC1A02003)         # movgt r2,r3: activation=min(draw,pane)
    else:
        # Exact established behavior when the row selector is absent.
        a.emit(0xE5992050)         # preview-pane left edge, or zero
        a.emit(0xE3520000)
        a.branch('width_ready', cond=0x0)
        a.emit(0xE5993054)
        a.emit(0xE0422003)         # pane x - title x
        a.emit(0xE3520000)
        a.branch('width_ready', cond=0xD)
        a.emit(0xE152000A)
        a.emit(0xB1A0A002)         # use smaller pane-limited width
    a.label('width_ready')
    a.emit(0xE5993058)             # title width
    if live_preview_gate:
        a.emit(0xE1530002)         # compare against activation width
    else:
        a.emit(0xE153000A)         # exact established compare against draw width
    a.branch('disabled', cond=0xD) # no overflow -> stock behavior

    # Normal overflow arms synthetic repainting.  A frozen leave-screen state
    # deliberately stays disarmed so transition frames cannot start the wake loop.
    a.emit(0xE599306C)             # reset_pending
    a.emit(0xE3530002)
    a.emit(0x13A02001)             # movne r2,#1
    a.emit(0x03A02000)             # moveq r2,#0
    a.emit(0xE5892044)             # armed = (not frozen-exit)
    a.emit(0xE5992004)             # idle delay
    a.emit(0xE5993014)             # start tick
    a.emit(0xE0413003)             # total elapsed
    a.emit(0xE1530002)
    a.branch('stock', cond=0x3)    # before idle: exact stock blit

    # Derive marquee phase from an absolute active-scroll epoch rather than
    # advancing it once per render-hook entry. Duplicate/nested renders at the
    # same wall-clock time therefore resolve to the exact same source x.
    a.emit(0xE5990024)             # r0 = active epoch tick, or zero
    a.emit(0xE3500000)
    a.branch('epoch_ready', cond=0x1)
    a.emit(0xE5993014)             # selection/start tick
    a.emit(0xE5992004)             # idle delay
    a.emit(0xE0830002)             # epoch = start + idle
    a.emit(0xE5890024)
    a.emit(0xE3A02000)
    a.emit(0xE5892028)             # base phase = 0
    a.label('epoch_ready')
    a.emit(0xE0410000)             # r0 = now - epoch

    # Split elapsed into whole seconds q=r1 and remainder_ms=r0.
    a.ldr_literal(2, 0x10624DD3)
    a.emit(0xE0823290)             # umull r3,r2,r0,reciprocal
    a.emit(0xE1A01322)             # r1 = whole seconds
    a.ldr_literal(2, 1000)
    a.emit(0xE0030192)             # r3 = q*1000
    a.emit(0xE0400003)             # r0 = remainder ms

    # Rebase only on whole-second boundaries. Repeated draws within a second
    # are pure reads of the same base state. If more than one whole second was
    # missed, advance the epoch but freeze the base phase instead of catching
    # up through a large scheduler/suspend jump.
    a.emit(0xE3510000)
    a.branch('base_ready', cond=0x0)
    a.emit(0xE5992024)             # epoch
    a.emit(0xE0822003)             # epoch += q*1000
    a.emit(0xE5892024)
    a.emit(0xE3510001)
    a.branch('base_ready', cond=0x8)  # bhi: freeze across >1s stall
    a.emit(0xE5992028)             # base phase
    a.emit(0xE5993008)             # speed px/s
    a.emit(0xE0010193)             # r1 = q*speed
    a.emit(0xE0822001)             # base += q*speed
    a.emit(0xE5993058)             # title width
    a.emit(0xE283303C)             # cycle = title_width + 60
    a.label('normalize_base')
    a.emit(0xE1520003)
    a.emit(0x20422003)             # subhs base,base,cycle
    a.branch('normalize_base', cond=0x2)
    a.emit(0xE5892028)
    a.branch('have_base')
    a.label('base_ready')
    a.emit(0xE5992028)             # unchanged base phase
    a.label('have_base')

    # Add current-second fraction as a pure function of wall-clock time.
    a.emit(0xE5993008)             # speed
    a.emit(0xE0000093)             # r0 = remainder_ms*speed
    a.ldr_literal(3, 0x10624DD3)
    a.emit(0xE0831390)             # umull r1,r3,r0,reciprocal
    a.emit(0xE1A00323)             # r0 = partial pixels = high >> 6
    a.emit(0xE0823000)             # r3 = draw phase = base + partial
    a.emit(0xE5992058)             # title width
    a.emit(0xE282203C)             # cycle = title_width + 60
    a.label('normalize_draw')
    a.emit(0xE1530002)
    a.emit(0x20433002)             # subhs draw_phase,draw_phase,cycle
    a.branch('normalize_draw', cond=0x2)
    a.emit(0xE5893080)             # publish draw phase for this render only

    # Common source height/y.
    a.emit(0xE3A00000)
    a.emit(0xE1C901BE)             # source1.y = 0
    a.emit(0xE594000C)
    a.emit(0xE1C902B2)             # source1.h = surface.h

    # phase < title_width => draw suffix first.
    a.emit(0xE5992058)
    a.emit(0xE1530002)
    a.branch('gap_only', cond=0x2) # phase >= title width
    a.emit(0xE0421003)             # r1 = suffix width
    a.emit(0xE151000A)
    a.emit(0x81A0100A)             # first width=min(suffix,viewport)
    a.emit(0xE1C931BC)             # source1.x = phase
    a.emit(0xE1C912B0)             # source1.w = first width
    a.emit(0xE289101C)             # r1 = source1
    a.emit(0xE1A00004)
    a.emit(0xE1A02006)
    a.emit(0xE1A03007)
    a.branch(upper_blit_va, link=True)

    # If suffix fills viewport, this frame is complete.
    a.emit(0xE5993080)             # reload phase across SDL_UpperBlit
    a.emit(0xE5992058)
    a.emit(0xE0421003)             # full suffix width again
    a.emit(0xE151000A)
    a.branch('done', cond=0x2)     # suffix >= viewport
    a.emit(0xE281103C)             # second destination offset = suffix + gap
    a.emit(0xE151000A)
    a.branch('done', cond=0x2)     # gap extends past viewport
    a.branch('draw_prefix')

    # Entire original title has moved left; only remaining gap precedes prefix.
    a.label('gap_only')
    a.emit(0xE282103C)             # title_width + gap
    a.emit(0xE0411003)             # remaining blank pixels
    a.emit(0xE151000A)
    a.branch('blank_done', cond=0x2)

    a.label('draw_prefix')
    a.emit(0xE1A08001)             # r8 = repeated-prefix destination offset
    # r1 = destination offset of repeated prefix. Prefix width is the remaining
    # viewport, bounded by the title surface width.
    a.emit(0xE04A2001)             # r2 = viewport - offset
    a.emit(0xE5993058)
    a.emit(0xE1520003)
    a.emit(0x81A02003)             # min(remaining viewport,title width)

    # source2 = {0,0,prefix_w,surface_h} at sp.
    a.emit(0xE3A03000)
    a.emit(0xE1CD30B0)
    a.emit(0xE1CD30B2)
    a.emit(0xE1CD20B4)
    a.emit(0xE594300C)
    a.emit(0xE1CD30B6)

    # destination2 copies stock destination, with x += stream offset.
    a.emit(0xE1D700B0)
    a.emit(0xE0800008)             # stock x + preserved stream offset
    a.emit(0xE1CD00B8)
    a.emit(0xE1D700B2)
    a.emit(0xE1CD00BA)
    a.emit(0xE1D700B4)
    a.emit(0xE1CD00BC)
    a.emit(0xE1D700B6)
    a.emit(0xE1CD00BE)
    a.emit(0xE1A0100D)             # source2
    a.emit(0xE1A00004)
    a.emit(0xE1A02006)
    a.emit(0xE28D3008)             # destination2
    a.branch(upper_blit_va, link=True)
    a.branch('done')

    a.label('blank_done')
    a.emit(0xE3A00000)
    a.branch('done')

    a.label('disabled')
    a.emit(0xE3A00000)
    a.emit(0xE5890044)
    a.emit(0xE5890080)             # draw phase reset when not overflowing/enabled
    a.emit(0xE5890024)             # active epoch reset
    a.emit(0xE5890028)             # base phase reset
    a.label('stock')
    a.emit(0xE1A01005)
    a.emit(0xE1A00004)
    a.emit(0xE1A02006)
    a.emit(0xE1A03007)
    a.branch(upper_blit_va, link=True)
    a.branch('done')

    a.label('done')
    a.emit(0xE28DD010)
    a.emit(0xE8BD87F0)
    return a.finish()

def build_title_scroll_synthetic_update_gate(base_va: int, state_va: int) -> bytes:
    """Skip slot-8 window update only for stable synthetic thumbnail repaints.

    At the central modal-loop call site r0 is the window object and r3 is the
    original vtable slot-8 function pointer.  A synthetic marquee wake marks
    state+136.  If the pre-draw geometry from the previous frame says the
    preview is already active, no input/selection state can have changed, so
    this one housekeeping update is unnecessary for a pure title repaint.
    Otherwise tail-call the exact stock function pointer.
    """
    a = ArmBuilder(base_va)
    a.ldr_literal(1, state_va)
    a.emit(0xE5912088)             # r2 = synthetic-wake flag (state+136)
    a.emit(0xE3520001)
    a.branch('stock', cond=0x1)    # not synthetic
    a.emit(0xE5912084)             # live preview-active flag (state+132)
    a.emit(0xE3520001)
    a.branch('stock', cond=0x1)    # preview not yet stable/live
    a.emit(0xE3A02000)
    a.emit(0xE5812088)             # consume synthetic flag
    a.emit(0xE12FFF1E)             # bx lr: skip slot-8 update
    a.label('stock')
    a.emit(0xE3A02000)
    a.emit(0xE5812088)             # consume flag before stock update too
    a.emit(0xE12FFF13)             # bx r3: exact original vtable call
    return a.finish()


def build_title_scroll_wait_event(base_va: int, state_va: int,
                                  get_ticks_va: int, poll_event_va: int,
                                  wait_event_va: int, delay_va: int) -> bytes:
    """Wake MainUI's normal draw cycle while a marquee is active.

    This retains the proven single central-wait hook. Compared with the main
    patcher, it shares one real-event classifier between polled and blocking
    events and calls MainUI's existing ``SDL_Delay`` import instead of issuing
    ``nanosleep`` directly.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}
    a.emit(0xE1A04000)             # SDL_Event *
    a.ldr_literal(5, state_va)
    a.emit(0xE3540000)
    a.branch('stock_wait', cond=0x0)
    a.emit(0xE5950044)             # armed?
    a.emit(0xE3500000)
    a.branch('stock_wait', cond=0x0)

    a.label('poll')
    a.emit(0xE1A00004)
    a.branch(poll_event_va, link=True)
    a.emit(0xE3500000)
    a.branch('real_event', cond=0x1)

    a.branch(get_ticks_va, link=True)
    a.emit(0xE1A06000)             # now
    a.emit(0xE5950014)             # start tick
    a.emit(0xE0460000)             # elapsed
    a.emit(0xE5951004)             # idle threshold
    a.emit(0xE1500001)
    a.branch('sleep_idle', cond=0x3)
    a.emit(0xE5950018)             # last rendered tick
    a.emit(0xE0460000)             # elapsed = now - last rendered
    a.emit(0xE3500000 | TITLE_SCROLL_FRAME_MS)  # 33 ms target cadence (~30 Hz)
    a.branch('sleep_frame', cond=0x3)

    a.emit(0xE3A00018)             # SDL_USEREVENT
    a.emit(0xE5840000)
    a.emit(0xE3A01000)             # zero code/data payload
    a.emit(0xE5841004)
    a.emit(0xE5841008)
    a.emit(0xE584100C)
    a.emit(0xE3A01001)
    a.emit(0xE5851088)             # state+136 = synthetic repaint pending
    a.emit(0xE3A00001)
    a.emit(0xE8BD81F0)

    a.label('sleep_idle')
    a.emit(0xE3A00000 | TITLE_SCROLL_IDLE_POLL_MS)
    a.branch(delay_va, link=True)   # retain 33 ms idle-wait polling cadence
    a.branch('poll')

    a.label('sleep_frame')
    # We only reach this path when unsigned elapsed < FRAME_MS, so
    # FRAME_MS-elapsed is already safely clamped to [1, FRAME_MS].
    a.emit(0xE2600000 | TITLE_SCROLL_FRAME_MS)  # rsb r0,r0,#FRAME_MS
    a.branch(delay_va, link=True)   # SDL_Delay(remaining frame time)
    a.branch('poll')

    a.label('stock_wait')
    a.emit(0xE3A01000)
    a.emit(0xE5851088)             # real/stock path is never synthetic
    a.emit(0xE1A00004)
    a.branch(wait_event_va, link=True)
    a.emit(0xE3500000)
    a.branch('return_stock', cond=0x0)

    a.label('real_event')
    a.emit(0xE3A01000)
    a.emit(0xE5851088)             # polled real event cancels synthetic marker
    # KEYDOWN receives key-specific handling. KEYUP must not arm a fresh hold
    # after a selection-changing key has already reset normally. Joystick input
    # is conservatively treated as a leave/move key; an actual selected-index
    # change in the row helper overrides the hold with reset_pending=1.
    a.emit(0xE5D42000)             # SDL_Event.type
    a.emit(0xE3520002)             # SDL_KEYDOWN
    a.branch('keydown', cond=0x0)
    a.emit(0xE3520003)             # SDL_KEYUP
    a.branch('return_real', cond=0x0)
    a.emit(0xE2422009)
    a.emit(0xE3520002)
    a.branch('hold_input', cond=0x9)  # joystick types 9..11
    a.branch('return_real')

    a.label('keydown')
    a.emit(0xE5942008)             # SDL_keysym.sym
    a.emit(arm_movw(1, SDLK_LEFT))
    a.emit(0xE1520001)
    a.branch('hold_input', cond=0x1)
    # LEFT remains the explicit user reset.
    a.emit(0xE3A01000)
    a.emit(0xE5851044)             # disarm
    a.emit(0xE5851050)             # clear pane boundary
    a.emit(0xE3A01001)
    a.emit(0xE585106C)             # reset on next selected draw
    a.branch('return_real')

    a.label('hold_input')
    # Stop synthetic wakeups during a transition, but retain geometry and phase.
    # reset_pending=2 freezes the published marquee until the row has been absent
    # long enough to identify a return; the blit then resets before first draw.
    a.emit(0xE3A01000)
    a.emit(0xE5851044)             # disarm
    a.emit(0xE3A01002)
    a.emit(0xE585106C)             # hold one outgoing frame

    a.label('return_real')
    a.emit(0xE3A00001)
    a.emit(0xE8BD81F0)

    a.label('return_stock')
    a.emit(0xE8BD81F0)
    return a.finish()

def build_rom_list_end_jump(base_va: int, state_va: int,
                            original_keymap_va: int,
                            rom_forward_loader_va: int,
                            rom_backward_loader_va: int,
                            letter_jump_state_va: int | None = None) -> bytes:
    """Map held UP + fresh L2 to first, and held DOWN + fresh R2 to last.

    The wrapper asks the stock translator to copy its consumed SDL_Event into a
    local buffer and tracks only UP, DOWN, L2, and R2 while the caller has one
    of the two known game-list vtables. Direction state must have been recorded
    by an earlier keydown before the shoulder keydown arrives. A shoulder-first
    sequence therefore remains stock page movement even if a later repeat occurs
    while the direction is held. Accepted modified shoulders are consumed and
    latched until that shoulder's keyup. ROM lists use the matching stock loader
    after selection changes; parsed lists need no asynchronous load.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D47F0)             # push {r4-r10,lr}
    a.emit(0xE24DD018)             # 20-byte SDL_Event + alignment
    a.emit(0xE3A00000)
    a.emit(0xE58D0000)             # clear event type when no event is returned
    a.emit(0xE58D0008)             # clear keysym for the same case
    a.emit(0xE1A0000D)             # r0 = sp; request copied event
    a.branch(original_keymap_va, link=True)
    a.emit(0xE1A05000)             # r5 = translated action
    a.emit(0xE51B4018)             # r4 = caller's TextMenu this
    a.ldr_literal(8, state_va)
    a.emit(0xE3540000)
    a.branch('invalid_list', cond=0x0)
    a.emit(0xE5946000)             # r6 = vtable
    a.ldr_literal(0, ROM_VTABLE)
    a.emit(0xE1560000)
    a.branch('valid_list', cond=0x0)
    a.ldr_literal(0, PARSED_LIST_VTABLE)
    a.emit(0xE1560000)
    a.branch('invalid_list', cond=0x1)

    a.label('valid_list')
    a.emit(0xE5980000)             # tracked object
    a.emit(0xE1500004)
    a.branch('object_ready', cond=0x0)
    a.emit(0xE5884000)
    a.emit(0xE3A07000)
    a.emit(0xE5887004)
    a.label('object_ready')

    a.emit(0xE5DD0000)             # SDL_Event.type
    a.emit(0xE3500002)             # SDL_KEYDOWN
    a.branch('keydown', cond=0x0)
    a.emit(0xE3500003)             # SDL_KEYUP
    a.branch('keyup', cond=0x0)
    a.branch('return_action')

    a.label('decode_key')
    a.emit(0xE59D1008)             # SDL_keysym.sym
    a.emit(0xE3510009)             # SDLK_TAB / L2 (stock page up)
    a.branch('decoded_l2', cond=0x0)
    a.emit(0xE3510008)             # SDLK_BACKSPACE / R2 (stock page down)
    a.branch('decoded_r2', cond=0x0)
    a.emit(arm_movw(0, END_JUMP_UP_KEYSYM))
    a.emit(0xE1510000)
    a.branch('decoded_up', cond=0x0)
    a.emit(arm_movw(0, END_JUMP_DOWN_KEYSYM))
    a.emit(0xE1510000)
    a.branch('decoded_down', cond=0x0)
    a.emit(0xE3A00000)             # unrelated key
    a.emit(0xE12FFF1E)
    a.label('decoded_up')
    a.emit(0xE3A00001)
    a.emit(0xE12FFF1E)
    a.label('decoded_down')
    a.emit(0xE3A00002)
    a.emit(0xE12FFF1E)
    a.label('decoded_l2')
    a.emit(0xE3A00003)
    a.emit(0xE12FFF1E)
    a.label('decoded_r2')
    a.emit(0xE3A00004)
    a.emit(0xE12FFF1E)

    a.label('keydown')
    a.branch('decode_key', link=True)
    a.emit(0xE3500001)
    a.branch('down_up', cond=0x0)
    a.emit(0xE3500002)
    a.branch('down_down', cond=0x0)
    a.emit(0xE3500003)
    a.branch('down_l2', cond=0x0)
    a.emit(0xE3500004)
    a.branch('down_r2', cond=0x0)
    a.branch('return_action')

    a.label('down_up')
    a.emit(0xE5987004)
    a.emit(0xE3877001)             # UP held
    a.emit(0xE5887004)
    a.branch('return_action')

    a.label('down_down')
    a.emit(0xE5987004)
    a.emit(0xE3877002)             # DOWN held
    a.emit(0xE5887004)
    a.branch('return_action')

    a.label('down_l2')
    a.emit(0xE5987004)
    a.emit(0xE3170004)             # already physically down / repeat?
    a.branch('repeat_l2', cond=0x1)
    a.emit(0xE3877004)             # remember first L2 keydown
    a.emit(0xE5887004)
    a.emit(0xE3170001)             # UP was already held
    a.branch('return_action', cond=0x0)
    a.emit(0xE3877010)             # latch accepted UP+L2
    a.emit(0xE5887004)
    a.branch('jump_top')
    a.label('repeat_l2')
    a.emit(0xE3170010)
    a.branch('return_zero', cond=0x1)
    a.branch('return_action')       # shoulder-first repeat keeps page action

    a.label('down_r2')
    a.emit(0xE5987004)
    a.emit(0xE3170008)             # already physically down / repeat?
    a.branch('repeat_r2', cond=0x1)
    a.emit(0xE3877008)             # remember first R2 keydown
    a.emit(0xE5887004)
    a.emit(0xE3170002)             # DOWN was already held
    a.branch('return_action', cond=0x0)
    a.emit(0xE3877020)             # latch accepted DOWN+R2
    a.emit(0xE5887004)
    a.branch('jump_bottom')
    a.label('repeat_r2')
    a.emit(0xE3170020)
    a.branch('return_zero', cond=0x1)
    a.branch('return_action')       # shoulder-first repeat keeps page action

    # Cancel an in-progress initial-letter scan before the direct selection.
    a.label('cancel_letter_scan')
    if letter_jump_state_va is not None:
        a.ldr_literal(12, letter_jump_state_va)
        a.emit(0xE3A01000)
        a.emit(0xE58C1000)
        a.emit(0xE58C1004)
    a.emit(0xE12FFF1E)

    a.label('jump_top')
    a.branch('cancel_letter_scan', link=True)
    a.emit(0xE3A00000)
    a.emit(0xE584000C)
    a.emit(0xE5946000)
    a.ldr_literal(1, ROM_VTABLE)
    a.emit(0xE1560001)
    a.branch('return_zero', cond=0x1)
    a.emit(0xE1A00004)
    a.branch(rom_forward_loader_va, link=True)
    a.branch('return_zero')

    a.label('jump_bottom')
    a.branch('cancel_letter_scan', link=True)
    a.emit(0xE5946000)
    a.emit(0xE5963020)             # virtual size()
    a.emit(0xE1A00004)
    a.emit(0xE12FFF33)
    a.emit(0xE3500000)
    a.branch('return_zero', cond=0x0)
    a.emit(0xE2400001)
    a.emit(0xE584000C)
    a.emit(0xE5946000)
    a.ldr_literal(1, ROM_VTABLE)
    a.emit(0xE1560001)
    a.branch('return_zero', cond=0x1)
    a.emit(0xE1A00004)
    a.branch(rom_backward_loader_va, link=True)
    a.branch('return_zero')

    a.label('keyup')
    a.branch('decode_key', link=True)
    a.emit(0xE3500001)
    a.branch('up_up', cond=0x0)
    a.emit(0xE3500002)
    a.branch('up_down', cond=0x0)
    a.emit(0xE3500003)
    a.branch('up_l2', cond=0x0)
    a.emit(0xE3500004)
    a.branch('up_r2', cond=0x0)
    a.branch('return_action')

    a.label('up_up')
    a.emit(0xE5987004)
    a.emit(0xE3C77001)
    a.emit(0xE5887004)
    a.branch('return_action')
    a.label('up_down')
    a.emit(0xE5987004)
    a.emit(0xE3C77002)
    a.emit(0xE5887004)
    a.branch('return_action')
    a.label('up_l2')
    a.emit(0xE5987004)
    a.emit(0xE3C77014)             # clear L2-down and its latch
    a.emit(0xE5887004)
    a.branch('return_action')
    a.label('up_r2')
    a.emit(0xE5987004)
    a.emit(0xE3C77028)             # clear R2-down and its latch
    a.emit(0xE5887004)
    a.branch('return_action')

    a.label('invalid_list')
    a.emit(0xE3A00000)
    a.emit(0xE5880000)
    a.emit(0xE5880004)
    a.label('return_action')
    a.emit(0xE1A00005)
    a.emit(0xE28DD018)
    a.emit(0xE8BD87F0)
    a.label('return_zero')
    a.emit(0xE3A00000)
    a.emit(0xE28DD018)
    a.emit(0xE8BD87F0)
    return a.finish()


def build_rom_list_letter_jump(base_va: int, state_va: int,
                               original_keymap_va: int, c_str_va: int,
                               rom_forward_loader_va: int,
                               rom_backward_loader_va: int,
                               click_chunk_global_va: int,
                               mix_play_channel_timed_va: int,
                               push_event_va: int) -> bytes:
    """Map L1/R1 to deterministic initial-character jumps in game lists.

    Parsed lists and ROM systems use the same contiguous-group scan over the
    labels returned by TextMenu's item accessor. Short-name Arcade systems keep
    MainUI's stock cache fields; their runtime GetGameName labels are scanned in
    physical list order. This deliberately avoids rewriting `disp` from a
    temporary pinyin string and avoids the previous Arcade-only exhaustive scan,
    whose repeated asynchronous traversal was unsafe on device.

    ROM lists expose only a small loaded map, so a missing index queues exactly
    one stock asynchronous window load for that index. The scan resumes on a
    normal loader-completion/idle event or a later L1/R1 press. Unrelated actions
    no longer destroy pending progress, while a changed visible selection safely
    cancels it before any stale destination can be applied. After selecting the destination,
    ROM lists receive the same direction-matched final stock window load that
    ordinary navigation would have queued. No visible-window fields are written
    and no page method is called. A stock repaint event is posted after every
    accepted destination so a jump whose target window is already resident is
    visible immediately instead of appearing to require a second shoulder press.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D47F0)             # push {r4-r10,lr}
    a.branch(original_keymap_va, link=True)
    a.emit(0xE1A05000)             # r5 = translated action
    a.emit(0xE51B4018)             # r4 = caller's TextMenu this
    a.emit(0xE3540000)
    a.branch('return_action', cond=0x0)
    a.emit(0xE5946000)             # r6 = vtable
    a.ldr_literal(0, ROM_VTABLE)
    a.emit(0xE1560000)
    a.branch('valid_list', cond=0x0)
    a.ldr_literal(0, PARSED_LIST_VTABLE)
    a.emit(0xE1560000)
    a.branch('return_action', cond=0x1)

    a.label('valid_list')
    a.ldr_literal(8, state_va)

    # Resolve an existing pending scan before accepting another shoulder
    # request. Completion/idle events and another L1/R1 press can all make
    # progress. Other actions pass through while the scan remains pending; if
    # one of them changes the visible selection, the next event detects the
    # origin mismatch and cancels before the old scan can publish a destination.
    a.emit(0xE5980000)             # pending object
    a.emit(0xE3500000)
    a.branch('idle_state', cond=0x0)
    a.emit(0xE1500004)
    a.branch('stale_state', cond=0x1)
    a.emit(0xE5983004)             # pending phase
    a.emit(0xE3530000)
    a.branch('idle_state', cond=0x0)
    a.emit(0xE5981018)             # saved origin selection
    a.emit(0xE594000C)             # current visible selection
    a.emit(0xE1500001)
    a.branch('cancel_return_action', cond=0x1)
    a.emit(0xE3550000)
    a.branch('load_count', cond=0x0)  # idle/non-key event
    a.emit(0xE3550018)             # row-loader SDL_USEREVENT action 24
    a.branch('load_count', cond=0x0)
    a.emit(0xE355000E)
    a.branch('load_count', cond=0x0)  # L1 repeat also polls/resumes
    a.emit(0xE355000F)
    a.branch('load_count', cond=0x0)  # R1 repeat also polls/resumes
    a.branch('return_action')      # preserve pending scan for unrelated action

    a.label('stale_state')
    a.emit(0xE3A00000)
    a.emit(0xE5880000)
    a.emit(0xE5880004)
    a.emit(0xE5880018)

    a.label('idle_state')
    a.emit(0xE355000E)             # L1 action 14
    a.branch('new_request', cond=0x0)
    a.emit(0xE355000F)             # R1 action 15
    a.branch('new_request', cond=0x0)
    a.emit(0xE3550000)
    a.branch('return_zero', cond=0x0)
    a.branch('return_action')

    a.label('cancel_return_action')
    a.emit(0xE3A00000)
    a.emit(0xE5880000)
    a.emit(0xE5880004)
    a.emit(0xE5880018)
    a.branch('return_action')

    a.label('new_request')
    a.branch('read_count')

    # Shared size() call. New requests continue at initialize_request; pending
    # events dispatch from the saved phase.
    a.label('load_count')
    a.emit(0xE3A0A001)             # r10=1 marks pending dispatch
    a.branch('call_size')
    a.label('read_count')
    a.emit(0xE3A0A000)             # r10=0 marks new request
    a.label('call_size')
    a.emit(0xE5963020)
    a.emit(0xE1A00004)
    a.emit(0xE12FFF33)
    a.emit(0xE1A07000)             # r7 = count
    a.emit(0xE3570001)
    a.branch('clear_consume', cond=0xD)  # <=1
    a.emit(0xE35A0000)
    a.branch('dispatch_pending', cond=0x1)

    a.label('initialize_request')
    a.emit(0xE594A00C)             # selected index
    a.emit(0xE588A018)             # remember scan origin selection
    a.emit(0xE15A0007)
    a.branch('clear_consume', cond=0x2)
    a.emit(0xE1A0100A)
    a.branch('get_group', link=True)
    a.emit(0xE3700001)             # cmn r0,#1 -- missing
    a.branch('clear_consume', cond=0x0)
    a.emit(0xE1A09000)             # r9 = current group

    # Stock intentionally suppresses the generic shoulder click for physical
    # L1/R1. Play the same navigation sample once for an accepted game-list
    # letter request. Repeats used to resume an existing pending scan return
    # through the dispatch path above and therefore do not replay the click.
    a.ldr_literal(3, click_chunk_global_va)
    a.emit(0xE5931000)             # r1 = normal navigation Mix_Chunk*
    a.emit(0xE3510000)
    a.branch('after_click', cond=0x0)
    a.emit(0xE3E03000)             # loops=-1
    a.emit(0xE3A02000)             # ticks=0
    a.emit(0xE3A00001)             # channel=1
    a.branch(mix_play_channel_timed_va, link=True)
    a.label('after_click')

    a.emit(0xE5884000)             # pending object
    a.emit(0xE5889008)             # current visible-name group

    # Keep every cache field stock, including Arcade `disp`. Use the proven
    # standard scan over runtime labels; the former full-list Arcade scan could
    # cycle through many asynchronous windows and was observed to crash.
    a.branch('standard_request')

    a.label('standard_request')
    a.emit(0xE3A02000)
    a.emit(0xE5882014)             # examined = 0
    a.emit(0xE355000F)
    a.branch('start_forward', cond=0x0)

    a.emit(0xE35A0000)             # L1 at first item wraps to final group
    a.branch('begin_prev_wrap', cond=0x0)
    a.emit(0xE24AA001)
    a.emit(0xE588A00C)
    a.emit(0xE3A03003)             # PREV_FIND
    a.emit(0xE5883004)
    a.branch('prev_find')

    a.label('start_arcade_request')
    a.emit(0xE3E00000)             # -1 = no candidate/best group yet
    a.emit(0xE5880010)
    a.emit(0xE5880014)
    a.emit(0xE3A0A000)             # scan from logical index 0
    a.emit(0xE588A00C)
    a.emit(0xE355000F)
    a.branch('start_arcade_forward', cond=0x0)
    a.emit(0xE3A03009)             # ARCADE_PREV
    a.emit(0xE5883004)
    a.emit(0xE1A05000)             # best index = -1
    a.emit(0xE1A02000)             # best group = -1
    a.branch('arcade_prev_scan')

    a.label('start_arcade_forward')
    a.emit(0xE3A03007)             # ARCADE_FORWARD
    a.emit(0xE5883004)
    a.emit(0xE1A05000)             # best index = -1
    a.emit(0xE1A02000)             # best group = -1
    a.branch('arcade_forward_scan')

    a.label('start_forward')
    a.emit(0xE28AA001)
    a.emit(0xE588A00C)
    a.emit(0xE3A03001)             # FORWARD
    a.emit(0xE5883004)
    a.branch('forward_scan')

    a.label('dispatch_pending')
    a.emit(0xE5983004)
    a.emit(0xE3530001)
    a.branch('resume_forward', cond=0x0)
    a.emit(0xE3530002)
    a.branch('resume_forward_wait', cond=0x0)
    a.emit(0xE3530003)
    a.branch('resume_prev_find', cond=0x0)
    a.emit(0xE3530004)
    a.branch('resume_prev_find_wait', cond=0x0)
    a.emit(0xE3530005)
    a.branch('resume_prev_start', cond=0x0)
    a.emit(0xE3530006)
    a.branch('resume_prev_start_wait', cond=0x0)
    a.emit(0xE3530007)
    a.branch('resume_arcade_forward', cond=0x0)
    a.emit(0xE3530008)
    a.branch('resume_arcade_forward_wait', cond=0x0)
    a.emit(0xE3530009)
    a.branch('resume_arcade_prev', cond=0x0)
    a.emit(0xE353000A)
    a.branch('resume_arcade_prev_wait', cond=0x0)
    a.branch('clear_consume')

    a.label('resume_forward')
    a.emit(0xE5989008)
    a.emit(0xE598A00C)
    a.emit(0xE5982014)
    a.branch('forward_scan')

    a.label('resume_forward_wait')
    a.emit(0xE5989008)
    a.emit(0xE598A00C)
    a.emit(0xE5982014)
    a.emit(0xE1A0100A)
    a.branch('get_group', link=True)
    a.emit(0xE3700001)
    a.branch('return_zero', cond=0x0)
    a.emit(0xE3A03001)
    a.emit(0xE5883004)
    a.branch('forward_have_group')

    a.label('resume_prev_find')
    a.emit(0xE5989008)
    a.emit(0xE598A00C)
    a.emit(0xE5982014)
    a.branch('prev_find')

    a.label('resume_prev_find_wait')
    a.emit(0xE5989008)
    a.emit(0xE598A00C)
    a.emit(0xE5982014)
    a.emit(0xE1A0100A)
    a.branch('get_group', link=True)
    a.emit(0xE3700001)
    a.branch('return_zero', cond=0x0)
    a.emit(0xE3A03003)
    a.emit(0xE5883004)
    a.branch('prev_find_have_group')

    a.label('resume_prev_start')
    a.emit(0xE5989008)
    a.emit(0xE598A00C)
    a.emit(0xE5985010)
    a.emit(0xE5982014)
    a.branch('prev_start')

    a.label('resume_prev_start_wait')
    a.emit(0xE5989008)
    a.emit(0xE598A00C)
    a.emit(0xE5985010)
    a.emit(0xE5982014)
    a.emit(0xE1A0100A)
    a.branch('get_group', link=True)
    a.emit(0xE3700001)
    a.branch('return_zero', cond=0x0)
    a.emit(0xE3A03005)
    a.emit(0xE5883004)
    a.branch('prev_start_have_group')

    a.label('resume_arcade_forward')
    a.emit(0xE5989008)             # current group
    a.emit(0xE598A00C)             # scan index
    a.emit(0xE5985010)             # best index
    a.emit(0xE5982014)             # best group
    a.branch('arcade_forward_scan')

    a.label('resume_arcade_forward_wait')
    a.emit(0xE5989008)
    a.emit(0xE598A00C)
    a.emit(0xE5985010)
    a.emit(0xE5982014)
    a.emit(0xE1A0100A)
    a.branch('get_group', link=True)
    a.emit(0xE3700001)
    a.branch('return_zero', cond=0x0)
    a.emit(0xE3A03007)
    a.emit(0xE5883004)
    a.branch('arcade_forward_have_group')

    a.label('resume_arcade_prev')
    a.emit(0xE5989008)
    a.emit(0xE598A00C)
    a.emit(0xE5985010)
    a.emit(0xE5982014)
    a.branch('arcade_prev_scan')

    a.label('resume_arcade_prev_wait')
    a.emit(0xE5989008)
    a.emit(0xE598A00C)
    a.emit(0xE5985010)
    a.emit(0xE5982014)
    a.emit(0xE1A0100A)
    a.branch('get_group', link=True)
    a.emit(0xE3700001)
    a.branch('return_zero', cond=0x0)
    a.emit(0xE3A03009)
    a.emit(0xE5883004)
    a.branch('arcade_prev_have_group')

    # Short-name arcade lists are sorted by the filename-derived DB key rather
    # than the visible GetGameName label. Scan every logical row and rank its
    # visible initial alphabetically. A direct group on the requested side of
    # the current initial always beats a wrap group; within either class R1
    # chooses the lowest code point and L1 the highest. The first list index for
    # a winning initial is retained, making repeated jumps deterministic even
    # when the same visible initial occurs in several noncontiguous runs.
    a.label('arcade_forward_scan')
    a.emit(0xE15A0007)
    a.branch('arcade_finish', cond=0x2)  # index >= count
    a.emit(0xE1A0100A)
    a.branch('get_group', link=True)
    a.emit(0xE3700001)
    a.branch('arcade_forward_missing', cond=0x0)
    a.label('arcade_forward_have_group')
    a.emit(0xE1500009)
    a.branch('arcade_next', cond=0x0)    # ignore current group
    a.emit(0xE3720001)                   # best group == -1?
    a.branch('arcade_accept', cond=0x0)
    a.emit(0xE1500009)                   # candidate > current?
    a.branch('arcade_forward_direct', cond=0x8)
    # Candidate is a wrap group. A direct best wins; otherwise lower is nearer
    # after wrapping from the maximum initial back to the minimum.
    a.emit(0xE1520009)
    a.branch('arcade_next', cond=0x8)
    a.emit(0xE1500002)
    a.branch('arcade_accept', cond=0x3)  # candidate < best
    a.branch('arcade_next')
    a.label('arcade_forward_direct')
    a.emit(0xE1520009)
    a.branch('arcade_accept', cond=0x9)  # best is wrap (<= current)
    a.emit(0xE1500002)
    a.branch('arcade_accept', cond=0x3)
    a.branch('arcade_next')

    a.label('arcade_prev_scan')
    a.emit(0xE15A0007)
    a.branch('arcade_finish', cond=0x2)
    a.emit(0xE1A0100A)
    a.branch('get_group', link=True)
    a.emit(0xE3700001)
    a.branch('arcade_prev_missing', cond=0x0)
    a.label('arcade_prev_have_group')
    a.emit(0xE1500009)
    a.branch('arcade_next', cond=0x0)
    a.emit(0xE3720001)
    a.branch('arcade_accept', cond=0x0)
    a.emit(0xE1500009)                   # candidate < current?
    a.branch('arcade_prev_direct', cond=0x3)
    # Candidate is a wrap group. A direct best wins; otherwise higher is nearer
    # after wrapping from the minimum initial back to the maximum.
    a.emit(0xE1520009)
    a.branch('arcade_next', cond=0x3)
    a.emit(0xE1500002)
    a.branch('arcade_accept', cond=0x8)  # candidate > best
    a.branch('arcade_next')
    a.label('arcade_prev_direct')
    a.emit(0xE1520009)
    a.branch('arcade_accept', cond=0x2)  # best is wrap (>= current)
    a.emit(0xE1500002)
    a.branch('arcade_accept', cond=0x8)
    a.branch('arcade_next')

    a.label('arcade_accept')
    a.emit(0xE1A0500A)             # best index = current scan index
    a.emit(0xE1A02000)             # best group = candidate group
    a.emit(0xE5885010)
    a.emit(0xE5882014)
    a.label('arcade_next')
    a.emit(0xE28AA001)
    # Return to the phase-specific loop without changing its saved direction.
    a.emit(0xE5983004)
    a.emit(0xE3530007)
    a.branch('arcade_forward_scan', cond=0x0)
    a.branch('arcade_prev_scan')

    a.label('arcade_forward_missing')
    a.emit(0xE3A03008)             # ARCADE_FORWARD_WAIT
    a.emit(0xE5883004)
    a.emit(0xE588A00C)
    a.emit(0xE5885010)
    a.emit(0xE5882014)
    a.branch('queue_forward_load')

    a.label('arcade_prev_missing')
    a.emit(0xE3A0300A)             # ARCADE_PREV_WAIT
    a.emit(0xE5883004)
    a.emit(0xE588A00C)
    a.emit(0xE5885010)
    a.emit(0xE5882014)
    a.branch('queue_forward_load') # scan order is ascending in both directions

    a.label('arcade_finish')
    a.emit(0xE3750001)             # best index == -1?
    a.branch('clear_consume', cond=0x0)
    a.emit(0xE1A0A005)
    a.branch('select_index')

    # R1: scan contiguous loaded indices. A missing ROM entry queues exactly
    # one forward loader request for that index and waits for completion.
    a.label('forward_scan')
    a.emit(0xE1520007)
    a.branch('clear_consume', cond=0x2)  # full cycle without another group
    a.emit(0xE15A0007)
    a.branch('begin_forward_wrap', cond=0x2)
    a.emit(0xE1A0100A)
    a.branch('get_group', link=True)
    a.emit(0xE3700001)
    a.branch('forward_missing', cond=0x0)
    a.label('forward_have_group')
    a.emit(0xE1500009)
    a.branch('select_index', cond=0x1)
    a.emit(0xE28AA001)
    a.emit(0xE2822001)
    a.branch('forward_scan')

    a.label('forward_missing')
    a.emit(0xE3A03002)             # FORWARD_WAIT
    a.emit(0xE5883004)
    a.emit(0xE588A00C)
    a.emit(0xE5882014)
    a.branch('queue_forward_load')

    # L1 phase 1: locate any item in the preceding group.
    a.label('prev_find')
    a.emit(0xE1520007)
    a.branch('clear_consume', cond=0x2)  # full cycle without another group
    a.emit(0xE35A0000)
    a.branch('begin_prev_wrap', cond=0xB)
    a.emit(0xE1A0100A)
    a.branch('get_group', link=True)
    a.emit(0xE3700001)
    a.branch('prev_find_missing', cond=0x0)
    a.label('prev_find_have_group')
    a.emit(0xE1500009)
    a.branch('prev_group_found', cond=0x1)
    a.emit(0xE24AA001)
    a.emit(0xE2822001)
    a.branch('prev_find')

    a.label('prev_find_missing')
    a.emit(0xE3A03004)             # PREV_FIND_WAIT
    a.emit(0xE5883004)
    a.emit(0xE588A00C)
    a.emit(0xE5882014)
    a.branch('queue_backward_load')

    a.label('prev_group_found')
    a.emit(0xE1A09000)             # r9 = preceding group
    a.emit(0xE1A0500A)             # candidate = current index
    a.emit(0xE24AA001)
    a.emit(0xE2822001)
    a.emit(0xE5889008)
    a.emit(0xE5885010)
    a.emit(0xE588A00C)
    a.emit(0xE5882014)
    a.emit(0xE3A03005)             # PREV_START
    a.emit(0xE5883004)

    # L1 phase 2: continue backward to the first item of that group.
    a.label('prev_start')
    a.emit(0xE1520007)
    a.branch('select_candidate', cond=0x2)
    a.emit(0xE35A0000)
    a.branch('select_candidate', cond=0xB)
    a.emit(0xE1A0100A)
    a.branch('get_group', link=True)
    a.emit(0xE3700001)
    a.branch('prev_start_missing', cond=0x0)
    a.label('prev_start_have_group')
    a.emit(0xE1500009)
    a.branch('select_candidate', cond=0x1)
    a.emit(0xE1A0500A)
    a.emit(0xE24AA001)
    a.emit(0xE2822001)
    a.branch('prev_start')

    a.label('prev_start_missing')
    a.emit(0xE3A03006)             # PREV_START_WAIT
    a.emit(0xE5883004)
    a.emit(0xE5889008)
    a.emit(0xE588A00C)
    a.emit(0xE5885010)
    a.emit(0xE5882014)
    a.branch('queue_backward_load')

    a.label('select_candidate')
    a.emit(0xE1A0A005)
    a.branch('select_index')

    # Wraps continue the same directional scan. They do not immediately select
    # index 0/count-1, because the normalized initial at the opposite list end
    # may match the current group (for example under case-sensitive sorting).
    a.label('begin_forward_wrap')
    a.emit(0xE3A0A000)
    a.ldr_literal(0, ROM_VTABLE)
    a.emit(0xE1560000)
    a.branch('forward_scan', cond=0x1)
    a.emit(0xE3A03002)             # FORWARD_WAIT
    a.emit(0xE5883004)
    a.emit(0xE588A00C)
    a.emit(0xE5882014)
    a.branch('queue_forward_load')

    a.label('begin_prev_wrap')
    a.emit(0xE247A001)             # last index = count-1
    a.ldr_literal(0, ROM_VTABLE)
    a.emit(0xE1560000)
    a.branch('prev_find', cond=0x1)
    a.emit(0xE3A03004)             # PREV_FIND_WAIT
    a.emit(0xE5883004)
    a.emit(0xE588A00C)
    a.emit(0xE5882014)
    a.branch('queue_backward_load')

    # Queue one contiguous ROM cache window without exposing the temporary
    # loader anchor as the visible selection.
    a.label('queue_forward_load')
    a.emit(0xE24DD008)
    a.emit(0xE594300C)
    a.emit(0xE58D3000)
    a.emit(0xE584A00C)
    a.emit(0xE1A00004)
    a.branch(rom_forward_loader_va, link=True)
    a.emit(0xE59D3000)
    a.emit(0xE584300C)
    a.emit(0xE28DD008)
    a.branch('return_zero')

    a.label('queue_backward_load')
    a.emit(0xE24DD008)
    a.emit(0xE594300C)
    a.emit(0xE58D3000)
    a.emit(0xE584A00C)
    a.emit(0xE1A00004)
    a.branch(rom_backward_loader_va, link=True)
    a.emit(0xE59D3000)
    a.emit(0xE584300C)
    a.emit(0xE28DD008)
    a.branch('return_zero')

    a.label('select_index')
    # A far jump bypasses TextMenu's ordinary up/down virtuals, which normally
    # queue a direction-matched ROM window after changing the selection. Save
    # the scan phase, clear the pending scan first, then issue that same final
    # stock load for ROM lists. This ensures the complete newly visible window
    # receives a completion repaint instead of leaving edge rows as LOADING.
    a.emit(0xE5983004)             # r3 = saved scan phase/direction
    a.emit(0xE584A00C)             # selected index = destination
    a.emit(0xE3A00000)
    a.emit(0xE5880000)             # clear pending object before new worker
    a.emit(0xE5880004)             # clear pending phase
    a.emit(0xE5880018)             # clear saved origin
    a.ldr_literal(1, ROM_VTABLE)
    a.emit(0xE1560001)             # parsed lists are fully resident
    a.branch('post_repaint', cond=0x1)
    # Standard phases 1/2 are R1/forward; phases 3..6 are L1/backward.
    a.emit(0xE1A00004)             # r0 = ROM list object
    a.emit(0xE3530002)
    a.branch('final_forward_load', cond=0x9)   # <= 2
    a.branch('final_backward_load')
    a.label('final_forward_load')
    a.branch(rom_forward_loader_va, link=True)
    a.branch('post_repaint')
    a.label('final_backward_load')
    a.branch(rom_backward_loader_va, link=True)

    # A resident destination may not cause the stock window loader to post a
    # completion event. Queue the same harmless SDL_USEREVENT used by MainUI's
    # loading callbacks so the changed selection is always repainted once.
    a.label('post_repaint')
    a.emit(0xE24DD018)             # one 24-byte SDL_Event
    a.emit(0xE3A03018)             # SDL_USEREVENT
    a.emit(0xE5CD3000)             # event.type
    a.emit(0xE58D3004)             # event.user.code
    a.emit(0xE1A0000D)             # r0 = &event
    a.branch(push_event_va, link=True)
    a.emit(0xE28DD018)
    a.branch('return_zero')

    a.label('clear_consume')
    a.emit(0xE3A00000)
    a.emit(0xE5880000)
    a.emit(0xE5880004)
    a.emit(0xE5880018)
    a.label('return_zero')
    a.emit(0xE3A00000)
    a.emit(0xE8BD87F0)
    a.label('return_action')
    a.emit(0xE1A00005)
    a.emit(0xE8BD87F0)

    # Return the normalized first UTF-8 code point from the item object's
    # primary string: this is the exact display label consumed by TextMenu and,
    # for short-name arcade systems, contains the runtime GetGameName result
    # without modifying the filename-derived database `disp` key. Return -1
    # when the item is not currently resident. ASCII and Latin-1 uppercase
    # letters are folded.
    a.label('get_group')
    a.emit(0xE92D400E)             # push {r1-r3,lr}
    a.emit(0xE5963014)             # virtual item(index)
    a.emit(0xE1A00004)
    a.emit(0xE12FFF33)
    a.emit(0xE3500000)
    a.branch('group_missing', cond=0x0)
    a.branch(c_str_va, link=True)
    a.emit(0xE3500000)
    a.branch('group_missing', cond=0x0)
    a.label('skip_space')
    a.emit(0xE4D01001)
    a.emit(0xE3510000)
    a.branch('group_missing', cond=0x0)
    a.emit(0xE3510020)
    a.branch('skip_space', cond=0x9)
    a.emit(0xE3510080)
    a.branch('group_ascii', cond=0x3)
    a.emit(0xE35100E0)
    a.branch('group_three', cond=0x2)
    a.emit(0xE35100C2)
    a.branch('group_raw', cond=0x3)
    a.emit(0xE201201F)
    a.emit(0xE5D03000)
    a.emit(0xE203303F)
    a.emit(0xE1830302)
    a.branch('group_normalize')
    a.label('group_three')
    a.emit(0xE35100F0)
    a.branch('group_four', cond=0x2)
    a.emit(0xE201200F)
    a.emit(0xE4D01001)
    a.emit(0xE201103F)
    a.emit(0xE1812302)
    a.emit(0xE5D03000)
    a.emit(0xE203303F)
    a.emit(0xE1830302)
    a.branch('group_normalize')
    a.label('group_four')
    a.emit(0xE35100F5)
    a.branch('group_raw', cond=0x2)
    a.emit(0xE2012007)
    a.emit(0xE4D01001)
    a.emit(0xE201103F)
    a.emit(0xE1812302)
    a.emit(0xE4D01001)
    a.emit(0xE201103F)
    a.emit(0xE1812302)
    a.emit(0xE5D03000)
    a.emit(0xE203303F)
    a.emit(0xE1830302)
    a.branch('group_normalize')
    a.label('group_ascii')
    a.emit(0xE1A00001)
    a.label('group_normalize')
    a.emit(0xE3500041)
    a.branch('group_latin_1', cond=0x3)
    a.emit(0xE350005A)
    a.emit(0x92800020)
    a.label('group_latin_1')
    a.emit(0xE30010C0)
    a.emit(0xE1500001)
    a.branch('group_latin_2', cond=0x3)
    a.emit(0xE30010D6)
    a.emit(0xE1500001)
    a.emit(0x92800020)
    a.label('group_latin_2')
    a.emit(0xE30010D8)
    a.emit(0xE1500001)
    a.branch('group_done', cond=0x3)
    a.emit(0xE30010DE)
    a.emit(0xE1500001)
    a.emit(0x92800020)
    a.branch('group_done')
    a.label('group_raw')
    a.emit(0xE1A00001)
    a.label('group_done')
    a.emit(0xE8BD800E)
    a.label('group_missing')
    a.emit(0xE3E00000)
    a.emit(0xE8BD800E)
    return a.finish()


def build_active_theme_scan_preloader(base_va: int, state_va: int,
                                      prefix_va: int,
                                      fopen_va: int, fclose_va: int,
                                      free_va: int, access_va: int,
                                      strncmp_va: int, strlen_va: int,
                                      strncpy_va: int) -> bytes:
    """Read only system.json's selected external-theme path before /Themes scan.

    The stock system.json loader runs later at its original site and remains
    untouched. This helper mirrors the stock JSON parser/object ownership just
    far enough to read the top-level ``theme`` string into bounded private
    state. Missing/malformed/default/out-of-tree selections fail open by
    leaving state[0] == 0.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}; AAPCS-aligned
    a.emit(0xE24DD008)             # 8-byte local: raw parse pointer + spare
    a.ldr_literal(4, state_va)
    a.emit(0xE3A03000)             # mov r3,#0
    a.emit(0xE5843000)             # valid = 0
    a.emit(0xE5C43004)             # path[0] = NUL
    a.emit(0xE58D3000)             # raw parse pointer = NULL
    a.emit(0xE3A07000)             # r7 = converted JSON object = NULL

    a.ldr_literal(0, THEME_ACTIVE_ONLY_SYSTEM_JSON_VA)
    a.ldr_literal(1, THEME_ACTIVE_ONLY_READ_MODE_VA)
    a.branch(fopen_va, link=True)
    a.emit(0xE1A05000)             # r5 = FILE*
    a.emit(0xE3550000)
    a.branch('finish', cond=0x0)

    # Mirror stock 0x14BCA8 / generic scanner ownership:
    # parse(path, FILE*, &raw), raw_to_object(raw), object_free(obj), free(raw).
    a.ldr_literal(0, THEME_ACTIVE_ONLY_SYSTEM_JSON_VA)
    a.emit(0xE1A01005)             # r1 = FILE*
    a.emit(0xE1A0200D)             # r2 = &raw parse pointer
    a.branch(THEME_ACTIVE_ONLY_JSON_PARSE_VA, link=True)
    a.emit(0xE1A03000)             # r3 = parser status
    a.emit(0xE59D6000)             # r6 = raw parse pointer, even on failure
    a.emit(0xE3530000)
    a.branch('raw_close', cond=0xB) # blt: parser failure
    a.emit(0xE3560000)
    a.branch('close_only', cond=0x0)

    a.emit(0xE1A00006)
    a.branch(THEME_ACTIVE_ONLY_JSON_ROOT_VA, link=True)
    a.emit(0xE1A07000)             # r7 = converted root object
    a.emit(0xE3570000)
    a.branch('raw_close', cond=0x0)

    a.emit(0xE1A00007)
    a.ldr_literal(1, THEME_ACTIVE_ONLY_THEME_KEY_VA)
    a.branch(THEME_ACTIVE_ONLY_JSON_GET_VA, link=True)
    a.emit(0xE1A03000)             # r3 = theme node
    a.emit(0xE3530000)
    a.branch('object_raw_close', cond=0x0)
    a.emit(0xE593200C)             # node type
    a.emit(0xE3520010)             # string == 16
    a.branch('object_raw_close', cond=0x1)
    a.emit(0xE5938010)             # r8 = theme path string
    a.emit(0xE3580000)
    a.branch('object_raw_close', cond=0x0)

    # Optimize only normal external themes.  Default './', malformed paths,
    # and future layouts deliberately fall back to the complete stock scan.
    a.emit(0xE1A00008)
    a.ldr_literal(1, prefix_va)
    a.emit(arm_movw(2, THEME_ACTIVE_ONLY_PREFIX_LEN))
    a.branch(strncmp_va, link=True)
    a.emit(0xE3500000)
    a.branch('object_raw_close', cond=0x1)

    a.emit(0xE1A00008)
    a.branch(strlen_va, link=True)
    a.emit(0xE58D0004)             # save selected path byte length
    a.emit(arm_movw(3, THEME_ACTIVE_ONLY_PREFIX_LEN + 1))
    a.emit(0xE1500003)             # at least prefix + one byte
    a.branch('object_raw_close', cond=0x3)  # blo
    a.emit(arm_movw(3, THEME_ACTIVE_ONLY_PATH_SIZE))
    a.emit(0xE1500003)
    a.branch('object_raw_close', cond=0x2)  # bhs

    # Require exactly one direct child beneath /Themes, with an optional final
    # slash.  Any nested/malformed path fails open to the stock all-theme scan.
    a.emit(0xE2881013)             # r1 = first byte after 19-byte prefix
    a.emit(0xE2402013)             # r2 = bytes after prefix
    a.emit(0xE2423001)             # r3 = last byte index
    a.emit(0xE7D10003)             # ldrb r0,[r1,r3]
    a.emit(0xE350002F)             # trailing '/'?
    a.emit(0x02422001)             # subeq r2,r2,#1
    a.emit(0xE3520000)
    a.branch('object_raw_close', cond=0x0)
    a.emit(0xE3A00000)             # index = 0
    a.label('child_path_check')
    a.emit(0xE7D13000)             # ldrb r3,[r1,r0]
    a.emit(0xE353002F)             # no embedded '/'
    a.branch('object_raw_close', cond=0x0)
    a.emit(0xE2800001)
    a.emit(0xE1500002)
    a.branch('child_path_check', cond=0x3)  # lo

    a.emit(0xE1A00008)
    a.emit(0xE3A01000)             # F_OK
    a.branch(access_va, link=True)
    a.emit(0xE3500000)
    a.branch('object_raw_close', cond=0x1)

    a.emit(0xE2840004)             # state path destination
    a.emit(0xE1A01008)             # selected path source
    a.emit(arm_movw(2, THEME_ACTIVE_ONLY_PATH_SIZE - 1))
    a.branch(strncpy_va, link=True)
    a.emit(0xE3A03000)
    a.emit(0xE5C43103)             # state[4+255] = NUL
    a.emit(0xE3A03001)
    a.emit(0xE5843000)             # valid = 1

    a.label('object_raw_close')
    a.emit(0xE1A00007)
    a.branch(THEME_ACTIVE_ONLY_JSON_FREE_VA, link=True)
    a.label('raw_close')
    a.emit(0xE3560000)
    a.branch('close_only', cond=0x0)
    a.emit(0xE1A00006)
    a.branch(free_va, link=True)
    a.label('close_only')
    a.emit(0xE1A00005)
    a.branch(fclose_va, link=True)
    a.label('finish')
    # Replay the stock instruction replaced by the preload hook. The following
    # MOVT at 0x4A7F4 still completes /mnt/SDCARD/Themes in r1.
    a.emit(arm_movw(1, 0x55D0))
    a.emit(0xE28DD008)
    a.emit(0xE8BD81F0)             # pop {r4-r8,pc}
    return a.finish()


def build_active_theme_scan_filter(base_va: int, state_va: int,
                                   strlen_va: int, memcmp_va: int) -> bytes:
    """Skip inactive /Themes entries before any child config path/file access."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}; AAPCS-aligned

    # The generic scanner is shared. Apply filtering only to the unique stock
    # theme callback used by the sole /mnt/SDCARD/Themes wrapper.
    a.emit(0xE51B3094)             # callback argument saved at fp-0x94
    a.ldr_literal(4, THEME_ACTIVE_ONLY_CALLBACK_VA)
    a.emit(0xE1530004)
    a.branch('allow', cond=0x1)

    a.ldr_literal(4, state_va)
    a.emit(0xE5943000)
    a.emit(0xE3530001)
    a.branch('allow', cond=0x1)    # unresolved selection => stock scan
    a.emit(0xE2845004)             # r5 = copied full theme path

    a.emit(0xE1A00005)
    a.branch(strlen_va, link=True)
    a.emit(0xE1A06000)             # r6 = full length
    a.emit(0xE3560013)
    a.branch('allow', cond=0x9)    # <= prefix length: fail open
    a.emit(0xE2855013)             # r5 = selected directory name
    a.emit(0xE2466013)             # r6 = selected name(+slash) length

    # Stock theme object paths normally carry a trailing slash. Accept either
    # form so this filter remains robust if system.json stores it without one.
    a.emit(0xE2467001)
    a.emit(0xE7D53007)             # ldrb r3,[r5,r7]
    a.emit(0xE353002F)             # '/'
    a.branch('name_ready', cond=0x1)
    a.emit(0xE2466001)
    a.label('name_ready')
    a.emit(0xE3560000)
    a.branch('allow', cond=0x0)

    a.emit(0xE51B701C)             # current dirent*
    a.emit(0xE287700B)             # d_name
    a.emit(0xE1A00007)
    a.branch(strlen_va, link=True)
    a.emit(0xE1500006)
    a.branch('skip', cond=0x1)

    a.emit(0xE1A00007)             # entry name
    a.emit(0xE1A01005)             # selected name
    a.emit(0xE1A02006)             # exact selected-name length
    a.branch(memcmp_va, link=True)
    a.emit(0xE3500000)
    a.branch('skip', cond=0x1)

    a.label('allow')
    a.emit(0xE8BD41F0)             # restore including lr
    a.emit(0xE51B301C)             # replay stock hook instruction
    a.branch(THEME_ACTIVE_ONLY_SCAN_CONTINUE_VA)

    a.label('skip')
    a.emit(0xE8BD41F0)
    a.branch(THEME_ACTIVE_ONLY_SCAN_SKIP_VA)
    return a.finish()


def build_theme_patch_record_store(base_va: int, table_va: int,
                                   strlen_va: int, strcmp_va: int,
                                   strncpy_va: int) -> bytes:
    """Upsert one exact-path theme record without touching live theme state.

    Inputs:
      r0 = NUL-terminated exact theme path
      r1 = encoded bold state (1 normal, 2 stock bold)
      r2 = encoded icon-left-margin state (0 unset, N+1 explicit)
      r3 = update mask: bit0 bold, bit1 margin

    The table is bounded.  Overlong paths or a full table fail closed: no record
    is written, so the later active-theme resolver falls back to defaults.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D47F0)             # push {r4-r10,lr}; 32 bytes/aligned
    a.emit(0xE1A04000)             # r4 = path
    a.emit(0xE1A05001)             # r5 = bold state
    a.emit(0xE1A06002)             # r6 = margin state
    a.emit(0xE1A07003)             # r7 = update mask

    # Refuse paths that cannot be stored exactly.
    a.emit(0xE1A00004)
    a.branch(strlen_va, link=True)
    a.emit(arm_movw(3, THEME_PATCH_PATH_SIZE))
    a.emit(0xE1500003)             # cmp len,path_size
    a.branch('done', cond=0x2)     # hs: overlong -> fail closed

    a.ldr_literal(8, table_va)
    a.emit(0xE5989000)             # r9 = count
    a.emit(0xE3A0A000)             # r10 = index 0

    a.label('search')
    a.emit(0xE15A0009)             # cmp index,count
    a.branch('not_found', cond=0x2)  # hs
    a.emit(arm_movw(3, THEME_PATCH_RECORD_SIZE))
    a.emit(0xE000039A)             # mul r0,r10,r3
    a.emit(0xE0880000)             # + table base
    a.emit(0xE2800004)             # + count word
    a.emit(0xE1A01004)             # r1 = path
    a.branch(strcmp_va, link=True)
    a.emit(0xE3500000)
    a.branch('found', cond=0x0)
    a.emit(0xE28AA001)             # ++index
    a.branch('search')

    a.label('not_found')
    a.emit(arm_movw(3, THEME_PATCH_RECORD_MAX))
    a.emit(0xE1590003)             # cmp count,max
    a.branch('done', cond=0x2)     # full -> fail closed
    # rec = base + 4 + count*record_size
    a.emit(arm_movw(3, THEME_PATCH_RECORD_SIZE))
    a.emit(0xE0000399)             # mul r0,r9,r3
    a.emit(0xE0880000)
    a.emit(0xE2800004)
    a.emit(0xE1A01004)             # src path
    a.emit(arm_movw(2, THEME_PATCH_PATH_SIZE - 1))
    a.branch(strncpy_va, link=True)
    # recompute record after strncpy and terminate exactly.
    a.emit(arm_movw(3, THEME_PATCH_RECORD_SIZE))
    a.emit(0xE0000399)             # mul r0,r9,r3
    a.emit(0xE0880000)
    a.emit(0xE2800004)
    a.emit(0xE3A03000)
    a.emit(0xE5C030FF)             # path[255] = '\0'
    a.emit(0xE3A03002)
    a.emit(0xE5803100)             # default bold=true
    a.emit(0xE3A03000)
    a.emit(0xE5803104)             # default margin=unset
    a.emit(0xE2893001)
    a.emit(0xE5883000)             # count++
    a.branch('apply')

    a.label('found')
    # Recompute matched record from r10 because strcmp clobbered r0-r3.
    a.emit(arm_movw(3, THEME_PATCH_RECORD_SIZE))
    a.emit(0xE000039A)             # mul r0,r10,r3
    a.emit(0xE0880000)
    a.emit(0xE2800004)

    a.label('apply')
    a.emit(0xE3170001)             # update bold?
    a.emit(0x15805100)             # strne r5,[r0,#256]
    a.emit(0xE3170002)             # update margin?
    a.emit(0x15806104)             # strne r6,[r0,#260]

    a.label('done')
    a.emit(0xE8BD87F0)             # pop {r4-r10,pc}
    return a.finish()


def build_theme_gamelist_bold_probe(base_va: int, record_store_va: int,
                                     original_get_object_va: int,
                                     cxx_string_c_str_va: int,
                                     gamelist_key_va: int,
                                     bold_key_va: int) -> bytes:
    """Stage this scanned theme's ``gamelist.bold`` under its exact path.

    This helper intentionally never writes the live game-list bold state.
    Missing/invalid values are recorded as stock bold for this theme only.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}
    a.emit(0xE1A05000)             # r5 = scanned theme root
    a.branch(original_get_object_va, link=True)  # preserve stock `list` lookup
    a.emit(0xE1A04000)             # r4 = original list result
    a.emit(0xE3A06002)             # r6 = default bold=true

    a.emit(0xE3550000)
    a.branch('store', cond=0x0)
    a.emit(0xE1A00005)
    a.ldr_literal(1, gamelist_key_va)
    a.branch(original_get_object_va, link=True)
    a.emit(0xE3500000)
    a.branch('store', cond=0x0)
    a.ldr_literal(1, bold_key_va)
    a.branch(original_get_object_va, link=True)
    a.emit(0xE3500000)
    a.branch('store', cond=0x0)
    a.emit(0xE590300C)
    a.emit(0xE6EF3073)
    a.emit(0xE3530001)             # cJSON_False
    a.emit(0x03A06001)             # false -> normal
    a.branch('store', cond=0x0)
    a.emit(0xE3530002)             # cJSON_True
    a.emit(0x03A06002)

    a.label('store')
    # The verified theme parser's local Theme object starts at fp-0x1a0 and its
    # exact root-path std::string is +0x18 => fp-0x188.
    a.emit(0xE24B0F62)             # sub r0,fp,#0x188
    a.branch(cxx_string_c_str_va, link=True)
    a.emit(0xE1A01006)             # bold state
    a.emit(0xE3A02000)             # margin ignored here
    a.emit(0xE3A03001)             # update-mask bold
    a.branch(record_store_va, link=True)

    a.emit(0xE1A00004)
    a.emit(0xE8BD81F0)
    return a.finish()


def build_theme_gamelist_icon_margin_probe(
        base_va: int, record_store_va: int,
        list_get_va: int, raw_get_object_va: int,
        cxx_string_c_str_va: int,
        gamelist_key_va: int, margin_key_va: int) -> bytes:
    """Stage this scanned theme's optional ``gamelist.iconLeftMargin``.

    Live geometry state is untouched.  Missing/invalid values record ``unset``
    for this exact theme, preventing values from any other scanned theme from
    surviving into active-theme initialization.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}
    a.emit(0xE1A05000)             # r5 = scanned theme root
    a.emit(0xE3A06000)             # r6 = margin unset by default
    a.branch(list_get_va, link=True)
    a.emit(0xE1A04000)             # original list result
    a.emit(0xE3550000)
    a.branch('store', cond=0x0)

    a.emit(0xE1A00005)
    a.ldr_literal(1, gamelist_key_va)
    a.branch(raw_get_object_va, link=True)
    a.emit(0xE3500000)
    a.branch('store', cond=0x0)
    a.ldr_literal(1, margin_key_va)
    a.branch(raw_get_object_va, link=True)
    a.emit(0xE3500000)
    a.branch('store', cond=0x0)
    a.emit(0xE590300C)
    a.emit(0xE6EF3073)
    a.emit(0xE3530008)             # cJSON_Number
    a.branch('store', cond=0x1)
    a.emit(0xE5903014)             # valueint
    a.emit(0xE3530000)
    a.branch('store', cond=0xB)    # negative -> unset
    a.emit(arm_movw(2, THEME_ICON_LEFT_MARGIN_MAX))
    a.emit(0xE1530002)
    a.emit(0xC1A03002)             # clamp > max
    a.emit(0xE2836001)             # r6 = N+1 encoded

    a.label('store')
    a.emit(0xE24B0F62)             # exact scanned theme path std::string
    a.branch(cxx_string_c_str_va, link=True)
    a.emit(0xE3A01002)             # bold ignored; harmless default
    a.emit(0xE1A02006)             # margin state
    a.emit(0xE3A03002)             # update-mask margin
    a.branch(record_store_va, link=True)

    a.emit(0xE1A00004)
    a.emit(0xE8BD81F0)
    return a.finish()


def build_active_theme_patch_state_resolver(
        base_va: int, table_va: int,
        bold_state_va: int | None,
        margin_state_va: int | None,
        strcmp_va: int, printf_va: int) -> bytes:
    """Resolve staged custom settings for the one exact active theme path.

    Entry is the stock ``printf("sys lang..., path %s, ...")`` call.  r2 is the
    selected theme's exact root path.  Reset all enabled live custom-theme state
    to defaults first, then apply only an exact-path table match, and tail-call
    stock printf with its original arguments/registers restored.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D41FF)             # push {r0-r8,lr}; 40 bytes/aligned
    a.emit(0xE1A04002)             # r4 = active theme path cstr

    if bold_state_va is not None:
        a.ldr_literal(8, bold_state_va)
        a.emit(0xE3A03002)
        a.emit(0xE5883000)         # default stock bold
    if margin_state_va is not None:
        a.ldr_literal(8, margin_state_va)
        a.emit(0xE3A03000)
        a.emit(0xE5883000)         # default margin unset

    a.ldr_literal(5, table_va)
    a.emit(0xE5956000)             # count
    a.emit(0xE3A07000)             # index
    a.label('search')
    a.emit(0xE1570006)
    a.branch('finish', cond=0x2)   # hs -> no exact record
    a.emit(arm_movw(3, THEME_PATCH_RECORD_SIZE))
    a.emit(0xE0000397)             # mul r0,r7,r3
    a.emit(0xE0850000)
    a.emit(0xE2800004)
    a.emit(0xE1A01004)
    a.branch(strcmp_va, link=True)
    a.emit(0xE3500000)
    a.branch('matched', cond=0x0)
    a.emit(0xE2877001)
    a.branch('search')

    a.label('matched')
    a.emit(arm_movw(3, THEME_PATCH_RECORD_SIZE))
    a.emit(0xE0000397)
    a.emit(0xE0850000)
    a.emit(0xE2800004)
    if bold_state_va is not None:
        a.emit(0xE5903100)
        a.ldr_literal(8, bold_state_va)
        a.emit(0xE5883000)
    if margin_state_va is not None:
        a.emit(0xE5903104)
        a.ldr_literal(8, margin_state_va)
        a.emit(0xE5883000)

    a.label('finish')
    a.emit(0xE8BD41FF)             # restore original printf arguments + lr
    a.branch(printf_va)             # tail-call stock printf
    return a.finish()


def find_active_theme_syslang_printf_call(data: bytes | bytearray,
                                           segs: list[Segment],
                                           printf_va: int) -> int:
    """Locate the one stock active-theme ``sys lang..., path ...`` printf call."""
    needle = b'sys lang %s, path %s, support multilanguage %d\n\0'
    off = data.find(needle)
    if off < 0 or data.find(needle, off + 1) >= 0:
        raise ValueError('expected one active-theme sys-lang format string')
    fmt_va = off2va(segs, off)
    movw = arm_movw(0, fmt_va & 0xFFFF)
    movt = arm_movt(0, fmt_va >> 16)
    candidates: list[int] = []
    for seg in segs:
        if not (seg.flags & 1):
            continue
        begin = align_up(seg.file_off, 4)
        finish = seg.file_off + seg.file_size - 12
        for pos in range(begin, finish + 1, 4):
            if read_word(data, pos) != movw or read_word(data, pos + 4) != movt:
                continue
            call = pos + 8
            if decode_arm_branch_target(read_word(data, call), off2va(segs, call)) == printf_va:
                candidates.append(call)
    if len(candidates) != 1:
        raise ValueError(
            f'expected one active-theme sys-lang printf call, found {len(candidates)}')
    return candidates[0]


def build_theme_bold_font_loader(base_va: int, state_va: int,
                                 inner_loader_va: int,
                                 raw_loader_va: int,
                                 close_font_va: int,
                                 set_style_va: int,
                                 font_cache_va: int) -> bytes:
    """Maintain a private game-list font without mutating MainUI's shared font.

    ``inner_loader_va`` returns the normal stock/shared font and, when the
    configurable font-size selector is enabled, may also publish a private
    size-override font at ``font_cache_va+0x2c``.  This wrapper never changes
    the style of the returned shared font.  It styles only that private font;
    when ``gamelist.bold`` is explicitly false and no size-override font exists,
    it opens a second font at the stock theme size through ``raw_loader_va`` and
    caches that private normal-style copy instead.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}
    a.emit(0xE24DD018)             # local/save area, keep 8-byte alignment
    a.emit(0xE58D0004)             # save r0-r3 and fifth arg
    a.emit(0xE58D1008)
    a.emit(0xE58D200C)
    a.emit(0xE58D3010)
    a.emit(0xE59D4030)             # incoming fifth arg / stock theme size
    a.emit(0xE58D4014)

    # Drop the previous private row font before the current theme layer opens
    # its replacement.  The inner configurable-size wrapper sees the cleared
    # slot and therefore cannot double-close it.
    a.ldr_literal(8, font_cache_va)
    a.emit(0xE598002C)
    a.emit(0xE3500000)
    a.branch('old_cleared', cond=0x0)
    a.emit(0xE3A03000)
    a.emit(0xE588302C)
    a.branch(close_font_va, link=True)
    a.label('old_cleared')

    a.emit(0xE59D4014)             # original fifth arg
    a.emit(0xE58D4000)             # outgoing fifth arg
    a.emit(0xE59D0004)
    a.emit(0xE59D1008)
    a.emit(0xE59D200C)
    a.emit(0xE59D3010)
    a.branch(inner_loader_va, link=True)
    a.emit(0xE1A04000)             # r4 = stock/shared list font

    # Resolve requested style.  Only explicit false selects NORMAL.
    a.ldr_literal(5, state_va)
    a.emit(0xE5955000)
    a.emit(0xE3550001)
    a.emit(0x03A06000)             # false -> NORMAL
    a.emit(0x13A06001)             # true/missing -> BOLD

    # A configurable-size private font may already exist. Style that private
    # object only; never call TTF_SetFontStyle on r4/shared font.
    a.emit(0xE598702C)
    a.emit(0xE3570000)
    a.branch('style_private', cond=0x1)

    # No private font is needed for stock-bold-at-stock-size.
    a.emit(0xE3560000)
    a.branch('done', cond=0x1)

    # Explicit normal style at the stock size needs a private duplicate.
    a.emit(0xE59D4014)
    a.emit(0xE58D4000)
    a.emit(0xE59D0004)
    a.emit(0xE59D1008)
    a.emit(0xE59D200C)
    a.emit(0xE59D3010)
    a.branch(raw_loader_va, link=True)
    a.emit(0xE1A07000)
    a.emit(0xE3570000)
    a.branch('done', cond=0x0)
    a.emit(0xE588702C)             # publish private same-size font

    a.label('style_private')
    a.emit(0xE1A00007)
    a.emit(0xE1A01006)
    a.branch(set_style_va, link=True)

    a.label('done')
    a.emit(0xE1A00004)             # original caller always receives stock font
    a.emit(0xE28DD018)
    a.emit(0xE8BD81F0)
    return a.finish()


def choose_rx_program_header_slot(data: bytes | bytearray,
                                  segs: list[Segment]) -> tuple[int, int, int]:
    """Return ``(index, file_offset, original_type)`` for a reusable PHDR.

    Prefer an unused PT_NULL entry.  The supported MainUI layout may instead
    expose a PT_NOTE entry; notes are metadata rather than load requirements,
    so that entry can be repurposed while the note bytes and sections remain in
    the file.  Other program-header types are left untouched.
    """
    phoff = struct.unpack_from('<I', data, 0x1C)[0]
    phentsize = struct.unpack_from('<H', data, 0x2A)[0]
    phnum = struct.unpack_from('<H', data, 0x2C)[0]
    if phentsize < 32:
        raise ValueError('ELF program-header entries are smaller than ELF32')
    note_candidate: tuple[int, int, int] | None = None
    for index in range(phnum):
        off = phoff + index * phentsize
        typ = struct.unpack_from('<I', data, off)[0]
        if typ == 0:  # PT_NULL
            return index, off, typ
        if typ == 4 and note_candidate is None:  # PT_NOTE
            (_typ, note_file_off, note_va, _pa, note_file_size,
             note_mem_size, _flags, _align) = struct.unpack_from('<8I', data, off)
            # Only reuse a note whose bytes and memory range are already
            # covered by a normal load segment.  Removing the PT_NOTE view
            # then changes metadata discovery, not which bytes are mapped.
            covered = any(
                load.file_off <= note_file_off and
                note_file_off + note_file_size <= load.file_off + load.file_size and
                load.vaddr <= note_va and
                note_va + note_mem_size <= load.vaddr + load.mem_size
                for load in segs)
            if covered:
                note_candidate = (index, off, typ)
    if note_candidate is not None:
        return note_candidate
    raise ValueError(
        'title-scroll R-X injection needs a reusable PT_NULL or PT_NOTE '
        'program-header entry')


def choose_rx_segment_layout(data: bytes | bytearray, segs: list[Segment],
                             rw_seg: Segment, rw_growth: int) -> tuple[int, int, int]:
    """Choose page-congruent file/virtual addresses for an appended R-X load."""
    # Retain the largest normal load alignment used by the input.  This avoids
    # assuming a smaller target page granularity than the original linker did.
    valid_alignments = [
        seg.align for seg in segs
        if seg.align >= 0x1000 and not (seg.align & (seg.align - 1))]
    alignment = max(valid_alignments, default=0x1000)
    payload_off = align_up(len(data), alignment)
    highest_end = 0
    for seg in segs:
        mem_size = seg.mem_size + (rw_growth if seg.ph_index == rw_seg.ph_index else 0)
        highest_end = max(highest_end, seg.vaddr + mem_size)
    payload_va = align_up(highest_end, alignment)
    if payload_off % alignment != payload_va % alignment:
        raise ValueError('internal R-X segment offset/VA congruence failure')
    return payload_off, payload_va, alignment


def append_rx_payload(d: bytearray, phdr_off: int, payload_off: int,
                      payload_va: int, alignment: int, payload: bytes) -> int:
    """Append a separate read/execute PT_LOAD without changing RW permissions."""
    if payload_off < len(d):
        raise ValueError('R-X payload offset overlaps the existing file')
    padding = payload_off - len(d)
    d.extend(b'\0' * padding)
    d.extend(payload)
    struct.pack_into(
        '<8I', d, phdr_off,
        1,                    # PT_LOAD
        payload_off,
        payload_va,
        payload_va,
        len(payload),
        len(payload),
        0x5,                  # PF_R | PF_X
        alignment,
    )
    return padding + len(payload)


def build_get_font_size(base_va: int, data_va: int, path_va: int,
                        open_va: int, read_va: int, close_va: int,
                        atoi_va: int) -> bytes:
    """Read optional game-list font size once; return 0 for theme default."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}; 8-byte aligned
    a.ldr_literal(4, data_va)       # r4 = shared cache
    a.emit(0xE5940028)             # ldr r0,[r4,#40] encoded cache
    a.emit(0xE3500000)             # cmp r0,#0 (0 = uninitialized)
    a.branch('cached', cond=0x1)   # bne cached
    a.emit(0xE3A05001)             # mov r5,#1 = encoded no override
    a.ldr_literal(0, path_va)
    a.emit(0xE3A01000)             # mov r1,#O_RDONLY
    a.branch(open_va, link=True)
    a.emit(0xE1A06000)             # mov r6,r0 fd
    a.emit(0xE3560000)             # cmp r6,#0
    a.branch('store', cond=0xB)    # blt store
    a.emit(0xE1A00006)             # mov r0,r6
    a.emit(0xE2841030)             # add r1,r4,#48 font buffer
    a.emit(0xE3A0200C)             # mov r2,#12
    a.branch(read_va, link=True)
    a.emit(0xE1A07000)             # mov r7,r0 bytes read
    a.emit(0xE1A00006)             # mov r0,r6
    a.branch(close_va, link=True)
    a.emit(0xE3570000)             # cmp r7,#0
    a.branch('store', cond=0xD)    # ble store
    a.emit(0xE2840030)             # add r0,r4,#48
    a.branch(atoi_va, link=True)
    a.emit(0xE1A05000)             # mov r5,r0
    a.emit(0xE3550000)             # cmp r5,#0
    a.branch('none', cond=0xD)     # ble none
    a.emit(0xE3550008)             # cmp r5,#8
    a.emit(0xB3A05008)             # movlt r5,#8
    a.emit(0xE355003C)             # cmp r5,#60
    a.emit(0xC3A0503C)             # movgt r5,#60
    a.emit(0xE2855001)             # add r5,r5,#1 encoded size
    a.branch('store')
    a.label('none')
    a.emit(0xE3A05001)             # mov r5,#1 encoded no override
    a.label('store')
    a.emit(0xE5845028)             # str r5,[r4,#40]
    a.emit(0xE1A00005)             # mov r0,r5
    a.label('cached')
    a.emit(0xE2400001)             # sub r0,r0,#1 (1 -> 0/default)
    a.emit(0xE8BD81F0)             # pop {r4-r8,pc}
    return a.finish()


def build_font_loader_wrapper(base_va: int, data_va: int, get_font_size_va: int,
                              original_loader_va: int, close_font_va: int,
                              set_style_va: int) -> bytes:
    """Open stock theme font and optional second game-list override font."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}
    a.emit(0xE24DD018)             # sub sp,sp,#24
    a.emit(0xE58D0004)             # save r0
    a.emit(0xE58D1008)             # save r1
    a.emit(0xE58D200C)             # save r2
    a.emit(0xE58D3010)             # save r3
    a.emit(0xE59D4030)             # ldr r4,[sp,#48] incoming fifth arg
    a.emit(0xE58D4014)             # save original theme size
    a.emit(0xE58D4000)             # fifth arg for stock call
    a.emit(0xE59D0004)
    a.emit(0xE59D1008)
    a.emit(0xE59D200C)
    a.emit(0xE59D3010)
    a.branch(original_loader_va, link=True)
    a.emit(0xE1A05000)             # r5 = stock TTF_Font*
    a.ldr_literal(8, data_va)
    a.emit(0xE598002C)             # old override font
    a.emit(0xE3500000)
    a.branch('no_old', cond=0x0)
    a.branch(close_font_va, link=True)
    a.emit(0xE3A00000)
    a.emit(0xE588002C)             # clear old pointer
    a.label('no_old')
    a.branch(get_font_size_va, link=True)
    a.emit(0xE3500000)             # no override?
    a.branch('done', cond=0x0)
    a.emit(0xE1500004)             # same as theme size?
    a.branch('done', cond=0x0)
    a.emit(0xE1A06000)             # r6 = override size
    a.emit(0xE58D6000)             # fifth arg override
    a.emit(0xE59D0004)
    a.emit(0xE59D1008)
    a.emit(0xE59D200C)
    a.emit(0xE59D3010)
    a.branch(original_loader_va, link=True)
    a.emit(0xE1A07000)             # r7 = override font
    a.emit(0xE3570000)
    a.branch('done', cond=0x0)
    a.emit(0xE1A00007)
    a.emit(0xE3A01001)             # same bold style as stock list font
    a.branch(set_style_va, link=True)
    a.emit(0xE588702C)             # cache override font pointer
    a.label('done')
    a.emit(0xE1A00005)             # return stock font to original caller
    a.emit(0xE28DD018)
    a.emit(0xE8BD81F0)             # pop {r4-r8,pc}
    return a.finish()


def build_font_select(base_va: int, continue_va: int, data_va: int) -> bytes:
    """Preserve established pointer tagging, then add one exact Search-list fallback.

    The established active/previous pointer path remains first and unchanged in
    meaning for ROM, Favourites and Recent. Only an object that misses both
    pointer slots is tested for exact DBCachedTextMenu identity, which adds the
    contextual Search-result case without gating or reclassifying old lists.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D5017)             # push {r0-r2,r4,ip,lr}
    a.ldr_literal(0, FONT_GLOBAL_PTR)
    a.emit(0xE5903000)             # r3 = stock theme list font
    a.ldr_literal(0, data_va)
    a.emit(0xE590102C)             # r1 = override font
    a.emit(0xE3510000)
    a.branch('done', cond=0x0)
    a.emit(0xE51B2050)             # r2 = current menu object

    # Established behavior first: all constructor-tagged game lists remain recognized.
    a.emit(0xE5904040)             # r4 = active game-list pointer
    a.emit(0xE1520004)
    a.branch('use', cond=0x0)
    a.emit(0xE590C044)             # ip = previous game-list pointer
    a.emit(0xE152000C)
    a.emit(0x05804044)             # streq previous = old active
    a.emit(0x05802040)             # streq active = current
    a.branch('use', cond=0x0)

    # New narrow fallback only after a pointer miss: contextual Search results
    # share exact DBCachedTextMenu identity with ordinary ROM lists.
    a.emit(0xE592C000)             # ip = exact vptr
    a.emit(arm_movw(4, ROM_VTABLE & 0xFFFF))
    a.emit(arm_movt(4, ROM_VTABLE >> 16))
    a.emit(0xE15C0004)
    a.branch('done', cond=0x1)
    a.label('use')
    a.emit(0xE1A03001)             # r3 = override font
    a.label('done')
    a.emit(0xE8BD5017)
    a.branch(continue_va)
    return a.finish()



def build_context_search_before_run(base_va: int, continue_va: int,
                                    state_va: int) -> bytes:
    """Mark the exact contextual Search MenuWindow activation in progress.

    The shared romwinidx restore hook can then distinguish this one construction
    from ordinary ROM-list restores and force the Search result viewport to the
    first row before the DBCachedTextMenu worker sees it. The normal post-run
    hook converts this temporary value to the established active-session state
    (1 on success, 0 on failure).
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D5003)             # push {r0,r1,ip,lr}
    a.ldr_literal(12, state_va)
    a.emit(arm_movw(0, CONTEXT_SEARCH_BUILDING_FLAG))
    a.emit(0xE58C0014)             # active/building contextual Search = 2
    a.emit(0xE8BD5003)
    a.emit(CONTEXT_SEARCH_BEFORE_RUN_STOCK)
    a.branch(continue_va)
    return a.finish()


def build_context_search_after_run(base_va: int, continue_va: int,
                                   state_va: int, marker_va: int,
                                   unlink_va: int) -> bytes:
    """Arm release filtering and remember an exact contextual Search session."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D50FF)             # push {r0-r7,ip,lr}; original r0 at [sp]
    a.ldr_literal(4, state_va)
    a.emit(0xE3500001)             # successful Search confirmation?
    a.branch('failed', cond=0x1)
    a.emit(0xE3A06001)
    a.emit(0xE5846000)             # pending A release = 1
    a.emit(0xE5846014)             # active contextual Search = 1
    a.emit(0xE51B6014)             # exact Search MenuWindow local
    a.emit(0xE5846018)             # remember parent pointer
    a.ldr_literal(0, marker_va)
    a.branch(unlink_va, link=True)  # discard any stale same-boot post-game marker
    a.branch('finish')
    a.label('failed')
    a.emit(0xE3A06000)
    a.emit(0xE5846000)
    a.emit(0xE5846014)
    a.emit(0xE5846018)
    a.label('finish')
    a.emit(0xE8BD50FF)
    a.emit(CONTEXT_SEARCH_AFTER_RUN_STOCK)
    a.branch(continue_va)
    return a.finish()


def build_context_search_event_filter(base_va: int, continue_va: int,
                                      poll_va: int, state_va: int) -> bytes:
    """Drop only the confirming physical A/Space events after Search returns."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D5017)             # push {r0-r2,r4,ip,lr}
    a.ldr_literal(4, state_va)
    a.emit(0xE5940000)             # pending
    a.emit(0xE3500000)
    a.branch('stock', cond=0x0)
    a.emit(0xE55B3028)             # event.type
    a.emit(0xE3530002)             # SDL_KEYDOWN
    a.branch('key', cond=0x0)
    a.emit(0xE3530003)             # SDL_KEYUP
    a.branch('stock', cond=0x1)    # unrelated events do not disarm
    a.label('key')
    a.emit(0xE51B2020)             # event.keysym.sym
    a.emit(0xE3520020)             # SDLK_SPACE / physical A
    a.branch('other_key', cond=0x1)
    a.emit(0xE3530003)             # matching keyup clears the one-shot state
    a.emit(0x03A00000)
    a.emit(0x05840000)
    a.emit(0xE8BD5017)
    a.branch(poll_va)               # consume and poll the next SDL event
    a.label('other_key')
    a.emit(0xE3A00000)
    a.emit(0xE5840000)             # a different key ends the narrow window
    a.label('stock')
    a.emit(0xE8BD5017)
    a.emit(CONTEXT_SEARCH_EVENT_STOCK)
    a.branch(continue_va)
    return a.finish()


def build_context_search_highlight_color(
        base_va: int, purple_color_va: int) -> bytes:
    """Return a stable Search fragment color without changing row geometry.

    The three stock highlight paths expect r3 to point at an SDL_Color word.
    Selected alignment modes 2/4 receive the caller's existing selected-text
    color at [fp,+0x14], so highlighted and selected rows use the identical
    fragment split and therefore identical glyph positions. Unselected rows
    use stock bright yellow on inferred dark backgrounds and #7B2CBF purple on
    inferred light backgrounds. r0/r2 are dead at every guarded hook.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE59B0018)             # row alignment/style mode
    a.emit(0xE3500002)
    a.branch('selected', cond=0x0)
    a.emit(0xE3500004)
    a.branch('selected', cond=0x0)
    a.ldr_literal(3, CONTEXT_SEARCH_LIST_COLOR_GLOBAL_VA)
    a.emit(0xE5930000)             # theme list SDL_Color
    a.emit(0xE20020FF)             # r2 = R
    a.emit(0xE1A03420)             # r3 = color >> 8
    a.emit(0xE20330FF)             # r3 = G
    a.emit(0xE0822083)             # r2 = R + 2*G
    a.emit(0xE1A03820)             # r3 = color >> 16
    a.emit(0xE20330FF)             # r3 = B
    a.emit(0xE0822003)             # r2 = R + 2*G + B
    a.emit(0xE3A03C02)             # r3 = 512
    a.emit(0xE1520003)
    a.branch('purple', cond=0x3)   # dark text -> inferred light background
    a.ldr_literal(3, CONTEXT_SEARCH_HIGHLIGHT_COLOR_GLOBAL_VA)
    a.emit(0xE12FFF1E)             # bx lr -- stock bright yellow
    a.label('purple')
    a.ldr_literal(3, purple_color_va)
    a.emit(0xE12FFF1E)             # bx lr -- #7B2CBF
    a.label('selected')
    a.emit(0xE28B3014)             # pointer to caller's selected SDL_Color
    a.emit(0xE12FFF1E)
    return a.finish()

def build_context_search_game_launch(
        base_va: int, continue_va: int, state_va: int, marker_va: int,
        open_va: int, close_va: int) -> bytes:
    """Create a same-boot marker only for a game launched from active Search."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D50FF)             # push {r0-r7,ip,lr}
    a.ldr_literal(4, state_va)
    a.emit(0xE5945014)             # active contextual Search
    a.emit(0xE3E06000)             # fd/result = -1
    a.emit(0xE3550000)
    a.branch('done', cond=0x0)
    a.ldr_literal(0, marker_va)
    a.emit(arm_movw(1, 0x0241))    # O_WRONLY|O_CREAT|O_TRUNC
    a.emit(arm_movw(2, 0x01B6))    # 0666
    a.branch(open_va, link=True)
    a.emit(0xE3500000)
    a.branch('done', cond=0xB)
    a.branch(close_va, link=True)
    a.label('done')
    a.emit(0xE8BD50FF)
    a.emit(CONTEXT_SEARCH_GAME_LAUNCH_STOCK)
    a.branch(continue_va)
    return a.finish()


def build_context_search_stack_pop_clear(
        base_va: int, continue_va: int, state_va: int) -> bytes:
    """Clear process-local Search ownership when its exact parent is popped."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D50FF)             # push {r0-r7,ip,lr}
    a.emit(0xE51B4008)             # vector argument
    a.ldr_literal(5, CONTEXT_SEARCH_STACK_GLOBAL_VA)
    a.emit(0xE5955000)             # global navigation vector object
    a.emit(0xE1540005)
    a.branch('replay', cond=0x1)
    a.emit(0xE5941000)             # begin
    a.emit(0xE5942004)             # end
    a.emit(0xE1520001)
    a.branch('replay', cond=0x0)
    a.emit(0xE2423004)
    a.emit(0xE5936000)             # raw object being popped
    a.ldr_literal(7, state_va)
    a.emit(0xE5972018)             # remembered exact Search parent
    a.emit(0xE3560000)
    a.branch('replay', cond=0x0)
    a.emit(0xE1560002)
    a.branch('replay', cond=0x1)
    a.emit(0xE3A05000)
    a.emit(0xE5875014)
    a.emit(0xE5875018)
    a.label('replay')
    a.emit(0xE8BD50FF)
    a.emit(CONTEXT_SEARCH_STACK_POP_STOCK)
    a.branch(continue_va)
    return a.finish()


def build_context_search_postgame_back(
        base_va: int, continue_va: int, marker_va: int,
        open_va: int, close_va: int, unlink_va: int) -> bytes:
    """After post-game B closes Search results, skip only the Search parent.

    This hook runs at the stock branch immediately after the first navigation
    vector pop. It therefore cannot fire during the result=3 game-launch path.
    The same-boot marker and exact exposed translation-153 MenuWindow must both
    agree before one additional pop. The removed object is never dereferenced.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}; aligned
    a.emit(0xE51B8010)             # result returned by removed top window
    a.emit(0xE3580001)
    a.branch('result_ok', cond=0x0)
    a.emit(0xE3580004)
    a.branch('done', cond=0x1)
    a.label('result_ok')

    # A marker exists only after launching a game from contextual Search.
    a.ldr_literal(0, marker_va)
    a.emit(0xE3A01000)             # O_RDONLY
    a.emit(0xE3A02000)
    a.branch(open_va, link=True)
    a.emit(0xE1A07000)             # marker fd / negative errno
    a.emit(0xE3500000)
    a.branch('probe_vector', cond=0xB)
    a.branch(close_va, link=True)
    a.label('probe_vector')

    # The first stock pop must have exposed the exact Search MenuWindow.
    a.emit(0xE51B4040)             # global navigation vector
    a.emit(0xE1A00004)
    a.branch(CONTEXT_SEARCH_VECTOR_SIZE_VA, link=True)
    a.emit(0xE1A05000)             # size after results pop
    a.emit(0xE3570000)
    a.branch('done', cond=0xB)
    a.emit(0xE3550000)
    a.branch('done', cond=0x0)
    a.emit(0xE1A00004)
    a.branch(CONTEXT_SEARCH_VECTOR_BACK_VA, link=True)
    a.emit(0xE5906000)             # exposed raw object
    a.emit(0xE3560000)
    a.branch('done', cond=0x0)
    a.emit(0xE5962000)
    a.emit(arm_movw(3, CONTEXT_SEARCH_MENU_WINDOW_VPTR & 0xFFFF))
    a.emit(arm_movt(3, CONTEXT_SEARCH_MENU_WINDOW_VPTR >> 16))
    a.emit(0xE1520003)
    a.branch('done', cond=0x1)
    a.emit(0xE5963004)
    a.emit(0xE3530099)             # translation id 153 / Search
    a.branch('done', cond=0x1)

    # Consume the marker only after every ownership/shape test passes.
    a.ldr_literal(0, marker_va)
    a.branch(unlink_va, link=True)
    a.emit(0xE1A00004)
    a.branch(CONTEXT_SEARCH_VECTOR_POP_VA, link=True)
    a.label('done')
    a.emit(0xE8BD41F0)
    a.branch(continue_va)
    return a.finish()



def build_context_search_keyboard_white(
        base_va: int, text_target_va: int) -> bytes:
    """Force only ImeWindow key-cap labels to opaque-independent white."""
    a = ArmBuilder(base_va)
    a.emit(arm_movw(12, CONTEXT_SEARCH_KEY_TEXT_WHITE & 0xFFFF))
    a.emit(arm_movt(12, CONTEXT_SEARCH_KEY_TEXT_WHITE >> 16))
    a.emit(0xE58DC004)             # replace SDL_Color stack argument only
    a.branch(text_target_va)       # tail-call; preserve caller LR
    return a.finish()


def build_favourite_page_local_init(base_va: int, continue_va: int) -> bytes:
    """Initialize the page-local favourite buffer, then replay the stock load."""
    a = ArmBuilder(base_va)
    a.emit(0xE3A03000)             # mov r3,#0
    a.emit(0xE50B314C)             # str r3,[fp,#-0x14c]
    a.emit(0xE51B3148)             # ldr r3,[fp,#-0x148] (overwritten stock)
    a.branch(continue_va)
    return a.finish()


def build_favourite_page_open_buffer(
        base_va: int, fopen_va: int, fseek_va: int, ftell_va: int,
        malloc_va: int, fread_va: int, free_va: int, rewind_va: int) -> bytes:
    """Open favourite.json and cache its complete bounded contents per page."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}; preserve caller fp
    a.branch(fopen_va, link=True)
    a.emit(0xE1A04000)             # r4 = FILE*
    a.emit(0xE3540000)             # cmp r4,#0
    a.branch('return_file', cond=0x0)

    a.emit(0xE1A00004)             # r0 = FILE*
    a.emit(0xE3A01000)             # offset = 0
    a.emit(0xE3A02002)             # SEEK_END
    a.branch(fseek_va, link=True)
    a.emit(0xE3500000)
    a.branch('fallback_rewind', cond=0x1)

    a.emit(0xE1A00004)
    a.branch(ftell_va, link=True)
    a.emit(0xE1A06000)             # r6 = length
    a.emit(0xE3560000)
    a.branch('fallback_rewind', cond=0xB)  # negative
    a.ldr_literal(7, FAVOURITE_PAGE_MAX_BUFFER_BYTES)
    a.emit(0xE1560007)             # cmp r6,r7
    a.branch('fallback_rewind', cond=0x8)  # unsigned higher

    a.emit(0xE2860001)             # malloc(length+1)
    a.branch(malloc_va, link=True)
    a.emit(0xE1A05000)             # r5 = buffer
    a.emit(0xE3550000)
    a.branch('fallback_rewind', cond=0x0)

    a.emit(0xE1A00004)
    a.branch(rewind_va, link=True)
    a.emit(0xE1A00005)             # ptr
    a.emit(0xE3A01001)             # size=1
    a.emit(0xE1A02006)             # nmemb=length
    a.emit(0xE1A03004)             # stream
    a.branch(fread_va, link=True)
    a.emit(0xE1500006)             # complete read?
    a.branch('read_failed', cond=0x1)

    a.emit(0xE0853006)             # end = buffer + length
    a.emit(0xE3A00000)
    a.emit(0xE5C30000)             # trailing NUL
    a.emit(0xE50B514C)             # publish page-local buffer
    a.emit(0xE1A00004)
    a.branch(rewind_va, link=True)
    a.branch('return_file')

    a.label('read_failed')
    a.emit(0xE1A00005)
    a.branch(free_va, link=True)
    a.label('fallback_rewind')
    a.emit(0xE1A00004)
    a.branch(rewind_va, link=True)
    a.label('return_file')
    a.emit(0xE1A00004)
    a.emit(0xE8BD81F0)             # pop {r4-r8,pc}
    return a.finish()


def build_favourite_page_close_buffer(
        base_va: int, free_va: int, fclose_va: int) -> bytes:
    """Free the page-local buffer, then perform the stock fclose."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D4010)             # push {r4,lr}
    a.emit(0xE1A04000)             # preserve FILE*
    a.emit(0xE51B014C)             # page buffer
    a.emit(0xE3500000)
    a.branch('close', cond=0x0)
    a.emit(0xE3A03000)
    a.emit(0xE50B314C)             # clear before free
    a.branch(free_va, link=True)
    a.label('close')
    a.emit(0xE1A00004)
    a.branch(fclose_va, link=True)
    a.emit(0xE8BD8010)             # pop {r4,pc}
    return a.finish()


def build_favourite_page_exception_cleanup(
        base_va: int, free_va: int, end_cleanup_va: int) -> bytes:
    """Release the page-local buffer before MainUI's exception cleanup."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D4010)             # preserve r4/lr and stack alignment
    a.emit(0xE51B014C)
    a.emit(0xE3500000)
    a.branch('tail', cond=0x0)
    a.emit(0xE3A03000)
    a.emit(0xE50B314C)
    a.branch(free_va, link=True)
    a.label('tail')
    a.emit(0xE8BD4010)             # restore original lr
    a.branch(end_cleanup_va)
    return a.finish()


def find_favourite_page_cache_sites(
        data: bytes | bytearray, segs: list[Segment],
        imports: dict[str, int]) -> dict[str, int]:
    """Resolve and validate the one ROM-page favourite lookup path."""
    page = unique(data, FAVOURITE_PAGE_FETCH_SIG,
                  'ROM database page fetch favourite scan')
    sites = {
        'page': page,
        'stack': page + FAVOURITE_PAGE_STACK_ALLOC_OFF,
        'init': page + FAVOURITE_PAGE_INIT_HOOK_OFF,
        'fopen': page + FAVOURITE_PAGE_FOPEN_CALL_OFF,
        'buffer_arg': page + FAVOURITE_PAGE_BUFFER_ARG_OFF,
        'isfav_call': page + FAVOURITE_PAGE_ISFAV_CALL_OFF,
        'fclose': page + FAVOURITE_PAGE_FCLOSE_CALL_OFF,
        'exception': page + FAVOURITE_PAGE_EXCEPTION_CALL_OFF,
    }
    if read_word(data, sites['stack']) != 0xE24DDE15:
        raise ValueError('ROM page-fetch stack frame is not stock 336 bytes')
    if read_word(data, sites['init']) != 0xE51B3148:
        raise ValueError('ROM page-fetch initial object load is not stock')
    for key, symbol in (('fopen', 'fopen'), ('fclose', 'fclose'),
                        ('exception', '__cxa_end_cleanup')):
        target = decode_arm_branch_target(
            read_word(data, sites[key]), off2va(segs, sites[key]))
        if target != imports[symbol]:
            raise ValueError(f'ROM page-fetch {symbol} call is not stock')
    if read_word(data, sites['buffer_arg']) != FAVOURITE_ISFAV_BUFFER_ARG_STOCK:
        raise ValueError('ROM page-fetch isFavourite buffer argument is not stock')
    isfav_va = decode_arm_branch_target(
        read_word(data, sites['isfav_call']), off2va(segs, sites['isfav_call']))
    if isfav_va is None:
        raise ValueError('could not resolve ROM page-fetch isFavourite helper')
    debug_site = va2off(segs, isfav_va, executable=True) + \
        FAVOURITE_ISFAV_BUFFER_PRINTF_OFF
    if decode_arm_branch_target(
            read_word(data, debug_site), off2va(segs, debug_site)) != imports['printf']:
        raise ValueError('isFavourite in-memory debug printf is not stock')
    sites['isfav_va'] = isfav_va
    sites['debug_printf'] = debug_site
    return sites


def build_favourite_type3_guard(base_va: int, is_favourite_va: int,
                                cleanup_va: int, label_sentinel: bool) -> bytes:
    """Refuse a type-3 Favourite when its exact label is already present."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D4010)             # push {r4,lr}; keep 8-byte alignment
    a.emit(0xE51B2008)             # r2 = label
    a.emit(0xE51B1014)             # r1 = FILE*
    a.emit(0xE3A00001 if label_sentinel else 0xE3A00000)
    # r0=1 is private to the folder-aware replacement; stock keeps NULL.
    a.branch(is_favourite_va, link=True)
    a.emit(0xE3500000)
    a.emit(0xE8BD4010)             # pop {r4,lr}
    a.branch(cleanup_va, cond=0x1) # duplicate: skip JSON append
    a.emit(0xE51B2008)             # original overwritten instruction
    a.emit(0xE12FFF1E)             # bx lr
    return a.finish()


def build_sql_escape_helpers(base_va: int,
                             entries: list[tuple[str, int]]) -> tuple[bytes, list[int]]:
    """Build stack-argument trampolines that SQL-escape apostrophes.

    Each entry is (source_register, independent_1024_byte_buffer_va). The
    returned entry VAs correspond to the input order. Escaping follows SQL
    literal rules: every single quote becomes two single quotes. Output is
    capped at 1023 bytes and always NUL-terminated.
    """
    a = ArmBuilder(base_va)
    entry_vas: list[int] = []
    for index, (source, buffer_va) in enumerate(entries):
        a.label(f'entry_{index}')
        entry_vas.append(a.va)
        if source == 'r3':
            a.emit(0xE1A00003)     # mov r0,r3
        elif source != 'r0':
            raise ValueError(f'unsupported SQL source register {source}')
        a.ldr_literal(2, buffer_va) # r2 = buffer start
        a.branch('core')

    a.label('core')
    a.emit(0xE1A03002)             # r3 = destination cursor
    a.emit(0xE300C3FF)             # movw ip,#1023 remaining bytes
    a.label('loop')
    a.emit(0xE35C0000)             # cmp ip,#0
    a.branch('done', cond=0x0)
    a.emit(0xE4D01001)             # ldrb r1,[r0],#1
    a.emit(0xE3510000)
    a.branch('done', cond=0x0)
    a.emit(0xE3510027)             # apostrophe?
    a.branch('single', cond=0x1)
    a.emit(0xE35C0002)             # need two bytes for a complete SQL quote pair
    a.branch('done', cond=0x3)     # blo done; never emit half a pair
    a.emit(0xE4C31001)             # first apostrophe
    a.emit(0xE24CC001)
    a.emit(0xE4C31001)             # duplicate apostrophe
    a.emit(0xE24CC001)
    a.branch('loop')
    a.label('single')
    a.emit(0xE4C31001)
    a.emit(0xE24CC001)
    a.branch('loop')
    a.label('done')
    a.emit(0xE3A01000)
    a.emit(0xE5C31000)             # NUL terminate
    a.emit(0xE58D2000)             # replace caller's first stack argument
    a.emit(0xE12FFF1E)             # bx lr
    return a.finish(), entry_vas


def validate_sql_escape_builder_guards() -> None:
    'Ensure both emitted SQL escapers contain the complete-pair boundary guard.'
    generic, _entries = build_sql_escape_helpers(
        0x1000, [('r0', 0x8000), ('r3', 0x9000)])
    if len(generic) != 120:
        raise ValueError(f'SQL escaping helper size regression: {len(generic)}')
    generic_words = [read_word(generic, off) for off in range(0, len(generic), 4)]
    try:
        guard_index = generic_words.index(0xE35C0002)
    except ValueError as exc:
        raise ValueError('generic SQL escaper lost two-byte quote guard') from exc
    if generic_words[guard_index + 1] >> 28 != 0x3:
        raise ValueError('generic SQL escaper quote guard no longer branches unsigned-lower')

    delete = build_delete_snprintf_escape_wrapper(0x2000, 0x9000, 0x3000)
    delete_words = [read_word(delete, off) for off in range(0, len(delete), 4)]
    try:
        guard_index = delete_words.index(0xE3520002)
    except ValueError as exc:
        raise ValueError('Delete-ROM SQL escaper lost two-byte quote guard') from exc
    if delete_words[guard_index + 1] >> 28 != 0x3:
        raise ValueError('Delete-ROM SQL escaper quote guard no longer branches unsigned-lower')




def build_case_sort_selector(
        base_va: int, state_va: int, path_va: int,
        query_pairs: list[tuple[int, int]],
        open_va: int, close_va: int
        ) -> tuple[bytes, list[int]]:
    """Return query pointers selected by a cached SD-card marker file.

    The state word is encoded as 0=uninitialized, 1=NOCASE and 2=stock
    case-sensitive. If the marker file can be opened, its contents are ignored
    and stock case-sensitive sorting is selected. A missing or unreadable file
    selects the patched NOCASE default. Each entry preserves the caller's
    registers except r2, which receives the selected query pointer.
    """
    a = ArmBuilder(base_va)
    entry_vas: list[int] = []
    for index, (stock_va, nocase_va) in enumerate(query_pairs):
        a.label(f'entry_{index}')
        entry_vas.append(a.va)
        a.emit(0xE92D43FB)             # push {r0,r1,r3-r9,lr}; 40 bytes
        a.ldr_literal(4, stock_va)      # r4 = stock BINARY query
        a.ldr_literal(5, nocase_va)     # r5 = COLLATE NOCASE query
        a.branch('core')

    a.label('core')
    a.ldr_literal(6, state_va)
    a.emit(0xE5967000)                 # ldr r7,[r6] cached mode
    a.emit(0xE3570000)                 # cmp r7,#0
    a.branch('choose', cond=0x1)       # bne choose

    a.emit(0xE3A07001)                 # default = NOCASE
    a.ldr_literal(0, path_va)
    a.emit(0xE3A01000)                 # O_RDONLY
    a.branch(open_va, link=True)
    a.emit(0xE1A08000)                 # r8 = fd
    a.emit(0xE3580000)
    a.branch('store', cond=0xB)         # blt: marker absent/unreadable
    a.emit(0xE1A00008)
    a.branch(close_va, link=True)
    a.emit(0xE3A07002)                 # marker exists -> case-sensitive

    a.label('store')
    a.emit(0xE5867000)

    a.label('choose')
    a.emit(0xE3570002)
    a.emit(0x01A02004)                 # stock query
    a.emit(0x11A02005)                 # NOCASE query
    a.emit(0xE8BD83FB)                 # pop {r0,r1,r3-r9,pc}
    return a.finish(), entry_vas


def build_rom_database_delete_helper(base_va: int, command_va: int,
                                     system_va: int) -> bytes:
    """Call system(command) with ABI-aligned stack and return its status."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D4010)             # push {r4,lr}; preserve 8-byte alignment
    a.ldr_literal(0, command_va)
    a.branch(system_va, link=True)
    a.emit(0xE8BD8010)             # pop {r4,pc}
    return a.finish()


def build_rom_database_rebuild_helper(
        base_va: int, stock_begin_va: int, sync_va: int, journal_va: int,
        wrapper_va: int) -> bytes:
    """Execute two rebuild PRAGMAs and stock BEGIN as separate SQL calls."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D4070)             # push {r4-r6,lr}; 16-byte aligned
    a.emit(0xE24DD008)             # reserve fifth argument + padding
    a.emit(0xE1A04000)             # r4 = database connection/object
    a.emit(0xE3A05000)             # r5 = zero
    a.emit(0xE58D5000)             # fifth wrapper argument = 0
    for sql_va in (sync_va, journal_va, stock_begin_va):
        a.emit(0xE1A00004)         # r0 = database connection/object
        a.ldr_literal(1, sql_va)    # r1 = one SQL statement
        a.emit(0xE1A02005)         # r2 = 0
        a.emit(0xE1A03005)         # r3 = 0
        a.branch(wrapper_va, link=True)
    a.emit(0xE28DD008)
    a.emit(0xE8BD8070)             # return final BEGIN result
    return a.finish()


def build_deferred_rom_database_index_wrapper(
        base_va: int, caller_table_fp_offset: int,
        snprintf_va: int, wrapper_va: int,
        fixed_index_format_va: int | None = None,
        index_format_selector_va: int | None = None) -> bytes:
    """Create the browse index immediately before the stock commit.

    Entry uses the original END-call ABI: r0 is the database object and r1 is
    the stock END TRANSACTION string. The caller's frame pointer is still live,
    so each site-specific wrapper can recover its system table-name pointer.
    Index creation and commit are separate wrapper calls: a failed CREATE INDEX
    therefore cannot suppress the commit, leaving a correct unindexed cache as
    the fallback. The return value is the stock commit call's result.
    """
    if (fixed_index_format_va is None) == (index_format_selector_va is None):
        raise ValueError(
            'deferred index wrapper needs exactly one format selection mode')
    if caller_table_fp_offset <= 0:
        raise ValueError('deferred index caller frame offset must be positive')

    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}; 24-byte aligned
    a.emit(0xE1A04000)             # r4 = database object
    a.emit(0xE1A05001)             # r5 = stock END TRANSACTION string
    a.ldr_literal(6, caller_table_fp_offset)
    a.emit(0xE04B6006)             # r6 = caller fp - table-name offset
    a.emit(0xE5966000)             # r6 = system table-name pointer
    a.emit(0xE3A08000)             # r8 = shared zero
    if index_format_selector_va is not None:
        a.branch(index_format_selector_va, link=True)
        a.emit(0xE1A07002)         # r7 = selected BINARY/NOCASE format
    else:
        assert fixed_index_format_va is not None
        a.ldr_literal(7, fixed_index_format_va)

    # Keep one 512-byte SQL buffer above an eight-byte aligned outgoing-argument
    # area. The format is bounded far below the stock rebuild buffer size.
    a.emit(0xE24DDC02)             # sub sp,sp,#512
    a.emit(0xE24DD008)             # sub sp,sp,#8
    a.emit(0xE28D0008)             # r0 = SQL buffer
    a.emit(0xE3A01C02)             # r1 = 512
    a.emit(0xE1A02007)             # r2 = selected index format
    a.emit(0xE1A03006)             # r3 = system table-name pointer
    a.branch(snprintf_va, link=True)

    # Execute CREATE INDEX. Ignore its status deliberately: the stock cache is
    # still valid without the optional browse index, and must always commit.
    a.emit(0xE58D8000)             # fifth wrapper argument = 0
    a.emit(0xE1A00004)
    a.emit(0xE28D1008)             # r1 = formatted CREATE INDEX SQL
    a.emit(0xE1A02008)
    a.emit(0xE1A03008)
    a.branch(wrapper_va, link=True)

    # Execute the original commit separately and return its result.
    a.emit(0xE58D8000)
    a.emit(0xE1A00004)
    a.emit(0xE1A01005)
    a.emit(0xE1A02008)
    a.emit(0xE1A03008)
    a.branch(wrapper_va, link=True)
    a.emit(0xE28DD008)
    a.emit(0xE28DDC02)
    a.emit(0xE8BD81F0)             # pop {r4-r8,pc}; preserve r0 result
    return a.finish()


def build_rom_list_count_cache(
        base_va: int, state_va: int,
        mutation_entries: list[tuple[str, int, int]],
        folder_count_state_va: int | None = None
        ) -> tuple[bytes, int, int, int, dict[str, int]]:
    """Build one-entry COUNT(*) cache helpers and mutation trampolines.

    ``mutation_entries`` contains ``(label, function_va, stock_prologue_word)``.
    Each trampoline executes the overwritten function prologue, invalidates the
    shared generation, and branches back to ``function_va + 4``.

    The lookup/store helpers intentionally use the caller's frame pointer.  The
    target count routine has a verified unused local word at ``fp-0x24`` where a
    miss records the current generation.  Publication happens only if that word
    still matches, preventing a mutation that begins during the query from
    repopulating the previous generation. Lock ownership must never cross an
    early return; each acquisition is nevertheless bounded and fails open to
    stock/no-cache behavior so a future invariant violation cannot hang MainUI.
    """
    a = ArmBuilder(base_va)

    # Lookup entry.  It replaces three stock setup instructions.  A miss returns
    # with Z=1 and recreates r0/r2/r3 for the untouched worker-request call.  A
    # hit writes the positive count to the stock local and returns with Z=0.
    lookup_va = a.va
    a.emit(0xE92D41F0)             # push {r4-r8,lr}
    a.emit(0xE1A0800B)             # r8 = caller fp
    a.ldr_literal(4, state_va)
    a.emit(0xE3A03001)             # r3 = lock value 1
    a.emit(0xE3A05040)             # r5 = bounded lock attempts (64)
    a.label('lookup_lock')
    a.emit(0xE1940F9F)             # ldrex r0,[r4]
    a.emit(0xE3500000)
    a.emit(0x01841F93)             # strexeq r1,r3,[r4]
    a.emit(0x03510000)             # cmpeq r1,#0
    a.branch('lookup_locked', cond=0x0)
    a.emit(0xE2555001)             # subs r5,r5,#1
    a.branch('lookup_lock', cond=0x1)
    # Fail open: never hang MainUI if a future edit leaks the lock. Force the
    # subsequent store to reject publication, then execute the stock query.
    a.emit(0xE3E00000)             # r0 = 0xffffffff generation sentinel
    a.emit(0xE5080024)             # [caller fp-0x24]
    a.emit(0xE518003C)             # recreate ldr r0,[fp,#-0x3c]
    a.emit(0xE2482040)             # recreate sub r2,fp,#0x40
    a.emit(0xE3A03000)             # recreate mov r3,#0
    a.emit(0xE3530000)             # Z=1 => continue stock request
    a.emit(0xE8BD81F0)             # pop {r4-r8,pc}
    a.label('lookup_locked')
    a.emit(0xF57FF05B)             # dmb ish

    a.emit(0xE5940004)             # valid?
    a.emit(0xE3500000)
    a.branch('lookup_miss_locked', cond=0x0)
    a.emit(0xE594000C)             # cached system object
    a.emit(0xE5181050)             # current system object [caller fp-0x50]
    a.emit(0xE1500001)
    a.branch('lookup_miss_locked', cond=0x1)
    a.emit(0xE5985004)             # generated COUNT SQL buffer
    a.emit(0xE2846018)             # cached SQL buffer
    a.emit(arm_movw(7, ROM_LIST_COUNT_CACHE_QUERY_SIZE))
    a.label('lookup_compare')
    a.emit(0xE4D50001)             # ldrb r0,[r5],#1
    a.emit(0xE4D61001)             # ldrb r1,[r6],#1
    a.emit(0xE1500001)
    a.branch('lookup_miss_locked', cond=0x1)
    a.emit(0xE3500000)
    a.branch('lookup_hit_locked', cond=0x0)
    a.emit(0xE2577001)             # subs r7,r7,#1
    a.branch('lookup_compare', cond=0x1)

    a.label('lookup_miss_locked')
    a.emit(0xE5940008)             # snapshot generation
    a.emit(0xE5080024)             # [caller fp-0x24]
    a.emit(0xF57FF05B)             # release lock
    a.emit(0xE3A01000)
    a.emit(0xE5841000)
    a.emit(0xE518003C)             # recreate ldr r0,[fp,#-0x3c]
    a.emit(0xE2482040)             # recreate sub r2,fp,#0x40
    a.emit(0xE3A03000)             # recreate mov r3,#0
    a.emit(0xE3530000)             # Z=1 => continue stock request
    a.emit(0xE8BD81F0)             # pop {r4-r8,pc}

    a.label('lookup_hit_locked')
    a.emit(0xE5940010)             # cached positive total row count
    a.emit(0xE5080010)             # stock local [caller fp-0x10]
    if folder_count_state_va is not None:
        a.emit(0xE5941014)         # cached folder count
        a.ldr_literal(2, folder_count_state_va)
        a.emit(0xE5821000)         # restore draw-time folder state on hit
    a.emit(0xF57FF05B)
    a.emit(0xE3A01000)
    a.emit(0xE5841000)
    a.emit(0xE3500000)             # positive => Z=0
    a.emit(0xE8BD81F0)

    # Store entry.  Preserve the stock write first.  Non-positive counts are
    # not cached because MainUI uses that path for rebuild/error handling.
    store_va = a.va
    a.emit(0xE50B3010)             # stock str r3,[fp,#-0x10]
    a.emit(0xE3530000)
    a.emit(0xD12FFF1E)             # bxle lr
    a.emit(0xE92D47F0)             # push {r4-r10,lr}
    a.emit(0xE1A0A00B)             # r10 = caller fp
    a.ldr_literal(4, state_va)
    a.emit(0xE3A03001)
    a.emit(0xE3A05040)             # bounded lock attempts (64)
    a.label('store_lock')
    a.emit(0xE1940F9F)
    a.emit(0xE3500000)
    a.emit(0x01841F93)
    a.emit(0x03510000)
    a.branch('store_locked', cond=0x0)
    a.emit(0xE2555001)
    a.branch('store_lock', cond=0x1)
    a.emit(0xE8BD87F0)             # fail open: keep stock result, skip cache
    a.label('store_locked')
    a.emit(0xF57FF05B)

    a.emit(0xE5940008)             # current generation
    a.emit(0xE51A1024)             # generation at query miss
    a.emit(0xE1500001)
    a.branch('store_release', cond=0x1)
    a.emit(0xE3A00000)
    a.emit(0xE5840004)             # invalidate while publishing
    a.emit(0xE51A0050)
    a.emit(0xE584000C)             # system object key
    a.emit(0xE51A0010)
    a.emit(0xE5840010)             # positive total row count value
    if folder_count_state_va is not None:
        a.ldr_literal(1, folder_count_state_va)
        a.emit(0xE5911000)         # exact folder count from dual-column result
        a.emit(0xE5841014)         # cache alongside total row count
    a.emit(0xE59A5004)             # source query buffer
    a.emit(0xE2846018)             # destination query buffer
    a.emit(arm_movw(7, ROM_LIST_COUNT_CACHE_QUERY_SIZE - 1))
    a.label('store_copy')
    a.emit(0xE4D50001)
    a.emit(0xE4C60001)
    a.emit(0xE3500000)
    a.branch('store_publish', cond=0x0)
    a.emit(0xE2577001)
    a.branch('store_copy', cond=0x1)
    a.emit(0xE3A00000)
    a.emit(0xE5C60000)             # force final NUL if truncated
    a.label('store_publish')
    a.emit(0xF57FF05B)
    a.emit(0xE3A00001)
    a.emit(0xE5840004)             # valid is published last

    a.label('store_release')
    a.emit(0xF57FF05B)
    a.emit(0xE3A00000)
    a.emit(0xE5840000)
    a.emit(0xE8BD87F0)             # pop {r4-r10,pc}

    # Shared invalidator.  Four-byte state writes are atomic on ARM; the lock
    # serializes them against lookup/publication and DMB provides publication
    # ordering for the copied query bytes.
    invalidate_va = a.va
    a.emit(0xE92D401F)             # push {r0-r4,lr}
    a.ldr_literal(4, state_va)
    a.emit(0xE3A03001)
    a.emit(0xE3A02040)             # bounded lock attempts (64)
    a.label('invalidate_lock')
    a.emit(0xE1940F9F)
    a.emit(0xE3500000)
    a.emit(0x01841F93)
    a.emit(0x03510000)
    a.branch('invalidate_locked', cond=0x0)
    a.emit(0xE2522001)
    a.branch('invalidate_lock', cond=0x1)
    a.emit(0xE8BD801F)             # fail open: never deadlock the UI
    a.label('invalidate_locked')
    a.emit(0xF57FF05B)
    a.emit(0xE3A00000)
    a.emit(0xE5840004)             # valid = 0
    a.emit(0xE5940008)
    a.emit(0xE2800001)
    a.emit(0xE5840008)             # generation++
    a.emit(0xF57FF05B)
    a.emit(0xE3A00000)
    a.emit(0xE5840000)
    a.emit(0xE8BD801F)             # pop {r0-r4,pc}

    trampoline_vas: dict[str, int] = {}
    for label, function_va, prologue_word in mutation_entries:
        trampoline_vas[label] = a.va
        a.emit(prologue_word)
        a.branch(invalidate_va, link=True)
        a.branch(function_va + 4)

    return a.finish(), lookup_va, store_va, invalidate_va, trampoline_vas


def build_rom_list_count_delete_action_invalidator(
        base_va: int, invalidate_va: int) -> bytes:
    """Invalidate only our RAM COUNT cache after stock single-ROM deletion.

    This hook replaces the first instruction after DeleteRomAction's virtual
    call to DBCachedTextMenu::deleteRow. The delete method itself remains
    byte-for-byte stock. The shared invalidator preserves r0-r4; reproduce the
    displaced ``ldr r3,[fp,#-8]`` and return to the next stock instruction.
    Invalidating after a failed/no-op delete is harmless and avoids coupling
    this helper to MainUI's internal success status.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D4010)             # push {r4,lr}; keep 8-byte alignment
    a.branch(invalidate_va, link=True)
    a.emit(0xE8BD4010)             # pop {r4,lr}
    a.emit(DELETE_ROM_ACTION_POST_DELETE_STOCK)
    a.emit(0xE12FFF1E)             # bx lr
    return a.finish()

def build_database_schema_selector_entry(
        base_va: int, core_va: int, binary_schema_va: int,
        nocase_schema_va: int) -> bytes:
    """Enter the shared case-setting selector with schema pointers in r4/r5.

    The shared core preserves the caller registers saved here and returns the
    selected schema in r2, exactly like its normal query-selector entries.
    """
    a = ArmBuilder(base_va)
    # The indexed schema contains two ordinary %s substitutions. MainUI passes
    # the table name in r3 for the first one; publish the same pointer as the
    # fifth ABI argument before making our own aligned stack frame. This avoids
    # libc-specific positional formats such as %1$s in the cache-build path.
    a.emit(0xE58D3000)             # str r3,[sp]
    a.emit(0xE92D43FB)             # push {r0,r1,r3-r9,lr}
    a.ldr_literal(4, binary_schema_va)
    a.ldr_literal(5, nocase_schema_va)
    a.branch(core_va)
    return a.finish()


def build_fixed_database_schema_selector_entry(
        base_va: int, schema_va: int) -> bytes:
    """Return one indexed schema and duplicate MainUI's table-name argument."""
    a = ArmBuilder(base_va)
    a.emit(0xE58D3000)             # fifth snprintf argument = table name
    a.emit(arm_movw(2, schema_va & 0xFFFF))
    a.emit(arm_movt(2, schema_va >> 16))
    a.emit(0xE12FFF1E)
    return a.finish()


def arm_movw(rd: int, immediate: int) -> int:
    """Encode ARM-state MOVW Rd,#imm16."""
    immediate &= 0xFFFF
    return (0xE3000000 | ((immediate & 0xF000) << 4) |
            ((rd & 0xF) << 12) | (immediate & 0x0FFF))


def arm_movt(rd: int, immediate: int) -> int:
    """Encode ARM-state MOVT Rd,#imm16."""
    immediate &= 0xFFFF
    return (0xE3400000 | ((immediate & 0xF000) << 4) |
            ((rd & 0xF) << 12) | (immediate & 0x0FFF))


def build_game_detail_title_line_height_stub(
        base_va: int, return_va: int, font_height_va: int,
        state_va: int, *, multiply_index: bool = False) -> bytes:
    """Return r3=scaled title row height, or index*height for multiline Y."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D40F7)             # push {r0-r2,r4-r7,lr}; 32-byte aligned
    if multiply_index:
        a.emit(0xE1A06003)         # mov r6,r3: preserve line index
    a.ldr_literal(4, GAME_DETAIL_TITLE_FONT_GLOBAL)
    a.emit(0xE5940000)             # ldr r0,[r4]
    a.emit(0xE3500000)             # cmp r0,#0
    a.branch('fallback', cond=0x0)
    a.branch(font_height_va, link=True)
    a.emit(0xE3500000)             # cmp r0,#0
    a.branch('fallback', cond=0xD) # ble
    a.emit(0xE1A021A0)             # mov r2,r0,lsr#3
    a.emit(0xE0403002)             # sub r3,r0,r2 => 7/8 font height
    a.branch('clamp')
    a.label('fallback')
    a.emit(0xE3A0301E)             # mov r3,#30
    a.label('clamp')
    a.emit(0xE3530014)             # cmp r3,#20
    a.emit(0xB3A03014)             # movlt r3,#20
    a.emit(0xE3530028)             # cmp r3,#40
    a.emit(0xC3A03028)             # movgt r3,#40
    a.ldr_literal(5, state_va)
    a.emit(0xE5853000)             # str r3,[r5]
    if multiply_index:
        a.emit(0xE0030396)         # mul r3,r6,r3
    a.emit(0xE8BD40F7)             # pop {r0-r2,r4-r7,lr}
    a.branch(return_va)
    return a.finish()


def build_game_detail_counter_x_stub(base_va: int, return_va: int) -> bytes:
    """Align the first of four counter digits exactly with x=276."""
    a = ArmBuilder(base_va)
    a.ldr_literal(2, DETAIL_COUNTER_DIGIT_SURFACE_GLOBAL)
    a.emit(0xE5922000)             # digit strip SDL_Surface *
    a.emit(0xE3520000)
    a.branch('fallback', cond=0x0)
    a.emit(0xE5922008)             # surface->w
    a.emit(0xE3A03000)             # digit width = 0
    a.label('divide10')
    a.emit(0xE352000A)
    a.emit(0x2242200A)             # subcs r2,r2,#10
    a.emit(0x22833001)             # addcs r3,r3,#1
    a.branch('divide10', cond=0x2)
    a.emit(0xE1A03083)             # lsl r3,r3,#1
    # rect.x = 276 - (124 - 4*(digit_width+1))/2
    #        = 216 + 2*digit_width
    a.emit(0xE28330D8)
    a.branch(return_va)
    a.label('fallback')
    a.emit(arm_movw(3, DETAIL_COUNTER_X_FALLBACK))
    a.branch(return_va)
    return a.finish()


def build_game_detail_favourite_icon_x_stub(
        base_va: int, return_va: int) -> bytes:
    """Right-align the favourite surface to the detail text area's x=634 edge."""
    a = ArmBuilder(base_va)
    a.emit(0xE51B2030)             # detail this
    a.emit(0xE5922088)             # favourite SDL_Surface *
    a.emit(0xE3520000)
    a.branch('none', cond=0x0)
    a.emit(0xE5922008)             # surface->w
    a.emit(arm_movw(3, 634))        # text x 274 + width 360
    a.emit(0xE0433002)             # text right - icon width
    a.emit(arm_movw(1, 274))
    a.emit(0xE1530001)
    a.emit(0xB1A03001)             # clamp to text area's left edge
    a.branch(return_va)
    a.label('none')
    a.emit(0xE3A03000)
    a.branch(return_va)
    return a.finish()


def build_game_detail_favourite_icon_y_stub(
        base_va: int, return_va: int) -> bytes:
    """Place the favourite icon at y=60 in the game-detail text area."""
    a = ArmBuilder(base_va)
    a.emit(0xE51B2030)             # detail this
    a.emit(0xE5922088)             # favourite SDL_Surface *
    a.emit(0xE3520000)
    a.branch('none', cond=0x0)
    a.emit(arm_movw(3, DETAIL_FAV_ICON_Y))
    a.branch(return_va)
    a.label('none')
    a.emit(0xE3A03000)
    a.branch(return_va)
    return a.finish()


def build_miyoogamelist_clear_image(
        base_va: int, empty_cstr_va: int, string_assign_va: int,
        validation_va: int) -> bytes:
    """Clear the reused XML image std::string, then resume validation."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D4010)             # push {r4,lr}; keep SP 8-byte aligned
    a.emit(0xE24B00AC)             # sub r0,fp,#0xac (image std::string)
    a.ldr_literal(1, empty_cstr_va) # r1 = ""
    a.branch(string_assign_va, link=True)
    a.emit(0xE8BD4010)             # pop {r4,lr}
    a.branch(validation_va)
    return a.finish()


def build_miyoogamelist_filename_set(
        base_va: int, state_va: int, opendir_va: int, readdir_va: int,
        closedir_va: int, calloc_va: int, free_va: int, strlen_va: int,
        strcasecmp_va: int, memcpy_va: int) -> bytes:
    """Build one bounded case-insensitive set for the XML import directory.

    Entered in place of ``str r3,[fp,#-0x20]`` immediately before the XML
    entry loop. r11 deliberately remains the importer's frame pointer, so the
    helper can read the strdup'd ROM-directory path at [r11-0x28]. The global
    state is published only after a complete directory scan. Any failure frees
    the block and leaves the state NULL, making the in-loop helper call stock
    access().
    """
    a = ArmBuilder(base_va)
    a.emit(0xE50B3020)             # original str r3,[fp,#-0x20]
    a.emit(0xE92D47F0)             # push {r4-r10,lr}
    a.emit(0xE24DD010)             # 16 bytes: name,len,slot,temp
    a.ldr_literal(4, state_va)      # r4 = global block-pointer word
    a.emit(0xE5940000)
    a.emit(0xE3500000)
    a.branch('no_old', cond=0x0)
    a.emit(0xE3A01000)
    a.emit(0xE5841000)             # clear before free
    a.branch(free_va, link=True)

    a.label('no_old')
    a.emit(0xE51B0028)             # directory path strdup
    a.branch(opendir_va, link=True)
    a.emit(0xE1A05000)             # r5 = DIR*
    a.emit(0xE3550000)
    a.branch('done', cond=0x0)      # opendir failure => access fallback

    a.emit(0xE3A00001)
    a.ldr_literal(1, MIYOOGAMELIST_SET_BLOCK_SIZE)
    a.branch(calloc_va, link=True)
    a.emit(0xE1A06000)             # r6 = zeroed block
    a.emit(0xE3560000)
    a.branch('close_only', cond=0x0)

    a.emit(0xE51B0028)
    a.emit(0xE5860000)             # header.root pointer
    a.branch(strlen_va, link=True)
    a.emit(0xE5860004)             # header.root length
    a.ldr_literal(0, MIYOOGAMELIST_SET_POOL_OFFSET)
    a.emit(0xE0867000)             # r7 = pool cursor
    a.ldr_literal(0, MIYOOGAMELIST_SET_BLOCK_SIZE)
    a.emit(0xE0868000)             # r8 = block end
    a.emit(0xE3A09000)             # r9 = entry count
    a.ldr_literal(10, MIYOOGAMELIST_SET_MASK)

    a.label('read_next')
    a.emit(0xE1A00005)
    a.branch(readdir_va, link=True)
    a.emit(0xE3500000)
    a.branch('publish', cond=0x0)
    a.emit(0xE280100B)             # d_name at dirent+11

    # Skip only the synthetic dot entries; real dot-prefixed ROMs remain.
    a.emit(0xE5D12000)
    a.emit(0xE352002E)
    a.branch('not_dot', cond=0x1)
    a.emit(0xE5D12001)
    a.emit(0xE3520000)
    a.branch('read_next', cond=0x0)
    a.emit(0xE352002E)
    a.branch('not_dot', cond=0x1)
    a.emit(0xE5D12002)
    a.emit(0xE3520000)
    a.branch('read_next', cond=0x0)

    a.label('not_dot')
    a.emit(arm_movw(2, MIYOOGAMELIST_SET_MAX_ENTRIES))
    a.emit(0xE1590002)
    a.branch('fallback_free', cond=0x2)  # bhs
    a.emit(0xE58D1000)             # save d_name
    a.emit(0xE1A00001)
    a.branch(strlen_va, link=True)
    a.emit(0xE2802001)             # include NUL
    a.emit(0xE58D2004)
    a.emit(0xE0873002)
    a.emit(0xE1530008)
    a.branch('fallback_free', cond=0x8)  # bhi pool end

    # FNV-1a over ASCII-lowercased bytes. Non-ASCII bytes remain exact, which
    # matches strcasecmp in MainUI's normal C locale.
    a.emit(0xE59D1000)
    a.ldr_literal(2, MIYOOGAMELIST_FNV_OFFSET)
    a.ldr_literal(12, MIYOOGAMELIST_FNV_PRIME)
    a.label('hash_loop')
    a.emit(0xE4D13001)
    a.emit(0xE3530000)
    a.branch('hash_done', cond=0x0)
    a.emit(0xE3530080)
    a.branch('read_next', cond=0x2)  # non-ASCII uses access fallback
    a.emit(0xE3530041)
    a.branch('hash_folded', cond=0x3)  # blo
    a.emit(0xE353005A)
    a.emit(0x92833020)             # addls r3,r3,#32
    a.label('hash_folded')
    a.emit(0xE0222003)
    a.emit(0xE002029C)             # mul r2,r12,r2
    a.branch('hash_loop')

    a.label('hash_done')
    a.emit(0xE002200A)             # index &= mask
    a.label('probe')
    a.emit(0xE2860010)
    a.emit(0xE0800102)             # slot = block+16+index*4
    a.emit(0xE5901000)
    a.emit(0xE3510000)
    a.branch('insert', cond=0x0)
    a.emit(0xE58D2008)             # preserve index across strcasecmp
    a.emit(0xE59D0000)
    a.branch(strcasecmp_va, link=True)
    a.emit(0xE3500000)
    a.branch('read_next', cond=0x0)  # duplicate spelling/case
    a.emit(0xE59D2008)
    a.emit(0xE2822001)
    a.emit(0xE002200A)
    a.branch('probe')

    a.label('insert')
    a.emit(0xE58D0008)             # save empty slot address
    a.emit(0xE1A00007)
    a.emit(0xE59D1000)
    a.emit(0xE59D2004)
    a.branch(memcpy_va, link=True)
    a.emit(0xE59D3008)
    a.emit(0xE5837000)
    a.emit(0xE59D2004)
    a.emit(0xE0877002)
    a.emit(0xE2899001)
    a.branch('read_next')

    a.label('fallback_free')
    a.emit(0xE1A00005)
    a.branch(closedir_va, link=True)
    a.emit(0xE1A00006)
    a.branch(free_va, link=True)
    a.branch('done')

    a.label('publish')
    a.emit(0xE1A00005)
    a.branch(closedir_va, link=True)
    a.emit(0xE5846000)             # atomic aligned pointer publication
    a.branch('done')

    a.label('close_only')
    a.emit(0xE1A00005)
    a.branch(closedir_va, link=True)

    a.label('done')
    a.emit(0xE28DD010)
    a.emit(0xE8BD87F0)
    return a.finish()


def build_miyoogamelist_filename_lookup(
        base_va: int, state_va: int, strncmp_va: int, strrchr_va: int,
        strcasecmp_va: int, access_va: int) -> bytes:
    """Return access-compatible 0/-1 from the transient filename set.

    Only direct root-directory filenames use the set. Prefix mismatch, empty
    names, and nested paths call stock access() so unusual XML retains exact
    behaviour rather than being approximated by basename matching.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}
    a.emit(0xE24DD008)
    a.emit(0xE1A04000)             # r4 = full absolute path
    a.ldr_literal(5, state_va)
    a.emit(0xE5955000)
    a.emit(0xE3550000)
    a.branch('fallback', cond=0x0)
    a.emit(0xE5956000)             # root path
    a.emit(0xE5957004)             # root length
    a.emit(0xE1A00004)
    a.emit(0xE1A01006)
    a.emit(0xE1A02007)
    a.branch(strncmp_va, link=True)
    a.emit(0xE3500000)
    a.branch('fallback', cond=0x1)
    a.emit(0xE0844007)
    a.emit(0xE5D40000)
    a.emit(0xE350002F)
    a.branch('fallback', cond=0x1)
    a.emit(0xE2844001)

    a.label('strip_dot_slash')
    a.emit(0xE5D40000)
    a.emit(0xE350002E)
    a.branch('stripped', cond=0x1)
    a.emit(0xE5D40001)
    a.emit(0xE350002F)
    a.branch('stripped', cond=0x1)
    a.emit(0xE2844002)
    a.branch('strip_dot_slash')

    a.label('stripped')
    a.emit(0xE5D40000)
    a.emit(0xE3500000)
    a.branch('fallback', cond=0x0)
    a.emit(0xE1A00004)
    a.emit(0xE3A0102F)
    a.branch(strrchr_va, link=True)
    a.emit(0xE3500000)
    a.branch('fallback', cond=0x1)  # nested path: exact access fallback

    a.emit(0xE1A01004)
    a.ldr_literal(6, MIYOOGAMELIST_FNV_OFFSET)
    a.ldr_literal(8, MIYOOGAMELIST_SET_MASK)
    a.ldr_literal(12, MIYOOGAMELIST_FNV_PRIME)
    a.label('hash_loop')
    a.emit(0xE4D13001)
    a.emit(0xE3530000)
    a.branch('hash_done', cond=0x0)
    a.emit(0xE3530080)
    a.branch('fallback', cond=0x2)  # preserve filesystem Unicode semantics
    a.emit(0xE3530041)
    a.branch('hash_folded', cond=0x3)
    a.emit(0xE353005A)
    a.emit(0x92833020)
    a.label('hash_folded')
    a.emit(0xE0266003)
    a.emit(0xE006069C)
    a.branch('hash_loop')

    a.label('hash_done')
    a.emit(0xE0066008)
    a.label('probe')
    a.emit(0xE2850010)
    a.emit(0xE0800106)
    a.emit(0xE5907000)
    a.emit(0xE3570000)
    a.branch('not_found', cond=0x0)
    a.emit(0xE58D6000)
    a.emit(0xE1A00004)
    a.emit(0xE1A01007)
    a.branch(strcasecmp_va, link=True)
    a.emit(0xE3500000)
    a.branch('found', cond=0x0)
    a.emit(0xE59D6000)
    a.emit(0xE2866001)
    a.emit(0xE0066008)
    a.branch('probe')

    a.label('found')
    a.emit(0xE3A00000)
    a.branch('done')
    a.label('not_found')
    a.emit(0xE3E00000)
    a.branch('done')
    a.label('fallback')
    a.emit(0xE1A00004)
    a.emit(0xE3A01000)
    a.branch(access_va, link=True)
    a.label('done')
    a.emit(0xE28DD008)
    a.emit(0xE8BD81F0)
    return a.finish()


def build_miyoogamelist_set_cleanup(
        base_va: int, state_va: int, free_va: int,
        original_instruction: int) -> bytes:
    """Free and clear the transient set, then recreate the hooked instruction."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D40F7)             # push {r0-r2,r4-r7,lr}; aligned
    a.ldr_literal(4, state_va)
    a.emit(0xE5940000)
    a.emit(0xE3500000)
    a.branch('recreate', cond=0x0)
    a.emit(0xE3A05000)
    a.emit(0xE5845000)             # clear before free / possible re-entry
    a.branch(free_va, link=True)
    a.label('recreate')
    a.emit(original_instruction)
    a.emit(0xE8BD80F7)
    return a.finish()


def build_game_detail_pixel_wrap_end(
        base_va: int, scratch_va: int, c_str_va: int,
        render_utf8_va: int, free_surface_va: int) -> bytes:
    """Return the next title byte offset in r3 using measured pixel width.

    This helper replaces both stock ``add r3,r3,#15`` instructions inside
    GameDetailWindow's title splitter. It deliberately does not create its own
    frame pointer: r11 therefore remains the caller's frame, giving access to:

      [r11-0x0c] current byte offset
      [r11-0x14] complete UTF-8 byte length
      [r11-0x78] GameDetailWindow ``this`` pointer

    Candidate lines are rendered with TTF_RenderUTF8_Blended using the actual
    detail-title TTF_Font. The temporary SDL_Surface width is compared with
    DETAIL_TITLE_MAX_PIXELS and then freed. Word boundaries are preferred; an
    oversized individual word is split only at complete UTF-8 code points.

    The original instruction changed only r3, so all other caller registers are
    preserved. If font measurement is unavailable, the helper falls back to the
    stock 15-byte step with the stock UTF-8 continuation-byte adjustment.
    """
    a = ArmBuilder(base_va)

    # Preserve every caller-visible register except r3, which is the result.
    # Twelve registers = 48 bytes, retaining the caller's 8-byte stack alignment.
    a.emit(0xE92D57F7)             # push {r0-r2,r4-r10,ip,lr}
    a.emit(0xE51B400C)             # r4 = current byte offset
    a.emit(0xE51B5014)             # r5 = total byte length
    a.emit(0xE1540005)             # cmp r4,r5
    a.branch('return_len', cond=0x2)  # bhs

    a.emit(0xE3A06000)             # r6 = NULL until c_str succeeds
    a.emit(0xE51B0078)             # r0 = this
    a.emit(0xE280000C)             # r0 = &this->title std::string
    a.branch(c_str_va, link=True)
    a.emit(0xE1A06000)             # r6 = title c_str
    a.emit(0xE3560000)             # cmp r6,#0
    a.branch('fallback', cond=0x0)

    a.ldr_literal(10, GAME_DETAIL_TITLE_FONT_GLOBAL)
    a.emit(0xE59AA000)             # r10 = actual detail-title TTF_Font*
    a.emit(0xE35A0000)             # cmp r10,#0
    a.branch('fallback', cond=0x0)
    a.ldr_literal(7, scratch_va)    # r7 = 1 KiB scratch buffer
    a.emit(0xE30013FF)             # movw r1,#1023 usable bytes

    # First pass: grow the candidate by complete words. Each tested candidate
    # starts at r4 and ends at r8. r9 retains the last fitting word boundary.
    a.emit(0xE1A08004)             # r8 = scan offset = start
    a.emit(0xE1A09004)             # r9 = last fit = start
    a.emit(0xE3A02000)             # r2 = scratch byte count
    a.label('word_loop')
    a.emit(0xE1580005)             # cmp r8,r5
    a.branch('measure_word', cond=0x2)  # bhs
    a.emit(0xE1520001)             # cmp r2,r1
    a.branch('word_overflow', cond=0x2) # bhs
    a.emit(0xE7D60008)             # ldrb r0,[r6,r8]
    a.emit(0xE7C70002)             # strb r0,[r7,r2]
    a.emit(0xE2888001)             # add r8,r8,#1
    a.emit(0xE2822001)             # add r2,r2,#1
    a.emit(0xE3500020)             # cmp r0,#' '
    a.branch('measure_word', cond=0x0)
    a.emit(0xE1580005)             # cmp r8,r5
    a.branch('word_loop', cond=0x3) # blo

    a.label('measure_word')
    a.emit(0xE3A00000)             # NUL terminate candidate
    a.emit(0xE7C70002)             # strb r0,[r7,r2]
    a.branch('measure', link=True)
    a.emit(0xE3700001)             # cmn r0,#1 (measurement failure?)
    a.branch('fallback', cond=0x0)
    a.emit(arm_movw(3, DETAIL_TITLE_MAX_PIXELS))
    a.emit(0xE1500003)             # cmp measured width,r3
    a.branch('word_too_wide', cond=0x8) # bhi
    a.emit(0xE1A09008)             # last fit = scan offset
    a.emit(0xE1580005)             # cmp scan,len
    a.branch('return_r9', cond=0x2) # bhs
    a.branch('word_loop')

    a.label('word_overflow')
    a.emit(0xE1590004)             # cmp last fit,start
    a.branch('return_r9', cond=0x8) # bhi
    a.branch('char_init')

    a.label('word_too_wide')
    a.emit(0xE1590004)             # cmp last fit,start
    a.branch('return_r9', cond=0x8) # previous complete word fits

    # The first word itself exceeds the pixel limit. Rebuild from the start and
    # test after every complete UTF-8 code point, never in a continuation byte.
    a.label('char_init')
    a.emit(0xE1A08004)             # scan = start
    a.emit(0xE1A09004)             # last fit = start
    a.emit(0xE3A02000)             # scratch length = 0
    a.label('char_loop')
    a.emit(0xE1580005)             # cmp scan,len
    a.branch('return_r9', cond=0x2)
    a.emit(0xE1520001)             # cmp scratch length,1023
    a.branch('char_buffer_full', cond=0x2)

    # Copy the first byte of one code point.
    a.emit(0xE7D60008)             # ldrb r0,[r6,r8]
    a.emit(0xE1A03000)             # remember first byte across measurement
    a.emit(0xE7C70002)             # strb r0,[r7,r2]
    a.emit(0xE2888001)             # scan++
    a.emit(0xE2822001)             # scratch length++

    # Copy any UTF-8 continuation bytes belonging to that code point.
    a.label('continuation_check')
    a.emit(0xE1580005)             # cmp scan,len
    a.branch('measure_char', cond=0x2)
    a.emit(0xE7D60008)             # next byte
    a.emit(0xE200C0C0)             # and ip,r0,#0xc0; preserve first byte in r3
    a.emit(0xE35C0080)             # cmp ip,#0x80
    a.branch('measure_char', cond=0x1) # bne
    a.emit(0xE1520001)             # buffer full before continuation?
    a.branch('measure_char', cond=0x2)
    a.emit(0xE7C70002)             # copy continuation byte
    a.emit(0xE2888001)
    a.emit(0xE2822001)
    a.branch('continuation_check')

    a.label('measure_char')
    a.emit(0xE3A00000)
    a.emit(0xE7C70002)             # NUL terminate
    a.branch('measure', link=True)
    a.emit(0xE3700001)
    a.branch('fallback', cond=0x0)
    a.emit(arm_movw(3, DETAIL_TITLE_MAX_PIXELS))
    a.emit(0xE1500003)
    a.branch('char_too_wide', cond=0x8)
    a.emit(0xE1A09008)             # this code point fits
    a.emit(0xE1580005)
    a.branch('return_r9', cond=0x2)
    a.branch('char_loop')

    a.label('char_buffer_full')
    a.emit(0xE1590004)
    a.branch('return_r9', cond=0x8)
    a.branch('fallback')

    a.label('char_too_wide')
    # A trailing space is visually harmless. If adding only that space crossed
    # the limit, consume it with the previous line so the next line does not
    # begin with a blank character.
    a.emit(0xE3530020)             # cmp first byte,#' '
    a.emit(0x01A09008)             # moveq last fit,scan (after the space)
    a.branch('return_r9', cond=0x0)
    a.emit(0xE1590004)             # did an earlier code point fit?
    a.branch('return_r9', cond=0x8)
    a.emit(0xE1A09008)             # force progress by one full code point

    a.label('return_r9')
    a.emit(0xE1A03009)             # r3 = chosen next byte offset
    a.branch('done')

    a.label('return_len')
    a.emit(0xE1A03005)
    a.branch('done')

    # Conservative failure path: reproduce the stock 15-byte advance and move
    # forward until the result no longer points inside a UTF-8 continuation.
    a.label('fallback')
    a.emit(0xE284300F)             # r3 = start+15
    a.emit(0xE1530005)             # cmp r3,len
    a.emit(0x81A03005)             # movhi r3,len
    a.emit(0xE3560000)             # source available?
    a.branch('done', cond=0x0)
    a.label('fallback_utf8')
    a.emit(0xE1530005)
    a.branch('done', cond=0x2)
    a.emit(0xE7D60003)             # ldrb r0,[r6,r3]
    a.emit(0xE20000C0)             # and r0,r0,#0xc0
    a.emit(0xE3500080)
    a.branch('done', cond=0x1)
    a.emit(0xE2833001)
    a.branch('fallback_utf8')

    a.label('done')
    a.emit(0xE8BD97F7)             # pop {...,pc}; r3 survives

    # Local width-measurement subroutine. SDL_ttf does not expose TTF_SizeUTF8
    # through this binary's PLT, so render the short candidate with the same
    # UTF-8 renderer used by MainUI, read surface.w, and immediately free it.
    a.label('measure')
    a.emit(0xE92D403E)             # push {r1-r5,lr}; 24 bytes, aligned
    a.emit(0xE1A0000A)             # r0 = title font
    a.emit(0xE1A01007)             # r1 = UTF-8 candidate
    a.ldr_literal(3, GAME_DETAIL_TEXT_COLOR_GLOBAL)
    a.emit(0xE5932000)             # r2 = SDL_Color value
    a.branch(render_utf8_va, link=True)
    a.emit(0xE1A04000)             # r4 = temporary SDL_Surface*
    a.emit(0xE3540000)
    a.branch('measure_fail', cond=0x0)
    a.emit(0xE5945008)             # r5 = surface->w
    a.emit(0xE1A00004)
    a.branch(free_surface_va, link=True)
    a.emit(0xE1A00005)             # return measured width
    a.emit(0xE8BD803E)             # pop {r1-r5,pc}
    a.label('measure_fail')
    a.emit(0xE3E00000)             # return UINT_MAX failure marker
    a.emit(0xE8BD803E)
    return a.finish()


def build_game_detail_system_name_draw_wrapper(
        base_va: int, original_draw_va: int, c_str_va: int,
        strlen_va: int, memcpy_va: int) -> bytes:
    """Call stock detail draw, then render a trimmed this+0x24 label.

    Only leading and trailing ASCII space bytes are removed. The original
    std::string is never modified: labels shorter than 1024 bytes are copied
    into a stack scratch buffer and NUL-terminated before the existing
    left-aligned x=274,y=98,w=360,h=30 draw. Unusually large labels keep their
    leading-space adjustment but otherwise fall back to the original storage.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}; aligned
    a.emit(0xE24DDB01)             # sub sp,sp,#1024 scratch
    a.emit(0xE1A04000)             # r4 = this
    a.emit(0xE1A05001)             # r5 = destination SDL_Surface
    a.branch(original_draw_va, link=True)
    a.emit(0xE1A06000)             # preserve stock return value

    a.emit(0xE2840024)             # r0 = &this->systemLabel (std::string)
    a.branch(c_str_va, link=True)
    a.emit(0xE3500000)             # null pointer?
    a.branch('done', cond=0x0)
    a.emit(0xE1A07000)             # r7 = original text pointer
    a.emit(0xE5D73000)             # empty string?
    a.emit(0xE3530000)
    a.branch('done', cond=0x0)
    a.emit(0xE1A00007)             # strlen(text)
    a.branch(strlen_va, link=True)
    a.emit(0xE1A08000)             # r8 = byte length
    a.emit(0xE3580000)
    a.branch('done', cond=0x0)

    a.label('trim_leading')
    a.emit(0xE5D73000)             # byte = *r7
    a.emit(0xE3530020)             # ASCII space only
    a.branch('trim_trailing', cond=0x1)
    a.emit(0xE2877001)             # r7++
    a.emit(0xE2588001)             # --r8
    a.branch('done', cond=0x0)
    a.branch('trim_leading')

    a.label('trim_trailing')
    a.emit(0xE2482001)             # r2 = r8 - 1
    a.emit(0xE7D73002)             # byte = r7[r2]
    a.emit(0xE3530020)             # ASCII space only
    a.branch('prepare_text', cond=0x1)
    a.emit(0xE2588001)             # --r8
    a.branch('done', cond=0x0)
    a.branch('trim_trailing')

    a.label('prepare_text')
    a.emit(0xE3580B01)             # cmp r8,#1024
    a.branch('draw_text', cond=0x2) # bhs: implausibly long; use existing pointer
    a.emit(0xE1A0000D)             # r0 = scratch
    a.emit(0xE1A01007)             # r1 = trimmed start
    a.emit(0xE1A02008)             # r2 = trimmed length
    a.branch(memcpy_va, link=True)
    a.emit(0xE3A03000)
    a.emit(0xE7CD3008)             # scratch[r8] = NUL
    a.emit(0xE1A0700D)             # r7 = scratch

    a.label('draw_text')
    a.emit(0xE24DD010)             # 16 bytes for stack arguments
    a.emit(0xE58D7000)             # trimmed text pointer
    a.ldr_literal(3, GAME_DETAIL_SYSTEM_FONT_GLOBAL)
    a.emit(0xE5931000)             # r1 = TTF_Font*
    a.emit(0xE3510000)
    a.branch('cleanup_args', cond=0x0)
    a.ldr_literal(3, GAME_DETAIL_TEXT_COLOR_GLOBAL)
    a.emit(0xE5932000)
    a.emit(0xE58D2004)             # text color
    a.emit(0xE3A02000)
    a.emit(0xE58D2008)
    a.emit(0xE58D200C)
    a.emit(0xE1A00005)             # r0 = destination surface
    a.ldr_literal(2, 0x00620112)   # SDL_Rect {x=274,y=98,...}
    a.ldr_literal(3, 0x001E0168)   # SDL_Rect {...,w=360,h=30}
    a.branch(GAME_DETAIL_DRAW_TEXT_VA, link=True)
    a.label('cleanup_args')
    a.emit(0xE28DD010)
    a.label('done')
    a.emit(0xE28DDB01)             # add sp,sp,#1024
    a.emit(0xE1A00006)
    a.emit(0xE8BD81F0)             # pop {r4-r8,pc}
    return a.finish()


def build_key_repeat_wrapper(base_va: int, path_va: int,
                             open_va: int, read_va: int, close_va: int,
                             atoi_va: int,
                             sdl_enable_key_repeat_va: int) -> bytes:
    """Read and apply MainUI SDL key-repeat timing once during startup.

    The compact parser accepts the documented ``DELAY INTERVAL`` and
    ``DELAY,INTERVAL`` forms without leading whitespace. Missing or unreadable
    files and non-positive parsed values retain the default 500/100 values.
    Valid values are clamped to
    delay 100..2000 ms and interval 30..500 ms.

    The path is placed immediately after this helper. An ARM ``ADR``-style
    PC-relative add avoids a separate literal-pool word, to avoid filling 
    MainUI's executable/file gap.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}; 24 bytes
    a.emit(0xE24DD020)             # sub sp,sp,#32; total stack use stays aligned
    a.emit(0xE3A04F7D)             # mov r4,#500 stock/default delay
    a.emit(0xE3A05064)             # mov r5,#100 stock/default interval
    a.emit(0xE3A08000)             # mov r8,#0; O_RDONLY and NUL byte

    # The key-repeat path is allocated directly after this fixed-size helper.
    path_delta = path_va - (a.va + 8)
    if not 0 <= path_delta <= 0xFF:
        raise ValueError('key-repeat config path is outside compact ADR range')
    a.emit(0xE28F0000 | path_delta)  # add r0,pc,#path_delta
    a.emit(0xE1A01008)             # mov r1,r8 (O_RDONLY)
    a.branch(open_va, link=True)
    a.emit(0xE1A07000)             # mov r7,r0 fd
    a.emit(0xE3570000)             # cmp r7,#0
    a.branch('apply', cond=0xB)    # blt apply defaults

    a.emit(0xE1A00007)             # mov r0,r7
    a.emit(0xE1A0100D)             # mov r1,sp buffer
    a.emit(0xE3A0201F)             # mov r2,#31
    a.branch(read_va, link=True)
    a.emit(0xE1A06000)             # mov r6,r0 byte count
    a.emit(0xE1A00007)             # mov r0,r7
    a.branch(close_va, link=True)
    a.emit(0xE3560000)             # cmp r6,#0
    a.branch('apply', cond=0xD)    # ble apply defaults
    a.emit(0xE7CD8006)             # strb r8,[sp,r6] NUL terminate

    # Parse the first positive integer. atoi handles normal decimal text; the
    # delimiter scan below verifies that a second field is present.
    a.emit(0xE1A0600D)             # mov r6,sp cursor
    a.emit(0xE1A00006)             # mov r0,r6
    a.branch(atoi_va, link=True)
    a.emit(0xE1A07000)             # mov r7,r0 parsed delay

    a.label('scan_separator')
    a.emit(0xE4D68001)             # ldrb r8,[r6],#1
    a.emit(0xE3580000)             # cmp r8,#0
    a.branch('apply', cond=0x0)    # no delimiter -> defaults
    a.emit(0xE358002C)             # cmp r8,#','
    a.branch('parse_second', cond=0x0)
    a.emit(0xE3580020)             # cmp r8,#' '
    a.branch('scan_separator', cond=0x1)

    a.label('parse_second')
    a.emit(0xE1A00006)             # mov r0,r6; atoi accepts extra spaces
    a.branch(atoi_va, link=True)
    a.emit(0xE3570000)             # cmp r7,#0
    a.emit(0xC3500000)             # cmpgt r0,#0
    a.branch('apply', cond=0xD)    # either non-positive -> defaults
    a.emit(0xE1A04007)             # mov r4,r7 delay
    a.emit(0xE1A05000)             # mov r5,r0 interval

    # Conservative clamping. 500 and 2000 are ARM rotated immediates, so no
    # MOVW scratch-register pair is required.
    a.emit(0xE3540064)             # cmp r4,#100
    a.emit(0xB3A04064)             # movlt r4,#100
    a.emit(0xE3540E7D)             # cmp r4,#2000
    a.emit(0xC3A04E7D)             # movgt r4,#2000
    a.emit(0xE355001E)             # cmp r5,#30
    a.emit(0xB3A0501E)             # movlt r5,#30
    a.emit(0xE3550F7D)             # cmp r5,#500
    a.emit(0xC3A05F7D)             # movgt r5,#500

    a.label('apply')
    a.emit(0xE1A00004)             # mov r0,r4 delay
    a.emit(0xE1A01005)             # mov r1,r5 interval
    a.branch(sdl_enable_key_repeat_va, link=True)
    a.emit(0xE28DD020)             # add sp,sp,#32
    a.emit(0xE8BD81F0)             # pop {r4-r8,pc}; preserve SDL return in r0
    return a.finish()

def build_direct_touch_helper(base_va: int, open_va: int,
                              close_va: int) -> bytes:
    """Create/truncate nothing: stock touch semantics via open(O_CREAT|O_WRONLY)."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D4010)             # push {r4,lr}; aligned
    a.emit(0xE3A01041)             # r1 = O_WRONLY|O_CREAT
    a.emit(arm_movw(2, 0x01B6))    # r2 = 0666
    a.branch(open_va, link=True)
    a.emit(0xE3500000)             # cmp r0,#0
    a.branch('done', cond=0xB)     # blt done
    a.branch(close_va, link=True)
    a.label('done')
    a.emit(0xE8BD8010)             # pop {r4,pc}
    return a.finish()


def build_direct_governor_write_helper(base_va: int, open_va: int,
                                       write_va: int, close_va: int,
                                       value_va: int) -> bytes:
    """Write the stock governor token directly to the sysfs file in r0."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D4030)             # push {r4,r5,lr}; 12-byte frame
    a.emit(0xE24DD004)             # align stack to 16 bytes
    a.emit(0xE3A01001)             # r1 = O_WRONLY
    a.branch(open_va, link=True)
    a.emit(0xE1A04000)             # r4 = fd
    a.emit(0xE3500000)
    a.branch('done', cond=0xB)
    a.ldr_literal(1, value_va)
    a.emit(0xE3A02009)             # len("ondemand\n")
    a.emit(0xE1A00004)
    a.branch(write_va, link=True)
    a.emit(0xE1A00004)
    a.branch(close_va, link=True)
    a.label('done')
    a.emit(0xE28DD004)
    a.emit(0xE8BD8030)             # pop {r4,r5,pc}
    return a.finish()


def build_rom_artwork_root_imgs_skip(base_va: int, *,
                                     recursion_flag_word: int,
                                     dentry_load_word: int,
                                     stock_word: int,
                                     skip_va: int) -> bytes:
    """Skip a root-level directory named exactly ``Imgs`` before recursion.

    The two rebuild walks use different frame layouts, so their guarded helper
    instances supply only the stock frame-load instructions.  r0-r2 and LR are
    preserved; r3 is the only register the overwritten stock instruction itself
    changes.  Non-matches therefore return with the exact original instruction
    recreated, while a match restores registers and jumps to that walk's own
    next-entry continuation.
    """
    a = ArmBuilder(base_va)
    a.emit(0xE92D4007)             # push {r0-r2,lr}
    a.emit(recursion_flag_word)    # r3 = root/recursive flag
    a.emit(0xE3530000)
    a.branch('stock', cond=0x1)    # recursive child: never suppress by name
    a.emit(dentry_load_word)       # r3 = struct dirent *
    a.emit(0xE283300B)             # d_name
    for off, ch in enumerate(b'Imgs\0'):
        a.emit(0xE5D30000 | off)    # ldrb r0,[r3,#off]
        a.emit(0xE3500000 | ch)
        a.branch('stock', cond=0x1)
    a.emit(0xE8BD4007)             # pop {r0-r2,lr}
    a.branch(skip_va)
    a.label('stock')
    a.emit(0xE8BD4007)
    a.emit(stock_word)             # recreate overwritten stock instruction
    a.emit(0xE12FFF1E)             # bx lr
    return a.finish()

def build_background_poll_wrapper(base_va: int, state_va: int,
                                  battery_va: int, wifi_va: int) -> bytes:
    """Run the stock battery and Wi-Fi probes once per five one-second ticks."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D4010)             # push {r4,lr}; aligned
    a.ldr_literal(4, state_va)
    a.emit(0xE5943000)             # ldr r3,[r4]
    a.emit(0xE3530000)             # cmp r3,#0
    a.branch('advance', cond=0x1)  # bne advance
    a.branch(battery_va, link=True)
    a.branch(wifi_va, link=True)
    a.emit(0xE3A03000)             # stock calls may clobber r3
    a.label('advance')
    a.emit(0xE2833001)             # add r3,r3,#1
    a.emit(0xE3530005)             # cmp r3,#5
    a.emit(0xA3A03000)             # movge r3,#0
    a.emit(0xE5843000)             # str r3,[r4]
    a.emit(0xE8BD8010)             # pop {r4,pc}
    return a.finish()


def build_wifi_state_one_pass(base_va: int, wifi_enabled_va: int,
                               opendir_va: int, readdir_va: int,
                               closedir_va: int, snprintf_va: int,
                               open_va: int, read_va: int, close_va: int,
                               strstr_va: int, proc_path_va: int,
                               cmdline_format_va: int, wpa_name_va: int,
                               hostapd_name_va: int) -> bytes:
    """Return 1/2/3 using one /proc walk, or no walk when Wi-Fi is disabled."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}; aligned
    a.emit(0xE24DDC01)             # sub sp,sp,#256
    a.emit(0xE1A0800D)             # r8=cmdline buffer
    a.emit(0xE3A05001)             # default disabled/not-running state
    a.branch(wifi_enabled_va, link=True)
    a.emit(0xE3500000)
    a.branch('done', cond=0x0)
    a.ldr_literal(0, proc_path_va)
    a.branch(opendir_va, link=True)
    a.emit(0xE1A04000)             # r4=DIR*
    a.emit(0xE3540000)
    a.branch('done', cond=0x0)

    a.label('loop')
    a.emit(0xE1A00004)
    a.branch(readdir_va, link=True)
    a.emit(0xE1A06000)             # r6=dirent*
    a.emit(0xE3560000)
    a.branch('close_done', cond=0x0)
    a.emit(0xE286300B)             # stock ARM dirent d_name offset is 11
    a.emit(0xE5D32000)
    a.emit(0xE3520030)
    a.branch('loop', cond=0x3)      # blo
    a.emit(0xE3520039)
    a.branch('loop', cond=0x8)      # bhi
    a.emit(0xE1A00008)
    a.emit(0xE3A01C01)             # 256
    a.ldr_literal(2, cmdline_format_va)
    # r3 still points to d_name.
    a.branch(snprintf_va, link=True)
    a.emit(0xE1A00008)
    a.emit(0xE3A01000)
    a.branch(open_va, link=True)
    a.emit(0xE1A07000)             # r7=fd
    a.emit(0xE3570000)
    a.branch('loop', cond=0xB)      # blt
    a.emit(0xE1A00007)
    a.emit(0xE1A01008)
    a.emit(0xE3A020FF)
    a.branch(read_va, link=True)
    a.emit(0xE1A06000)             # r6=read length
    a.emit(0xE1A00007)
    a.branch(close_va, link=True)
    a.emit(0xE3560000)
    a.branch('loop', cond=0xD)      # ble
    a.emit(0xE3A03000)
    a.emit(0xE7C83006)             # strb r3,[r8,r6]
    a.emit(0xE1A00008)
    a.ldr_literal(1, wpa_name_va)
    a.branch(strstr_va, link=True)
    a.emit(0xE3500000)
    a.branch('check_hostapd', cond=0x0)
    a.emit(0xE3A05002)
    a.branch('close_done')
    a.label('check_hostapd')
    a.emit(0xE1A00008)
    a.ldr_literal(1, hostapd_name_va)
    a.branch(strstr_va, link=True)
    a.emit(0xE3500000)
    a.branch('loop', cond=0x0)
    a.emit(0xE3A05003)

    a.label('close_done')
    a.emit(0xE1A00004)
    a.branch(closedir_va, link=True)
    a.label('done')
    a.emit(0xE1A00005)
    a.emit(0xE28DDC01)             # add sp,sp,#256
    a.emit(0xE8BD81F0)
    return a.finish()

def build_governor_write_value_helper(base_va: int, path_va: int,
                                      open_va: int, write_va: int,
                                      close_va: int) -> bytes:
    """Write r0/r1 bytes to the governor path; return one only on full write."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D4070)             # push {r4-r6,lr}; aligned
    a.emit(0xE1A04000)             # r4=value
    a.emit(0xE1A05001)             # r5=len
    a.ldr_literal(0, path_va)
    a.emit(0xE3A01001)             # O_WRONLY
    a.branch(open_va, link=True)
    a.emit(0xE1A06000)             # r6=fd
    a.emit(0xE3560000)
    a.branch('fail', cond=0xB)     # blt fail
    a.emit(0xE1A00006)
    a.emit(0xE1A01004)
    a.emit(0xE1A02005)
    a.branch(write_va, link=True)
    a.emit(0xE1A04000)             # r4=written
    a.emit(0xE1A00006)
    a.branch(close_va, link=True)
    a.emit(0xE1540005)             # cmp r4,r5
    a.emit(0x03A00001)             # moveq r0,#1
    a.emit(0x13A00000)             # movne r0,#0
    a.emit(0xE8BD8070)
    a.label('fail')
    a.emit(0xE3A00000)
    a.emit(0xE8BD8070)
    return a.finish()


def build_burst_governor_acquire(base_va: int, state_va: int,
                                 marker_path_va: int, performance_va: int,
                                 fallback_va: int, governor_path_va: int,
                                 write_helper_va: int, open_va: int, read_va: int, write_va: int,
                                 close_va: int, unlink_va: int) -> bytes:
    """Nested acquire with saved-token marker for process-spanning launch handoff."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)             # push {r4-r8,lr}; aligned
    a.ldr_literal(4, state_va)
    a.emit(0xE5945000)             # refcount
    a.emit(0xE3550000)
    a.branch('first', cond=0x0)
    a.emit(0xE2855001)
    a.emit(0xE5845000)
    a.emit(0xE5940018)             # return marker_ready
    a.emit(0xE8BD81F0)

    a.label('first')
    a.emit(0xE3A08000)             # ready=0
    a.emit(0xE5848004)             # saved_len=0 temporarily
    a.emit(0xE5848018)             # marker_ready=0

    # Prefer an existing handoff marker from a previous MainUI process.
    a.ldr_literal(0, marker_path_va)
    a.emit(0xE3A01000)             # O_RDONLY
    a.branch(open_va, link=True)
    a.emit(0xE1A06000)
    a.emit(0xE3560000)
    a.branch('read_current', cond=0xB)
    a.emit(0xE1A00006)
    a.emit(0xE2841008)
    a.emit(0xE3A0200F)
    a.branch(read_va, link=True)
    a.emit(0xE1A05000)
    a.emit(0xE1A00006)
    a.branch(close_va, link=True)
    a.emit(0xE3550000)
    a.branch('read_current', cond=0xD)  # ble
    a.emit(0xE355000F)
    a.emit(0xC3A0500F)             # movgt r5,#15
    a.emit(0xE3A08001)
    a.branch('activate')

    # No valid marker: save the currently active governor token.
    a.label('read_current')
    a.ldr_literal(0, governor_path_va)
    a.emit(0xE3A01000)
    a.branch(open_va, link=True)
    a.emit(0xE1A06000)
    a.emit(0xE3560000)
    a.branch('fallback', cond=0xB)
    a.emit(0xE1A00006)
    a.emit(0xE2841008)
    a.emit(0xE3A0200F)
    a.branch(read_va, link=True)
    a.emit(0xE1A05000)
    a.emit(0xE1A00006)
    a.branch(close_va, link=True)
    a.emit(0xE3550000)
    a.branch('fallback', cond=0xD)
    a.emit(0xE355000F)
    a.emit(0xC3A0500F)
    a.branch('create_marker')

    a.label('fallback')
    a.ldr_literal(6, fallback_va)
    a.emit(0xE5967000)
    a.emit(0xE5847008)
    a.emit(0xE5967004)
    a.emit(0xE584700C)
    a.emit(0xE5D67008)
    a.emit(0xE5C47010)
    a.emit(0xE3A05009)

    a.label('create_marker')
    a.ldr_literal(0, marker_path_va)
    a.emit(arm_movw(1, 0x0241))    # O_WRONLY|O_CREAT|O_TRUNC
    a.emit(arm_movw(2, 0x01B6))    # 0666
    a.branch(open_va, link=True)
    a.emit(0xE1A06000)
    a.emit(0xE3560000)
    a.branch('activate', cond=0xB)
    a.emit(0xE1A00006)
    a.emit(0xE2841008)
    a.emit(0xE1A02005)
    a.branch(write_va, link=True)
    a.emit(0xE1A07000)
    a.emit(0xE1A00006)
    a.branch(close_va, link=True)
    a.emit(0xE1570005)
    a.branch('bad_marker', cond=0x1)
    a.emit(0xE3A08001)
    a.branch('activate')
    a.label('bad_marker')
    a.ldr_literal(0, marker_path_va)
    a.branch(unlink_va, link=True)

    a.label('activate')
    a.emit(0xE5845004)             # saved_len
    a.emit(0xE5848018)             # marker_ready
    a.emit(0xE3A05001)
    a.emit(0xE5845000)             # refcount=1
    a.ldr_literal(0, performance_va)
    a.emit(0xE3A0100C)             # len("performance\\n")
    a.branch(write_helper_va, link=True)
    a.emit(0xE0000008)             # and r0,r0,r8
    a.emit(0xE8BD81F0)
    return a.finish()


def build_burst_governor_release(base_va: int, state_va: int,
                                 marker_path_va: int, fallback_va: int,
                                 write_helper_va: int, unlink_va: int) -> bytes:
    """Nested release; restore the saved token and remove the handoff marker."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D41F0)
    a.ldr_literal(4, state_va)
    a.emit(0xE5945000)
    a.emit(0xE3550000)
    a.branch('done', cond=0xD)
    a.emit(0xE2455001)
    a.emit(0xE5845000)
    a.emit(0xE3550000)
    a.branch('done', cond=0x1)
    a.emit(0xE5945004)
    a.emit(0xE3550000)
    a.branch('fallback', cond=0xD)
    a.emit(0xE355000F)
    a.branch('fallback', cond=0xC)
    a.emit(0xE2840008)
    a.emit(0xE1A01005)
    a.branch(write_helper_va, link=True)
    a.branch('restore_done')
    a.label('fallback')
    a.ldr_literal(0, fallback_va)
    a.emit(0xE3A01009)
    a.branch(write_helper_va, link=True)
    a.label('restore_done')
    a.emit(0xE3500000)
    a.branch('clear', cond=0x0)     # retain marker for next-start retry
    a.ldr_literal(0, marker_path_va)
    a.branch(unlink_va, link=True)
    a.label('clear')
    a.emit(0xE3A03000)
    a.emit(0xE5843004)
    a.emit(0xE5843018)
    a.label('done')
    a.emit(0xE8BD81F0)
    return a.finish()


def build_call_preserving_wrapper(base_va: int, helper_va: int,
                                  target_va: int, *, release_on_zero: int | None = None) -> bytes:
    """Call helper while preserving r0-r3/r12, then tail-call target."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D500F)             # push {r0-r3,r12,lr}; aligned
    a.branch(helper_va, link=True)
    if release_on_zero is not None:
        a.emit(0xE3500000)
        a.branch('ready', cond=0x1)
        a.branch(release_on_zero, link=True)
        a.label('ready')
    a.emit(0xE8BD500F)
    a.branch(target_va)
    return a.finish()


def build_call_preserving_skip_wrapper(base_va: int, helper_va: int,
                                       *, release_on_zero: int | None = None) -> bytes:
    """Call helper while preserving the caller ABI, then return success."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D500F)             # push {r0-r3,r12,lr}; aligned
    a.branch(helper_va, link=True)
    if release_on_zero is not None:
        a.emit(0xE3500000)
        a.branch('ready', cond=0x1)
        a.branch(release_on_zero, link=True)
        a.label('ready')
    a.emit(0xE8BD500F)
    a.emit(0xE3A00001)             # mov r0,#1
    a.emit(0xE12FFF1E)             # bx lr
    return a.finish()


def build_burst_entry_trampoline(base_va: int, acquire_va: int,
                                 original_entry_va: int,
                                 original_prologue_word: int) -> bytes:
    a = ArmBuilder(base_va)
    a.emit(0xE92D500F)
    a.branch(acquire_va, link=True)
    a.emit(0xE8BD500F)
    a.emit(original_prologue_word)
    a.branch(original_entry_va + 4)
    return a.finish()


def build_release_result_r3_wrapper(base_va: int, release_va: int) -> bytes:
    a = ArmBuilder(base_va)
    a.emit(0xE92D4008)             # push {r3,lr}
    a.branch(release_va, link=True)
    a.emit(0xE8BD4008)
    a.emit(0xE1A00003)             # mov r0,r3
    a.emit(0xE12FFF1E)
    return a.finish()

def expect_c_string_at_va(data: bytes, segs: list[Segment], va: int,
                          expected: bytes, label: str) -> None:
    off = va2off(segs, va)
    if data[off:off + len(expected)] != expected:
        raise ValueError(f'{label} command string changed at {va:#x}')


def rewrite_r0_literal_call(d: bytearray, raw: bytes, segs: list[Segment],
                            call_va: int, old_string_va: int,
                            old_target_va: int, new_string_va: int,
                            new_target_va: int) -> None:
    call_off = va2off(segs, call_va, executable=True)
    expected = (
        arm_movw(0, old_string_va & 0xffff),
        arm_movt(0, old_string_va >> 16),
    )
    if tuple(read_word(raw, call_off - 8 + 4 * i) for i in range(2)) != expected:
        raise ValueError(f'command pointer setup changed at {call_va:#x}')
    if decode_arm_branch_target(read_word(raw, call_off), call_va) != old_target_va:
        raise ValueError(f'command call target changed at {call_va:#x}')
    if d[call_off - 8:call_off + 4] != raw[call_off - 8:call_off + 4]:
        raise ValueError(f'command call site already modified at {call_va:#x}')
    write_word(d, call_off - 8, arm_movw(0, new_string_va & 0xffff))
    write_word(d, call_off - 4, arm_movt(0, new_string_va >> 16))
    write_word(d, call_off, branch_word(call_va, new_target_va, link=True))


def update_segment_sizes(d: bytearray, seg: Segment, file_size: int | None = None,
                         mem_size: int | None = None) -> None:
    if file_size is not None:
        struct.pack_into('<I', d, seg.ph_file_off + 16, file_size)
    if mem_size is not None:
        struct.pack_into('<I', d, seg.ph_file_off + 20, mem_size)



def verify_main_menu_layout_hooks(data: bytes | bytearray,
                                  segs: list[Segment]) -> dict[str, int]:
    expected_words = {
        FAVOURITE_CREATE_MENU_VA: FAVOURITE_CREATE_MENU_PROLOGUE,
        MAIN_MENU_GET_ACTION_HOOK_VA: 0xE3A00000,
        MAIN_MENU_FINAL_ACTION_HOOK_VA: 0xE1A00003,
        MAIN_MENU_CONTEXT_HOOK_VA: 0xE51B30D8,
        MAIN_MENU_CONTEXT_HOOK_VA + 4: 0xE5933008,
        MAIN_MENU_CONTEXT_HOOK_VA + 8: 0xE3530000,
        MAIN_MENU_CONTEXT_HOOK_VA + 12: 0x0A000007,
        MAIN_MENU_POPUP_VISIBLE_COUNT_HOOK_VA: MAIN_MENU_POPUP_VISIBLE_COUNT_WORDS[0],
        MAIN_MENU_POPUP_VISIBLE_COUNT_HOOK_VA + 4: MAIN_MENU_POPUP_VISIBLE_COUNT_WORDS[1],
        MAIN_MENU_POPUP_VISIBLE_COUNT_HOOK_VA + 8: MAIN_MENU_POPUP_VISIBLE_COUNT_WORDS[2],
    }
    for va, expected in expected_words.items():
        off = va2off(segs, va, executable=True)
        actual = read_word(data, off)
        if actual != expected:
            raise ValueError(
                f'main-menu hook changed at {va:#x}: '
                f'{actual:#010x}, expected {expected:#010x}')
    call_off = va2off(segs, MAIN_MENU_GET_ACTION_CALL_VA, executable=True)
    if decode_arm_branch_target(
            read_word(data, call_off), MAIN_MENU_GET_ACTION_CALL_VA) != 0x00017744:
        raise ValueError('main-menu input translator call target changed')
    branch_off = va2off(segs, MAIN_MENU_CONTEXT_HOOK_VA + 12, executable=True)
    if decode_arm_branch_target(
            read_word(data, branch_off), MAIN_MENU_CONTEXT_HOOK_VA + 12) != 0x00030630:
        raise ValueError('main-menu stock context type branch changed')
    popup_call_off = va2off(
        segs, MAIN_MENU_POPUP_IMAGE_LOAD_CALL_VA, executable=True)
    if tuple(read_word(data, popup_call_off - 12 + 4 * i) for i in range(3)) != (
            MAIN_MENU_POPUP_IMAGE_LOAD_PRELUDE):
        raise ValueError('shared PopupWindow image-loader prelude changed')
    if decode_arm_branch_target(
            read_word(data, popup_call_off),
            MAIN_MENU_POPUP_IMAGE_LOAD_CALL_VA) != MAIN_MENU_POPUP_IMAGE_LOAD_TARGET_VA:
        raise ValueError('shared PopupWindow image-loader target changed')
    for path_va, expected_path in MAIN_MENU_STOCK_POPUP_PATHS:
        path_off = va2off(segs, path_va)
        if bytes(data[path_off:path_off + len(expected_path)]) != expected_path:
            raise ValueError(
                f'stock numbered popup path changed at {path_va:#x}')
    vtable_off = va2off(segs, MAIN_MENU_CLEAR_ACTION_VTABLE_VA)
    expected_vtable = (
        0x00000000, 0x0001543B8, 0x00039F20, 0x00039F5C,
        0x00019FD8, 0x000397FC, 0x00039828,
    )
    actual_vtable = struct.unpack_from('<7I', data, vtable_off)
    if actual_vtable != expected_vtable:
        raise ValueError('main-menu source action vtable layout changed')
    # Guard the constructor and collection ABIs used by the replacement builder.
    call_targets = {
        0x000377B8: 0x0001591C,
        0x000377F4: 0x00025C8C,
        0x00037874: 0x000256F0,
        0x00037880: 0x00027A30,
        0x00030634: 0x0001591C,
        0x00030658: 0x00020500,
        0x00030684: 0x00039BAC,
        0x000306A8: 0x0003A5A8,
        0x000306E4: 0x00025510,
        0x000306F0: 0x00020898,
        0x00030700: 0x0003A6A8,
        0x00030728: 0x0003225C,
        0x000322C4: 0x00123AF0,
        0x00032450: 0x0001D99C,
    }
    for va, expected in call_targets.items():
        off = va2off(segs, va, executable=True)
        if decode_arm_branch_target(read_word(data, off), va) != expected:
            raise ValueError(f'main-menu stock call target changed at {va:#x}')
    # The numbered-popup existence probe depends on the exact active-theme
    # prefix global already consumed by stock PopupWindow construction.
    popup_theme_words = {
        0x00032294: 0xE3013970,
        0x00032298: 0xE3403018,
        0x0003229C: 0xE5930000,
    }
    for va, expected in popup_theme_words.items():
        if read_word(data, va2off(segs, va, executable=True)) != expected:
            raise ValueError(
                f'popup active-theme prefix provenance changed at {va:#x}')

    for va in MAIN_MENU_DRAW_CALL_VAS:
        off = va2off(segs, va, executable=True)
        if decode_arm_branch_target(read_word(data, off), va) != MAIN_MENU_DRAW_TEXT_VA:
            raise ValueError(f'main-menu label draw call changed at {va:#x}')
    for va, expected in ((MAIN_MENU_WINDOW_DRAW_VA, MAIN_MENU_WINDOW_DRAW_STOCK_PROLOGUE),
                         (0x000258D4, 0xE92D4800),
                         (0x0002E978, 0xE92D4800),
                         (0x0003984C, 0xE92D4800),
                         (0x0003A32C, 0xE92D4800),
                         (0x0013EDFC, 0xE92D4800),
                         (0x00027014, 0xE92D4810),
                         (0x000193A8, 0xE92D4830),
                         (0x0003A678, 0xE52DB004),
                         (0x0001D99C, 0xE52DB004)):
        if read_word(data, va2off(segs, va, executable=True)) != expected:
            raise ValueError(f'main-menu required helper changed at {va:#x}')

    for va, target in ((MAIN_MENU_EXPERT_CTOR_CALL_VA,
                        MAIN_MENU_EXPERT_CTOR_TARGET_VA),
                       (MAIN_MENU_EXPERT_ADD_CALL_VA,
                        MAIN_MENU_EXPERT_ADD_TARGET_VA)):
        word = read_word(data, va2off(segs, va, executable=True))
        if word != 0xE1A00000 and decode_arm_branch_target(word, va) != target:
            raise ValueError(f'main-menu Expert call changed at {va:#x}')
    # Guard every stock Settings row that the replacement builder reproduces.
    # Wi-Fi is the one capability row that may legitimately be hidden/NOPed on
    # a binary that does not expose it today; an explicit JSON true may not
    # manufacture support that the source binary did not have.
    settings_metadata = (
        (0x00038074, 0xE3A03012, 0x00038078, 0xE30324CC, 0x00038080, 0xE3A01056),
        (0x000380AC, 0xE3A03003, 0x000380B0, 0xE30324E4, 0x000380B8, 0xE3A0101A),
        (0x000380E4, 0xE3A03013, 0x000380E8, 0xE3032500, 0x000380F0, 0xE3A01083),
        (0x0003811C, 0xE3A0300D, 0x00038120, 0xE303251C, 0x00038128, 0xE3A01076),
        (0x00038184, 0xE3A0300B, 0x00038188, 0xE303252C, 0x00038190, 0xE3A01017),
        (0x000381F4, 0xE3A03002, 0x000381F8, 0xE3032568, 0x00038200, 0xE3A01019),
        (0x00038254, 0xE3A0300F, 0x00038258, 0xE303257C, 0x00038260, 0xE3A0107D),
        (0x00038298, 0xE3A0300C, 0x0003829C, 0xE30325A8, 0x000382A4, 0xE3A01073),
        (0x000382D0, 0xE3A03010, 0x000382D4, 0xE30325C8, 0x000382DC, 0xE3A01082),
        (0x00038340, 0xE3A03007, 0x00038344, 0xE30325A8, 0x0003834C, 0xE3A0101E),
    )
    for target_va, target_word, icon_va, icon_word, label_va, label_word in settings_metadata:
        for va, expected in ((target_va, target_word), (icon_va, icon_word),
                             (label_va, label_word), (icon_va + 4, 0xE3402015)):
            actual = read_word(data, va2off(segs, va, executable=True))
            if actual != expected:
                raise ValueError(
                    f'Settings row metadata changed at {va:#x}: '
                    f'{actual:#010x}, expected {expected:#010x}')
    active_calls = (
        (0x00038088, 0x000282D0), (0x00038094, 0x00020898),
        (0x000380C0, 0x000282D0), (0x000380CC, 0x00020898),
        (0x00038130, 0x000282D0), (0x0003813C, 0x00020898),
        (0x00038198, 0x000282D0), (0x000381A4, 0x00020898),
        (0x00038208, 0x000282D0), (0x00038214, 0x00020898),
        (0x000382AC, 0x000282D0), (0x000382B8, 0x00020898),
        (0x00038354, 0x000282D0), (0x00038360, 0x00020898),
    )
    for va, expected_target in active_calls:
        word = read_word(data, va2off(segs, va, executable=True))
        if decode_arm_call_target(word, va) != expected_target:
            raise ValueError(f'Settings stock row call changed at {va:#x}')
    for va in (0x00038268, 0x00038274, 0x000382E4, 0x000382F0):
        if read_word(data, va2off(segs, va, executable=True)) != 0xE1A00000:
            raise ValueError(f'Settings stock-hidden row call changed at {va:#x}')
    wifi_ctor = read_word(data, va2off(segs, 0x000380F8, executable=True))
    wifi_add = read_word(data, va2off(segs, 0x00038104, executable=True))
    wifi_active = (decode_arm_call_target(wifi_ctor, 0x000380F8) == 0x000282D0 and
                   decode_arm_call_target(wifi_add, 0x00038104) == 0x00020898)
    wifi_hidden = wifi_ctor == 0xE1A00000 and wifi_add == 0xE1A00000
    if not wifi_active and not wifi_hidden:
        raise ValueError('Settings Wi-Fi capability row changed inconsistently')
    for va, target in ((0x00038140, 0x00134F34), (0x00038150, 0x0003CA64)):
        if decode_arm_call_target(
                read_word(data, va2off(segs, va, executable=True)), va) != target:
            raise ValueError(f'Settings language availability call changed at {va:#x}')
    if read_word(data, va2off(segs, 0x00038060, executable=True)) != 0xE51B4054:
        raise ValueError('Settings builder row-list entry changed')
    if read_word(data, va2off(segs, 0x0003839C, executable=True)) != 0xE51B3054:
        raise ValueError('Settings builder row-list continuation changed')
    return {
        'clear_vtable_off': vtable_off,
        'settings_caps': 1 if wifi_active else 0,
    }


def build_main_menu_layout_context(imports: dict[str, int], state_va: int,
                                   custom_action_vptr: int,
                                   callback_vas: tuple[int, ...],
                                   settings_caps: int) -> bytes:
    words = [
        state_va, imports['fopen'], imports['fclose'], imports['fseek'],
        imports['ftell'], imports['fread'], imports['malloc'], imports['free'],
        imports['strlen'], imports['strcmp'], imports['strncmp'], imports['memcpy'],
        imports['memset'], imports['SDL_PushEvent'], imports['snprintf'], imports['open'], imports['close'],
        0x0001591C, 0x00015904, 0x00039750, 0x00039794,
        0x00025C8C, 0x000258D4, 0x00027A30, FAVOURITE_CREATE_MENU_VA,
        0x00017744, 0x00020500, 0x00020898, 0x00025510,
        0x0003225C, 0x0003A6A8, 0x0003B2D8, 0x00135150,
        0x0003A5A8, 0x00039BAC, 0x00029C4C, 0x00014EA8,
        0x00014EF0, 0x0001540C, 0x0003984C, 0x0003B3BC,
        0x0003B400, imports[CXX_STRING_C_STR], 0x0002E978,
        custom_action_vptr, MAIN_MENU_WINDOW_STACK_GLOBAL_VA,
        MAIN_MENU_STANDARD_VECTOR_VA, MAIN_MENU_EXPERT_VECTOR_VA,
        MAIN_MENU_LANGUAGE_GLOBAL_VA, imports['TTF_RenderUTF8_Blended'],
        imports['SDL_FreeSurface'], MAIN_MENU_DRAW_TEXT_VA, 0x0003A678,
        imports['SDL_CreateRGBSurface'], imports['SDL_UpperBlit'], 0x0001D99C,
        *callback_vas, 0x00181970, MAIN_MENU_POPUP_IMAGE_LOAD_TARGET_VA,
        0x000282D0, 0x00134F34, 0x0003CA64, settings_caps,
        0x000333EC, 0x0001761C,
    ]
    if len(words) * 4 != MAIN_MENU_LAYOUT_CONTEXT_SIZE:
        raise ValueError('main-menu layout context mismatch')
    return struct.pack('<' + 'I' * len(words), *words)


