def build_settings_external_rows_after_display_stub(
        base_va: int, context_va: int, available_helper_va: int) -> bytes:
    """Insert restored Themes/Tweaks rows immediately after stock Display.

    This reuses the exact stock SettingsItem constructor/add path and the
    original destination IDs 15/16.  The later stock-hidden row sites stay
    untouched, avoiding vector surgery or duplicate row machinery.
    """
    a = ArmBuilder(base_va)
    # We enter by replacing the stock call at 0x38140, immediately after the
    # Display row was appended. Keep the constructor's live callee-saved state
    # intact across our helper/allocator/constructor calls; 24 bytes preserves
    # the 8-byte stack alignment used by the stock function.
    a.emit(0xE92D50F0)             # push {r4-r7,r12,lr}

    def emit_row(section: int, label_id: int, icon_va: int, suffix: str) -> None:
        a.ldr_literal(0, context_va)
        a.emit(arm_movw(1, section))
        a.branch(available_helper_va, link=True)
        a.emit(0xE3500000)         # cmp r0,#0
        a.branch(f'skip_{suffix}', cond=0x0)  # beq
        a.emit(0xE51B4054)         # ldr r4,[r11,#-0x54] Settings menu
        a.emit(0xE3A00024)         # mov r0,#36 sizeof stock SettingsItem
        a.branch(0x0001591C, link=True)       # operator new@plt
        a.emit(0xE1A05000)         # mov r5,r0
        a.emit(arm_movw(3, section))
        a.ldr_literal(2, icon_va)
        a.emit(arm_movw(1, label_id))
        a.emit(0xE1A00005)         # mov r0,r5
        a.branch(0x000282D0, link=True)       # stock SettingsItem ctor
        a.emit(0xE1A01005)         # mov r1,r5
        a.emit(0xE1A00004)         # mov r0,r4
        a.branch(0x00020898, link=True)       # stock menu add
        a.label(f'skip_{suffix}')

    emit_row(15, 125, 0x0015357C, 'themes')
    emit_row(16, 130, 0x001535C8, 'tweaks')
    a.emit(0xE8BD50F0)             # pop {r4-r7,r12,lr}
    # Replay the displaced stock call, then resume at its following word.
    a.branch(SETTINGS_DISPLAY_AFTER_ADD_REPLAY_TARGET_VA, link=True)
    a.branch(SETTINGS_DISPLAY_AFTER_ADD_CONTINUE_VA)
    return a.finish()


def build_settings_external_gate_stub(base_va: int, context_va: int,
                                      available_helper_va: int, section: int,
                                      continue_va: int, skip_va: int,
                                      replay_word: int | None = None) -> bytes:
    a = ArmBuilder(base_va)
    a.emit(0xE92D500F)             # push {r0-r3,r12,lr}; aligned
    a.ldr_literal(0, context_va)
    a.emit(arm_movw(1, section))
    a.branch(available_helper_va, link=True)
    a.emit(0xE3500000)             # cmp r0,#0
    a.emit(0xE8BD500F)             # pop {r0-r3,r12,lr}; condition flags retained
    a.branch('skip', cond=0x0)     # beq
    if replay_word is not None:
        a.emit(replay_word)
    a.branch(continue_va)
    a.label('skip')
    a.branch(skip_va)
    return a.finish()


