def build_main_menu_visible_range_stub(base_va: int, state_va: int) -> bytes:
    """Repair a stale restored range only on the replacement top-level menu."""
    a = ArmBuilder(base_va)
    # MainMenuWindow::draw is shared by the top-level menu and stock grids such
    # as Games/systems.  The SF repair assumes a one-row top-level menu, so
    # first require the exact window pointer published by main_menu_build().
    # Every other MainMenuWindow takes the untouched stock draw path.
    a.emit(0xE92D4013)             # push {r0,r1,r4,lr}
    a.emit(0xE1A04000)             # mov r4,r0 -- MainMenuWindow*
    a.ldr_literal(12, state_va + MAIN_MENU_STATE_MAIN_WINDOW_OFF)
    a.emit(0xE59CC000)             # ldr r12,[r12] -- replacement main_window
    a.emit(0xE154000C)             # cmp r4,r12
    a.branch('done', cond=0x1)     # bne: stock/non-top-level MainMenuWindow
    # Preserve the draw arguments and caller state while asking the stock
    # vector for the current dynamic top-level row count.  The replacement
    # top-level window is one row high, so +0x54 is its page capacity.
    a.emit(0xE2840048)             # add r0,r4,#0x48 -- row vector
    a.branch(0x0003B0AC, link=True)
    a.emit(0xE1A03000)             # mov r3,r0 -- row count
    a.emit(0xE3530000)             # cmp r3,#0
    a.branch('done', cond=0x0)     # beq
    a.emit(0xE5942054)             # ldr r2,[r4,#0x54] -- columns/page capacity
    a.emit(0xE3520000)             # cmp r2,#0
    a.branch('done', cond=0x0)     # beq
    a.emit(0xE5940010)             # ldr r0,[r4,#0x10] -- first visible
    a.emit(0xE0800002)             # add r0,r0,r2
    a.emit(0xE2400001)             # sub r0,r0,#1 -- page-end candidate
    a.emit(0xE2431001)             # sub r1,r3,#1 -- final real row
    a.emit(0xE1500001)             # cmp r0,r1
    a.emit(0x81A00001)             # movhi r0,r1 -- min(candidate,last row)
    a.emit(0xE5941014)             # ldr r1,[r4,#0x14] -- current last visible
    a.emit(0xE1510000)             # cmp r1,r0
    a.emit(0xB5840014)             # strlt r0,[r4,#0x14] -- extend only
    a.label('done')
    a.emit(0xE8BD4013)             # pop {r0,r1,r4,lr}
    a.emit(MAIN_MENU_WINDOW_DRAW_STOCK_PROLOGUE)
    a.branch(MAIN_MENU_WINDOW_DRAW_CONTINUE_VA)
    return a.finish()


