def build_favourite_rom_context_label_stub(
        base_va: int, state_va: int, context_va: int, helper_va: int) -> bytes:
    """Return stock Add ID 55 or private Favourite Remove ID 405."""
    a = ArmBuilder(base_va)
    a.emit(0xE92D5210)             # push {r4,r9,ip,lr}; 16 bytes
    a.emit(0xE51B0064)             # r0 = selected TextItem ([fp,#-0x64])
    a.emit(0xE5900018)             # r0 = GameAction/info
    a.ldr_literal(9, state_va)
    a.ldr_literal(1, context_va)
