    title_scroll_preview_code = b''
    title_scroll_favourite_code = b''
    title_scroll_wait_code = b''
    dynamic_fav_position_payload_parts: list[tuple[int, bytes, str]] = []
    rom_list_repaint_timer_code = b''
    rom_list_repaint_scheduler_code = b''
    rom_list_initial_warmup_va: int | None = None
