    if rom_parent_folder_patch:
        # MainUI formats both SELECT and COUNT text into a 512-byte local
        # buffer.  Validate conservative maximum substitutions before any
        # payload is allocated so a future SQL edit cannot silently overflow
        # the target buffer.
        for query_name, query_bytes, ppath_first in (
                ('BINARY list', ROM_PARENT_LIST_QUERY_BINARY, True),
                ('NOCASE list', ROM_PARENT_LIST_QUERY_NOCASE, True),
                ('COUNT', ROM_PARENT_COUNT_SQL, False),
                ('game/folder COUNT',
                 ROM_PARENT_GAME_FOLDER_COUNT_SQL, False)):
            query_text = query_bytes[:-1].decode('ascii')
            formatted_query = query_text
            first_string = ('P' * ROM_PARENT_WORST_PPATH_BYTES
                            if ppath_first else
                            'S' * ROM_PARENT_WORST_SYSTEM_BYTES)
            second_string = ('S' * ROM_PARENT_WORST_SYSTEM_BYTES
                             if ppath_first else
                             'P' * ROM_PARENT_WORST_PPATH_BYTES)
            formatted_query = formatted_query.replace(
                '%s', first_string, 1)
            formatted_query = formatted_query.replace(
                '%s', second_string, 1)
            formatted_query = formatted_query.replace(
                '%d', '2147483647', 1)
            formatted_query = formatted_query.replace(
                '%d', '2147483647', 1)
            formatted_worst_case = len(formatted_query) + 1
            if formatted_worst_case > ROM_PARENT_QUERY_BUFFER_SIZE:
                raise ValueError(
                    f'ordinary ROM parent-row {query_name} SQL exceeds '
                    'the stock 512-byte snprintf buffer')

