            assert game_icon_text_item_wrapper_va is not None
            append_payload_chunk(
                game_icon_text_item_wrapper_va,
                game_icon_text_item_wrapper_code,
                'Favourite/Recent themed game-icon TextItem wrapper')
            assert row_padding_va is not None
