PATCH_NAME_TO_ATTR: dict[str, str] = {
    attr.replace('_', '-'): attr for attr, _label in PATCH_OPTIONS
}
PATCH_ALL_ATTRS: frozenset[str] = frozenset(
    attr for attr, _label in PATCH_OPTIONS
)


def expand_patch_selectors(
        parser: argparse.ArgumentParser, values: list[str], option: str) -> set[str]:
    """Resolve repeatable/comma-separated patch names to argparse attributes."""
    selected: set[str] = set()
    for raw_value in values:
        for raw_name in raw_value.split(','):
            name = raw_name.strip()
            if name.startswith('--'):
                name = name[2:]
            if not name:
                parser.error(f'{option} contains an empty patch name')
            if name == 'all':
                selected.update(PATCH_ALL_ATTRS)
                continue
            attr = PATCH_NAME_TO_ATTR.get(name)
            if attr is None:
                available = ', '.join(PATCH_NAME_TO_ATTR)
                parser.error(
                    f'unknown patch name for {option}: {raw_name!r}\n'
                    f'available names: {available}')
            selected.add(attr)
    return selected



def resolve_patch_selection(named_includes: set[str], named_excludes: set[str],
                            patch_all: bool
                            ) -> tuple[set[str], str, list[str]]:
    'Resolve patch selection and dependency rules without argparse side effects.'
    all_attrs = set(PATCH_ALL_ATTRS)
    include_only = bool(named_includes) and not patch_all
    if include_only:
        selected_attrs = set(named_includes)
        selection_mode = 'include-only'
    else:
        selected_attrs = set(all_attrs)
        selection_mode = 'all patches by default'
    selected_attrs -= named_excludes

    dependency_notes: list[str] = []
    dependencies = (
        ('improve_game_details', 'fix_game_detail_title_on_open',
         'System-name display automatically includes the detail-title fix',
         'Excluding fix-game-detail-title-on-open also excludes improve-game-details, which requires it'),
        ('restore_favourite_folder_after_game_exit', 'add_favourite_folders_json',
         'Favourite-folder return automatically includes add-favourite-folders-json',
         'Excluding add-favourite-folders-json also excludes restore-favourite-folder-after-game-exit, which requires it'),
        ('sort_favourite_folder_a_z', 'add_favourite_folders_json',
         'Favourite-folder A-Z sorting automatically includes add-favourite-folders-json',
         'Excluding add-favourite-folders-json also excludes sort-favourite-folder-a-z, which requires it'),
        ('reuse_onion_arcade_name_lookup', 'use_rom_database_display_names',
         'Arcade rebuild-name caching automatically includes use-rom-database-display-names so the removed rebuild-time GetGameName warm-up cannot reappear as a cold browse stall',
         'Excluding use-rom-database-display-names also excludes reuse-onion-arcade-name-lookup, which requires the browse-time bypass'),
    )
    for dependent, required, auto_note, exclude_note in dependencies:
        if dependent not in selected_attrs or required in selected_attrs:
            continue
        if required in named_excludes:
            selected_attrs.remove(dependent)
            dependency_notes.append(exclude_note)
        else:
            selected_attrs.add(required)
            dependency_notes.append(auto_note)
    return selected_attrs, selection_mode, dependency_notes


def validate_patch_selection_models() -> None:
    'Regression tests for include/exclude precedence and dependency closure.'
    all_attrs = set(PATCH_ALL_ATTRS)
    selected, _mode, _notes = resolve_patch_selection(set(), set(), False)
    if selected != all_attrs:
        raise ValueError('default patch selection no longer equals all patches')
    selected_all, _mode, _notes = resolve_patch_selection(set(), set(), True)
    if selected_all != selected:
        raise ValueError('--patch-all differs from default patch selection')

    rows = 'patch_rom_list_rows'
    font = 'patch_rom_list_font_size'
    selected, mode, _notes = resolve_patch_selection({rows, font}, set(), False)
    if selected != {rows, font} or mode != 'include-only':
        raise ValueError('include-only patch selection regression')
    selected, _mode, _notes = resolve_patch_selection({rows, font}, {font}, False)
    if selected != {rows}:
        raise ValueError('patch exclusion no longer wins over inclusion')
    selected, _mode, _notes = resolve_patch_selection(set(), all_attrs, False)
    if selected:
        raise ValueError('excluding every patch did not produce an empty selection')

    folders = 'add_favourite_folders_json'
    return_attr = 'restore_favourite_folder_after_game_exit'
    sort_attr = 'sort_favourite_folder_a_z'
    selected, _mode, _notes = resolve_patch_selection({return_attr}, set(), False)
    if selected != {return_attr, folders}:
        raise ValueError('Favourite return dependency closure regression')
    selected, _mode, _notes = resolve_patch_selection({return_attr}, {folders}, False)
    if return_attr in selected or folders in selected:
        raise ValueError('Favourite return survived exclusion of required folders')
    selected, _mode, _notes = resolve_patch_selection({sort_attr}, set(), False)
    if selected != {sort_attr, folders}:
        raise ValueError('Favourite sort dependency closure regression')

    improve = 'improve_game_details'
    title = 'fix_game_detail_title_on_open'
    selected, _mode, _notes = resolve_patch_selection({improve}, set(), False)
    if selected != {improve, title}:
        raise ValueError('game-detail dependency closure regression')
    selected, _mode, _notes = resolve_patch_selection({improve}, {title}, False)
    if improve in selected or title in selected:
        raise ValueError('game-detail dependent survived required-patch exclusion')

    arcade_cache = 'reuse_onion_arcade_name_lookup'
    db_disp = 'use_rom_database_display_names'
    selected, _mode, _notes = resolve_patch_selection(
        {arcade_cache}, set(), False)
    if selected != {arcade_cache, db_disp}:
        raise ValueError(
            'Arcade rebuild-name cache no longer implies DB display-name bypass')
    selected, _mode, _notes = resolve_patch_selection(
        {arcade_cache}, {db_disp}, False)
    if arcade_cache in selected or db_disp in selected:
        raise ValueError(
            'Arcade rebuild-name cache survived exclusion of DB display-name bypass')


    console_refresh = 'add_console_refresh_roms'
    selected, _mode, _notes = resolve_patch_selection(
        {console_refresh}, set(), False)
    if selected != {console_refresh}:
        raise ValueError('per-console refresh is no longer standalone')

    parser = argparse.ArgumentParser(add_help=False)
    expanded = expand_patch_selectors(
        parser, ['patch-rom-list-rows,patch-rom-list-font-size',
                 '--patch-rom-list-rows'], '--include')
    if expanded != {rows, font}:
        raise ValueError('repeatable/comma-separated selector expansion regression')
    if expand_patch_selectors(parser, ['all'], '--include') != all_attrs:
        raise ValueError('all-selector expansion no longer covers every patch')


def main() -> None:
    parser = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument(
        '--version', action='version',
        version=f'OnionOS MainUI patcher {PROGRAM_VERSION}')
    parser.add_argument('--config-path', default=DEFAULT_CONFIG_PATH,
                        help='runtime row-count config path')
    parser.add_argument('--font-config-path', default=DEFAULT_FONT_CONFIG_PATH,
                        help='runtime game-list font-size config path')
    parser.add_argument('--sort-config-path', default=DEFAULT_SORT_CONFIG_PATH,
                        help='runtime case-sensitive-sort marker path')
    parser.add_argument('--key-repeat-config-path',
                        default=DEFAULT_KEY_REPEAT_CONFIG_PATH,
                        help='runtime MainUI key-repeat delay/interval config path')
    parser.add_argument('--title-scroll-config-path',
                        default=DEFAULT_TITLE_SCROLL_CONFIG_PATH,
                        help='runtime long-title idle/speed config path')
    parser.add_argument(
        '--include', action='append', default=[], metavar='PATCH[,PATCH...]',
        help=('include named patches only; repeat or use comma-separated names. '
              'Patch names omit the leading --'))
    parser.add_argument(
        '--exclude', action='append', default=[], metavar='PATCH[,PATCH...]',
        help=('exclude named patches from the selected set; repeat or use '
              'comma-separated names. Exclusions always win'))
    parser.add_argument(
        '--patch-all', action='store_true',
        help=('explicitly select every patch; this is already the default when '
              'no --include selector is supplied'))
    parser.add_argument(
        '--inplace', action='store_true',
        help=('replace each input after creating FILE.pre-mainui-patches.bak '
              'when that backup does not already exist; the default writes '
              'FILE.patched and leaves the input unchanged'))
    parser.add_argument('files', nargs='+', type=Path)
    args = parser.parse_args()

    all_attrs = set(PATCH_ALL_ATTRS)
    named_includes = expand_patch_selectors(parser, args.include, '--include')
    named_excludes = expand_patch_selectors(parser, args.exclude, '--exclude')
    selected_attrs, selection_mode, dependency_notes = resolve_patch_selection(
        named_includes, named_excludes, args.patch_all)

    partial_selection = selected_attrs != all_attrs

    for attr, _label in PATCH_OPTIONS:
        setattr(args, attr, attr in selected_attrs)

    selected_labels = [
        label for attr, label in PATCH_OPTIONS if attr in selected_attrs
    ]
    if not selected_labels:
        for note in dependency_notes:
            print(f'[NOTE] {note}')
        print('No patches remain after selection/exclusion.')
        print('Nothing was changed and no output file was created.')
        return

    print(f'Selection mode: {selection_mode}')
    if named_excludes:
        print('Excluded patches:')
        for attr, label in PATCH_OPTIONS:
            if attr in named_excludes:
                print(f'  [EXCLUDE] {label}')
    print('Selected patches:')
    for label in selected_labels:
        print(f'  [PATCH] {label}')
    for note in dependency_notes:
        print(f'  [NOTE] {note}')

    output_paths: list[Path] = []
    for file in args.files:
        print(f'\nPatching {file}:')
        input_raw = file.read_bytes()
        input_sha256, supported_name = input_sha256_status(input_raw)
        input_warning_emitted = supported_name is None
        if input_warning_emitted:
            for line in unrecognized_input_warning_lines(input_sha256):
                print(f'  {line}')
        else:
            print(f'  [INPUT] Recognized {supported_name}: {input_sha256}')
        print(f'  [BUILD] Applying {len(selected_labels)} selected patches')
        progress_meter = PatchProgressMeter()
        progress_meter.start()
        try:
            patch_result = patch(
                file, args.config_path, args.font_config_path,
            args.sort_config_path, args.key_repeat_config_path,
            args.title_scroll_config_path, args.inplace,
            rom_list_rows_patch=args.patch_rom_list_rows,
            rom_list_font_patch=args.patch_rom_list_font_size,
            detail_title_fix=args.fix_game_detail_title_on_open,
            detail_title_wrap_width_fix=args.fix_game_detail_title_wrap_width,
            sleep_timer_fix=args.fix_sleep_timer_left_right,
            invalid_main_menu_state_fix=args.fix_invalid_main_menu_state,
            game_list_context_menu_background_fix=(
                args.fix_game_list_context_menu_background),
            context_menu_selection_background_patch=(
                args.patch_context_menu_selection_background),
            dialog_action_theme_style_fix=args.fix_dialog_action_theme_style,
            case_insensitive_game_list_sorting=args.fix_case_sensitive_game_list_sorting,
            improve_game_details=args.improve_game_details,
            miyoogamelist_detail_metadata_patch=(
                args.show_gamelist_metadata_in_game_details),
            prevent_favourite_label_collisions=args.prevent_favourite_label_collisions,
            escape_apostrophes_in_rom_paths=args.escape_apostrophes_in_rom_paths,
            key_repeat_settings_patch=args.patch_key_repeat_settings,
            rom_list_title_scroll_patch=args.patch_rom_list_title_scroll,
            rom_list_letter_jump_patch=args.patch_rom_list_letter_jump,
            rom_list_end_jump_patch=args.patch_rom_list_end_jump,
            inactive_theme_config_skip_patch=args.skip_inactive_theme_configs,
            theme_list_font_bold_patch=args.patch_theme_list_font_bold,
            game_list_rapid_navigation_fix=(
                args.fix_game_list_rapid_navigation),
            rom_list_thumbnail_cache_limit_patch=(
                args.limit_rom_list_thumbnail_cache),
            rom_preview_surface_copy_skip_patch=(
                args.skip_rom_preview_surface_copy),
            list_skin_image_cache_patch=args.cache_list_skin_images,
            identity_thumbnail_rescale_skip_patch=(
                args.skip_identity_thumbnail_rescale),
            favourite_refresh_sweep_optimization_patch=(
                args.optimize_favourite_refresh_sweep),
            rom_database_deletion_optimization_patch=(
                args.optimize_rom_database_deletion),
            direct_shell_operation_optimization_patch=(
                args.optimize_direct_shell_operations),
            rom_artwork_directory_scan_skip_patch=(
                args.skip_rom_artwork_directory_scan),
            background_status_polling_patch=(
                args.throttle_background_status_polling),
            burst_cpu_governor_patch=(
                args.optimize_burst_cpu_governor),
            rom_database_rebuild_optimization_patch=(
                args.optimize_rom_database_rebuild),
            rom_rebuild_path_safety_patch=(
                args.fix_rom_rebuild_path_safety),
            wifi_network_shell_quoting_fix=(
                args.fix_wifi_network_shell_quoting),
            miyoogamelist_file_check_optimization_patch=(
                args.optimize_miyoogamelist_file_checks),
            miyoogamelist_entry_timing_suppression_patch=(
                args.suppress_miyoogamelist_entry_timing),
            miyoogamelist_missing_image_fix_patch=(
                args.allow_missing_miyoogamelist_image_tags),
            favourite_lookup_page_cache_patch=(
                args.cache_favourite_lookups_per_page),
            favourite_folders_json_patch=(
                args.add_favourite_folders_json),
            favourite_folder_sort_az_patch=(
                args.sort_favourite_folder_a_z),
            favourite_folder_return_patch=(
                args.restore_favourite_folder_after_game_exit),
            recent_remove_from_list_patch=(
                args.add_recent_remove_from_list),
            console_refresh_roms_patch=(
                args.add_console_refresh_roms),
            optimize_recent_list_loading_patch=(
                args.optimize_recent_list_loading),
            recent_preview_paths_fix=(
                args.fix_recent_preview_paths),
            search_favourite_status_fix=(
                args.fix_search_favourite_status),
            rom_database_display_names_patch=(
                args.use_rom_database_display_names),
            extend_recent_list_to_50_patch=(
                args.extend_recent_list_to_50),
            exclude_apps_from_recent_list_patch=(
                args.exclude_apps_from_recent_list),
            rom_database_debug_logging_suppression_patch=(
                args.suppress_rom_database_debug_logging),
            rom_database_refresh_sync_skip_patch=(
                args.skip_rom_database_refresh_sync),
            rom_list_count_cache_patch=args.cache_rom_list_counts,
            reuse_onion_arcade_name_lookup_patch=(
                args.reuse_onion_arcade_name_lookup),
            rom_list_database_indexes_patch=(
                args.optimize_rom_list_database_indexes),
            game_detail_folder_skip_patch=(
                args.skip_folders_in_game_detail_navigation),
            rom_parent_folder_patch=(
                args.add_parent_folder_to_rom_lists),
                main_menu_layout_patch=args.patch_main_menu_layout,
                contextual_search_fix=args.fix_contextual_search,
                input_warning_emitted=input_warning_emitted,
                progress=progress_meter.update)
        finally:
            progress_meter.finish_line()
        print(patch_result)
        output_paths.append(file if args.inplace else Path(str(file) + '.patched'))

    print(f'\n          Patched file count: {len(output_paths)}')
    for output in output_paths:
        print(f'          Output: {output}')
    print('[SUCCESS] All requested patches were applied successfully.')
    if partial_selection:
        print('[WARNING] Experimental patch combination: not all available patches were included.')
        print('[WARNING] Only the complete all-patches build is normally tested as an integrated configuration.')


def run_cli() -> None:
    """Run the command-line interface without exposing routine tracebacks."""
    try:
        main()
    except Exception as exc:
        message = str(exc).strip() or exc.__class__.__name__
        print(f'[ERROR] {message}', file=sys.stderr)
        raise SystemExit(1) from None


if __name__ == '__main__':
    run_cli()
